def _looks_like_ansible_text_config_artifact_name(value: str) -> bool:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return False
    segments = [segment for segment in normalized.split("/") if segment]
    if not segments:
        return False
    name = segments[-1]
    parent_segments = set(segments[:-1])
    suffix = Path(name).suffix.lower()
    if name == "ansible.cfg":
        return True
    if name == "inventory" and parent_segments & {"ansible", "inventories", "inventory"}:
        return True
    if name.startswith("inventory.") and suffix in {".ini", ".cfg", ".conf", ".json", ".yml", ".yaml"}:
        return True
    if parent_segments & {"group_vars", "host_vars"} and suffix in {"", ".json", ".yml", ".yaml", ".ini", ".cfg"}:
        return True
    return False


