def _ansible_inventory_line_host_tokens(raw_line: str) -> list[str]:
    line = str(raw_line or "").split("#", 1)[0].strip()
    if not line:
        return []
    if line.startswith(("[", "---", "...")):
        return []
    host_tokens: list[str] = []
    mapping_match = re.match(
        r"""^\s*["']?(?P<host>[A-Za-z0-9_.-]+\.?[A-Za-z0-9-]*)["']?\s*:\s*(?:[{\[]?.*)?$""",
        line,
    )
    if mapping_match:
        host_tokens.append(mapping_match.group("host"))
    else:
        first_token = line.split(None, 1)[0].strip().strip("\"'[]{}(),;")
        if first_token and "=" not in first_token and ":" not in first_token:
            host_tokens.append(first_token)
    host_tokens.extend(
        match.group("value").strip().strip("\"'")
        for match in _ARTIFACT_ANSIBLE_HOST_FIELD_RE.finditer(line)
    )
    return [token for token in host_tokens if token]


