def _extract_artifact_network_endpoint_seeds(
    text: str,
    *,
    source_file: str = "",
) -> list[tuple[str, str]]:
    values: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    text_value = str(text or "")
    dsn_seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [match.group(0) for match in _ARTIFACT_NETWORK_DSN_RE.finditer(text_value)],
        _artifact_network_dsn_seed_entries,
        default_factory=list,
    )
    for dsn_seed_batch in dsn_seed_batches:
        for seed in dsn_seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    family_names = [
        "ssh",
        "remote_access",
        "dns_zone",
        "hosts_file",
        "dhcp_lease",
        "vpn_endpoint",
    ]
    if _looks_like_ansible_text_config_artifact_name(source_file):
        family_names.append("ansible_inventory")
    if _looks_like_cloud_init_text_config_artifact_name(source_file):
        family_names.append("cloud_init")
    if _looks_like_os_installer_text_config_artifact_name(source_file):
        family_names.append("os_installer")
    if _looks_like_vagrantfile_text_config_artifact_name(source_file):
        family_names.append("vagrantfile")
    if connection_client_config_artifact_label(source_file):
        family_names.append("connection_client")
    if database_client_config_artifact_label(source_file):
        family_names.append("database_client")
    family_seed_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [(family, text_value) for family in family_names],
        _artifact_network_endpoint_family_seed_entries,
        default_factory=list,
    )
    for family_seed_batch in family_seed_batches:
        for seed in family_seed_batch:
            if seed in seen:
                continue
            seen.add(seed)
            values.append(seed)
    return values


def _artifact_url_query_key_is_sensitive(value: str) -> bool:
    key = str(value or "").strip().lower()
    if not key:
        return False
    compact = key.replace("-", "_").replace(".", "_")
    if compact in {
        "access_key",
        "access_key_id",
        "access_token",
        "api_key",
        "apikey",
        "auth",
        "auth_token",
        "authorization",
        "client_secret",
        "code",
        "credential",
        "id_token",
        "key",
        "password",
        "refresh_token",
        "relaystate",
        "samlrequest",
        "samlresponse",
        "secret",
        "security_token",
        "session",
        "session_id",
        "sessionid",
        "session_token",
        "shared_access_signature",
        "sig",
        "sigalg",
        "signature",
        "sid",
        "jsessionid",
        "phpsessid",
        "token",
        "x_amz_credential",
        "x_amz_security_token",
        "x_amz_signature",
    }:
        return True
    return (
        compact.endswith("_token")
        or compact.endswith("_secret")
        or compact.endswith("_session")
        or "signature" in compact
        or "credential" in compact
    )


def _strip_artifact_url_userinfo_in_text(value: str) -> str:
    sanitized = _ARTIFACT_URL_RE.sub(
        lambda match: _normalize_artifact_text_url(match.group(0)),
        str(value or ""),
    )
    return _ARTIFACT_NETWORK_DSN_RE.sub(
        lambda match: _strip_artifact_network_dsn_userinfo(match.group(0)),
        sanitized,
    )


def _strip_artifact_network_dsn_userinfo(value: str) -> str:
    oracle_jdbc_match = _ARTIFACT_ORACLE_JDBC_DSN_RE.search(str(value or ""))
    if oracle_jdbc_match:
        return f"jdbc:oracle:thin:@//{oracle_jdbc_match.group('host').lower()}"
    candidate = _normalize_artifact_network_dsn_token(value)
    prefix = "jdbc:" if str(value or "").strip().lower().startswith("jdbc:") else ""
    parsed = urlparse(candidate)
    if parsed.scheme.lower() not in _ARTIFACT_NETWORK_DSN_SCHEMES or not parsed.hostname:
        return candidate
    hostname = parsed.hostname.lower()
    if ":" in hostname and not hostname.startswith("["):
        hostname = f"[{hostname}]"
    try:
        port = parsed.port
    except ValueError:
        port = None
    netloc = f"{hostname}:{port}" if port else hostname
    return f"{prefix}{parsed._replace(netloc=netloc, query='').geturl()}"


def _normalize_artifact_route_token(value: str) -> str:
    candidate = str(value or "").strip()
    if not candidate:
        return ""
    candidate = (
        candidate.replace("\\/", "/")
        .replace("\\u002f", "/")
        .replace("\\u002F", "/")
    )
    candidate = unquote(candidate.strip().strip("[](){}<>,;\"'`"))
    while candidate:
        previous = candidate
        candidate = _ARTIFACT_URL_ESCAPED_CONTROL_SUFFIX_RE.sub("", candidate)
        candidate = candidate.rstrip(")]}.,;\"'`\\")
        if candidate == previous:
            break
    return candidate


def _looks_like_electron_update_metadata_name(value: str) -> bool:
    name = Path(str(value or "").strip().lower()).name
    return bool(name and _ELECTRON_UPDATE_METADATA_NAME_RE.fullmatch(name))


def _artifact_route_path_is_useful(
    raw_value: str,
    *,
    allow_bare_file: bool = False,
    allow_route_path: bool = False,
) -> bool:
    candidate = _normalize_artifact_route_token(raw_value)
    if not candidate:
        return False
    lowered_candidate = candidate.lower()
    if lowered_candidate.startswith(("data:", "javascript:", "mailto:", "tel:")):
        return False
    parsed = urlparse(candidate)
    if parsed.scheme and parsed.scheme not in {"http", "https"}:
        return False
    path = str(parsed.path or candidate).replace("\\", "/")
    lowered_path = path.lower()
    if not lowered_path or lowered_path in {"/", ".", "./", "../"}:
        return False
    if lowered_path.startswith(_ARTIFACT_RELATIVE_ROUTE_SKIP_PREFIXES):
        return False
    if _special_text_config_route_label(lowered_path):
        return True
    path_name = Path(unquote(lowered_path)).name
    if _looks_like_browser_binary_string_artifact_name(path_name):
        return True
    if windows_registry_hive_artifact_label(unquote(lowered_path)):
        return True
    if _looks_like_electron_update_metadata_name(path_name):
        return True
    if _looks_like_react_native_bundle_artifact_name(path_name):
        return True
    suffix = Path(unquote(lowered_path)).suffix.lower()
    if suffix in _ARTIFACT_RELATIVE_ROUTE_FILE_SUFFIXES:
        return True
    if allow_bare_file and suffix:
        return suffix in _ARTIFACT_RELATIVE_ROUTE_FILE_SUFFIXES
    if allow_route_path and lowered_path.startswith("/"):
        return True
    return lowered_path.startswith(_ARTIFACT_RELATIVE_ROUTE_ALLOWED_PREFIXES)


def _resolve_artifact_route_url(
    raw_value: str,
    *,
    base_url: str,
    allow_bare_file: bool = False,
    allow_route_path: bool = False,
) -> str:
    parsed_base = urlparse(str(base_url or "").strip())
    if parsed_base.scheme not in {"http", "https"} or not parsed_base.netloc:
        return ""
    candidate = _normalize_artifact_route_token(raw_value)
    if not _artifact_route_path_is_useful(
        candidate,
        allow_bare_file=allow_bare_file,
        allow_route_path=allow_route_path,
    ):
        return ""
    parsed_candidate = urlparse(candidate)
    if parsed_candidate.scheme in {"http", "https"} and parsed_candidate.netloc:
        return _normalize_artifact_text_url(candidate)
    if candidate.startswith("//"):
        return _normalize_artifact_text_url(f"{parsed_base.scheme}:{candidate}")
    if not candidate.startswith(("/", "./", "../")):
        first_segment = candidate.split("/", 1)[0].lower()
        if first_segment in _ARTIFACT_RELATIVE_ROUTE_ROOT_PREFIXES:
            candidate = f"/{candidate}"
        elif not allow_bare_file:
            return ""
    resolved = _normalize_artifact_text_url(urljoin(base_url, candidate))
    parsed_resolved = urlparse(resolved)
    if parsed_resolved.scheme not in {"http", "https"} or not parsed_resolved.netloc:
        return ""
    return resolved


def _extract_artifact_relative_route_urls(text: str, *, base_url: str) -> list[str]:
    ordered_urls: list[str] = []
    seen: set[str] = set()

    route_family_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        (
            "source_mapping",
            "electron_update_metadata",
            "route_object_keys",
            "route_declarations",
            "route_lists",
            "relative_routes",
        ),
        lambda family: _artifact_relative_route_family_candidates(
            family,
            text=text,
            base_url=base_url,
        ),
        default_factory=list,
    )
    for route_family_batch in route_family_batches:
        for resolved in route_family_batch:
            if not resolved or resolved in seen:
                continue
            seen.add(resolved)
            ordered_urls.append(resolved)
    return ordered_urls


def _artifact_relative_route_family_candidates(
    family: str,
    *,
    text: str,
    base_url: str,
) -> list[str]:
    ordered_urls: list[str] = []

    def _append(
        raw_value: str,
        *,
        allow_bare_file: bool = False,
        allow_route_path: bool = False,
    ) -> None:
        resolved = _resolve_artifact_route_url(
            raw_value,
            base_url=base_url,
            allow_bare_file=allow_bare_file,
            allow_route_path=allow_route_path,
        )
        if resolved:
            ordered_urls.append(resolved)

    raw_text = str(text or "")
    if family == "source_mapping":
        for match in _ARTIFACT_SOURCE_MAPPING_URL_RE.finditer(raw_text):
            _append(match.group(1), allow_bare_file=True)
        return ordered_urls
    if family == "electron_update_metadata":
        for match in _ELECTRON_UPDATE_METADATA_ROUTE_RE.finditer(raw_text):
            _append(match.group("path"), allow_bare_file=True)
        return ordered_urls
    if family == "route_object_keys":
        for match in _ARTIFACT_ROUTE_OBJECT_KEY_RE.finditer(raw_text):
            _append(match.group("path"), allow_route_path=True)
        return ordered_urls
    if family == "route_declarations":
        for match in _ARTIFACT_ROUTE_DECLARATION_RE.finditer(raw_text):
            _append(match.group("path"), allow_route_path=True)
        return ordered_urls
    if family == "route_lists":
        for list_match in _ARTIFACT_ROUTE_LIST_FIELD_RE.finditer(raw_text):
            for route_match in _ARTIFACT_QUOTED_SLASH_ROUTE_RE.finditer(list_match.group("body")):
                _append(route_match.group("path"), allow_route_path=True)
        return ordered_urls
    if family == "relative_routes":
        for match in _ARTIFACT_RELATIVE_ROUTE_RE.finditer(raw_text):
            _append(match.group("path"))
        return ordered_urls
    return ordered_urls


def _normalize_protocol_relative_artifact_url(value: str) -> str:
    candidate = _normalize_artifact_text_url(str(value or "").strip())
    if not candidate.startswith("//"):
        return ""
    parsed = urlparse(f"https:{candidate}")
    if parsed.scheme != "https" or not parsed.hostname:
        return ""
    host = parsed.hostname.lower()
    try:
        netloc = f"{host}:{parsed.port}" if parsed.port else host
    except ValueError:
        netloc = host
    path = parsed.path.rstrip("/")
    return f"https://{netloc}{path}"


def _artifact_managed_cloud_url_candidate(value: str) -> str:
    raw = str(value or "").strip().strip("\"'")
    if not raw or re.search(r"\s", raw):
        return ""
    lowered = raw.lower()
    if lowered.startswith(("mailto:", "tel:", "s3://", "gs://")):
        return ""
    if raw.startswith("//"):
        candidate = f"https:{raw}"
    elif "://" not in raw:
        candidate = f"https://{raw}"
    else:
        candidate = raw
    normalized = _normalize_artifact_text_url(candidate)
    parsed = urlparse(normalized)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        return ""
    hostname = str(parsed.hostname or "").strip().lower().strip(".")
    if not _is_managed_cloud_provider_host(hostname):
        return ""
    return normalized


def _artifact_package_registry_url_candidate(raw_url: str) -> str:
    candidate = str(raw_url or "").strip()
    normalized = (
        _normalize_protocol_relative_artifact_url(candidate)
        if candidate.startswith("//")
        else _normalize_artifact_text_url(candidate)
    )
    parsed = urlparse(normalized)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    return normalized


def _artifact_package_registry_host_or_url_candidate(raw_url: str) -> str:
    candidate = str(raw_url or "").strip().strip("\"'")
    if not candidate or re.search(r"\s", candidate):
        return ""
    if any(marker in candidate for marker in ("${", "$(", "{{", "}}", "<", ">")):
        return ""
    if "://" not in candidate and re.fullmatch(
        r"[A-Za-z0-9_.+\-]+@[A-Za-z0-9\-]+(?:\.[A-Za-z]{2,})+",
        candidate,
    ):
        return ""
    lowered = candidate.lower()
    if lowered.startswith(("mailto:", "tel:", "s3://", "gs://")):
        return ""
    if lowered.startswith(("docker://", "oci://")):
        candidate = candidate.split("://", 1)[1]
    if candidate.startswith("//"):
        candidate = f"https:{candidate}"
    elif "://" not in candidate:
        candidate = f"https://{candidate}"
    normalized = _normalize_artifact_text_url(candidate)
    parsed = urlparse(normalized)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        return ""
    hostname = str(parsed.hostname or "").strip().lower().strip(".")
    if not hostname or (hostname != "localhost" and "." not in hostname and ":" not in hostname):
        return ""
    return normalized


def _artifact_package_registry_family_candidates(family: str, *, text: str) -> list[str]:
    ordered_urls: list[str] = []

    raw_text = str(text or "")
    if family == "protocol_relative_registry_directives":
        for match in _ARTIFACT_PACKAGE_PROTOCOL_RELATIVE_REGISTRY_DIRECTIVE_RE.finditer(raw_text):
            candidate = _artifact_package_registry_url_candidate(match.group("url"))
            if candidate:
                ordered_urls.append(candidate)
        return ordered_urls
    if family == "protocol_relative_auth":
        for match in _ARTIFACT_PACKAGE_PROTOCOL_RELATIVE_AUTH_RE.finditer(raw_text):
            candidate = _artifact_package_registry_url_candidate(match.group("url"))
            if candidate:
                ordered_urls.append(candidate)
        return ordered_urls
    if family == "package_urls":
        for match in _ARTIFACT_PACKAGE_URL_RE.finditer(raw_text):
            candidate = _artifact_package_registry_url_candidate(
                _artifact_package_url_registry_candidate(
                    match.group("type"),
                    match.group("body"),
                )
            )
            if candidate:
                ordered_urls.append(candidate)
        return ordered_urls
    return ordered_urls


def _extract_artifact_package_registry_urls(text: str) -> list[str]:
    ordered_urls: list[str] = []
    seen: set[str] = set()

    registry_family_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        (
            "protocol_relative_registry_directives",
            "protocol_relative_auth",
            "package_urls",
        ),
        lambda family: _artifact_package_registry_family_candidates(
            family,
            text=text,
        ),
        default_factory=list,
    )
    for registry_family_batch in registry_family_batches:
        for url in registry_family_batch:
            if not url or url in seen:
                continue
            seen.add(url)
            ordered_urls.append(url)
    return ordered_urls


def _extract_artifact_container_image_urls(text: str, *, source_hint: str = "") -> list[str]:
    ordered_urls: list[str] = []
    seen: set[str] = set()
    raw_text = str(text or "")

    line_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        raw_text.splitlines(),
        _artifact_container_image_line_candidates,
        default_factory=list,
    )
    field_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [
            match.group("body")
            for match in _ARTIFACT_CONTAINER_IMAGE_REF_FIELD_RE.finditer(raw_text)
        ],
        _artifact_container_image_ref_body_candidates,
        default_factory=list,
    )
    docker_image_uri_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        [
            match.group("value")
            for match in _ARTIFACT_CONTAINER_DOCKER_IMAGE_URI_RE.finditer(raw_text)
        ],
        lambda value: [
            _artifact_container_image_url_candidate(
                f"docker-image://{value}",
                require_explicit_registry=True,
            )
        ],
        default_factory=list,
    )
    jenkins_groovy_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        _artifact_container_image_jenkins_groovy_values(
            raw_text,
            source_hint=source_hint,
        ),
        lambda value: [
            _artifact_container_image_url_candidate(
                value,
                require_explicit_registry=True,
            )
        ],
        default_factory=list,
    )
    earthfile_save_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        _artifact_container_image_earthfile_save_values(
            raw_text,
            source_hint=source_hint,
        ),
        lambda value: [
            _artifact_container_image_url_candidate(
                value,
                require_explicit_registry=True,
            )
        ],
        default_factory=list,
    )
    starlark_image_batches = ArtifactQueueProcessor._run_ordered_static_batch(
        starlark_container_image_values(
            raw_text,
            source_hint=source_hint,
        ),
        lambda value: [
            _artifact_container_image_url_candidate(
                value,
                require_explicit_registry=True,
            )
        ],
        default_factory=list,
    )
    for candidate_batch in (
        *line_batches,
        *field_batches,
        *docker_image_uri_batches,
        *jenkins_groovy_batches,
        *earthfile_save_batches,
        *starlark_image_batches,
    ):
        for normalized in candidate_batch:
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            ordered_urls.append(normalized)
    return ordered_urls


def _artifact_container_image_jenkins_groovy_values(
    text: str,
    *,
    source_hint: str = "",
) -> list[str]:
    raw_text = str(text or "")
    positioned_values: list[tuple[int, str]] = []
    seen: set[str] = set()

    def _append(position: int, value: str) -> None:
        candidate = str(value or "").strip().strip("\"'")
        if not candidate or candidate.lower() in seen:
            return
        seen.add(candidate.lower())
        positioned_values.append((position, candidate))

    for match in _ARTIFACT_JENKINS_DOCKER_IMAGE_CALL_RE.finditer(raw_text):
        _append(match.start(), match.group("value"))

    if _jenkinsfile_config_artifact_label(source_hint):
        for match in _ARTIFACT_JENKINS_DECLARATIVE_IMAGE_RE.finditer(raw_text):
            _append(match.start(), match.group("value"))

    return [value for _position, value in sorted(positioned_values, key=lambda item: item[0])]


def _artifact_container_image_earthfile_save_values(
    text: str,
    *,
    source_hint: str = "",
) -> list[str]:
    if Path(str(source_hint or "").replace("\\", "/")).name.lower() != "earthfile":
        return []
    values: list[str] = []
    seen: set[str] = set()
    for line in str(text or "").splitlines():
        match = re.match(r"(?i)^\s*SAVE\s+IMAGE\s+(?P<body>.+?)\s*$", line)
        if not match:
            continue
        try:
            tokens = shlex.split(match.group("body"), comments=True, posix=True)
        except ValueError:
            tokens = re.findall(r"""["']([^"'\r\n]+)["']|([^\s#]+)""", match.group("body"))
            tokens = [quoted or bare for quoted, bare in tokens]
        for token in tokens:
            candidate = str(token or "").strip()
            if not candidate or candidate.startswith("--") or candidate.lower() in seen:
                continue
            seen.add(candidate.lower())
            values.append(candidate)
    return values


def _artifact_container_image_ref_body_candidates(raw_body: str) -> list[str]:
    body = str(raw_body or "").strip()
    if not body:
        return []
    quoted_tokens = re.findall(r"""["']([^"'\r\n]{1,1024})["']""", body)
    tokens = quoted_tokens or re.split(r"[\s,\[\]]+", body)
    values: list[str] = []
    seen: set[str] = set()
    for raw_token in tokens:
        token = str(raw_token or "").strip().strip(",[]{}()\"'")
        if not token:
            continue
        ref_match = re.search(r"(?:^|,)ref=(?P<ref>[^,\s]+)", token, re.IGNORECASE)
        if ref_match:
            token = ref_match.group("ref")
        elif token.lower().startswith("ref="):
            token = token.split("=", 1)[1]
        if token.lower().startswith(("type=", "mode=", "scope=", "src=", "dest=")):
            continue
        candidate = _artifact_container_image_url_candidate(
            token,
            require_explicit_registry=True,
        )
        if not candidate or candidate in seen:
            continue
        seen.add(candidate)
        values.append(candidate)
    return values


def _artifact_container_image_line_candidates(raw_line: str) -> list[str]:
    line = str(raw_line or "").strip()
    if not line or line.startswith("#"):
        return []
    dockerfile_match = re.match(r"(?i)^FROM\s+(?P<body>.+)$", line)
    if dockerfile_match:
        for token in dockerfile_match.group("body").split():
            if token.startswith("--"):
                continue
            candidate = _artifact_container_image_url_candidate(token)
            return [candidate] if candidate else []
        return []
    dockerfile_from_flag_candidates = _artifact_container_image_dockerfile_from_flag_candidates(
        line
    )
    if dockerfile_from_flag_candidates:
        return dockerfile_from_flag_candidates
    image_match = re.match(
        r"""(?ix)
        ^(?:-\s*)?
        ["']?
        (?:image|container_image|containerImage|image_name|imageName)
        ["']?
        \s*(?::|=)\s*
        (?P<value>.+?)
        \s*$
        """,
        line,
    )
    if image_match:
        candidate = _artifact_container_image_url_candidate(image_match.group("value"))
        return [candidate] if candidate else []
    repository_match = re.match(
        r"""(?ix)
        ^(?:-\s*)?
        ["']?
        (?:repository|container_repository|containerRepository|image_repository|imageRepository)
        ["']?
        \s*(?::|=)\s*
        (?P<value>.+?)
        \s*$
        """,
        line,
    )
    if repository_match:
        candidate = _artifact_container_image_url_candidate(
            repository_match.group("value"),
            require_explicit_registry=True,
        )
        return [candidate] if candidate else []
    oci_url_match = re.match(
        r"""(?ix)
        ^(?:-\s*)?
        ["']?
        (?:url|registry_url|registryUrl|repository_url|repositoryUrl|repo_url|repoUrl|chart_repository|chartRepository)
        ["']?
        \s*(?::|=)\s*
        (?P<value>oci://.+?)
        \s*$
        """,
        line,
    )
    if oci_url_match:
        candidate = _artifact_container_image_url_candidate(
            oci_url_match.group("value"),
            require_explicit_registry=True,
        )
        return [candidate] if candidate else []
    pull_match = re.match(
        r"""(?ix)
        ^(?:-\s*)?
        (?:docker|podman|nerdctl)
        \s+
        (?:image\s+)?
        pull
        \s+
        (?P<value>[^\s;&|]+)
        """,
        line,
    )
    if pull_match:
        candidate = _artifact_container_image_url_candidate(
            pull_match.group("value"),
            require_explicit_registry=True,
        )
        return [candidate] if candidate else []
    return []


def _artifact_container_image_dockerfile_from_flag_candidates(line: str) -> list[str]:
    text = str(line or "").strip()
    if not text:
        return []
    raw_values: list[str] = []
    if re.match(r"(?i)^(?:COPY|ADD)\s+", text):
        raw_values.extend(
            match.group("value")
            for match in re.finditer(r"--from=(?P<value>[^\s]+)", text, re.IGNORECASE)
        )
    if re.match(r"(?i)^RUN\s+", text):
        for mount_match in re.finditer(r"--mount=(?P<body>[^\s]+)", text, re.IGNORECASE):
            for part in mount_match.group("body").split(","):
                if part.lower().startswith("from="):
                    raw_values.append(part.split("=", 1)[1])
    values: list[str] = []
    seen: set[str] = set()
    for raw_value in raw_values:
        candidate = _artifact_container_image_url_candidate(
            raw_value,
            require_explicit_registry=True,
        )
        if not candidate or candidate in seen:
            continue
        seen.add(candidate)
        values.append(candidate)
    return values


def _artifact_container_image_url_candidate(
    value: str,
    *,
    require_explicit_registry: bool = False,
) -> str:
    raw = str(value or "").strip().strip(",")
    if not raw:
        return ""
    raw = raw.split("#", 1)[0].strip().strip("\"'")
    if not raw or raw.lower() in {"scratch", "none", "null"}:
        return ""
    if any(marker in raw for marker in ("${", "$(", "{{", "}}", "<", ">")):
        return ""
    lowered = raw.lower()
    if lowered.startswith("docker://"):
        raw = raw[len("docker://") :]
    elif lowered.startswith("docker-image://"):
        raw = raw[len("docker-image://") :]
    elif lowered.startswith("oci://"):
        raw = raw[len("oci://") :]
    elif "://" in raw:
        return ""
    raw = raw.strip().strip("\"'")
    if not raw or re.search(r"\s", raw):
        return ""

    image_ref = raw.split("@", 1)[0].strip("/")
    last_slash = image_ref.rfind("/")
    tag_colon = image_ref.rfind(":")
    if tag_colon > last_slash:
        image_ref = image_ref[:tag_colon]
    image_ref = image_ref.strip("/")
    if not image_ref:
        return ""

    parts = [part for part in image_ref.split("/") if part]
    if not parts:
        return ""
    registry = parts[0].lower()
    docker_registries = {
        "docker.io",
        "index.docker.io",
        "registry-1.docker.io",
    }
    has_explicit_registry = (
        "." in registry
        or ":" in registry
        or registry == "localhost"
        or registry in docker_registries
    )

    if has_explicit_registry:
        repository_parts = parts[1:]
        if not repository_parts:
            return ""
        repository = "/".join(repository_parts)
        if registry in docker_registries:
            if "/" not in repository:
                repository = f"library/{repository}"
            return _normalize_artifact_text_url(
                f"https://hub.docker.com/r/{quote(repository, safe='/._-+~')}"
            )
        if registry == "quay.io":
            return _normalize_artifact_text_url(
                f"https://quay.io/repository/{quote(repository, safe='/._-+~')}"
            )
        return _normalize_artifact_text_url(
            f"https://{registry}/{quote(repository, safe='/._-+~')}"
        )

    if require_explicit_registry:
        return ""
    repository = image_ref if "/" in image_ref else f"library/{image_ref}"
    return _normalize_artifact_text_url(
        f"https://hub.docker.com/r/{quote(repository, safe='/._-+~')}"
    )


def _artifact_templated_container_image_url_candidate(
    value: str,
    *,
    require_explicit_registry: bool = False,
) -> str:
    raw = str(value or "").strip().strip(",").strip("\"'")
    if not raw:
        return ""
    if "{{" in raw or "}}" in raw:
        raw = raw.split("{{", 1)[0].strip().rstrip(":-_./@")
    return _artifact_container_image_url_candidate(
        raw,
        require_explicit_registry=require_explicit_registry,
    )


def _artifact_package_url_registry_candidate(package_type: str, body: str) -> str:
    candidate = package_url_registry_candidate(package_type, body)
    return _normalize_artifact_text_url(candidate) if candidate else ""


def _extract_artifact_ip_seeds(text: str) -> list[tuple[str, str]]:
    candidates: list[str] = []
    seen_candidates: set[str] = set()
    markup_normalized_text = re.sub(r"</?[^>]+>", " ", text)

    for match in _ARTIFACT_IPV4_RE.finditer(text):
        candidate = str(match.group(0) or "").strip()
        if candidate and candidate not in seen_candidates:
            seen_candidates.add(candidate)
            candidates.append(candidate)

    for token in re.split(r"\s+", markup_normalized_text):
        candidate = str(token or "").strip()
        candidate = candidate.strip("[](){}<>,;\"'")
        if not candidate or "://" in candidate or candidate.count(":") < 2:
            continue
        candidate = candidate.rstrip(".")
        if candidate and candidate not in seen_candidates:
            seen_candidates.add(candidate)
            candidates.append(candidate)

    seed_entries = ArtifactQueueProcessor._run_ordered_static_batch(
        candidates,
        _artifact_ip_seed_entry,
        default_factory=lambda: None,
    )
    values: list[tuple[str, str]] = []
    seen_values: set[tuple[str, str]] = set()
    for seed_entry in seed_entries:
        if not seed_entry:
            continue
        if seed_entry in seen_values:
            continue
        seen_values.add(seed_entry)
        values.append(seed_entry)
    return values


def _artifact_ip_seed_entry(candidate: str) -> tuple[str, str] | None:
    try:
        parsed_ip = ipaddress.ip_address(str(candidate or "").strip())
    except ValueError:
        return None
    normalized = str(parsed_ip)
    if _is_placeholder_host_ip(normalized):
        return None
    seed_type = "ipv6" if parsed_ip.version == 6 else "ipv4"
    return normalized, seed_type


