def _artifact_member_scan_byte_limit(member_name: str) -> int:
    suffix = Path(str(member_name or "").lower()).suffix
    if suffix in _OCR_IMAGE_SUFFIXES:
        return _MAX_OCR_IMAGE_BYTES
    if suffix in _HAR_SUFFIXES:
        return _MAX_HAR_BYTES
    return _MAX_ARTIFACT_MEMBER_BYTES


