def _cache_prefixed_special_text_config_name(name: str) -> str:
    match = re.fullmatch(r"\d+-(.+)", str(name or "").strip().lower())
    if not match:
        return ""
    candidate = match.group(1)
    if candidate in _CACHE_PREFIXED_SPECIAL_TEXT_CONFIG_NAMES:
        return candidate
    return ""


def _special_text_config_route_label(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    parsed = urlparse(text)
    raw_path = parsed.path if parsed.scheme or parsed.netloc else text
    normalized = unquote(str(raw_path or "")).replace("\\", "/").strip().strip("/").lower()
    if not normalized:
        return ""
    if parsed.scheme in {"http", "https"} and normalized in _EXACT_REMOTE_TEXT_CONFIG_ROUTE_LABELS:
        return _EXACT_REMOTE_TEXT_CONFIG_ROUTE_LABELS[normalized]
    for suffix, label in _SPECIAL_TEXT_CONFIG_ROUTE_LABELS.items():
        if normalized.endswith(suffix):
            return label
    return ""


