def _scheduler_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = tuple(part for part in normalized.split("/") if part)
    name = parts[-1] if parts else Path(normalized).name
    if not name or name in {"readme", "readme.md", "license"}:
        return ""
    suffix = Path(name).suffix.lower()
    if name in _SCHEDULER_CONFIG_NAMES or suffix == ".cron":
        return "cron-config"
    if name.startswith("crontab.") and suffix in {"", ".conf", ".cron", ".txt"}:
        return "cron-config"
    parent_segments = set(parts[:-1])
    if parent_segments & _SCHEDULER_CONFIG_PARENT_SEGMENTS:
        if suffix in {"", ".conf", ".cron", ".env", ".sh", ".bash", ".txt"}:
            return "cron-config"
    if len(parts) >= 3 and parts[-3:-1] == ("spool", "cron") and suffix in {"", ".conf", ".txt"}:
        return "cron-config"
    return ""


