def _ai_agent_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = tuple(part for part in normalized.split("/") if part)
    name = parts[-1] if parts else ""
    if not name:
        return ""

    if (
        name in {".mcp.json", "mcp.json", "mcp.yaml", "mcp.yml", "mcp.toml"}
        or normalized.endswith("/.cursor/mcp.json")
        or normalized.endswith("/.vscode/mcp.json")
    ):
        return "mcp-config"
    if name in {"claude_desktop_config.json", "claude-desktop-config.json"}:
        return "claude-desktop-config"
    if name in {".claude.json", "claude.json"} or normalized.endswith("/.claude/settings.json"):
        return "claude-config"
    if (
        name in {".cursorrules", "cursorrules"}
        or normalized.endswith("/.cursor/rules")
        or "/.cursor/rules/" in f"/{normalized}/"
    ):
        return "cursor-rules"
    if (
        name in {".windsurfrules", "windsurfrules", "windsurf.rules", "windsurf_rules"}
        or normalized.endswith("/.windsurf/rules")
        or "/.windsurf/rules/" in f"/{normalized}/"
    ):
        return "windsurf-rules"
    if name in {".continue.json", "continue.json"} or (
        "/.continue/" in f"/{normalized}/"
        and name in {"config.json", "config.yaml", "config.yml", "config.ts"}
    ):
        return "continue-config"
    if name in {
        ".aider.conf",
        ".aider.conf.yml",
        ".aider.conf.yaml",
        "aider.conf",
        "aider.conf.yml",
        "aider.conf.yaml",
    }:
        return "aider-config"
    if name == "codex.toml" or ("/.codex/" in f"/{normalized}/" and name == "config.toml"):
        return "codex-config"
    if name in {"agents.md", "agent.md"}:
        return "agents-md"
    return ""


def _observability_text_config_artifact_label(value: str) -> str:
    raw_value = str(value or "").strip().replace("\\", "/").lower()
    name = Path(raw_value).name
    if not name:
        return ""
    if re.fullmatch(r"prometheus(?:[-_.](?:config|rules|scrape))?\.(?:ya?ml|json)", name):
        return "prometheus-config"
    if re.fullmatch(r"alertmanager(?:[-_.]config)?\.(?:ya?ml|json)", name):
        return "alertmanager-config"
    if re.fullmatch(r"(?:otel|otelcol|otel-collector)(?:[-_.]config)?\.(?:ya?ml|json)", name):
        return "otel-config"
    if re.fullmatch(r"(?:loki|tempo|grafana)(?:[-_.]config)?\.(?:ya?ml|json|ini)", name):
        return f"{name.split('.', 1)[0].split('-', 1)[0]}-config"
    if name in {"datasource.yaml", "datasource.yml", "datasources.yaml", "datasources.yml"}:
        path_segments = {segment for segment in raw_value.split("/") if segment}
        if "grafana" in path_segments:
            return "grafana-config"
    return ""


def _edge_proxy_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = [part for part in normalized.split("/") if part]
    name = parts[-1] if parts else ""
    if not name:
        return ""
    segments = set(parts[:-1])

    if name == "caddyfile":
        return "caddyfile"
    if name in {"nginx.conf", "nginx-default.conf"}:
        return "nginx-config"
    if "nginx" in segments and (
        name.endswith(".conf")
        or name
        in {
            "fastcgi_params",
            "proxy_params",
            "scgi_params",
            "uwsgi_params",
        }
    ):
        return "nginx-config"
    if {"sites-enabled", "sites-available"} & segments and name.endswith(".conf"):
        return "nginx-config"
    if name in {"httpd.conf", "apache2.conf"}:
        return "apache-config"
    if {"apache", "apache2", "httpd"} & segments and (
        name.endswith(".conf") or name in {"proxy_params"}
    ):
        return "apache-config"
    if name in {"haproxy.cfg", "haproxy.conf"} or ("haproxy" in segments and name.endswith((".cfg", ".conf"))):
        return "haproxy-config"
    if name in {"traefik.yml", "traefik.yaml", "traefik.toml", "traefik.json"} or (
        "traefik" in segments and name.endswith((".yml", ".yaml", ".toml", ".json"))
    ):
        return "traefik-config"
    if name in {"envoy.yml", "envoy.yaml", "envoy.json"} or (
        "envoy" in segments and name.endswith((".yml", ".yaml", ".json"))
    ):
        return "envoy-config"
    if name in {"kong.yml", "kong.yaml", "kong.json", "kong.conf"} or (
        "kong" in segments and name.endswith((".yml", ".yaml", ".json", ".conf"))
    ):
        return "kong-config"
    return ""


def _container_orchestration_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = [part for part in normalized.split("/") if part]
    name = parts[-1] if parts else ""
    if not name:
        return ""
    segments = set(parts[:-1])
    suffix = Path(name).suffix.lower()
    stem = name[: -len(suffix)] if suffix else name

    if name in {
        "docker-compose.yml",
        "docker-compose.yaml",
        "docker-compose.override.yml",
        "docker-compose.override.yaml",
        "compose.yml",
        "compose.yaml",
        "compose.override.yml",
        "compose.override.yaml",
    }:
        return "docker-compose"
    if re.fullmatch(
        r"(?:docker-compose|compose)\.(?:dev|prod|production|staging|test|local|override)\.ya?ml",
        name,
    ):
        return "docker-compose"
    if name == "chart.yaml":
        return "helm-chart"
    if name == "chart.lock":
        return "helm-lock"
    if name in {"values.yaml", "values.yml"} and (
        segments & {"chart", "charts", "helm"} or _looks_like_packaged_helm_values_path(parts)
    ):
        return "helm-values"
    if name in {"helmfile", "helmfile.yaml", "helmfile.yml"}:
        return "helmfile"
    if name in {"kustomization", "kustomization.yaml", "kustomization.yml"}:
        return "kustomization"
    if name in {"kptfile", "kptfile.yaml", "kptfile.yml"}:
        return "kptfile"
    if name in {"skaffold", "skaffold.yaml", "skaffold.yml"}:
        return "skaffold"
    if name in {"nomad.hcl", "job.nomad", "job.nomad.hcl"}:
        return "nomad-job"
    if name.endswith(".nomad") or name.endswith(".nomad.hcl"):
        return "nomad-job"
    if suffix == ".hcl" and ("nomad" in stem or "nomad" in segments):
        return "nomad-job"
    if _looks_like_kubeconfig_text_config_artifact_name(normalized):
        return "kubeconfig"

    kubernetes_segments = {
        "chart",
        "charts",
        "deploy",
        "deployment",
        "helm",
        "k8s",
        "kubernetes",
        "manifests",
        "templates",
    }
    kubernetes_names = {
        "daemonset",
        "deployment",
        "destinationrule",
        "gateway",
        "httproute",
        "ingress",
        "service",
        "statefulset",
        "virtualservice",
    }
    if suffix in {".yaml", ".yml", ".json"} and (
        stem in kubernetes_names or bool(segments & kubernetes_segments)
    ):
        return "kubernetes-manifest"
    return ""


def _looks_like_packaged_helm_values_path(parts: list[str]) -> bool:
    if len(parts) < 3 or parts[-1] not in {"values.yaml", "values.yml"}:
        return False
    return any(part.endswith((".tgz", ".tar.gz")) for part in parts[:-2])


