def _api_spec_config_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    name = Path(normalized).name
    if not name:
        return ""
    if name in {"api-docs", "api_docs", "v3-api-docs", "v3_api_docs"}:
        return "openapi"
    if name in {"openapi", "swagger", "asyncapi", "arazzo"}:
        return name
    if name in {"api-blueprint", "api_blueprint", "apiary"}:
        return "api-blueprint"
    if name.endswith((".apib", ".api-blueprint", ".api_blueprint")):
        return "api-blueprint"
    if name.endswith(".arazzo"):
        return "arazzo"
    if name in {"openapi-overlay", "openapi_overlay"}:
        return "openapi-overlay"
    if name.endswith((".openapi-overlay", ".openapi_overlay")):
        return "openapi-overlay"
    for spec_label in ("openapi", "swagger", "asyncapi"):
        if name.endswith(f".{spec_label}"):
            return spec_label
    stem = name
    for suffix in (".json", ".jsonc", ".yaml", ".yml"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
            break
    if stem in {"api-docs", "api_docs", "v3-api-docs", "v3_api_docs"}:
        return "openapi"
    if stem in {"api-blueprint", "api_blueprint", "apiary"}:
        return "api-blueprint"
    if stem in {"arazzo", "arazzo-spec", "arazzo_spec"}:
        return "arazzo"
    if stem in {"openapi-overlay", "openapi_overlay", "openapi-overlay-spec", "openapi_overlay_spec"}:
        return "openapi-overlay"
    if stem == "overlay" and any(part in normalized for part in ("openapi", "oas")):
        return "openapi-overlay"
    if stem in {"openapi", "openapi-spec", "openapi_spec", "swagger", "asyncapi"}:
        return "openapi" if stem.startswith("openapi") else stem
    return ""


