def _iac_manifest_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    parts = tuple(part for part in normalized.split("/") if part)
    name = parts[-1] if parts else ""
    if _looks_like_terragrunt_config_name(normalized):
        return "terragrunt"
    if _looks_like_terraform_backend_config_name(normalized):
        return "terraform-backend"
    if name.endswith((".tfvars", ".tfvars.json", ".tfvars.jsonc", ".auto.tfvars", ".auto.tfvars.json")):
        return "terraform-variables"
    if name.endswith((".tf", ".tf.json")):
        return "terraform"
    if name.endswith((".tofu", ".tofu.json")):
        return "opentofu"
    if name.endswith(
        (
            ".pkrvars.hcl",
            ".pkrvars.json",
            ".auto.pkrvars.hcl",
            ".auto.pkrvars.json",
        )
    ):
        return "packer-variables"
    if name.endswith((".pkr.hcl", ".pkr.json")) or name == "packer.json":
        return "packer-template"
    stem = name
    for suffix in (".yaml", ".yml", ".json", ".toml"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
            break

    if name in {"pulumi.yaml", "pulumi.yml", "pulumi.json"} or stem == "pulumi":
        return "pulumi-project"
    if re.fullmatch(r"pulumi\.[a-z0-9_.\-]+", stem):
        return "pulumi-stack"
    if name == "serverless" or stem == "serverless":
        return "serverless"
    sst_config_label = sst_config_artifact_label(normalized)
    if sst_config_label:
        return sst_config_label
    aws_cdk_label = aws_cdk_artifact_label(normalized)
    if aws_cdk_label:
        return aws_cdk_label
    if name == "samconfig.toml" or stem in {"sam", "samconfig"}:
        return "sam-config"
    if stem in {"cloudformation", "cloudformation-template"} or name.endswith(".cfn"):
        return "cloudformation"
    if name in {"template.yaml", "template.yml", "template.json"}:
        if any(part in {"sam", "aws-sam"} for part in parts):
            return "sam-template"
        if any("cloudformation" in part for part in parts):
            return "cloudformation"
    return ""


def _dependency_manifest_artifact_label(value: str) -> str:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return ""
    name = normalized.rsplit("/", 1)[-1]
    exact_labels = {
        "package.json": "npm-package-manifest",
        "package-lock.json": "npm-package-lock",
        "npm-shrinkwrap.json": "npm-shrinkwrap",
        "yarn.lock": "yarn-lock",
        "pnpm-lock.yaml": "pnpm-lock",
        "pnpm-lock.yml": "pnpm-lock",
        "bun.lock": "bun-lock",
        "bun.lockb": "bun-lockb",
        "pipfile": "pipfile",
        "pipfile.lock": "pipfile-lock",
        "pdm.lock": "pdm-lock",
        "poetry.lock": "poetry-lock",
        "uv.lock": "uv-lock",
        "pyproject.toml": "pyproject",
        "setup.cfg": "python-setup-config",
        "requirements": "python-requirements",
        "constraints": "python-constraints",
        "cargo.lock": "cargo-lock",
        "cargo.toml": "cargo-manifest",
        "go.mod": "go-mod",
        "go.sum": "go-sum",
        "go.work": "go-work",
        "composer.json": "composer-manifest",
        "composer.lock": "composer-lock",
        "gemfile": "bundler-gemfile",
        "gemfile.lock": "bundler-lock",
        "podfile": "cocoapods-podfile",
        "podfile.lock": "cocoapods-lock",
        "cartfile": "carthage-cartfile",
        "cartfile.resolved": "carthage-resolved",
        "package.resolved": "swift-package-resolved",
        "gradle.lockfile": "gradle-lockfile",
    }
    if name in exact_labels:
        return exact_labels[name]
    if re.fullmatch(r"requirements(?:[-_.][a-z0-9_.-]+)?\.txt", name):
        return "python-requirements"
    if re.fullmatch(r"constraints(?:[-_.][a-z0-9_.-]+)?\.txt", name):
        return "python-constraints"
    if re.fullmatch(r"requirements(?:[-_.][a-z0-9_.-]+)?\.in", name):
        return "python-requirements-input"
    if name.endswith(".gemspec"):
        return "ruby-gemspec"
    if name.endswith(".podspec"):
        return "cocoapods-podspec"
    if name.endswith(".cabal"):
        return "cabal"
    if name.endswith(".opam"):
        return "opam"
    return ""


def _looks_like_browser_binary_string_artifact_name(value: str) -> bool:
    lowered = Path(str(value or "").strip().replace("\\", "/")).name.lower()
    return re.fullmatch(r"webcachev\d+\.dat", lowered) is not None


def _react_native_artifact_basename(value: str | Path) -> str:
    return str(value or "").strip().replace("\\", "/").rsplit("/", 1)[-1].lower()


def _looks_like_react_native_js_bundle_name(value: str | Path) -> bool:
    lowered = _react_native_artifact_basename(value)
    if not lowered:
        return False
    return (
        lowered.endswith(".jsbundle")
        or lowered.endswith(".android.bundle")
        or lowered.endswith(".ios.bundle")
    )


def _looks_like_hermes_bytecode_bundle_name(value: str | Path) -> bool:
    lowered = _react_native_artifact_basename(value)
    return bool(lowered) and lowered.endswith(".hbc")


def _looks_like_react_native_bundle_artifact_name(value: str | Path) -> bool:
    return _looks_like_react_native_js_bundle_name(
        value
    ) or _looks_like_hermes_bytecode_bundle_name(value)


def _looks_like_ssh_text_artifact_name(value: str) -> bool:
    lowered = Path(str(value or "").strip().replace("\\", "/")).name.lower()
    if not lowered:
        return False
    if lowered in _SSH_TEXT_ARTIFACT_NAMES:
        return True
    return any(lowered.startswith(f"{name}.") for name in _SSH_TEXT_ARTIFACT_NAMES)


def _looks_like_container_image_json_path(value: str) -> bool:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    if not normalized:
        return False
    name = normalized.rsplit("/", 1)[-1]
    if name in {"oci-layout", "index.json", "manifest.json", "repositories"}:
        return True
    return _looks_like_container_image_blob_path(normalized)


def _looks_like_container_image_blob_path(value: str) -> bool:
    normalized = str(value or "").strip().replace("\\", "/").strip("/").lower()
    return re.search(r"(?:^|/)blobs/sha256/[a-f0-9]{64}$", normalized) is not None


def _container_image_json_has_hint(value: Any) -> bool:
    if isinstance(value, dict):
        keys = {str(key or "").strip() for key in value}
        if keys & {
            "architecture",
            "config",
            "container_config",
            "history",
            "layers",
            "manifests",
            "mediaType",
            "os",
            "rootfs",
            "schemaVersion",
        }:
            return True
        config = value.get("config")
        if isinstance(config, dict):
            config_keys = {str(key or "").strip() for key in config}
            if config_keys & {"Cmd", "Entrypoint", "Env", "ExposedPorts", "Labels", "WorkingDir"}:
                return True
        return False
    if isinstance(value, list):
        return any(_container_image_json_has_hint(item) for item in value[:8])
    return False


def _looks_like_container_image_json_payload(data: bytes) -> bool:
    bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES].lstrip()
    if not bounded or bounded[:1] not in {b"{", b"["}:
        return False
    text = ArtifactQueueProcessor._decode_text_artifact_bytes(bounded)
    if not text:
        return False
    return _container_image_json_has_hint(_safe_json_loads(text))


