def _classify_artifact_name(value: str | Path) -> str | None:
    path = Path(str(value or "").strip())
    suffix = path.suffix.lower()
    if suffix in {".apk", ".aab"}:
        return "apk"
    if suffix == ".ipa":
        return "ipa"
    if _looks_text_config_name(str(path)):
        return "config"
    if (
        suffix in _SQLITE_DATABASE_SUFFIXES
        or _looks_like_browser_sqlite_artifact_name(path.name)
        or _looks_like_browser_binary_string_artifact_name(path.name)
        or windows_registry_hive_artifact_label(str(value or ""))
    ):
        return "document"
    if (
        suffix == ".pdf"
        or suffix in _PCAP_SUFFIXES
        or suffix == ".eml"
        or suffix == ".emlx"
        or suffix == ".mbox"
        or suffix in _MIME_ARCHIVE_SUFFIXES
        or suffix == ".svg"
        or suffix in _BINARY_STRING_ARTIFACT_SUFFIXES
        or suffix in _OCR_IMAGE_SUFFIXES
        or suffix in _OPENXML_DOCUMENT_SUFFIXES
        or suffix in _LEGACY_DOCUMENT_SUFFIXES
    ):
        return "document"
    if suffix in _ARCHIVE_SUFFIXES:
        return "archive"
    return None


def _classify_remote_artifact_url(raw_url: str, seed_type: str | None = None) -> str | None:
    normalized_seed_type = str(seed_type or "").strip().lower()
    if _special_text_config_route_label(raw_url):
        return "config"
    parsed_remote = urlparse(raw_url)
    if feed_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if json_feed_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if opensearch_description_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if saml_metadata_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if package_manager_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if windows_registry_hive_artifact_label(unquote(parsed_remote.path or "")):
        return "document"
    if connection_client_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if database_client_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if storage_client_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if amplify_client_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if ecs_task_definition_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if lambda_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if aws_app_runner_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if framework_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if orm_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if tunnel_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if _ai_agent_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_cloud_init_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_os_installer_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_os_package_repo_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _scheduler_config_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if _api_client_collection_artifact_label(unquote(parsed_remote.path or "")) == "pact-contract":
        return "config"
    if _looks_like_kubeconfig_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _kubernetes_secret_manifest_artifact_label(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_gcloud_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_aws_cli_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_azure_cli_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_oci_cli_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_rclone_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_kopia_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_borg_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if _looks_like_duplicacy_preferences_text_config_artifact_name(unquote(parsed_remote.path or "")):
        return "config"
    if normalized_seed_type == "apk_url":
        for candidate in _remote_artifact_name_candidates(raw_url):
            artifact_type = _classify_artifact_name(candidate)
            if artifact_type is not None:
                return artifact_type
        return "apk"
    for candidate in _remote_artifact_name_candidates(raw_url):
        artifact_type = _classify_artifact_name(candidate)
        if artifact_type is not None:
            return artifact_type
    return None


def _classify_remote_artifact_candidate(
    raw_url: str,
    seed_type: str | None = None,
    *,
    content_disposition: str = "",
    content_type: str = "",
    download_filename: str = "",
) -> str | None:
    artifact_type = _classify_remote_artifact_url(raw_url, seed_type)
    if artifact_type is not None:
        return artifact_type

    candidate_names: list[str] = []
    if download_filename:
        candidate_names.append(download_filename)
    candidate_names.extend(
        _remote_artifact_name_candidates(
            raw_url,
            content_disposition=content_disposition,
        )
    )
    for candidate in candidate_names:
        artifact_type = _classify_artifact_name(candidate)
        if artifact_type is not None:
            return artifact_type

    suffix = _suffix_from_content_type(content_type)
    if suffix:
        return _classify_artifact_name(f"artifact{suffix}")
    return None


def default_local_artifact_roots(base_dir: Path | None = None) -> list[Path]:
    root = Path(base_dir) if base_dir is not None else Path.cwd()
    candidates: list[Path] = []
    seen: set[str] = set()
    for segments in _DEFAULT_LOCAL_ARTIFACT_ROOT_SEGMENTS:
        candidate = root.joinpath(*segments)
        key = candidate.resolve().as_posix().lower() if candidate.exists() else candidate.as_posix().lower()
        if key in seen:
            continue
        seen.add(key)
        candidates.append(candidate)
    return candidates


def _select_remote_artifact_filename(
    artifact_id: int,
    source_url: str,
    artifact_type: str,
    *,
    content_disposition: str = "",
    content_type: str = "",
) -> str:
    route_label = _special_text_config_route_label(source_url)
    if route_label:
        return route_label
    parsed_source = urlparse(source_url)
    feed_label = feed_artifact_label(unquote(parsed_source.path or ""))
    if feed_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and feed_artifact_label(candidate) and Path(candidate).suffix:
            return candidate
        return feed_label
    json_feed_label = json_feed_artifact_label(unquote(parsed_source.path or ""))
    if json_feed_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and json_feed_artifact_label(candidate):
            return candidate
        return "feed.json"
    opensearch_label = opensearch_description_artifact_label(unquote(parsed_source.path or ""))
    if opensearch_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and opensearch_description_artifact_label(candidate) and Path(candidate).suffix:
            return candidate
        return "opensearch.xml"
    saml_label = saml_metadata_artifact_label(unquote(parsed_source.path or ""))
    if saml_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and saml_metadata_artifact_label(candidate):
            return candidate
        return "saml-metadata.xml"
    package_manager_filename = package_manager_config_remote_filename(
        unquote(parsed_source.path or "")
    )
    if package_manager_filename:
        return package_manager_filename
    gradle_filename = gradle_text_config_remote_filename(unquote(parsed_source.path or ""))
    if gradle_filename:
        return gradle_filename
    if _looks_like_cloud_init_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_os_installer_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_os_package_repo_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _scheduler_config_artifact_label(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            if Path(candidate).suffix.lower() == ".cron" or candidate.lower() in _SCHEDULER_CONFIG_NAMES:
                return candidate
            return f"{candidate}.cron"
        return "crontab"
    if windows_registry_hive_artifact_label(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            if windows_registry_hive_artifact_label(candidate):
                return candidate
            return f"{candidate}.reghive"
        return "windows-registry-hive.reghive"
    if _api_client_collection_artifact_label(unquote(parsed_source.path or "")) == "pact-contract":
        return pact_contract_remote_filename(
            unquote(parsed_source.path or ""),
            _suffix_from_content_type(content_type),
        )
    connection_client_label = connection_client_config_artifact_label(unquote(parsed_source.path or ""))
    if connection_client_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and connection_client_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{connection_client_label}"
        return f"connection-client.{connection_client_label}"
    database_client_label = database_client_config_artifact_label(unquote(parsed_source.path or ""))
    if database_client_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and database_client_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{database_client_label}"
        return f"database-client.{database_client_label}"
    storage_client_label = storage_client_config_artifact_label(unquote(parsed_source.path or ""))
    if storage_client_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and storage_client_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{storage_client_label}"
        return f"storage-client.{storage_client_label}"
    amplify_client_label = amplify_client_config_artifact_label(unquote(parsed_source.path or ""))
    if amplify_client_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and amplify_client_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{amplify_client_label}"
        return f"amplify-client.{amplify_client_label}"
    ecs_task_label = ecs_task_definition_artifact_label(unquote(parsed_source.path or ""))
    if ecs_task_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and ecs_task_definition_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{ecs_task_label}"
        return f"ecs-task.{ecs_task_label}"
    lambda_label = lambda_config_artifact_label(unquote(parsed_source.path or ""))
    if lambda_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and lambda_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{lambda_label}"
        return f"lambda.{lambda_label}"
    aws_app_runner_label = aws_app_runner_artifact_label(unquote(parsed_source.path or ""))
    if aws_app_runner_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and aws_app_runner_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{aws_app_runner_label}"
        return f"aws-app-runner.{aws_app_runner_label}"
    framework_config_label = framework_config_artifact_label(unquote(parsed_source.path or ""))
    if framework_config_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and framework_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{framework_config_label}"
        return f"framework-config.{framework_config_label}"
    orm_config_label = orm_config_artifact_label(unquote(parsed_source.path or ""))
    if orm_config_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and orm_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{orm_config_label}"
        return f"orm-config.{orm_config_label}"
    tunnel_config_label = tunnel_config_artifact_label(unquote(parsed_source.path or ""))
    if tunnel_config_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and tunnel_config_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{tunnel_config_label}"
        return f"tunnel-client.{tunnel_config_label}"
    if _looks_like_kubeconfig_text_config_artifact_name(unquote(parsed_source.path or "")):
        return "kubeconfig"
    kubernetes_secret_label = _kubernetes_secret_manifest_artifact_label(unquote(parsed_source.path or ""))
    if kubernetes_secret_label:
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate and _kubernetes_secret_manifest_artifact_label(candidate):
            return candidate
        if candidate:
            return f"{candidate}.{kubernetes_secret_label}"
        return f"kubernetes-secret.{kubernetes_secret_label}"
    if _looks_like_gcloud_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_aws_cli_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_azure_cli_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_oci_cli_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_rclone_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    if _looks_like_kopia_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate:
            return candidate
    borg_kind = _borg_text_config_artifact_kind(unquote(parsed_source.path or ""))
    if borg_kind:
        if borg_kind == "repository_config":
            return "borg.repository.config"
        if borg_kind == "key_type":
            return "borg.key-type"
        return "borg.location"
    if _looks_like_duplicacy_preferences_text_config_artifact_name(unquote(parsed_source.path or "")):
        candidate = Path(unquote(parsed_source.path or "")).name.strip()
        if candidate.lower() == "preferences":
            return "duplicacy.preferences"
        if candidate:
            return candidate
    for candidate in _remote_artifact_name_candidates(
        source_url,
        content_disposition=content_disposition,
    ):
        if _classify_artifact_name(candidate) is not None:
            return candidate
    suffix = _suffix_from_content_type(content_type) or _default_remote_artifact_suffix(artifact_type)
    return f"artifact-{artifact_id}{suffix}"


