def _artifact_progress_snapshot(
    *,
    total: int,
    workers: int,
    completed: int,
    failed: int,
    started_at: float,
) -> dict[str, object]:
    total_items = max(0, int(total or 0))
    active_workers = max(1, int(workers or 1)) if total_items else 0
    finished = max(0, min(total_items, int(completed or 0)))
    failed_items = max(0, min(finished, int(failed or 0)))
    remaining = max(0, total_items - finished)
    running = 0 if remaining <= 0 else min(active_workers, remaining)
    pending = max(0, remaining - running)
    payload: dict[str, object] = {
        "total": total_items,
        "workers": active_workers,
        "running": running,
        "pending": pending,
        "queue_depth": pending,
        "completed": finished,
        "failed": failed_items,
        "eta_seconds": None,
    }
    if total_items and remaining <= 0:
        payload["eta_seconds"] = 0.0
    elif total_items and finished > 0:
        elapsed = max(0.0, time.perf_counter() - started_at)
        if elapsed > 0:
            payload["eta_seconds"] = round((elapsed / finished) * remaining, 1)
    return payload


class SeedRunTracker:
    def __init__(self, db_path: Path, engagement_id: int) -> None:
        self._db_path = db_path
        self._engagement_id = engagement_id

    @staticmethod
    def _now() -> str:
        return datetime.now(timezone.utc).isoformat(timespec="milliseconds")

    @staticmethod
    def _metadata_json(metadata: dict[str, Any] | None) -> str:
        return json.dumps(metadata or {}, sort_keys=True)

    def recover_abandoned_running_runs(
        self,
        *,
        error: str = "abandoned before explicit completion",
    ) -> int:
        completed_at = self._now()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            cur = con.execute(
                """
                UPDATE seed_runs
                SET status='failed',
                    error=CASE
                        WHEN error IS NULL OR error='' THEN ?
                        ELSE error
                    END,
                    completed_at=COALESCE(completed_at, ?)
                WHERE engagement_id=? AND status='running'
                """,
                (
                    error[:512],
                    completed_at,
                    self._engagement_id,
                ),
            )
            con.commit()
            return max(0, int(cur.rowcount or 0))
        finally:
            con.close()

    def start_run(
        self,
        seed_value: str,
        seed_type: str,
        loop_name: str,
        *,
        source: str = "orchestrator",
        depth: int = 0,
        confidence: float = 1.0,
        input_count: int = 1,
        metadata: dict[str, Any] | None = None,
    ) -> SeedRunHandle:
        seed_text = seed_value.strip()
        if not seed_text:
            raise ValueError("seed_value must not be empty")
        started_at = self._now()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.row_factory = sqlite3.Row
            seed_id = self._ensure_seed_id(
                con,
                seed_text,
                seed_type,
                source=source,
                depth=depth,
                confidence=confidence,
                metadata=metadata,
            )
            con.execute(
                """
                UPDATE engagement_seeds
                SET status=CASE
                        WHEN status='completed' THEN status
                        WHEN status='failed' THEN status
                        ELSE 'running'
                    END,
                    updated_at=?
                WHERE id=?
                """,
                (started_at, seed_id),
            )
            con.execute(
                """
                INSERT INTO seed_runs
                    (engagement_id, seed_id, loop_name, status, input_count, output_count, metadata_json, started_at)
                VALUES (?, ?, ?, 'running', ?, 0, ?, ?)
                """,
                (
                    self._engagement_id,
                    seed_id,
                    loop_name,
                    max(0, int(input_count)),
                    self._metadata_json(metadata),
                    started_at,
                ),
            )
            run_id = int(con.execute("SELECT last_insert_rowid()").fetchone()[0])
            con.commit()
        finally:
            con.close()
        return SeedRunHandle(run_id=run_id, seed_id=seed_id)

    def finish_run(
        self,
        handle: SeedRunHandle,
        *,
        status: str,
        output_count: int = 0,
        error: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        completed_at = self._now()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.execute(
                """
                UPDATE seed_runs
                SET status=?,
                    output_count=?,
                    error=?,
                    metadata_json=?,
                    completed_at=?
                WHERE id=? AND engagement_id=?
                """,
                (
                    status,
                    max(0, int(output_count)),
                    (error or "")[:512] or None,
                    self._metadata_json(metadata),
                    completed_at,
                    handle.run_id,
                    self._engagement_id,
                ),
            )
            if status == "completed":
                con.execute(
                    """
                    UPDATE engagement_seeds
                    SET status='completed', updated_at=?
                    WHERE id=?
                    """,
                    (completed_at, handle.seed_id),
                )
            elif status == "failed":
                con.execute(
                    """
                    UPDATE engagement_seeds
                    SET status=CASE
                            WHEN status='completed' THEN status
                            ELSE 'failed'
                        END,
                        updated_at=?
                    WHERE id=?
                    """,
                    (completed_at, handle.seed_id),
                )
            elif status == "skipped":
                con.execute(
                    """
                    UPDATE engagement_seeds
                    SET status=CASE
                            WHEN status IN ('pending', 'ignored', 'running') THEN 'ignored'
                            ELSE status
                        END,
                        updated_at=?
                    WHERE id=?
                    """,
                    (completed_at, handle.seed_id),
                )
            con.commit()
        finally:
            con.close()

    def _ensure_seed_id(
        self,
        con: sqlite3.Connection,
        seed_value: str,
        seed_type: str,
        *,
        source: str,
        depth: int,
        confidence: float,
        metadata: dict[str, Any] | None = None,
    ) -> int:
        row = con.execute(
            """
            SELECT id
            FROM engagement_seeds
            WHERE engagement_id=? AND seed_type=? AND seed_value=?
            """,
            (self._engagement_id, seed_type, seed_value),
        ).fetchone()
        if row is not None:
            return int(row[0])
        con.execute(
            """
            INSERT INTO engagement_seeds
                (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json, discovered_at, updated_at)
            VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)
            """,
            (
                self._engagement_id,
                seed_value,
                seed_type,
                source,
                max(0, int(depth)),
                float(confidence),
                self._metadata_json(metadata),
                self._now(),
                self._now(),
            ),
        )
        return int(con.execute("SELECT last_insert_rowid()").fetchone()[0])


class EngagementRunTracker:
    def __init__(self, db_path: Path, engagement_id: int) -> None:
        self._db_path = db_path
        self._engagement_id = engagement_id

    @staticmethod
    def _now() -> str:
        return datetime.now(timezone.utc).isoformat(timespec="milliseconds")

    @staticmethod
    def _metadata_json(metadata: dict[str, Any] | None) -> str:
        return json.dumps(metadata or {}, sort_keys=True)

    @staticmethod
    def _abandon_run(db_path: Path, engagement_id: int, run_id: int) -> None:
        completed_at = datetime.now(timezone.utc).isoformat(timespec="milliseconds")
        con = sqlite3.connect(db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.execute(
                """
                UPDATE engagement_runs
                SET status='failed',
                    error=CASE
                        WHEN error IS NULL OR error='' THEN 'abandoned before explicit completion'
                        ELSE error
                    END,
                    completed_at=COALESCE(completed_at, ?),
                    updated_at=?
                WHERE id=? AND engagement_id=? AND status='running'
                """,
                (
                    completed_at,
                    completed_at,
                    run_id,
                    engagement_id,
                ),
            )
            con.commit()
        finally:
            con.close()

    def start_run(
        self,
        *,
        run_kind: str = "kill_chain",
        seed_value: str | None = None,
        seed_type: str | None = None,
        seed_count: int = 0,
        max_iterations: int = 0,
        current_iteration: int = 0,
        resume_enabled: bool = False,
        dry_run: bool = False,
        attack_mode: bool = False,
        metadata: dict[str, Any] | None = None,
    ) -> EngagementRunHandle:
        started_at = self._now()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.execute(
                """
                INSERT INTO engagement_runs
                    (
                        engagement_id,
                        run_kind,
                        status,
                        seed_value,
                        seed_type,
                        seed_count,
                        max_iterations,
                        current_iteration,
                        resume_enabled,
                        dry_run,
                        attack_mode,
                        metadata_json,
                        started_at,
                        updated_at
                    )
                VALUES (?, ?, 'running', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    self._engagement_id,
                    run_kind,
                    seed_value.strip() if seed_value else None,
                    seed_type.strip() if seed_type else None,
                    max(0, int(seed_count)),
                    max(0, int(max_iterations)),
                    max(0, int(current_iteration)),
                    1 if resume_enabled else 0,
                    1 if dry_run else 0,
                    1 if attack_mode else 0,
                    self._metadata_json(metadata),
                    started_at,
                    started_at,
                ),
            )
            run_id = int(con.execute("SELECT last_insert_rowid()").fetchone()[0])
            con.commit()
        finally:
            con.close()
        handle = EngagementRunHandle(run_id=run_id)
        handle._finalizer = weakref.finalize(
            handle,
            self._abandon_run,
            self._db_path,
            self._engagement_id,
            run_id,
        )
        return handle

    def update_run(
        self,
        handle: EngagementRunHandle,
        *,
        current_iteration: int | None = None,
        status: str | None = None,
        error: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        updated_at = self._now()
        con = sqlite3.connect(self._db_path, timeout=0.2)
        try:
            con.execute("PRAGMA busy_timeout=200")
            apply_schema(con)
            run_migrations(con)
            con.execute(
                """
                UPDATE engagement_runs
                SET current_iteration=COALESCE(?, current_iteration),
                    status=COALESCE(?, status),
                    error=COALESCE(?, error),
                    metadata_json=COALESCE(?, metadata_json),
                    updated_at=?
                WHERE id=? AND engagement_id=?
                """,
                (
                    max(0, int(current_iteration)) if current_iteration is not None else None,
                    status,
                    (error or "")[:512] or None,
                    self._metadata_json(metadata) if metadata is not None else None,
                    updated_at,
                    handle.run_id,
                    self._engagement_id,
                ),
            )
            con.commit()
        except sqlite3.OperationalError as exc:
            if "database is locked" in str(exc).lower():
                return
            raise
        finally:
            con.close()

    def finish_run(
        self,
        handle: EngagementRunHandle,
        *,
        status: str,
        current_iteration: int | None = None,
        error: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        finalizer = getattr(handle, "_finalizer", None)
        completed_at = self._now()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.execute(
                """
                UPDATE engagement_runs
                SET status=?,
                    current_iteration=COALESCE(?, current_iteration),
                    error=?,
                    metadata_json=?,
                    completed_at=?,
                    updated_at=?
                WHERE id=? AND engagement_id=?
                """,
                (
                    status,
                    max(0, int(current_iteration)) if current_iteration is not None else None,
                    (error or "")[:512] or None,
                    self._metadata_json(metadata),
                    completed_at,
                    completed_at,
                    handle.run_id,
                    self._engagement_id,
                ),
            )
            con.commit()
            if finalizer is not None:
                finalizer.detach()
                handle._finalizer = None
            try:
                from forge.audit.manifest import write_run_audit_manifest  # noqa: PLC0415

                write_run_audit_manifest(
                    con,
                    db_path=Path(self._db_path),
                    engagement_id=self._engagement_id,
                    run_id=handle.run_id,
                )
                con.commit()
            except Exception:  # noqa: BLE001
                con.rollback()
                _LOG.exception(
                    "Failed to write run audit manifest for engagement_id=%s run_id=%s",
                    self._engagement_id,
                    handle.run_id,
                )
        finally:
            con.close()


