    _MAX_LOCAL_BATCH_WORKERS = 4

    def __init__(self, db_path: Path, engagement_id: int, depth_limit: int = 3) -> None:
        self._db_path = db_path
        self._engagement_id = engagement_id
        self._depth_limit = depth_limit

    @classmethod
    def _run_ordered_local_batch(
        cls,
        batch_items: Sequence[Any],
        worker: Callable[[Any], Any],
        *,
        default_factory: Callable[[], Any],
    ) -> list[Any]:
        items = list(batch_items)
        if not items:
            return []
        if len(items) == 1:
            try:
                return [worker(items[0])]
            except Exception:  # noqa: BLE001
                return [default_factory()]
        bounded_workers = min(cls._MAX_LOCAL_BATCH_WORKERS, len(items))
        ordered_results: list[Any | None] = [None] * len(items)
        with ThreadPoolExecutor(max_workers=bounded_workers) as executor:
            future_map = {
                executor.submit(worker, item): index
                for index, item in enumerate(items)
            }
            for future in as_completed(future_map):
                index = future_map[future]
                try:
                    ordered_results[index] = future.result()
                except Exception:  # noqa: BLE001
                    ordered_results[index] = default_factory()
        return [result if result is not None else default_factory() for result in ordered_results]

    def run(self) -> SynthesisSummary:
        summary = SynthesisSummary()
        con = sqlite3.connect(self._db_path)
        try:
            apply_schema(con)
            run_migrations(con)
            con.row_factory = sqlite3.Row
            self._backfill_scope_seeds(con)
            candidates = self._derive_candidates(con)
            seed_ids: dict[tuple[str, str], int] = self._load_seed_ids(con)

            for candidate in candidates:
                if candidate.depth > self._depth_limit:
                    continue
                key = (candidate.seed_type, candidate.seed_value)
                before = key in seed_ids
                seed_id = self._upsert_seed(con, candidate)
                seed_ids[key] = seed_id
                if not before:
                    summary.seeds_inserted += 1
                    summary.promoted_count += 1
                    summary.promoted_seeds.append(candidate.seed_value)
                if candidate.parent_value and candidate.parent_type:
                    parent_id = self._lookup_seed_id(
                        seed_ids,
                        candidate.parent_type,
                        candidate.parent_value,
                    )
                    if parent_id is not None:
                        if self._insert_relation(
                            con,
                            parent_id,
                            seed_id,
                            candidate.relation_type,
                            candidate.confidence,
                            candidate.metadata,
                        ):
                            summary.relations_inserted += 1

            summary.relations_inserted += self._insert_identity_conflict_relations(con)
            summary.corroborated_count = self._refresh_seed_confidence(con)
            summary.root_domains = self._collect_root_domains(con)
            con.commit()
        finally:
            con.close()
        return summary

    def _backfill_scope_seeds(self, con: sqlite3.Connection) -> None:
        row = con.execute(
            "SELECT scope_json FROM engagements WHERE id=?",
            (self._engagement_id,),
        ).fetchone()
        scope_entries: list[object] = []
        if row is not None and row[0]:
            scope_entries = self._scope_seed_entries(_safe_json_loads(str(row[0])) or [])
        scope_candidate_batches = self._run_ordered_local_batch(
            scope_entries,
            self._scope_seed_candidate,
            default_factory=lambda: None,
        )
        for candidate in scope_candidate_batches:
            if isinstance(candidate, SeedCandidate):
                self._upsert_seed(con, candidate)

    @staticmethod
    def _scope_seed_candidate(value: Any) -> SeedCandidate | None:
        text = str(value or "").strip()
        if not text:
            return None
        cleaned = text[2:] if text.startswith("*.") else text
        seed_type = _classify_seed_value(text)
        return SeedCandidate(
            seed_value=cleaned,
            seed_type=seed_type,
            source="scope",
            depth=0,
            confidence=1.0,
        )

    def _derive_candidates(self, con: sqlite3.Connection) -> list[SeedCandidate]:
        seed_depths = self._load_seed_depths(con)
        email_domain_roots = self._email_domain_promotion_roots(con)
        prepared_email_candidate_batches: list[list[SeedCandidate]] = []
        if _table_exists(con, "emails"):
            rows = con.execute(
                "SELECT email, source FROM emails WHERE engagement_id=?",
                (self._engagement_id,),
            ).fetchall()
            email_candidate_batches = self._run_ordered_local_batch(
                rows,
                lambda row: self._email_seed_candidates_from_row(
                    row,
                    seed_depths,
                    email_domain_roots,
                ),
                default_factory=list,
            )
            prepared_email_candidate_batches = self._run_ordered_local_batch(
                list(enumerate(email_candidate_batches)),
                self._derive_candidate_batch_entries,
                default_factory=list,
            )

        prepared_host_candidate_batches: list[list[SeedCandidate]] = []
        if _table_exists(con, "hosts"):
            rows = con.execute(
                """
                SELECT ip, hostname
                FROM hosts
                WHERE engagement_id=?
                """,
                (self._engagement_id,),
            ).fetchall()
            host_candidate_batches = self._run_ordered_local_batch(
                rows,
                lambda row: self._host_seed_candidates_from_row(row, seed_depths),
                default_factory=list,
            )
            prepared_host_candidate_batches = self._run_ordered_local_batch(
                list(enumerate(host_candidate_batches)),
                self._derive_candidate_batch_entries,
                default_factory=list,
            )

        prepared_artifact_candidate_batches: list[list[SeedCandidate]] = []
        if _table_exists(con, "artifact_queue"):
            rows = con.execute(
                """
                SELECT source_url, local_path, artifact_type
                FROM artifact_queue
                WHERE engagement_id=?
                """,
                (self._engagement_id,),
            ).fetchall()
            artifact_candidate_batches = self._run_ordered_local_batch(
                rows,
                lambda row: self._artifact_seed_candidates_from_row(row, seed_depths),
                default_factory=list,
            )
            prepared_artifact_candidate_batches = self._run_ordered_local_batch(
                list(enumerate(artifact_candidate_batches)),
                self._derive_candidate_batch_entries,
                default_factory=list,
            )

        social_profile_anchor_candidates = self._derive_social_profile_anchor_candidates(con, seed_depths)
        social_profile_candidates = self._derive_social_profile_candidates(con, seed_depths)
        username_profile_candidates = self._derive_username_profile_candidates(con, seed_depths)
        candidate_families = [
            prepared_email_candidate_batches,
            prepared_host_candidate_batches,
            prepared_artifact_candidate_batches,
            [social_profile_anchor_candidates],
            [social_profile_candidates],
            [username_profile_candidates],
        ]
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(candidate_families)),
            self._derive_candidate_family_entries,
            default_factory=list,
        )
        candidates: list[SeedCandidate] = []
        for family in prepared_candidate_families:
            candidates.extend(family)
        return candidates

    @staticmethod
    def _derive_candidate_batch_entries(
        batch_entry: tuple[int, Sequence[SeedCandidate]],
    ) -> list[SeedCandidate]:
        _batch_index, batch = batch_entry
        return [candidate for candidate in batch if isinstance(candidate, SeedCandidate)]

    @staticmethod
    def _derive_candidate_family_entries(
        family_entry: tuple[int, Sequence[Sequence[SeedCandidate]]],
    ) -> list[SeedCandidate]:
        _family_index, family_batches = family_entry
        candidates: list[SeedCandidate] = []
        for family_batch in family_batches:
            for candidate in family_batch:
                if isinstance(candidate, SeedCandidate):
                    candidates.append(candidate)
        return candidates

    def _email_seed_candidates_from_row(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
        eligible_domain_roots: set[str] | None = None,
    ) -> list[SeedCandidate]:
        email = str(row["email"] or "").lower().strip()
        if "@" not in email:
            return []
        local, domain = email.split("@", 1)
        email_depth = seed_depths.get(("email", email), 0)
        candidates = [
            SeedCandidate(
                seed_value=email,
                seed_type="email",
                source="discovered",
                depth=max(1, email_depth or 1),
                confidence=0.82,
            )
        ]
        username = local.strip(".-_")
        if len(username) >= 3:
            candidates.append(
                SeedCandidate(
                    seed_value=username,
                    seed_type="username",
                    source="cross_reference",
                    depth=min(self._depth_limit, max(1, email_depth) + 1),
                    confidence=0.72,
                    parent_value=email,
                    parent_type="email",
                    metadata={"rule": "email_local_part"},
                )
            )
        if self._email_domain_is_promotable(domain, eligible_domain_roots or set()):
            candidates.append(
                SeedCandidate(
                    seed_value=domain,
                    seed_type="domain",
                    source="cross_reference",
                    depth=min(self._depth_limit, max(1, email_depth) + 1),
                    confidence=0.68,
                    parent_value=email,
                    parent_type="email",
                    relation_type="related_asset",
                    metadata={"rule": "email_domain"},
                )
            )
        return candidates

    def _email_domain_promotion_roots(self, con: sqlite3.Connection) -> set[str]:
        roots = self._scope_domain_roots(con)
        roots.update(self._seed_domain_roots_for_email_promotion(con))
        roots.update(self._observed_domain_roots_for_email_promotion(con))
        return {root for root in roots if root}

    def _scope_domain_roots(self, con: sqlite3.Connection) -> set[str]:
        row = con.execute(
            "SELECT scope_json FROM engagements WHERE id=?",
            (self._engagement_id,),
        ).fetchone()
        if row is None or not row[0]:
            return set()
        scope_entries = self._scope_domainish_entries(_safe_json_loads(str(row[0])) or [])
        roots: set[str] = set()
        for entry in scope_entries:
            root = self._domainish_root(entry)
            if root:
                roots.add(root)
        return roots

    def _seed_domain_roots_for_email_promotion(self, con: sqlite3.Connection) -> set[str]:
        if not _table_exists(con, "engagement_seeds"):
            return set()
        roots: set[str] = set()
        seed_rows = con.execute(
            """
            SELECT seed_type, seed_value, source, metadata_json
            FROM engagement_seeds
            WHERE engagement_id=?
              AND seed_type IN ('domain','subdomain','url','apk_url')
            """,
            (self._engagement_id,),
        ).fetchall()
        for seed_row in seed_rows:
            if not self._seed_row_allows_email_domain_promotion(seed_row):
                continue
            root = self._domainish_root(seed_row["seed_value"], str(seed_row["seed_type"] or ""))
            if root:
                roots.add(root)
        return roots

    def _observed_domain_roots_for_email_promotion(self, con: sqlite3.Connection) -> set[str]:
        roots: set[str] = set()
        if _table_exists(con, "hosts"):
            for host_row in con.execute(
                """
                SELECT hostname
                FROM hosts
                WHERE engagement_id=?
                """,
                (self._engagement_id,),
            ).fetchall():
                root = self._domainish_root(host_row["hostname"])
                if root:
                    roots.add(root)
        if _table_exists(con, "crawl_results"):
            for crawl_row in con.execute(
                """
                SELECT url, final_url
                FROM crawl_results
                WHERE engagement_id=?
                """,
                (self._engagement_id,),
            ).fetchall():
                for value in (crawl_row["final_url"], crawl_row["url"]):
                    root = self._domainish_root(value, "url")
                    if root:
                        roots.add(root)
        if _table_exists(con, "artifact_queue"):
            for artifact_row in con.execute(
                """
                SELECT source_url
                FROM artifact_queue
                WHERE engagement_id=?
                """,
                (self._engagement_id,),
            ).fetchall():
                root = self._domainish_root(artifact_row["source_url"], "url")
                if root:
                    roots.add(root)
        return roots

    @staticmethod
    def _seed_row_allows_email_domain_promotion(seed_row: Any) -> bool:
        metadata = _safe_json_loads(str(seed_row["metadata_json"] or "{}"))
        metadata_dict = metadata if isinstance(metadata, dict) else {}
        rule = str(metadata_dict.get("rule") or "").strip()
        synthesis = metadata_dict.get("synthesis")
        corroborated = isinstance(synthesis, dict) and bool(synthesis.get("corroborated"))
        source = str(seed_row["source"] or "").strip().lower()
        if source in {"scope", "operator"}:
            return True
        return rule == "email_domain" and corroborated

    @staticmethod
    def _scope_domainish_entries(payload: object) -> list[object]:
        if isinstance(payload, list):
            return list(payload)
        if not isinstance(payload, dict):
            return []
        entries: list[object] = []
        for key in ("domains", "domain_allowlist"):
            value = payload.get(key)
            if value is None:
                continue
            entries.extend(value if isinstance(value, list) else [value])
        return entries

    @staticmethod
    def _scope_seed_entries(payload: object) -> list[object]:
        if isinstance(payload, list):
            return list(payload)
        if not isinstance(payload, dict):
            return []
        entries: list[object] = []
        for key in (
            "domains",
            "domain_allowlist",
            "urls",
            "url_prefixes",
            "seeds",
            "authorized_seeds",
            "allowed_seeds",
            "targets",
            "allowed_targets",
        ):
            value = payload.get(key)
            if value is None:
                continue
            entries.extend(value if isinstance(value, list) else [value])
        return entries

    @staticmethod
    def _domainish_root(value: object, seed_type: str = "") -> str:
        raw = str(value or "").strip()
        if not raw:
            return ""
        kind = str(seed_type or "").strip().lower()
        if kind == "email" or ("@" in raw and _classify_seed_value(raw) == "email"):
            return ""
        parsed = urlparse(raw)
        if parsed.scheme in {"http", "https"} and parsed.hostname:
            raw = str(parsed.hostname or "").strip().lower().strip(".")
        elif kind in {"url", "apk_url"}:
            return ""
        if raw.startswith("*."):
            raw = raw[2:]
        classified = kind or _classify_seed_value(raw)
        if classified not in {"domain", "subdomain"}:
            return ""
        return _normalize_root_domain(raw)

    @staticmethod
    def _email_domain_is_promotable(domain: str, eligible_domain_roots: set[str]) -> bool:
        normalized = str(domain or "").strip().lower().strip(".")
        if not normalized:
            return False
        root = _normalize_root_domain(normalized)
        for eligible in eligible_domain_roots:
            allowed = str(eligible or "").strip().lower().strip(".")
            if allowed.startswith("*."):
                allowed = allowed[2:]
            if not allowed:
                continue
            if normalized == allowed or root == allowed or normalized.endswith(f".{allowed}"):
                return True
        return False

    def _host_seed_candidates_from_row(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        host_ip = str(row["ip"] or "").strip().lower()
        hostname = str(row["hostname"] or "").lower().strip()
        candidates: list[SeedCandidate] = []
        if host_ip and not _is_placeholder_host_ip(host_ip):
            ip_seed_type = _classify_seed_value(host_ip)
            if ip_seed_type in {"ipv4", "ipv6"}:
                host_parent_type = _classify_seed_value(hostname) if hostname and hostname != host_ip else ""
                ip_depth = seed_depths.get(
                    (ip_seed_type, host_ip),
                    seed_depths.get((host_parent_type, hostname), 0) if host_parent_type else 0,
                )
                candidates.append(
                    SeedCandidate(
                        seed_value=host_ip,
                        seed_type=ip_seed_type,
                        source="discovered",
                        depth=max(1, ip_depth or 1),
                        confidence=0.76,
                        parent_value=hostname if host_parent_type else None,
                        parent_type=host_parent_type or None,
                        relation_type="related_asset",
                        metadata={"rule": "host_ip"},
                    )
                )
        if not hostname or hostname == host_ip:
            return candidates
        if "." not in hostname:
            return candidates
        root_domain = _normalize_root_domain(hostname)
        host_depth = seed_depths.get(("subdomain", hostname), seed_depths.get(("domain", root_domain), 0))
        candidates.append(
            SeedCandidate(
                seed_value=hostname,
                seed_type="subdomain",
                source="discovered",
                depth=max(1, host_depth or 1),
                confidence=0.78,
            )
        )
        candidates.append(
            SeedCandidate(
                seed_value=root_domain,
                seed_type="domain",
                source="cross_reference",
                depth=min(self._depth_limit, max(1, host_depth) + 1),
                confidence=0.66,
                parent_value=hostname,
                parent_type="subdomain",
                relation_type="related_asset",
                metadata={"rule": "hostname_root_domain"},
            )
        )
        return candidates

    def _artifact_seed_candidates_from_row(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        source_url = str(row["source_url"] or "").strip()
        local_path = str(row["local_path"] or "").strip()
        artifact_type = str(row["artifact_type"] or "").strip().lower()
        parsed = urlparse(source_url) if source_url else urlparse("")
        candidates: list[SeedCandidate] = []
        if source_url and parsed.scheme in {"http", "https"}:
            parent_type = (
                "apk_url"
                if (
                    _is_mobile_bundle_url(source_url)
                    or _is_mobile_bundle_path(local_path)
                    or artifact_type in {"apk", "ipa"}
                )
                else "url"
            )
            artifact_depth = seed_depths.get((parent_type, source_url), 0)
            candidates.append(
                SeedCandidate(
                    seed_value=source_url,
                    seed_type=parent_type,
                    source="artifact",
                    depth=max(1, artifact_depth or 1),
                    confidence=0.7,
                )
            )
            if parsed.hostname:
                hostname = str(parsed.hostname or "").strip().lower().strip(".")
                if hostname and not _is_social_platform_host(hostname) and not _is_managed_cloud_provider_host(hostname):
                    root_domain = _normalize_root_domain(hostname)
                    host_depth = min(self._depth_limit, max(1, artifact_depth) + 1)
                    if hostname != root_domain:
                        candidates.append(
                            SeedCandidate(
                                seed_value=hostname,
                                seed_type="subdomain",
                                source="artifact",
                                depth=host_depth,
                                confidence=0.66,
                                parent_value=source_url,
                                parent_type=parent_type,
                                relation_type="related_asset",
                                metadata={"rule": "artifact_host"},
                            )
                        )
                        candidates.append(
                            SeedCandidate(
                                seed_value=root_domain,
                                seed_type="domain",
                                source="artifact",
                                depth=min(self._depth_limit, host_depth + 1),
                                confidence=0.6,
                                parent_value=hostname,
                                parent_type="subdomain",
                                relation_type="related_asset",
                                metadata={"rule": "artifact_host_root_domain"},
                            )
                        )
                    else:
                        candidates.append(
                            SeedCandidate(
                                seed_value=root_domain,
                                seed_type="domain",
                                source="artifact",
                                depth=host_depth,
                                confidence=0.6,
                                parent_value=source_url,
                                parent_type=parent_type,
                                relation_type="related_asset",
                                metadata={"rule": "artifact_host"},
                            )
                        )
        if _is_mobile_bundle_path(local_path) and parsed.scheme not in {"http", "https"}:
            candidates.append(
                SeedCandidate(
                    seed_value=local_path,
                    seed_type="apk_url",
                    source="artifact",
                    depth=max(1, seed_depths.get(("apk_url", local_path), 1)),
                    confidence=0.74,
                )
            )
        return candidates

    def _derive_social_profile_anchor_candidates(
        self,
        con: sqlite3.Connection,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        if not _table_exists(con, "social_profiles"):
            return []
        columns = _table_columns(con, "social_profiles")
        if "email" not in columns:
            return []
        source_expr = "source" if "source" in columns else "'' AS source"
        if "source" not in columns and "platform" in columns:
            source_expr = "platform AS source"
        order_expr = "id ASC" if "id" in columns else "rowid ASC"
        rows = con.execute(
            f"""
            SELECT email, {source_expr}
            FROM social_profiles
            WHERE engagement_id=?
            ORDER BY {order_expr}
            """,
            (self._engagement_id,),
        ).fetchall()
        anchor_candidate_batches = self._run_ordered_local_batch(
            rows,
            lambda row: self._social_profile_anchor_seed_candidate(row, seed_depths),
            default_factory=lambda: None,
        )
        return [
            candidate
            for candidate in anchor_candidate_batches
            if isinstance(candidate, SeedCandidate)
        ]

    def _social_profile_anchor_seed_candidate(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> SeedCandidate | None:
        anchor_raw = str(row["email"] or "").strip()
        anchor_value, anchor_type = self._normalize_social_profile_anchor(anchor_raw)
        if not anchor_value or not anchor_type:
            return None
        if anchor_type not in {
            "apk_url",
            "company",
            "domain",
            "email",
            "ipv4",
            "ipv6",
            "name",
            "phone",
            "subdomain",
            "url",
            "username",
        }:
            return None
        if (
            anchor_type == "username"
            and not anchor_value.startswith("@")
            and ("username", anchor_value) not in seed_depths
            and ("username", f"@{anchor_value}") in seed_depths
        ):
            return None
        source_label = str(row["source"] or "social_profile").strip().lower() or "social_profile"
        existing_depth = self._lookup_seed_depth(seed_depths, anchor_type, anchor_value)
        return SeedCandidate(
            seed_value=anchor_value,
            seed_type=anchor_type,
            source="discovered",
            depth=max(1, existing_depth or 1),
            confidence=self._social_profile_anchor_confidence(anchor_type, source_label),
            metadata={
                "rule": "social_profile_anchor",
                "source": source_label,
            },
        )

    @staticmethod
    def _social_profile_anchor_confidence(anchor_type: str, source_label: str) -> float:
        source_text = str(source_label or "").strip().lower()
        if anchor_type == "email":
            return 0.82
        if anchor_type in {"domain", "subdomain", "url", "apk_url"}:
            return 0.74
        if anchor_type == "phone":
            return 0.73 if "phone" in source_text else 0.7
        if anchor_type in {"name", "company"}:
            return 0.72
        if anchor_type == "username":
            return 0.7
        return 0.68

    def _derive_social_profile_candidates(
        self,
        con: sqlite3.Connection,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        if not _table_exists(con, "social_profiles"):
            return []
        columns = _table_columns(con, "social_profiles")
        if {"email", "source", "profile_data"}.issubset(columns):
            rows = con.execute(
                """
                SELECT email, source, profile_data
                FROM social_profiles
                WHERE engagement_id=?
                ORDER BY id ASC
                """,
                (self._engagement_id,),
            ).fetchall()
            return self._social_profile_candidates_from_rows(rows, seed_depths)
        if {"email", "platform", "profile_url", "display_name"}.issubset(columns):
            rows = con.execute(
                """
                SELECT email, platform, profile_url, display_name
                FROM social_profiles
                WHERE engagement_id=?
                ORDER BY id ASC
                """,
                (self._engagement_id,),
            ).fetchall()
            legacy_row_batches = self._run_ordered_local_batch(
                rows,
                self._legacy_social_profile_candidate_row,
                default_factory=lambda: None,
            )
            legacy_rows = [
                legacy_row for legacy_row in legacy_row_batches if isinstance(legacy_row, dict)
            ]
            return self._social_profile_candidates_from_rows(legacy_rows, seed_depths)
        return []

    def _derive_username_profile_candidates(
        self,
        con: sqlite3.Connection,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        if not _table_exists(con, "username_profiles"):
            return []
        columns = _table_columns(con, "username_profiles")
        if not {"username", "platform", "profile_url", "status"}.issubset(columns):
            return []
        source_expr = "source_tool" if "source_tool" in columns else "'' AS source_tool"
        rows = con.execute(
            f"""
            SELECT username, platform, profile_url, status, {source_expr}
            FROM username_profiles
            WHERE engagement_id=?
            ORDER BY id ASC
            """,
            (self._engagement_id,),
        ).fetchall()
        candidate_batches = self._run_ordered_local_batch(
            rows,
            lambda row: self._username_profile_row_candidates(row, seed_depths),
            default_factory=list,
        )
        prepared_candidate_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._social_profile_candidate_batch_entries,
            default_factory=list,
        )
        candidates: list[SeedCandidate] = []
        seen: set[tuple[str, str, str | None, str | None]] = set()
        for batch in prepared_candidate_batches:
            for candidate in batch:
                key = (
                    candidate.seed_type,
                    candidate.seed_value,
                    candidate.parent_type,
                    candidate.parent_value,
                )
                if key in seen:
                    continue
                seen.add(key)
                candidates.append(candidate)
        return candidates

    def _username_profile_row_candidates(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        status = str(row["status"] or "").strip().upper()
        if status != "CONFIRMED":
            return []
        row_username = self._normalize_social_profile_handle_candidate(row["username"])
        if not row_username:
            return []
        platform = str(row["platform"] or "").strip().lower()
        source_tool = str(row["source_tool"] or "handle_finder").strip().lower() or "handle_finder"
        raw_profile_url = str(row["profile_url"] or "").strip()
        profile_url = self._social_profile_url_candidate(raw_profile_url)
        profile_handle = ""
        if profile_url:
            profile_handle = self._extract_social_profile_handle_from_url(profile_url)
        elif raw_profile_url:
            profile_handle = self._social_profile_handle_url_candidate(
                raw_profile_url,
                platform=platform,
            )
        if profile_url and self._profile_url_has_known_social_host(profile_url) and not profile_handle:
            return []
        if (
            raw_profile_url
            and not profile_url
            and self._profile_uri_has_known_social_app_scheme(raw_profile_url)
            and not profile_handle
        ):
            return []
        username = profile_handle or row_username
        username_depth = self._lookup_seed_depth(seed_depths, "username", username)
        metadata = {
            "rule": "username_profile",
            "platform": platform,
            "source": source_tool,
            "status": status,
        }
        if profile_url:
            metadata["profile_url"] = profile_url
        candidates = [
            SeedCandidate(
                seed_value=username,
                seed_type="username",
                source="cross_reference",
                depth=min(self._depth_limit, max(1, username_depth or 1)),
                confidence=0.74,
                metadata=metadata,
            )
        ]
        if profile_url:
            candidates.append(
                SeedCandidate(
                    seed_value=profile_url,
                    seed_type="url",
                    source="cross_reference",
                    depth=min(self._depth_limit, max(1, username_depth or 1) + 1),
                    confidence=0.7,
                    parent_value=username,
                    parent_type="username",
                    relation_type="derived_from",
                    metadata={
                        "rule": "username_profile_url",
                        "platform": platform,
                        "source": source_tool,
                        "status": status,
                    },
                )
            )
        return candidates

    @staticmethod
    def _profile_url_has_known_social_host(profile_url: str) -> bool:
        parsed = urlparse(str(profile_url or "").strip())
        hostname = str(parsed.hostname or "").strip().lower()
        return bool(hostname and _is_social_platform_host(hostname))

    @staticmethod
    def _profile_uri_has_known_social_app_scheme(profile_url: str) -> bool:
        parsed = urlparse(str(profile_url or "").strip())
        scheme = str(parsed.scheme or "").strip().lower()
        return scheme in {"instagram", "linkedin", "matrix", "nostr", "telegram", "tg", "twitter", "x"}

    @staticmethod
    def _legacy_social_profile_candidate_row(row: Any) -> dict[str, str] | None:
        payload = json.dumps(
            {
                "source": "epieos",
                "platform": str(row["platform"] or ""),
                "profile_url": str(row["profile_url"] or ""),
                "display_name": str(row["display_name"] or ""),
            }
        )
        return {
            "email": str(row["email"] or ""),
            "source": str(row["platform"] or "epieos"),
            "profile_data": payload,
        }

    def _social_profile_candidates_from_rows(
        self,
        rows: list[Any],
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        candidate_batches = self._run_ordered_local_batch(
            rows,
            lambda row: self._social_profile_row_candidates(row, seed_depths),
            default_factory=list,
        )
        prepared_candidate_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._social_profile_candidate_batch_entries,
            default_factory=list,
        )
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(prepared_candidate_batches)),
            self._social_profile_candidate_family_entries,
            default_factory=list,
        )
        prepared_dedupe_families = self._run_ordered_local_batch(
            list(enumerate(prepared_candidate_families)),
            self._social_profile_candidate_dedupe_family_entries,
            default_factory=list,
        )
        candidates: list[SeedCandidate] = []
        seen: set[tuple[str, str, str, str]] = set()
        for family in prepared_dedupe_families:
            for dedupe_entry in family:
                dedupe_key, candidate = dedupe_entry
                if dedupe_key in seen:
                    continue
                seen.add(dedupe_key)
                candidates.append(candidate)
        return candidates

    @staticmethod
    def _social_profile_candidate_batch_entries(
        batch_entry: tuple[int, Sequence[SeedCandidate]],
    ) -> list[SeedCandidate]:
        _batch_index, batch = batch_entry
        return [candidate for candidate in batch if isinstance(candidate, SeedCandidate)]

    @staticmethod
    def _social_profile_candidate_family_entries(
        family_entry: tuple[int, Sequence[SeedCandidate]],
    ) -> list[SeedCandidate]:
        _family_index, family = family_entry
        return [candidate for candidate in family if isinstance(candidate, SeedCandidate)]

    @staticmethod
    def _social_profile_candidate_dedupe_family_entries(
        family_entry: tuple[int, Sequence[SeedCandidate]],
    ) -> list[tuple[tuple[str, str, str, str], SeedCandidate]]:
        _family_index, family = family_entry
        prepared_entries: list[tuple[tuple[str, str, str, str], SeedCandidate]] = []
        for candidate in family:
            if not isinstance(candidate, SeedCandidate):
                continue
            prepared_entries.append(
                (
                    (
                        candidate.seed_type,
                        candidate.seed_value,
                        candidate.parent_type,
                        candidate.parent_value,
                    ),
                    candidate,
                )
            )
        return prepared_entries

    def _social_profile_row_candidates(
        self,
        row: Any,
        seed_depths: dict[tuple[str, str], int],
    ) -> list[SeedCandidate]:
        anchor_raw = str(row["email"] or "").strip()
        anchor_value, anchor_type = self._normalize_social_profile_anchor(anchor_raw)
        base_depth = self._lookup_seed_depth(seed_depths, anchor_type, anchor_value)
        profile_data = _safe_social_profile_json_loads(str(row["profile_data"] or "{}"))
        profile_entries = self._social_profile_payload_entries(
            profile_data,
            row_source=str(row["source"] or "social_profile"),
        )
        candidate_batches = self._run_ordered_local_batch(
            profile_entries,
            lambda profile: self._social_profile_profile_candidates(
                profile,
                row=row,
                anchor_value=anchor_value,
                anchor_type=anchor_type,
                base_depth=base_depth,
            ),
            default_factory=list,
        )
        prepared_candidate_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._social_profile_candidate_batch_entries,
            default_factory=list,
        )
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(prepared_candidate_batches)),
            self._social_profile_candidate_family_entries,
            default_factory=list,
        )
        candidates: list[SeedCandidate] = []
        for family in prepared_candidate_families:
            candidates.extend(family)
        return candidates

    def _social_profile_profile_candidates(
        self,
        profile: dict[str, Any],
        *,
        row: Any,
        anchor_value: str,
        anchor_type: str,
        base_depth: int,
    ) -> list[SeedCandidate]:
        source_label = str(
            profile.get("source") or row["source"] or "social_profile"
        ).strip().lower()
        platform = str(
            profile.get("platform") or self._social_profile_platform_hint(profile)
        ).strip().lower()
        candidates: list[SeedCandidate] = []
        for seed_value, seed_type, relation_type, confidence, metadata in self._extract_social_profile_pivots(
            profile,
            source_label=source_label,
            platform=platform,
        ):
            if not seed_value or seed_value == anchor_value:
                continue
            candidates.append(
                SeedCandidate(
                    seed_value=seed_value,
                    seed_type=seed_type,
                    source="cross_reference",
                    depth=min(self._depth_limit, max(1, base_depth) + 1),
                    confidence=confidence,
                    parent_value=anchor_value,
                    parent_type=anchor_type,
                    relation_type=relation_type,
                    metadata=metadata,
                )
            )
        return candidates

    @classmethod
    def _social_profile_payload_entries(
        cls,
        profile_data: Any,
        *,
        row_source: str,
    ) -> list[dict[str, Any]]:
        payload_items = cls._social_profile_payload_candidate_items(profile_data)
        if not payload_items:
            return []
        entry_batches = cls._run_ordered_local_batch(
            payload_items,
            lambda item: cls._social_profile_payload_entry(item, row_source=row_source),
            default_factory=lambda: None,
        )
        entries: list[dict[str, Any]] = []
        seen: set[str] = set()
        for entry in entry_batches:
            if not isinstance(entry, dict):
                continue
            dedupe_key = cls._social_profile_payload_dedupe_key(entry)
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            entries.append(entry)
        return entries[: cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES]

    @classmethod
    def _social_profile_payload_candidate_items(cls, profile_data: Any) -> list[dict[str, Any]]:
        return cls._social_profile_payload_candidate_items_at_depth(
            profile_data,
            depth=0,
            seen=set(),
            inherited_context={},
        )

    @classmethod
    def _social_profile_payload_candidate_items_at_depth(
        cls,
        item: Any,
        *,
        depth: int,
        seen: set[int],
        inherited_context: dict[str, Any],
    ) -> list[dict[str, Any]]:
        if depth > 4 or len(seen) > cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES * 4:
            return []
        if isinstance(item, list):
            candidates: list[dict[str, Any]] = []
            child_jobs = [
                (child, depth + 1, set(seen), inherited_context)
                for child in item[: cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES]
            ]
            child_batches = cls._run_ordered_local_batch(
                child_jobs,
                cls._social_profile_payload_child_candidate_items,
                default_factory=list,
            )
            for child_candidates in child_batches:
                candidates.extend(child_candidates)
                if len(candidates) >= cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES:
                    break
            return candidates[: cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES]
        if not isinstance(item, dict):
            return []
        object_id = id(item)
        if object_id in seen:
            return []
        seen.add(object_id)

        profile_item = cls._social_profile_payload_with_inherited_context(
            item,
            inherited_context,
        )
        child_context = cls._social_profile_payload_child_context(
            profile_item,
            inherited_context,
        )

        candidates: list[dict[str, Any]] = []
        if cls._social_profile_payload_has_profile_hint(profile_item):
            candidates.append(profile_item)
        else:
            container_keys = {
                key
                for key in cls._SOCIAL_PROFILE_PAYLOAD_CONTAINER_KEYS
                if key in profile_item
            }
            if not container_keys:
                candidates.append(profile_item)

        child_jobs = [
            (value, depth + 1, set(seen), child_context)
            for key in cls._SOCIAL_PROFILE_PAYLOAD_CONTAINER_KEYS
            if isinstance((value := profile_item.get(key)), (dict, list))
        ]
        child_batches = cls._run_ordered_local_batch(
            child_jobs,
            cls._social_profile_payload_child_candidate_items,
            default_factory=list,
        )
        for child_candidates in child_batches:
            candidates.extend(child_candidates)
            if len(candidates) >= cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES:
                break
        return candidates[: cls._MAX_SOCIAL_PROFILE_PAYLOAD_ENTRIES]

    @classmethod
    def _social_profile_payload_child_candidate_items(
        cls,
        job: tuple[Any, int, set[int], dict[str, Any]],
    ) -> list[dict[str, Any]]:
        child, depth, seen, inherited_context = job
        return cls._social_profile_payload_candidate_items_at_depth(
            child,
            depth=depth,
            seen=set(seen),
            inherited_context=dict(inherited_context),
        )

    @classmethod
    def _social_profile_payload_with_inherited_context(
        cls,
        item: dict[str, Any],
        inherited_context: dict[str, Any],
    ) -> dict[str, Any]:
        profile_item = dict(item)
        if profile_item.get("source") in (None, "") and inherited_context.get("source") not in (None, ""):
            profile_item["source"] = inherited_context["source"]
        if profile_item.get("platform") in (None, ""):
            platform = inherited_context.get("platform") or cls._social_profile_direct_platform(profile_item)
            if platform not in (None, ""):
                profile_item["platform"] = platform
        return profile_item

    @classmethod
    def _social_profile_payload_child_context(
        cls,
        item: dict[str, Any],
        inherited_context: dict[str, Any],
    ) -> dict[str, Any]:
        context = dict(inherited_context)
        source = item.get("source")
        if source not in (None, ""):
            context["source"] = source
        platform = item.get("platform") or cls._social_profile_direct_platform(item)
        if platform not in (None, ""):
            context["platform"] = platform
        return context

    @classmethod
    def _social_profile_payload_has_profile_hint(cls, item: dict[str, Any]) -> bool:
        for key in cls._SOCIAL_PROFILE_PAYLOAD_PROFILE_HINT_KEYS:
            value = item.get(key)
            if value not in (None, "", [], {}):
                return True
        return False

    @staticmethod
    def _social_profile_payload_dedupe_key(entry: dict[str, Any]) -> str:
        try:
            return json.dumps(entry, sort_keys=True, default=str)
        except TypeError:
            return repr(sorted((str(key), str(value)) for key, value in entry.items()))

    @staticmethod
    def _social_profile_payload_entry(
        item: Any,
        *,
        row_source: str,
    ) -> dict[str, Any] | None:
        if not isinstance(item, dict):
            return None
        entry = dict(item)
        if row_source and "source" not in entry:
            entry["source"] = row_source
        return entry

    @staticmethod
    def _normalize_social_profile_anchor(value: str) -> tuple[str, str]:
        text = value.strip()
        lowered = text.lower()
        if lowered.startswith("domain:"):
            normalized = text.split(":", 1)[1].strip().lower().strip(".")
            return normalized, "domain"
        if lowered.startswith("subdomain:"):
            normalized = text.split(":", 1)[1].strip().lower().strip(".")
            return normalized, "subdomain"
        if lowered.startswith("phone:"):
            normalized = _normalize_phone_seed_value(text.split(":", 1)[1])
            return normalized, "phone"
        if lowered.startswith("name:"):
            normalized = text.split(":", 1)[1].strip()
            return normalized, "name"
        if lowered.startswith("company:"):
            normalized = text.split(":", 1)[1].strip()
            return normalized, "company"
        if lowered.startswith("instagram:"):
            normalized = text.split(":", 1)[1].strip().lstrip("@")
            return normalized, "username"
        if lowered.startswith("username:"):
            normalized = text.split(":", 1)[1].strip().lstrip("@")
            return normalized, "username"
        if lowered.startswith("email:"):
            normalized = text.split(":", 1)[1].strip().lower()
            return normalized, "email"
        normalized = text.lstrip("@")
        return normalized, _classify_seed_value(normalized)

    @staticmethod
    def _seed_lookup_keys(seed_type: str, seed_value: str) -> list[tuple[str, str]]:
        normalized_type = str(seed_type or "").strip()
        normalized_value = str(seed_value or "").strip()
        if not normalized_type or not normalized_value:
            return []
        keys = [(normalized_type, normalized_value)]
        if normalized_type == "username":
            bare_value = normalized_value.lstrip("@")
            if bare_value:
                keys.append((normalized_type, bare_value))
                keys.append((normalized_type, f"@{bare_value}"))
        return list(dict.fromkeys(keys))

    @classmethod
    def _lookup_seed_id(
        cls,
        seed_ids: dict[tuple[str, str], int],
        seed_type: str,
        seed_value: str,
    ) -> int | None:
        for key in cls._seed_lookup_keys(seed_type, seed_value):
            if key in seed_ids:
                return int(seed_ids[key])
        return None

    @classmethod
    def _lookup_seed_depth(
        cls,
        seed_depths: dict[tuple[str, str], int],
        seed_type: str,
        seed_value: str,
    ) -> int:
        for key in cls._seed_lookup_keys(seed_type, seed_value):
            if key in seed_depths:
                return int(seed_depths[key])
        return 0

    def _extract_social_profile_pivots(
        self,
        profile: dict[str, Any],
        *,
        source_label: str,
        platform: str,
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        base_confidence = self._social_profile_base_confidence(source_label, platform)
        verified = bool(profile.get("verified") or profile.get("is_verified"))
        if verified:
            base_confidence = min(0.92, base_confidence + 0.04)

        company_profile = self._social_profile_is_company_profile(
            profile,
            source_label=source_label,
            platform=platform,
        )
        pivot_batches = self._run_ordered_local_batch(
            (
                "handles",
                "company",
                "name",
                "emails",
                "phones",
                "urls",
                "matrix_hosts",
                "federated_hosts",
                "hosts",
                "domain",
            ),
            lambda family: self._social_profile_pivot_family(
                family,
                profile=profile,
                source_label=source_label,
                platform=platform,
                base_confidence=base_confidence,
                company_profile=company_profile,
            ),
            default_factory=list,
        )
        prepared_pivot_batches = self._run_ordered_local_batch(
            list(enumerate(pivot_batches)),
            self._social_profile_pivot_batch_entries,
            default_factory=list,
        )
        prepared_pivot_families = self._run_ordered_local_batch(
            list(enumerate(prepared_pivot_batches)),
            self._social_profile_pivot_family_entries,
            default_factory=list,
        )
        pivots: list[tuple[str, str, str, float, dict[str, Any]]] = []
        for pivot_family in prepared_pivot_families:
            pivots.extend(pivot_family)
        return pivots

    @staticmethod
    def _social_profile_pivot_batch_entries(
        batch_entry: tuple[int, Sequence[tuple[str, str, str, float, dict[str, Any]]]],
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        _batch_index, batch = batch_entry
        return [
            pivot
            for pivot in batch
            if isinstance(pivot, tuple) and len(pivot) == 5 and isinstance(pivot[4], dict)
        ]

    @staticmethod
    def _social_profile_pivot_family_entries(
        family_entry: tuple[int, Sequence[tuple[str, str, str, float, dict[str, Any]]]],
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        _family_index, family = family_entry
        return [
            pivot
            for pivot in family
            if isinstance(pivot, tuple) and len(pivot) == 5 and isinstance(pivot[4], dict)
        ]

    @staticmethod
    def _social_profile_url_pivot_entry(
        entry: tuple[str, str, float, str],
    ) -> tuple[str, str, str, float, dict[str, Any]] | None:
        url, platform, base_confidence, source_label = entry
        url_type = _classify_seed_value(url)
        if url_type not in {"url", "apk_url"}:
            return None
        return (
            url,
            url_type,
            "related_asset",
            max(0.68, base_confidence - 0.02),
            {"rule": "social_profile_url", "platform": platform, "source": source_label},
        )

    @staticmethod
    def _social_profile_host_pivot_entry(
        entry: tuple[str, str, str, float, str],
    ) -> tuple[str, str, str, float, dict[str, Any]] | None:
        host_value, host_type, platform, base_confidence, source_label = entry
        if not host_value or not host_type:
            return None
        return (
            host_value,
            host_type,
            "related_asset",
            max(0.7, base_confidence - 0.01),
            {"rule": "social_profile_host", "platform": platform, "source": source_label},
        )

    @staticmethod
    def _social_profile_seed_pivot_entry(
        entry: tuple[str, str, str, float, str, str, str],
    ) -> tuple[str, str, str, float, dict[str, Any]] | None:
        seed_value, seed_type, relation_type, confidence, rule, platform, source_label = entry
        if not seed_value or not seed_type:
            return None
        return (
            seed_value,
            seed_type,
            relation_type,
            confidence,
            {"rule": rule, "platform": platform, "source": source_label},
        )

    @staticmethod
    def _social_profile_handle_pivot_entry(
        entry: tuple[str, str, float, str],
    ) -> tuple[str, str, str, float, dict[str, Any]] | None:
        handle, platform, base_confidence, source_label = entry
        if len(handle) < 3:
            return None
        if not EngagementSynthesisEngine._social_profile_handle_allowed_for_platform(
            platform,
            handle,
        ):
            return None
        return (
            handle,
            "username",
            "same_entity",
            min(0.9, base_confidence + 0.02),
            {"rule": "social_profile_handle", "platform": platform, "source": source_label},
        )

    def _social_profile_pivot_family(
        self,
        family: str,
        *,
        profile: dict[str, Any],
        source_label: str,
        platform: str,
        base_confidence: float,
        company_profile: bool,
    ) -> list[tuple[str, str, str, float, dict[str, Any]]]:
        pivots: list[tuple[str, str, str, float, dict[str, Any]]] = []
        if family == "handles":
            if company_profile:
                return []
            pivot_entries = self._run_ordered_local_batch(
                [
                    (handle, platform, base_confidence, source_label)
                    for handle in self._social_profile_handles(profile, platform=platform)
                ],
                self._social_profile_handle_pivot_entry,
                default_factory=lambda: None,
            )
            return [pivot for pivot in pivot_entries if isinstance(pivot, tuple)]
        if family == "company":
            company_name = self._social_profile_company_name(
                profile,
                source_label=source_label,
                platform=platform,
            )
            if company_name:
                return [
                    (
                        company_name,
                        "company",
                        "same_entity",
                        base_confidence,
                        {"rule": "social_profile_company", "platform": platform, "source": source_label},
                    )
                ]
            return []
        if family == "name":
            full_name = self._social_profile_name(profile)
            if full_name:
                return [
                    (
                        full_name,
                        "name",
                        "same_entity",
                        base_confidence,
                        {"rule": "social_profile_name", "platform": platform, "source": source_label},
                    )
                ]
            return []
        if family == "emails":
            pivot_entries = self._run_ordered_local_batch(
                [
                    (
                        email,
                        "email",
                        "same_entity",
                        min(0.9, base_confidence + 0.03),
                        "social_profile_email",
                        platform,
                        source_label,
                    )
                    for email in self._social_profile_emails(profile)
                ],
                self._social_profile_seed_pivot_entry,
                default_factory=lambda: None,
            )
            return [pivot for pivot in pivot_entries if isinstance(pivot, tuple)]
        if family == "phones":
            pivot_entries = self._run_ordered_local_batch(
                [
                    (
                        phone,
                        "phone",
                        "same_entity",
                        min(0.9, base_confidence + 0.02),
                        "social_profile_phone",
                        platform,
                        source_label,
                    )
                    for phone in self._social_profile_phones(profile)
                ],
                self._social_profile_seed_pivot_entry,
                default_factory=lambda: None,
            )
            return [pivot for pivot in pivot_entries if isinstance(pivot, tuple)]
        if family == "urls":
            pivot_entries = self._run_ordered_local_batch(
                [
                    (url, platform, base_confidence, source_label)
                    for url in self._social_profile_urls(profile)
                ],
                self._social_profile_url_pivot_entry,
                default_factory=lambda: None,
            )
            return [
                pivot
                for pivot in pivot_entries
                if isinstance(pivot, tuple)
            ]
        if family == "hosts":
            platform_profile_hosts = self._social_profile_platform_profile_hosts(profile, platform=platform)
            host_entries = [
                (host_value, host_type, platform, base_confidence, source_label)
                for host_value, host_type in self._social_profile_related_hosts(profile)
                if host_value not in platform_profile_hosts
            ]
            pivot_entries = self._run_ordered_local_batch(
                host_entries,
                self._social_profile_host_pivot_entry,
                default_factory=lambda: None,
            )
            return [
                pivot
                for pivot in pivot_entries
                if isinstance(pivot, tuple)
            ]
        if family == "matrix_hosts":
            if str(platform or "").strip().lower() != "matrix":
                return []
            pivot_entries = self._run_ordered_local_batch(
                [
                    (
                        host_value,
                        host_type,
                        "related_asset",
                        max(0.7, base_confidence - 0.01),
                        "social_profile_matrix_homeserver",
                        platform,
                        source_label,
                    )
                    for host_value, host_type in self._social_profile_matrix_homeserver_hosts(profile)
                ],
                self._social_profile_seed_pivot_entry,
                default_factory=lambda: None,
            )
            return [pivot for pivot in pivot_entries if isinstance(pivot, tuple)]
        if family == "federated_hosts":
            if not self._social_profile_platform_is_federated(platform):
                return []
            pivot_entries = self._run_ordered_local_batch(
                [
                    (
                        host_value,
                        host_type,
                        "related_asset",
                        max(0.7, base_confidence - 0.01),
                        "social_profile_federated_instance",
                        platform,
                        source_label,
                    )
                    for host_value, host_type in self._social_profile_federated_instance_hosts(
                        profile,
                        platform=platform,
                    )
                ],
                self._social_profile_seed_pivot_entry,
                default_factory=lambda: None,
            )
            return [pivot for pivot in pivot_entries if isinstance(pivot, tuple)]
        if family == "domain":
            pivot_entries = self._run_ordered_local_batch(
                [
                    (
                        domain_value,
                        domain_type,
                        "related_asset",
                        max(0.7, base_confidence - 0.01),
                        "social_profile_domain",
                        platform,
                        source_label,
                    )
                    for domain_value, domain_type in self._social_profile_domain_hosts(profile)
                ],
                self._social_profile_seed_pivot_entry,
                default_factory=lambda: None,
            )
            pivots.extend(pivot for pivot in pivot_entries if isinstance(pivot, tuple))
            if platform == "bluesky":
                for handle in self._social_profile_handles(profile, platform=platform):
                    domain_handle = handle.lower()
                    if _classify_seed_value(domain_handle) != "domain":
                        continue
                    if not self._should_promote_bluesky_domain_handle(
                        profile,
                        domain_handle,
                        source_label=source_label,
                    ):
                        continue
                    pivots.append(
                        (
                            domain_handle,
                            "domain",
                            "related_asset",
                            max(0.7, base_confidence - 0.01),
                            {
                                "rule": "social_profile_domain_handle",
                                "platform": platform,
                                "source": source_label,
                            },
                        )
                    )
            return pivots
        return []

    @staticmethod
    def _should_promote_bluesky_domain_handle(
        profile: dict[str, Any],
        domain_handle: str,
        *,
        source_label: str,
    ) -> bool:
        handle = str(domain_handle or "").strip().lower()
        if not handle:
            return False
        explicit_domain = str(profile.get("domain") or "").strip().lower()
        if explicit_domain == handle:
            return True
        for flag_key in (
            "custom_domain",
            "dns_verified",
            "domain_verified",
            "handle_verified",
            "is_custom_domain",
            "is_domain_handle",
            "verified_domain",
        ):
            if bool(profile.get(flag_key)):
                return True
        weak_source = str(source_label or "").strip().lower()
        if any(token in weak_source for token in ("name_search", "phone_dork", "phone_lookup")):
            return False
        return True

    @staticmethod
    def _linkedin_app_profile_path_parts(parsed: Any) -> list[str]:
        if str(getattr(parsed, "scheme", "") or "").strip().lower() != "linkedin":
            return []
        parts = [
            part
            for part in [
                str(getattr(parsed, "netloc", "") or "").strip("/"),
                *str(getattr(parsed, "path", "") or "").strip("/").split("/"),
            ]
            if part
        ]
        if len(parts) < 2:
            return []
        if parts[0].lower() not in {"in", "pub", "profile", "company", "school", "showcase"}:
            return []
        return parts

    @staticmethod
    def _social_profile_handle_allowed_for_platform(platform: str, handle: str) -> bool:
        platform_text = str(platform or "").strip().lower()
        handle_text = str(handle or "").strip().lstrip("@").lower()
        if not platform_text or not handle_text:
            return True
        if EngagementSynthesisEngine._social_profile_platform_is_federated(platform_text):
            return handle_text not in _MASTODON_RESERVED_PROFILE_HANDLES
        if platform_text == "facebook":
            return handle_text not in _FACEBOOK_RESERVED_PROFILE_HANDLES
        if platform_text == "linkedin":
            return handle_text not in _LINKEDIN_RESERVED_PROFILE_HANDLES
        if platform_text == "instagram":
            return handle_text not in _INSTAGRAM_RESERVED_PROFILE_PATHS
        if platform_text in {"telegram", "telegramme"}:
            return handle_text not in _TELEGRAM_RESERVED_PROFILE_PATHS
        if platform_text == "tiktok":
            return handle_text not in _TIKTOK_RESERVED_PROFILE_HANDLES
        if platform_text == "youtube":
            return handle_text not in _YOUTUBE_RESERVED_PROFILE_HANDLES
        if platform_text in {"devto", "dev.to"}:
            return handle_text not in _DEVTO_RESERVED_PROFILE_PATHS
        if platform_text in {"google_scholar", "googlescholar", "scholar"}:
            return bool(
                handle_text not in _GOOGLE_SCHOLAR_RESERVED_PROFILE_HANDLES
                and
                EngagementSynthesisEngine._normalize_google_scholar_user_id_candidate(handle)
            )
        if platform_text in {"nostr", "nostr_protocol"}:
            return bool(
                handle_text not in _NOSTR_RESERVED_PROFILE_PATHS
                and EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(handle)
            )
        if platform_text in {"twitter", "x"}:
            return handle_text not in _TWITTER_RESERVED_PROFILE_PATHS
        if platform_text == "bitbucket":
            return handle_text not in _BITBUCKET_RESERVED_PROFILE_PATHS
        if platform_text == "codeberg":
            return handle_text not in _CODEBERG_RESERVED_PROFILE_PATHS
        if platform_text == "codepen":
            return handle_text not in _CODEPEN_RESERVED_PROFILE_HANDLES
        if platform_text == "github":
            return handle_text not in _GITHUB_RESERVED_PROFILE_PATHS
        if platform_text in {"github_gist", "githubgist", "gist"}:
            return handle_text not in _GITHUB_GIST_RESERVED_PROFILE_PATHS
        if platform_text == "gitlab":
            return handle_text not in _GITLAB_RESERVED_PROFILE_PATHS
        if platform_text == "hashnode":
            return handle_text not in _HASHNODE_RESERVED_PROFILE_PATHS
        if platform_text == "medium":
            return (
                handle_text not in _MEDIUM_RESERVED_PROFILE_PATHS
                and handle_text not in _MEDIUM_RESERVED_SUBDOMAINS
            )
        if platform_text == "substack":
            return (
                handle_text not in _SUBSTACK_RESERVED_PROFILE_PATHS
                and handle_text not in _SUBSTACK_RESERVED_SUBDOMAINS
            )
        if platform_text == "flickr":
            return handle_text not in _FLICKR_RESERVED_PHOTOS_PATHS
        if platform_text == "letterboxd":
            return handle_text not in _LETTERBOXD_RESERVED_PROFILE_PATHS
        if platform_text == "mixcloud":
            return handle_text not in _MIXCLOUD_RESERVED_PROFILE_PATHS
        if platform_text in {"slideshare", "slide_share"}:
            return handle_text not in _SLIDESHARE_RESERVED_PROFILE_PATHS
        if platform_text in {"soundcloud", "sound_cloud"}:
            return handle_text not in _SOUNDCLOUD_RESERVED_PROFILE_PATHS
        if platform_text in {"speakerdeck", "speaker_deck"}:
            return handle_text not in _SPEAKERDECK_RESERVED_PROFILE_PATHS
        if platform_text == "vimeo":
            return handle_text not in _VIMEO_RESERVED_PROFILE_PATHS
        if platform_text == "keybase":
            return handle_text not in _KEYBASE_RESERVED_PROFILE_PATHS
        if platform_text == "orcid":
            return bool(_ORCID_PROFILE_ID_RE.fullmatch(handle_text))
        reserved_direct_handles = _DIRECT_HANDLE_RESERVED_PROFILE_PATHS_BY_PLATFORM.get(platform_text)
        if reserved_direct_handles:
            return handle_text not in reserved_direct_handles
        return True

    @staticmethod
    def _social_profile_platform_is_federated(platform: str) -> bool:
        return str(platform or "").strip().lower() in {
            "activity_pub",
            "activitypub",
            "fediverse",
            "mastodon",
            "mastodon_social",
            "webfinger",
        }

    @staticmethod
    def _social_profile_base_confidence(source_label: str, platform: str) -> float:
        text = f"{source_label} {platform}".lower()
        if "linkedin" in text or "crosslinked" in text:
            return 0.8
        if "instagram" in text:
            return 0.79
        if "gravatar" in text:
            return 0.77
        if "ghunt" in text or "google" in text:
            return 0.76
        if "name_search" in text:
            return 0.73
        if "phone_dork" in text:
            return 0.72
        return 0.74

    @classmethod
    def _social_profile_platform_hint(cls, profile: dict[str, Any]) -> str:
        direct_platform = cls._social_profile_direct_platform(profile)
        if direct_platform:
            return direct_platform
        platform_candidates = cls._run_ordered_local_batch(
            cls._social_profile_url_hint_values(profile),
            cls._social_profile_platform_hint_candidate,
            default_factory=str,
        )
        for platform_candidate in platform_candidates:
            if platform_candidate:
                return platform_candidate
        return ""

    @classmethod
    def _social_profile_direct_platform(cls, profile: dict[str, Any]) -> str:
        platform_candidates = cls._run_ordered_local_batch(
            [profile.get(key) for key in cls._SOCIAL_PROFILE_PLATFORM_ALIAS_KEYS],
            cls._social_profile_platform_label_candidate,
            default_factory=str,
        )
        for platform_candidate in platform_candidates:
            if platform_candidate:
                return platform_candidate
        return ""

    @classmethod
    def _social_profile_platform_label_candidate(cls, value: Any) -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        url_hint = cls._social_profile_platform_hint_candidate(text)
        if url_hint:
            return url_hint
        host_text = text.lower().removeprefix("www.").strip("/")
        if _is_social_platform_host(host_text):
            host_hint = cls._social_profile_platform_hint_candidate(f"https://{host_text}/")
            if host_hint:
                return host_hint
        normalized = re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")
        if not normalized or len(normalized) > 64:
            return ""
        normalized = cls._SOCIAL_PROFILE_PLATFORM_LABEL_ALIASES.get(normalized, normalized)
        return normalized

    @classmethod
    def _social_profile_url_hint_values(cls, profile: dict[str, Any]) -> list[Any]:
        values = cls._run_ordered_local_batch(
            [(profile, key) for key in cls._SOCIAL_PROFILE_URL_HINT_KEYS],
            cls._social_profile_url_hint_value_for_item_key,
            default_factory=lambda: None,
        )
        return [value for value in values if value not in (None, "", [], {})]

    @classmethod
    def _social_profile_scalar_url_hint_values(cls, profile: dict[str, Any]) -> list[Any]:
        values = cls._run_ordered_local_batch(
            [(profile, key) for key in cls._SOCIAL_PROFILE_URL_HINT_KEYS],
            cls._social_profile_scalar_url_hint_value_for_item_key,
            default_factory=lambda: None,
        )
        return [value for value in values if value not in (None, "")]

    @classmethod
    def _social_profile_identity_url_hint_values(cls, profile: dict[str, Any]) -> list[Any]:
        values = cls._run_ordered_local_batch(
            [(profile, key) for key in cls._SOCIAL_PROFILE_IDENTITY_URL_HINT_KEYS],
            cls._social_profile_url_hint_value_for_item_key,
            default_factory=lambda: None,
        )
        return [value for value in values if value not in (None, "", [], {})]

    @staticmethod
    def _social_profile_url_hint_value_for_item_key(
        item_key: tuple[dict[str, Any], str],
    ) -> Any:
        item, key = item_key
        if not isinstance(item, dict):
            return None
        return item.get(key)

    @staticmethod
    def _social_profile_scalar_url_hint_value_for_item_key(
        item_key: tuple[dict[str, Any], str],
    ) -> Any:
        item, key = item_key
        if not isinstance(item, dict):
            return None
        value = item.get(key)
        if value in (None, "") or isinstance(value, (dict, list, tuple, set)):
            return None
        return value

    @staticmethod
    def _coerce_social_profile_urlish_candidate(value: Any) -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        parsed = urlparse(text)
        if parsed.scheme:
            return text
        if text.startswith("//"):
            candidate = f"https:{text}"
            hostname = str(urlparse(candidate).hostname or "").strip().lower()
            if hostname and (
                _is_social_platform_host(hostname)
                or _classify_seed_value(hostname) in {"domain", "subdomain"}
            ):
                return candidate
            return text
        host_part = re.split(r"[/?#]", text, maxsplit=1)[0].strip().lower().strip(".")
        if host_part and _is_social_platform_host(host_part):
            return f"https://{text}"
        if host_part and _classify_seed_value(host_part) in {"domain", "subdomain"}:
            return f"https://{text}"
        return text

    @staticmethod
    def _social_profile_platform_hint_candidate(candidate: Any) -> str:
        candidate_text = EngagementSynthesisEngine._coerce_social_profile_urlish_candidate(candidate)
        parsed = urlparse(candidate_text)
        linkedin_app_parts = EngagementSynthesisEngine._linkedin_app_profile_path_parts(parsed)
        if linkedin_app_parts:
            if linkedin_app_parts[0].lower() in {"company", "school", "showcase"}:
                return "linkedin_company"
            return "linkedin"
        if EngagementSynthesisEngine._nostr_identity_handle_candidate(candidate_text):
            return "nostr"
        if str(parsed.scheme or "").strip().lower() == "acct":
            return "activitypub"
