    @staticmethod
    def _normalize_social_profile_handle_candidate(value: Any) -> str:
        candidate = str(value or "").strip().strip("/")
        if not candidate:
            return ""
        nostr_candidate = EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(candidate)
        if nostr_candidate:
            return nostr_candidate
        candidate = candidate.lstrip("@")
        if not candidate or " " in candidate or "/" in candidate:
            return ""
        if not re.match(r"^[A-Za-z0-9._-]{3,64}$", candidate):
            return ""
        return candidate

    @staticmethod
    def _normalize_nostr_public_identity_candidate(value: Any) -> str:
        candidate = unquote(str(value or "").strip()).strip("/#")
        if not candidate:
            return ""
        parsed = urlparse(candidate)
        scheme = str(parsed.scheme or "").strip().lower()
        if scheme == "nostr":
            candidate = str(parsed.path or parsed.netloc or "").strip("/")
        elif candidate.lower().startswith("nostr:"):
            candidate = candidate.split(":", 1)[1].strip("/")
        candidate = unquote(candidate).strip().strip("@").split("?", 1)[0].split("#", 1)[0].strip("/")
        if not candidate:
            return ""
        lowered = candidate.lower()
        if not _NOSTR_BECH32_ID_RE.fullmatch(lowered):
            return ""
        return lowered

    @staticmethod
    def _nostr_identity_handle_candidate(value: Any) -> str:
        candidate = EngagementSynthesisEngine._coerce_social_profile_urlish_candidate(value)
        direct_identity = EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(candidate)
        if direct_identity:
            return direct_identity
        parsed = urlparse(candidate)
        scheme = str(parsed.scheme or "").strip().lower()
        if scheme == "nostr":
            return EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(
                str(parsed.path or parsed.netloc or "")
            )
        hostname = str(parsed.hostname or "").strip().lower().strip(".")
        if hostname.startswith("www."):
            hostname = hostname[4:]
        if hostname not in {
            "nostr.com",
            "nostrudel.ninja",
            "njump.me",
            "primal.net",
            "iris.to",
            "snort.social",
            "yakihonne.com",
        }:
            return ""
        candidate_parts: list[str] = []
        candidate_parts.extend(part for part in parsed.path.strip("/").split("/") if part)
        candidate_parts.extend(part for part in unquote(str(parsed.fragment or "")).strip("/").split("/") if part)
        query_map = {
            str(key).strip().lower(): str(item_value).strip()
            for key, item_value in parse_qsl(parsed.query, keep_blank_values=False)
        }
        for query_key in ("npub", "nprofile", "profile", "pubkey", "public_key"):
            if query_map.get(query_key):
                candidate_parts.append(query_map[query_key])
        for part in candidate_parts:
            normalized = EngagementSynthesisEngine._normalize_nostr_public_identity_candidate(part)
            if normalized:
                return normalized
        return ""

    @staticmethod
    def _matrix_user_id_parts(value: Any) -> tuple[str, str]:
        text = unquote(str(value or "").strip())
        if not text:
            return "", ""
        parsed = urlparse(text)
        scheme = str(parsed.scheme or "").strip().lower()
        hostname = str(parsed.hostname or "").strip().lower()
        candidate = ""
        if scheme in {"http", "https"} and hostname == "matrix.to":
            fragment = unquote(str(parsed.fragment or "").strip()).strip("/")
            candidate = fragment.split("?", 1)[0].split("/", 1)[0].strip()
        elif scheme == "matrix":
            parts = [
                part
                for part in [
                    str(parsed.netloc or "").strip("/"),
                    *str(parsed.path or "").strip("/").split("/"),
                ]
                if part
            ]
            if parts and parts[0].lower() in {"u", "user"} and len(parts) >= 2:
                candidate = parts[1]
            elif parts:
                candidate = parts[0]
        elif text.startswith("@"):
            candidate = text
        if not candidate:
            return "", ""
        candidate = unquote(candidate).split("?", 1)[0].split("#", 1)[0].strip()
        match = re.fullmatch(
            r"@(?P<local>[A-Za-z0-9._-]{3,64}):(?P<server>[A-Za-z0-9][A-Za-z0-9.\-]{1,253})(?::\d{1,5})?",
            candidate,
        )
        if not match:
            return "", ""
        handle = EngagementSynthesisEngine._normalize_social_profile_handle_candidate(match.group("local"))
        server = match.group("server").lower().strip(".")
        if not handle or _classify_seed_value(server) != "domain":
            return "", ""
        if _is_social_platform_host(server) and not _is_mastodon_instance_host(server):
            return "", ""
        if _is_managed_cloud_provider_host(server):
            return "", ""
        return handle, server

    @classmethod
    def _matrix_user_handle_candidate(cls, value: Any) -> str:
        handle, _server = cls._matrix_user_id_parts(value)
        return handle

    @classmethod
    def _matrix_homeserver_host_entries(cls, value: Any) -> list[tuple[str, str]]:
        _handle, server = cls._matrix_user_id_parts(value)
        if not server:
            return []
        root_domain = _normalize_root_domain(server)
        entries: list[tuple[str, str]] = []
        if server != root_domain:
            entries.append((server, "subdomain"))
        if root_domain:
            entries.append((root_domain, "domain"))
        return entries

    @staticmethod
    def _federated_account_parts(value: Any) -> tuple[str, str]:
        text = unquote(str(value or "").strip())
        if not text:
            return "", ""
        parsed = urlparse(text)
        scheme = str(parsed.scheme or "").strip().lower()
        candidate = ""
        if scheme == "acct":
            candidate = str(parsed.path or parsed.netloc or "").strip()
        elif scheme in {"http", "https"}:
            query_map = {
                str(key).strip().lower(): str(item_value).strip()
                for key, item_value in parse_qsl(parsed.query, keep_blank_values=False)
            }
            candidate = query_map.get("resource", "")
        elif text.startswith("acct:"):
            candidate = text.split(":", 1)[1].strip()
        elif text.startswith("@") and text.count("@") >= 2:
            candidate = text[1:]
        else:
            candidate = text
        candidate = unquote(candidate).split("?", 1)[0].split("#", 1)[0].strip()
        if candidate.startswith("acct:"):
            candidate = candidate.split(":", 1)[1].strip()
        if candidate.startswith("@"):
            candidate = candidate[1:]
        match = re.fullmatch(
            r"(?P<local>[A-Za-z0-9._-]{3,64})@(?P<server>[A-Za-z0-9][A-Za-z0-9.\-]{1,253})(?::\d{1,5})?",
            candidate,
        )
        if not match:
            return "", ""
        handle = EngagementSynthesisEngine._normalize_social_profile_handle_candidate(match.group("local"))
        server = match.group("server").lower().strip(".")
        if not handle or _classify_seed_value(server) != "domain":
            return "", ""
        if _is_social_platform_host(server) and not _is_mastodon_instance_host(server):
            return "", ""
        if _is_managed_cloud_provider_host(server):
            return "", ""
        return handle, server

    @classmethod
    def _federated_account_handle_candidate(cls, value: Any) -> str:
        handle, _server = cls._federated_account_parts(value)
        return handle

    @staticmethod
    def _is_public_federated_service_host(hostname: str) -> bool:
        host = str(hostname or "").strip().lower().strip(".")
        if host.startswith("www."):
            host = host[4:]
        return host in _MASTODON_INSTANCE_DOMAINS

    @classmethod
    def _federated_account_host_entries(cls, value: Any, *, platform: str = "") -> list[tuple[str, str]]:
        handle, server = cls._federated_account_parts(value)
        if not handle or not server:
            return []
        if not cls._social_profile_handle_allowed_for_platform(platform or "mastodon", handle):
            return []
        if cls._is_public_federated_service_host(server):
            return []
        if _is_managed_cloud_provider_host(server):
            return []
        if _is_social_platform_host(server) and not _is_mastodon_instance_host(server):
            return []
        root_domain = _normalize_root_domain(server)
        entries: list[tuple[str, str]] = []
        if server != root_domain:
            entries.append((server, "subdomain"))
        if root_domain:
            entries.append((root_domain, "domain"))
        return entries

    @staticmethod
    def _normalize_google_scholar_user_id_candidate(value: Any) -> str:
        candidate = str(value or "").strip()
        if not candidate:
            return ""
        if not _GOOGLE_SCHOLAR_USER_ID_RE.fullmatch(candidate):
            return ""
        return candidate

    @staticmethod
    def _normalize_pinterest_profile_handle_candidate(value: Any) -> str:
        candidate = str(value or "").strip().strip("/").lstrip("@")
        if not candidate:
            return ""
        if not re.fullmatch(r"[A-Za-z0-9_]{3,30}", candidate):
            return ""
        if candidate.isdigit():
            return ""
        return candidate

