    @classmethod
    def _social_profile_mailto_candidate(cls, candidate: str) -> str:
        candidates = cls._social_profile_mailto_candidates(candidate)
        if candidates:
            return candidates[0]
        return ""

    @classmethod
    def _social_profile_mailto_candidates(cls, candidate: str) -> list[str]:
        parsed = urlparse(candidate)
        scheme = parsed.scheme.lower()
        if scheme not in {"mailto", "facetime", "facetime-audio", "sip", "sips", "xmpp"}:
            return []
        values: list[str] = []
        mailbox = unquote(parsed.path or parsed.netloc or "").strip().lower()
        if scheme in {"sip", "sips", "xmpp"}:
            mailbox = mailbox.split(";", 1)[0].split("/", 1)[0].strip()
            local_part = mailbox.split("@", 1)[0].strip()
            if cls._normalize_phone_candidate(local_part):
                mailbox = ""
        for mailbox_part in re.split(r"[,;]", mailbox):
            cleaned = cls._social_profile_email_candidate(mailbox_part)
            if cleaned:
                values.append(cleaned)
        query_map = {
            str(key).strip().lower(): str(value).strip()
            for key, value in parse_qsl(parsed.query, keep_blank_values=False)
        }
        query_batches = cls._run_ordered_local_batch(
            [(query_map, query_key) for query_key in ("to", "cc", "bcc")],
            cls._social_profile_mailto_query_email_candidates,
            default_factory=list,
        )
        query_entries = cls._run_ordered_local_batch(
            list(enumerate(query_batches)),
            cls._social_profile_value_batch_entries,
            default_factory=list,
        )
        for batch in query_entries:
            values.extend(batch)
        return list(dict.fromkeys(values))

    @classmethod
    def _social_profile_mailto_query_email_candidates(
        cls,
        query_entry: tuple[dict[str, str], str],
    ) -> list[str]:
        query_map, query_key = query_entry
        values: list[str] = []
        for mailbox_part in re.split(r"[,;]", unquote(query_map.get(query_key, ""))):
            cleaned = cls._social_profile_email_candidate(mailbox_part)
            if cleaned:
                values.append(cleaned)
        return values

    @staticmethod
    def _normalize_phone_candidate(value: Any) -> str:
        return _normalize_phone_seed_value(value)

    @classmethod
    def _social_profile_phones(cls, profile: dict[str, Any]) -> list[str]:
        values: list[str] = []
        direct_batches = cls._run_ordered_local_batch(
            [profile.get(key) for key in cls._SOCIAL_PROFILE_PHONE_FIELD_KEYS],
            cls._social_profile_phone_candidates,
            default_factory=list,
        )
        prepared_direct_batches = cls._run_ordered_local_batch(
            list(enumerate(direct_batches)),
            cls._social_profile_value_batch_entries,
            default_factory=list,
        )
        prepared_direct_families = cls._run_ordered_local_batch(
            list(enumerate(prepared_direct_batches)),
            cls._social_profile_value_family_entries,
            default_factory=list,
        )

        entry_jobs: list[Any] = []
        for key in (
            "phones",
            "phone_numbers",
            "phoneNumbers",
            "phone_numbers_in_bio",
            "contact_phones",
            "contactPhones",
        ):
            items = profile.get(key) or []
            if not isinstance(items, list):
                continue
            entry_jobs.extend(items)
        entry_jobs.extend(cls._social_profile_work_history_profile_entries(profile))
        entry_jobs.extend(cls._social_profile_nested_profile_dicts(profile))
        entry_jobs.extend(cls._social_profile_embedded_container_items(profile))
        entry_batches = cls._run_ordered_local_batch(
            entry_jobs,
            cls._social_profile_phone_candidates,
            default_factory=list,
        )
        prepared_entry_batches = cls._run_ordered_local_batch(
            list(enumerate(entry_batches)),
            cls._social_profile_value_batch_entries,
            default_factory=list,
        )
        prepared_entry_families = cls._run_ordered_local_batch(
            list(enumerate(prepared_entry_batches)),
            cls._social_profile_value_family_entries,
            default_factory=list,
        )

        raw_link_candidates = cls._social_profile_raw_link_values(profile)
        linked_candidate_batches = cls._run_ordered_local_batch(
            raw_link_candidates,
            cls._social_profile_contact_phone_candidates,
            default_factory=list,
        )
        linked_entries = cls._run_ordered_local_batch(
            list(enumerate(linked_candidate_batches)),
            cls._social_profile_value_batch_entries,
            default_factory=list,
        )
        text_phone_batches = cls._run_ordered_local_batch(
            cls._social_profile_text_values(profile),
            cls._social_profile_text_phone_candidates,
            default_factory=list,
        )
        text_phone_entries = cls._run_ordered_local_batch(
            list(enumerate(text_phone_batches)),
            cls._social_profile_value_batch_entries,
            default_factory=list,
        )
        value_groups = [
            *prepared_direct_families,
            *prepared_entry_families,
            *linked_entries,
            *text_phone_entries,
        ]
        prepared_value_groups = cls._run_ordered_local_batch(
            list(enumerate(value_groups)),
            cls._social_profile_value_group_entries,
            default_factory=list,
        )
        for group in prepared_value_groups:
            values.extend(group)
        return list(dict.fromkeys(values))

    @classmethod
    def _social_profile_phone_candidate(cls, value: Any) -> str:
        values = cls._social_profile_phone_values(value)
        return values[0] if values else ""

    @classmethod
    def _social_profile_phone_values(cls, value: Any) -> list[str]:
        text = str(value or "").strip()
        if not text:
            return []
        values: list[str] = []
        direct_phone = cls._normalize_phone_candidate(text)
        if direct_phone:
            values.append(direct_phone)
        values.extend(cls._extract_phones_from_contact_url(text))
        phone_candidates = cls._run_ordered_local_batch(
            [phone_match.group(1) for phone_match in _ARTIFACT_PHONE_RE.finditer(text)],
            cls._social_profile_phone_candidate_from_match,
            default_factory=str,
        )
        phone_entries = cls._run_ordered_local_batch(
            list(enumerate(phone_candidates)),
            cls._social_profile_value_entry,
            default_factory=lambda: None,
        )
        values.extend(value for value in phone_entries if value)
        return list(dict.fromkeys(values))

    @classmethod
    def _social_profile_phone_candidate_from_match(cls, value: Any) -> str:
        return cls._normalize_phone_candidate(value)

