    def _yaml_mapping_looks_like_buildkite_ci(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        steps = normalized.get("steps")
        if not isinstance(steps, list):
            return False
        for step_entry in steps[:64]:
            if not isinstance(step_entry, dict):
                continue
            step_normalized = self._yaml_normalized_mapping(step_entry)
            if any(key in step_normalized for key in ("label", "command", "commands", "plugins", "block", "wait")):
                return True
        return False

    def _yaml_buildkite_plugin_image_candidates(self, mapping: dict[str, Any]) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        plugin_jobs: list[tuple[int, Any]] = []
        for step_index, step_entry in enumerate(self._yaml_ref_collection(mapping, "steps")):
            if not isinstance(step_entry, dict):
                continue
            step_normalized = self._yaml_normalized_mapping(step_entry)
            plugins = step_normalized.get("plugins")
            if plugins is not None:
                plugin_jobs.append((step_index, plugins))

        plugin_batches = self._run_ordered_local_batch(
            plugin_jobs,
            self._yaml_buildkite_plugin_image_candidate_values,
            default_factory=list,
        )
        for plugin_batch in plugin_batches:
            for candidate in plugin_batch:
                if not candidate or candidate.lower() in seen:
                    continue
                seen.add(candidate.lower())
                candidates.append(candidate)
        return candidates

    def _yaml_buildkite_plugin_image_candidate_values(
        self,
        plugin_job: tuple[int, Any],
    ) -> list[str]:
        _step_index, plugins = plugin_job
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            candidate = _artifact_container_image_url_candidate(
                str(value or "").strip().strip("\"'"),
                require_explicit_registry=True,
            )
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        def _walk_plugins(value: Any) -> None:
            if isinstance(value, dict):
                normalized = self._yaml_normalized_mapping(value)
                _append(self._yaml_ref_value(normalized, "image", "container", "docker_image", "dockerImage"))
                for child in value.values():
                    if isinstance(child, (dict, list)):
                        _walk_plugins(child)
            elif isinstance(value, list):
                for item in value[:128]:
                    _walk_plugins(item)

        _walk_plugins(plugins)
        return candidates

