    def _yaml_mapping_looks_like_bitbucket_pipelines(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        pipelines = normalized.get("pipelines")
        if not isinstance(pipelines, dict):
            return False
        if any(key in normalized for key in ("definitions", "image", "clone", "options")):
            return True
        return any(
            self._yaml_key_fingerprint(str(key or "")) in {"default", "branches", "tags", "pullrequests", "custom"}
            for key in pipelines
        )

    def _yaml_bitbucket_pipelines_repository_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_bitbucket_repository_candidate_values(
            mapping,
            (),
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_bitbucket_repository_value_candidates(
        self,
        value: Any,
        *,
        allow_owner_repo: bool,
    ) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'").strip("/")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        candidates_for_value = self._yaml_gitops_repository_candidates(raw_value)
        if candidates_for_value:
            return candidates_for_value
        if not allow_owner_repo:
            return []
        parts = [part for part in raw_value.split("/") if part]
        if len(parts) < 2:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts[:2]):
            return []
        return [f"https://bitbucket.org/{parts[0]}/{parts[1]}"]

    def _yaml_bitbucket_repository_candidate_values(
        self,
        value: Any,
        path_parts: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            path_parts,
            self._yaml_bitbucket_repository_child_candidate_values,
            use_workers=use_workers,
            list_limit=256,
        )

    def _yaml_bitbucket_repository_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, path_parts = child_job
        if raw_key is None:
            return self._yaml_bitbucket_repository_candidate_values(
                child,
                path_parts,
                use_workers=False,
            )
        repo_key_names = {
            "giturl",
            "cloneurl",
            "repourl",
            "repositoryurl",
            "repository",
            "repositories",
            "repo",
        }
        key_name = self._yaml_key_fingerprint(str(raw_key or ""))
        child_path = (*path_parts, key_name)
        in_repository_context = any(
            part in {"repository", "repositories", "repo"}
            for part in path_parts
        )
        values: list[str] = []
        if isinstance(child, str) and (key_name in repo_key_names or in_repository_context):
            values.extend(
                self._yaml_bitbucket_repository_value_candidates(
                    child,
                    allow_owner_repo=key_name in repo_key_names or in_repository_context,
                )
            )
        values.extend(
            self._yaml_bitbucket_repository_candidate_values(
                child,
                child_path,
                use_workers=False,
            )
        )
        return values

    def _yaml_bitbucket_pipelines_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(candidate: str) -> None:
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_bitbucket_container_candidate_values(
            mapping,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_bitbucket_container_candidate_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_bitbucket_container_child_candidate_values,
            use_workers=use_workers,
            list_limit=256,
        )

    def _yaml_bitbucket_container_child_candidate_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[str]:
        raw_key, child, _state = child_job
        if raw_key is None:
            return self._yaml_bitbucket_container_candidate_values(
                child,
                use_workers=False,
            )
        values: list[str] = []
        key_name = self._yaml_key_fingerprint(str(raw_key or ""))
        if key_name in {"image", "container"}:
            if isinstance(child, dict):
                normalized_child = self._yaml_normalized_mapping(child)
                raw_value = self._yaml_ref_value(normalized_child, "name", "image", "container")
            else:
                raw_value = str(child or "").strip().strip("\"'")
            candidate = _artifact_container_image_url_candidate(
                raw_value,
                require_explicit_registry=True,
            )
            if candidate:
                values.append(candidate)
        values.extend(
            self._yaml_bitbucket_container_candidate_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_gitlab_ci_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path: tuple[str, ...],
    ) -> list[str]:
        if path or not self._yaml_mapping_looks_like_gitlab_ci(mapping, normalized):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        workflow = self._yaml_child_mapping(mapping, "workflow")
        if workflow:
            workflow_name = self._yaml_external_secret_ref_segment(
                self._yaml_ref_value(self._yaml_normalized_mapping(workflow), "name")
            )
            if workflow_name:
                _append(f"gitlab-pipeline://{workflow_name}")

        resource_batches = self._run_ordered_local_batch(
            (
                ("gitlab_ci", "includes", mapping),
                ("gitlab_ci", "services", mapping),
            ),
            self._yaml_ci_resource_family_candidates,
            default_factory=list,
        )
        for resource_values in resource_batches:
            for resource_candidate in resource_values:
                _append(resource_candidate)
        return candidates

    def _yaml_mapping_looks_like_gitlab_ci(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> bool:
        if any(key in normalized for key in ("include", "stages", "workflow", "before_script", "after_script")):
            return True
        for key, value in mapping.items():
            key_name = str(key or "").strip()
            if not key_name or key_name.startswith(".") or key_name in {"default", "variables", "cache"}:
                continue
            if not isinstance(value, dict):
                continue
            job_normalized = self._yaml_normalized_mapping(value)
            if any(job_key in job_normalized for job_key in ("script", "stage", "extends", "rules", "needs")):
                return True
        return False

    def _yaml_gitlab_ci_include_repository_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        normalized = self._yaml_normalized_mapping(mapping)
        include_value = normalized.get("include")
        if include_value is not None:
            for candidate in self._yaml_gitlab_ci_include_candidate_values(
                include_value,
                use_workers=use_workers,
            ):
                _append(candidate)
        return candidates

    def _yaml_gitlab_ci_include_candidate_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        if isinstance(value, dict):
            direct_values: list[str] = []
            normalized = self._yaml_normalized_mapping(value)
            remote_value = self._yaml_ref_value(normalized, "remote")
            if remote_value:
                direct_values.extend(self._yaml_gitops_repository_candidates(remote_value))
            direct_values.extend(
                self._yaml_gitlab_ci_project_repository_candidates(
                    self._yaml_ref_value(normalized, "project")
                )
            )
            direct_values.extend(
                self._yaml_gitlab_ci_component_candidates(
                    self._yaml_ref_value(normalized, "component")
                )
            )
            child_jobs = [
                child
                for child in value.values()
                if isinstance(child, (dict, list))
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._yaml_gitlab_ci_include_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitlab_ci_include_candidate_values(
                        child,
                        use_workers=False,
                    )
                    for child in child_jobs
                ]
            )
            return [
                *direct_values,
                *[
                    candidate
                    for child_values in child_batches
                    for candidate in child_values
                ],
            ]
        if isinstance(value, list):
            item_jobs = list(value)
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._yaml_gitlab_ci_include_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitlab_ci_include_candidate_values(
                        item,
                        use_workers=False,
                    )
                    for item in item_jobs
                ]
            )
            return [
                candidate
                for item_values in item_batches
                for candidate in item_values
            ]
        return []

    def _yaml_gitlab_ci_include_child_candidate_values(
        self,
        child: Any,
    ) -> list[str]:
        return self._yaml_gitlab_ci_include_candidate_values(
            child,
            use_workers=False,
        )

    def _yaml_gitlab_ci_project_repository_candidates(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'").strip("/")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        if raw_value.startswith(("http://", "https://", "git@", "ssh://", "git://")):
            return self._yaml_gitops_repository_candidates(raw_value)
        parts = [part for part in raw_value.split("/") if part]
        if len(parts) < 2:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts):
            return []
        if "." in parts[0]:
            return [f"https://{parts[0].lower()}/{'/'.join(parts[1:])}"]
        return [f"https://gitlab.com/{'/'.join(parts)}"]

    def _yaml_gitlab_ci_component_candidates(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'")
        if not raw_value or any(marker in raw_value for marker in ("${", "$(", "{{", "}}")):
            return []
        component_ref = raw_value.split("@", 1)[0].strip("/")
        parts = [part for part in component_ref.split("/") if part]
        if len(parts) < 3 or "." not in parts[0]:
            return []
        if not all(re.fullmatch(r"[A-Za-z0-9_.-]+", part) for part in parts[:3]):
            return []
        return [f"https://{parts[0].lower()}/{parts[1]}/{parts[2]}"]

    def _yaml_gitlab_ci_service_container_candidates(
        self,
        mapping: dict[str, Any],
        *,
        use_workers: bool = True,
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            raw_value = str(value or "").strip().strip("\"'")
            if not raw_value:
                return
            candidate = _artifact_container_image_url_candidate(raw_value, require_explicit_registry=True)
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for candidate in self._yaml_gitlab_ci_service_container_values(
            mapping,
            use_workers=use_workers,
        ):
            _append(candidate)
        return candidates

    def _yaml_gitlab_ci_service_container_values(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[Any]:
        return self._yaml_worker_walk_values(
            value,
            None,
            self._yaml_gitlab_ci_service_container_child_values,
            use_workers=use_workers,
        )

    def _yaml_gitlab_ci_service_container_child_values(
        self,
        child_job: tuple[Any, Any, Any],
    ) -> list[Any]:
        raw_key, child, _state = child_job
        if raw_key is None:
            return self._yaml_gitlab_ci_service_container_values(
                child,
                use_workers=False,
            )
        values: list[Any] = []
        if self._yaml_key_fingerprint(str(raw_key or "")) == "services":
            self._yaml_gitlab_ci_collect_service_images(child, values.append)
        values.extend(
            self._yaml_gitlab_ci_service_container_values(
                child,
                use_workers=False,
            )
        )
        return values

    def _yaml_gitlab_ci_collect_service_images(
        self,
        value: Any,
        append: Callable[[Any], None],
    ) -> None:
        if isinstance(value, str):
            append(value)
            return
        if isinstance(value, list):
            for item in value:
                self._yaml_gitlab_ci_collect_service_images(item, append)
            return
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            service_name = self._yaml_ref_value(normalized, "name", "image")
            if service_name:
                append(service_name)

    def _yaml_dependabot_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        if not self._yaml_mapping_looks_like_dependabot_config(mapping, normalized, path_hint):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            candidate = _artifact_package_registry_host_or_url_candidate(str(value or ""))
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for key in (
            "url",
            "registry",
            "registryUrl",
            "registry_url",
            "registryHost",
            "registry_host",
            "host",
            "hostName",
            "hostname",
            "host_name",
            "indexUrl",
            "index_url",
            "source",
        ):
            raw_value = self._yaml_ref_value(normalized, key)
            if raw_value:
                _append(raw_value)
        return candidates

    def _yaml_mapping_looks_like_dependabot_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        if any(key in normalized for key in ("updates", "registries")) and "version" in normalized:
            return True
        registry_type = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "type"))
        if registry_type in {
            "dockerregistry",
            "gitregistry",
            "hexorganization",
            "mavenrepository",
            "npmregistry",
            "nugetfeed",
            "pythonindex",
            "rubygemsserver",
            "terraformregistry",
        }:
            return True
        return "registries" in path_hint and any(
            key in normalized
            for key in (
                "url",
                "registry",
                "registryurl",
                "registryhost",
                "host",
                "hostname",
                "host_name",
                "indexurl",
                "source",
            )
        )

    def _yaml_renovate_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        if not self._yaml_mapping_looks_like_renovate_config(mapping, normalized, path_hint):
            return []

        raw_candidates: list[Any] = []
        candidates: list[str] = []
        seen: set[str] = set()

        def _append_candidate(candidate: str) -> None:
            if not candidate or candidate.lower() in seen:
                return
            seen.add(candidate.lower())
            candidates.append(candidate)

        for key in (
            "matchHost",
            "match_host",
            "host",
            "hostname",
            "hostName",
            "registryUrl",
            "registry_url",
            "endpoint",
            "npmRegistryServer",
            "npm_registry_server",
        ):
            raw_value = self._yaml_ref_value(normalized, key)
            if raw_value:
                raw_candidates.append(raw_value)

        for key in ("registryUrls", "registry_urls"):
            value = normalized.get(key) or normalized.get(self._yaml_key_fingerprint(key))
            if isinstance(value, list):
                for item in value[:64]:
                    if isinstance(item, (str, int, float)):
                        raw_candidates.append(item)
            elif isinstance(value, (str, int, float)):
                raw_candidates.append(value)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._renovate_text_candidate_entry,
            default_factory=str,
        )
        for candidate in candidate_entries:
            _append_candidate(candidate)
        return candidates

    def _yaml_mapping_looks_like_renovate_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        if any(key in normalized for key in ("hostrules", "packagerules", "renovate")):
            return True
        if any(part in path_hint for part in ("hostrules", "packagerules", "renovate")):
            return any(
                key in normalized
                for key in (
                    "matchhost",
                    "host",
                    "hostname",
                    "registryurl",
                    "registryurls",
                    "endpoint",
                    "npmregistryserver",
                )
            )
        if "hosttype" in normalized and any(
            key in normalized
            for key in ("matchhost", "registryurl", "endpoint", "host", "hostname")
        ):
            return True
        return False

    def _renovate_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        source_name = Path(str(source_hint or "").replace("\\", "/")).name.lower()
        if not (
            _renovate_config_artifact_label(source_hint)
            or source_name in {".renovaterc", "renovaterc"}
        ):
            return ""

        raw_candidates: list[str] = []
        in_registry_array = False
        key_pattern = re.compile(
            r"""
            ^["']?
            (?P<key>
                matchHost|match_host|registryUrl|registry_url|registryUrls|
                registry_urls|endpoint|npmRegistryServer|npm_registry_server|
                host|hostname|hostName|host_name
            )
            ["']?\s*[:=]\s*(?P<value>.+?)\s*,?\s*$
            """,
            re.IGNORECASE | re.VERBOSE,
        )

        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line or line.startswith(("//", "#")):
                continue

            candidate_values: list[str] = []
            key_match = key_pattern.match(line)
            if key_match:
                key = self._yaml_key_fingerprint(key_match.group("key"))
                value = key_match.group("value").strip()
                if key == "registryurls" and "[" in value and "]" not in value:
                    in_registry_array = True
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", value))
                if not candidate_values and not value.startswith(("[", "{")):
                    candidate_values.append(value.rstrip(","))
            elif in_registry_array:
                if "]" in line:
                    in_registry_array = False
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", line))

            raw_candidates.extend(candidate_values)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._renovate_text_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)

        return "\n".join(lines)

    @staticmethod
    def _renovate_text_candidate_entry(raw_value: Any) -> str:
        value = ArtifactQueueProcessor._parse_key_value_scalar(str(raw_value or "").strip())
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _security_scanner_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not _security_scanner_config_artifact_label(source_hint):
            return ""

        allowed_keys = {
            "apiurl",
            "baseurl",
            "bcapiurl",
            "dbrepository",
            "downloadurl",
            "endpoint",
            "godatabaserepository",
            "host",
            "hostname",
            "hosturl",
            "javadatabaserepository",
            "pythondatabaserepository",
            "registry",
            "registryurl",
            "repositories",
            "repos",
            "repo",
            "repository",
            "server",
            "serverurl",
            "sonarhosturl",
            "sonarlinkscis",
            "sonarlinksci",
            "sonarlinkshomepage",
            "sonarlinksissue",
            "sonarlinks scm",
            "source",
            "tokenendpoint",
            "url",
            "urls",
            "weburl",
        }
        allowed_keys = {self._yaml_key_fingerprint(key) for key in allowed_keys}
        list_keys = {
            "dbrepository",
            "repositories",
            "repository",
            "repos",
            "repo",
            "urls",
        }

        raw_candidates: list[str] = []
        in_value_array = False

        def _append_raw_candidate(raw_value: str) -> None:
            if len(raw_candidates) >= 4096:
                return
            value = str(raw_value or "").strip()
            if not value:
                return
            raw_candidates.append(value)

        document = _safe_json_loads(str(text or "").strip())
        if isinstance(document, (dict, list)):
            for candidate in self._security_scanner_structured_document_values(
                document,
                allowed_keys,
                use_workers=True,
            ):
                _append_raw_candidate(candidate)

        assignment_pattern = re.compile(
            r"""
            ^\s*-?\s*
            ["']?(?P<key>[A-Za-z0-9_.-]+)["']?
            \s*[:=]\s*
            (?P<value>.+?)\s*,?\s*$
            """,
            re.VERBOSE,
        )

        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line or line.startswith(("#", "//", "/*", "*")):
                continue

            candidate_values: list[str] = []
            match = assignment_pattern.match(line)
            if match:
                key = self._yaml_key_fingerprint(str(match.group("key") or ""))
                if key not in allowed_keys:
                    in_value_array = False
                    continue
                value = str(match.group("value") or "").strip()
                if key in list_keys and "[" in value and "]" not in value:
                    in_value_array = True
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", value))
                if not candidate_values and not value.startswith(("[", "{", "!", "&", "*")):
                    candidate_values.append(value.rstrip(","))
            elif in_value_array:
                if "]" in line:
                    in_value_array = False
                candidate_values.extend(re.findall(r"""["']([^"']+)["']""", line))
                if not candidate_values:
                    bare_value = line.rstrip(",").strip()
                    if bare_value and not bare_value.startswith(("]", "{", "#", "//")):
                        candidate_values.append(bare_value)

            for candidate_value in candidate_values:
                _append_raw_candidate(candidate_value)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._security_scanner_config_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)

        return "\n".join(lines)

    def _security_scanner_structured_document_values(
        self,
        value: Any,
        allowed_keys: set[str],
        *,
        use_workers: bool,
    ) -> list[str]:
        if isinstance(value, dict):
            child_jobs = [
                (child_index, raw_key, child, allowed_keys)
                for child_index, (raw_key, child) in enumerate(list(value.items())[:4096])
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._security_scanner_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._security_scanner_structured_document_child_values_for_entry(
                        raw_key,
                        child,
                        allowed_keys,
                    )
                    for _child_index, raw_key, child, allowed_keys in child_jobs
                ]
            )
            return [
                candidate
                for child_values in child_batches
                for candidate in child_values
            ][:4096]
        if isinstance(value, list):
            item_jobs = [
                (item_index, None, item, allowed_keys)
                for item_index, item in enumerate(value[:4096])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._security_scanner_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._security_scanner_structured_document_values(
                        item,
                        allowed_keys,
                        use_workers=False,
                    )
                    for _item_index, _raw_key, item, allowed_keys in item_jobs
                ]
            )
            return [
                candidate
                for item_values in item_batches
                for candidate in item_values
            ][:4096]
        return []

    def _security_scanner_structured_document_child_values(
        self,
        child_job: tuple[int, Any, Any, set[str]],
    ) -> list[str]:
        _child_index, raw_key, child, allowed_keys = child_job
        if raw_key is None:
            return self._security_scanner_structured_document_values(
                child,
                allowed_keys,
                use_workers=False,
            )
        return self._security_scanner_structured_document_child_values_for_entry(
            raw_key,
            child,
            allowed_keys,
        )

    def _security_scanner_structured_document_child_values_for_entry(
        self,
        raw_key: Any,
        child: Any,
        allowed_keys: set[str],
    ) -> list[str]:
        values: list[str] = []
        key = self._yaml_key_fingerprint(str(raw_key or ""))
        if key in allowed_keys:
            values.extend(self._security_scanner_structured_value_values(child))
        if isinstance(child, (dict, list)):
            values.extend(
                self._security_scanner_structured_document_values(
                    child,
                    allowed_keys,
                    use_workers=False,
                )
            )
        return values[:4096]

    def _security_scanner_structured_value_values(self, value: Any) -> list[str]:
        if isinstance(value, (str, int, float)):
            candidate = str(value).strip()
            return [candidate] if candidate else []
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:4096]:
                values.extend(self._security_scanner_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        if isinstance(value, dict):
            values = []
            for item in list(value.values())[:4096]:
                values.extend(self._security_scanner_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        return []

    @staticmethod
    def _security_scanner_config_candidate_entry(raw_value: Any) -> str:
        value = ArtifactQueueProcessor._parse_key_value_scalar(str(raw_value or "").strip())
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _recon_tool_output_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not _recon_tool_output_artifact_label(source_hint):
            return ""

        allowed_keys = {
            "a",
            "aaaa",
            "base_uri",
            "data",
            "domain",
            "domains",
            "endpoint",
            "endpoints",
            "finalurl",
            "final_url",
            "fqdn",
            "fqdnname",
            "host",
            "hostname",
            "hostnames",
            "hosts",
            "input",
            "ip",
            "ipaddress",
            "ip_address",
            "ip_str",
            "ipv4",
            "ipv6",
            "ips",
            "items",
            "matches",
            "location",
            "matched",
            "matchedat",
            "matchedurl",
            "name",
            "observed_name",
            "observed_url",
            "origin",
            "origin_url",
            "page_url",
            "path",
            "port",
            "records",
            "requesturl",
            "redirect",
            "redirectlocation",
            "results",
            "responseurl",
            "baseurl",
            "scanurl",
            "services",
            "site",
            "siteurl",
            "subdomain",
            "subdomains",
            "target",
            "targethost",
            "targethostname",
            "targets",
            "targeturl",
            "templateurl",
            "uri",
            "url",
            "urls",
            "webserver",
            "web_url",
            "weburl",
        }
        allowed_keys = {self._yaml_key_fingerprint(key) for key in allowed_keys}

        raw_candidates: list[str] = []

        def _append_candidate(raw_value: str) -> None:
            if len(raw_candidates) >= 4096:
                return
            value = self._parse_key_value_scalar(str(raw_value or "").strip())
            if not value:
                return
            raw_candidates.append(value)

        raw_text = str(text or "").strip()
        document = _safe_json_loads(raw_text)
        if isinstance(document, (dict, list)):
            for candidate in self._recon_tool_output_structured_document_values(
                document,
                allowed_keys,
                use_workers=True,
            ):
                _append_candidate(candidate)

        if "<" in raw_text and ">" in raw_text:
            for tag_match in re.finditer(
                r"<\s*([A-Za-z0-9_.:-]+)(?:\s[^>]*)?>([^<>]{1,4096})<\s*/\s*\1\s*>",
                raw_text,
                re.IGNORECASE,
            ):
                key = self._yaml_key_fingerprint(str(tag_match.group(1) or ""))
                if key not in allowed_keys:
                    continue
                value = html.unescape(str(tag_match.group(2) or "").strip())
                if value:
                    _append_candidate(value)

        line_candidate_batches = self._run_ordered_local_batch(
            [(raw_line, allowed_keys) for raw_line in raw_text.splitlines()[:4096]],
            self._recon_tool_output_line_candidate_values,
            default_factory=list,
        )
        for line_candidate_batch in line_candidate_batches:
            for candidate in line_candidate_batch:
                _append_candidate(candidate)

        candidate_entries = self._run_ordered_local_batch(
            raw_candidates,
            self._recon_tool_output_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _recon_tool_output_line_candidate_values(
        self,
        line_job: tuple[str, set[str]],
    ) -> list[str]:
        raw_line, allowed_keys = line_job
        line = str(raw_line or "").strip()
        if not line or line.startswith(("#", "//")):
            return []
        line_document = _safe_json_loads(line)
        if isinstance(line_document, (dict, list)):
            return self._recon_tool_output_structured_document_values(
                line_document,
                allowed_keys,
                use_workers=False,
            )
        first_field = re.split(r"[\t, ]+", line, maxsplit=1)[0].strip()
        return [first_field] if first_field else []

    def _recon_tool_output_structured_document_values(
        self,
        value: Any,
        allowed_keys: set[str],
        *,
        use_workers: bool,
    ) -> list[str]:
        if isinstance(value, dict):
            child_jobs = [
                (raw_key, child, allowed_keys)
                for raw_key, child in list(value.items())[:4096]
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._recon_tool_output_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._recon_tool_output_structured_document_child_values(
                        child_job
                    )
                    for child_job in child_jobs
                ]
            )
            return [
                candidate
                for child_values in child_batches
                for candidate in child_values
            ][:4096]
        if isinstance(value, list):
            item_jobs = [
                (None, item, allowed_keys)
                for item in value[:4096]
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._recon_tool_output_structured_document_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._recon_tool_output_structured_document_child_values(
                        item_job
                    )
                    for item_job in item_jobs
                ]
            )
            return [
                candidate
                for item_values in item_batches
                for candidate in item_values
            ][:4096]
        return []

    def _recon_tool_output_structured_document_child_values(
        self,
        child_job: tuple[Any, Any, set[str]],
    ) -> list[str]:
        raw_key, child, allowed_keys = child_job
        if raw_key is None:
            return self._recon_tool_output_structured_document_values(
                child,
                allowed_keys,
                use_workers=False,
            )
        values: list[str] = []
        key = self._yaml_key_fingerprint(str(raw_key or ""))
        if key in allowed_keys:
            values.extend(self._recon_tool_output_structured_value_values(child))
        if isinstance(child, (dict, list)):
            values.extend(
                self._recon_tool_output_structured_document_values(
                    child,
                    allowed_keys,
                    use_workers=False,
                )
            )
        return values[:4096]

    def _recon_tool_output_structured_value_values(self, value: Any) -> list[str]:
        if isinstance(value, (str, int, float)):
            candidate = str(value).strip()
            return [candidate] if candidate else []
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:4096]:
                values.extend(self._recon_tool_output_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        if isinstance(value, dict):
            values = []
            for item in list(value.values())[:4096]:
                values.extend(self._recon_tool_output_structured_value_values(item))
                if len(values) >= 4096:
                    return values[:4096]
            return values
        return []

    @staticmethod
    def _recon_tool_output_candidate_entry(raw_value: str) -> str:
        value = ArtifactQueueProcessor._parse_key_value_scalar(str(raw_value or "").strip())
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _maven_xml_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "").strip()
        if not raw_text or "<" not in raw_text or ">" not in raw_text:
            return ""
        source_label = _maven_xml_config_artifact_label(source_hint)
        if not source_label and not re.search(r"<\s*(?:project|settings)\b", raw_text, re.IGNORECASE):
            return ""

        try:
            root = ElementTree.fromstring(raw_text)
        except ElementTree.ParseError:
            if not source_label:
                return ""
            raw_values = self._maven_xml_tag_text_fallback_values(raw_text)
        else:
            if not self._maven_xml_root_looks_supported(root, source_hint=source_hint):
                return ""
            raw_values = self._maven_xml_urlish_values(root)

        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._maven_xml_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @classmethod
    def _maven_xml_root_looks_supported(
        cls,
        root: ElementTree.Element,
        *,
        source_hint: str,
    ) -> bool:
        if _maven_xml_config_artifact_label(source_hint):
            return True
        root_tag = cls._xml_local_name(root.tag)
        tags = {cls._xml_local_name(element.tag) for element in root.iter()}
        if root_tag == "project":
            return bool(
                tags
                & {
                    "artifactid",
                    "build",
                    "developers",
                    "distributionmanagement",
                    "groupid",
                    "modelversion",
                    "pluginrepositories",
                    "repositories",
                    "scm",
                }
            )
        if root_tag == "settings":
            return bool(tags & {"localrepository", "mirrors", "pluginGroups", "profiles", "servers"})
        return False

    @classmethod
    def _maven_xml_urlish_values(cls, root: ElementTree.Element) -> list[str]:
        values: list[str] = []
        for element in root.iter():
            tag = cls._xml_local_name(element.tag)
            if tag not in {"connection", "developerconnection", "url"}:
                continue
            value = "".join(element.itertext()).strip()
            if value:
                values.append(value)
        return values

    @staticmethod
    def _maven_xml_tag_text_fallback_values(text: str) -> list[str]:
        return [
            str(match.group("value") or "").strip()
            for match in re.finditer(
                r"""
                <\s*(?:url|connection|developerConnection)\b[^>]*>
                (?P<value>.*?)
                <\s*/\s*(?:url|connection|developerConnection)\s*>
                """,
                str(text or ""),
                re.IGNORECASE | re.DOTALL | re.VERBOSE,
            )
        ]

    @staticmethod
    def _xml_local_name(tag: object) -> str:
        value = str(tag or "").strip()
        if "}" in value:
            value = value.rsplit("}", 1)[-1]
        if ":" in value:
            value = value.rsplit(":", 1)[-1]
        return value.lower()

    @staticmethod
    def _maven_xml_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        direct_match = re.search(r"https?://[^\s<>()\"']+", value, re.IGNORECASE)
        if direct_match:
            return _artifact_package_registry_url_candidate(direct_match.group(0))
        return _artifact_package_registry_host_or_url_candidate(value)

    def _gradle_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "")
        if not raw_text.strip():
            return ""
        source_label = _gradle_text_config_artifact_label(source_hint)
        source_name = Path(str(source_hint or "").replace("\\", "/")).name.lower()
        if not source_label and Path(source_name).suffix not in {".gradle", ".kts"}:
            return ""
        lowered = raw_text.lower()
        if not source_label and not any(
            marker in lowered
            for marker in (
                "dependencyresolutionmanagement",
                "pluginmanagement",
                "repositories",
                "maven(",
                "maven {",
            )
        ):
            return ""

        raw_values = self._gradle_text_repository_values(raw_text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._gradle_text_repository_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _gradle_text_repository_values(text: str) -> list[str]:
        return gradle_text_repository_values(text)

    @staticmethod
    def _gradle_text_repository_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    def _js_runtime_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
        base_url: str = "",
    ) -> str:
        raw_text = str(text or "")
        source_label = _js_runtime_config_artifact_label(source_hint)
        if not raw_text.strip() or not source_label:
            return ""

        raw_values = self._js_runtime_text_candidate_values(
            raw_text,
            source_label=source_label,
            base_url=base_url,
        )
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._js_runtime_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _js_runtime_text_candidate_values(
        self,
        text: str,
        *,
        source_label: str = "",
        base_url: str = "",
    ) -> list[str]:
        raw_text = str(text or "")
        entries: list[tuple[int, str]] = []
        if source_label == "firebase-hosting-config":
            entries.extend(
                (len(raw_text) + index, value)
                for index, value in enumerate(firebase_hosting_site_urls(raw_text))
            )
        family_batches = self._run_ordered_local_batch(
            [("package", raw_text), ("registry", raw_text)],
            self._js_runtime_text_candidate_family_entries,
            default_factory=list,
        )
        entries.extend(
            entry
            for family_entries in family_batches
            for entry in family_entries
        )

        in_bun_scope_block = False
        offset = 0
        scope_assignment_pattern = re.compile(
            r"""^\s*["']?@?[A-Za-z0-9_.\-/]+["']?\s*=\s*["'](?P<value>[^"']+)["']"""
        )
        for raw_line in raw_text.splitlines(keepends=True):
            line = raw_line.strip()
            lowered = line.lower()
            if lowered.startswith("[") and lowered.endswith("]"):
                in_bun_scope_block = lowered in {"[install.scopes]", "[install.scope]"}
            elif in_bun_scope_block:
                match = scope_assignment_pattern.match(line)
                value = str(match.group("value") or "").strip() if match else ""
                if value:
                    entries.append((offset + raw_line.find(value), value))
            offset += len(raw_line)

        if source_label == "runtime-js-config":
            entries.extend(
                runtime_js_env_assignment_entries(
                    raw_text,
                    derived_candidates=lambda env_map: self._run_ordered_local_batch(
                        self._yaml_structured_candidates_from_env_map(
                            env_map,
                            source_hint="runtime-js-config",
                        ),
                        lambda candidate: str(candidate or "").strip(),
                        default_factory=str,
                    ),
                )
            )
        if source_label == "service-worker-js":
            entries.extend(
                service_worker_js_candidate_entries(
                    raw_text,
                    base_url=base_url,
                    derived_candidates=lambda env_map: self._run_ordered_local_batch(
                        self._yaml_structured_candidates_from_env_map(
                            env_map,
                            source_hint="service-worker-js",
                        ),
                        lambda candidate: str(candidate or "").strip(),
                        default_factory=str,
                    ),
                )
            )

        if self._js_runtime_source_uses_browser_endpoint_patterns(source_label):
            browser_batches = self._run_ordered_local_batch(
                [
                    (index, pattern, raw_text)
                    for index, pattern in enumerate(
                        self._js_runtime_browser_endpoint_patterns()
                    )
                ],
                self._js_runtime_browser_endpoint_pattern_entries,
                default_factory=list,
            )
            entries.extend(
                entry
                for pattern_entries in browser_batches
                for entry in pattern_entries
            )

        entries.sort(key=lambda item: item[0])
        return [value for _index, value in entries]

    @staticmethod
    def _js_runtime_text_candidate_family_entries(
        item: tuple[str, str],
    ) -> list[tuple[int, str]]:
        family, raw_text = item
        if family == "package":
            return [
                (match.start(), value)
                for match in re.finditer(
                    r"""["'](?P<value>(?:npm|jsr):[^"']+)["']""",
                    raw_text,
                )
                if (value := str(match.group("value") or "").strip())
            ]
        if family == "registry":
            registry_pattern = re.compile(
                r"""
                ["']?
                (?P<key>
                    registry|registries|registryUrl|registry_url|
                    npmRegistryServer|npm_registry_server
                )
                ["']?
                \s*(?::|=)\s*
                ["'](?P<value>[^"']+)["']
                """,
                re.IGNORECASE | re.VERBOSE,
            )
            return [
                (match.start(), value)
                for match in registry_pattern.finditer(raw_text)
                if (value := str(match.group("value") or "").strip())
            ]
        return []

    @staticmethod
    def _js_runtime_source_uses_browser_endpoint_patterns(source_label: str) -> bool:
        return source_label in {
            "astro-config",
            "next-config",
            "nuxt-config",
            "playwright-config",
            "remix-config",
            "storybook-config",
            "svelte-config",
            "cypress-config",
            "testcafe-config",
            "vite-config",
            "webdriverio-config",
            "nightwatch-config",
            "capacitor-config",
            "expo-app-config",
            "expo-eas-config",
            "firebase-hosting-config",
            "firebase-app-hosting-config",
            "ionic-config",
            "netlify-config",
            "service-worker-js",
            "vercel-config",
            "render-config",
            "fly-config",
            "runtime-js-config",
            "railway-config",
            "azure-static-web-app-config",
            "amplify-config",
            "heroku-config",
            "heroku-app-json",
            "static-json-config",
            "cordova-config",
        }

    @staticmethod
    def _js_runtime_browser_endpoint_patterns() -> tuple[re.Pattern[str], ...]:
        key_pattern = r"""
            apiBase|apiBaseURL|apiBaseUrl|apiEndpoint|apiHost|apiHostname|
            apiURL|apiUrl|appURL|appUrl|assetPrefix|assets|base|baseURL|
            baseUrl|base_url|buildHookURL|buildHookUrl|callbackURL|callbackUrl|
            cdnURL|cdnUrl|contentURL|contentUrl|destination|domain|endpoint|
            endpointURL|endpointUrl|host|hostname|href|launchURL|launchUrl|
            launch_url|origin|publicPath|redirectURL|redirectUrl|serverURL|
            serverUrl|site|siteURL|siteUrl|src|staticURL|staticUrl|target|to|
            updatesURL|updatesUrl|url|webServerURL|webServerUrl|webURL|webUrl|
            website|websiteURL|websiteUrl
        """
        return (
            re.compile(
                rf"""
                ["']?\b(?:{key_pattern})\b["']?
                \s*(?::|=)\s*
                (?P<quote>["'])(?P<value>[^"'\s,}}\]]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
            re.compile(
                rf"""
                ["']?\b(?:{key_pattern})\b["']?
                \s*(?::|=)\s*
                [^,\n;]+?\|\|\s*
                (?P<quote>["'])(?P<value>[^"'\s,}}\]]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
        )

    @staticmethod
    def _js_runtime_browser_endpoint_pattern_entries(
        item: tuple[int, re.Pattern[str], str],
    ) -> list[tuple[int, str]]:
        _index, pattern, raw_text = item
        return [
            (match.start(), value)
            for match in pattern.finditer(raw_text)
            if (value := str(match.group("value") or "").strip())
        ]

    @staticmethod
    def _js_runtime_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        lowered = value.lower()
        if lowered.startswith(("npm:", "jsr:")):
            return ArtifactQueueProcessor._js_runtime_package_specifier_url_candidate(value)
        if "@" in value:
            return ""
        return _artifact_package_registry_host_or_url_candidate(value)

    @staticmethod
    def _js_runtime_package_specifier_url_candidate(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        lowered = value.lower()
        if lowered.startswith("npm:"):
            body = value.split(":", 1)[1]
            return _artifact_package_registry_url_candidate(
                _artifact_package_url_registry_candidate("npm", body)
            )
        if lowered.startswith("jsr:"):
            body = value.split(":", 1)[1]
            package_path = package_url_package_path(body, ecosystem="jsr")
            if not package_path:
                return ""
            return _normalize_artifact_text_url(
                f"https://jsr.io/{quote(package_path, safe='@/._-+~')}"
            )
        return ""

    def _static_hosting_control_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
        base_url: str = "",
    ) -> str:
        source_label = _js_runtime_config_artifact_label(source_hint)
        if source_label not in {
            "cloudflare-pages-routes",
            "static-hosting-headers",
            "static-hosting-redirects",
        }:
            return ""

        raw_values = self._static_hosting_control_candidate_values(
            text,
            source_label=source_label,
        )
        candidate_entries = self._run_ordered_local_batch(
            [(raw_value, base_url) for raw_value in raw_values],
            self._static_hosting_control_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            lowered = normalized.lower()
            if not normalized or lowered in seen:
                continue
            seen.add(lowered)
            lines.append(normalized)
        return "\n".join(lines)

    def _static_hosting_control_candidate_values(
        self,
        text: str,
        *,
        source_label: str,
    ) -> list[str]:
        raw_text = str(text or "")
        values: list[str] = []

        def _append(value: object) -> None:
            candidate = self._static_hosting_control_candidate_entry(value)
            if not candidate:
                return
            values.append(candidate)

        if source_label == "cloudflare-pages-routes":
            document = _safe_json_loads(raw_text)
            if isinstance(document, dict):
                route_jobs: list[object] = []
                for key in ("include", "exclude"):
                    raw_entries = document.get(key)
                    if isinstance(raw_entries, list):
                        for entry in raw_entries[:256]:
                            route_jobs.append(entry)
                for route in list(document.get("routes") or [])[:256]:
                    route_jobs.append(route)
                route_batches = self._run_ordered_local_batch(
                    route_jobs,
                    self._static_hosting_control_cloudflare_route_candidate_values,
                    default_factory=list,
                )
                for route_batch in route_batches:
                    for candidate in route_batch:
                        _append(candidate)

        line_batches = self._run_ordered_local_batch(
            [(source_label, raw_line) for raw_line in raw_text.splitlines()[:4096]],
            self._static_hosting_control_line_candidate_values,
            default_factory=list,
        )
        for batch in line_batches:
            values.extend(batch)
        return values[:4096]

    @staticmethod
    def _static_hosting_control_candidate_entry(value: object) -> str:
        candidate = str(value or "").strip().strip("\"'`<>")
        if not candidate:
            return ""
        lowered = candidate.lower()
        if lowered in {"-", "/", "/*", "/:splat", "/:path*", "200", "301", "302", "303", "307", "308"}:
            return ""
        return candidate

    @staticmethod
    def _static_hosting_control_cloudflare_route_candidate_values(value: object) -> list[str]:
        if isinstance(value, dict):
            candidate = (
                value.get("pattern")
                or value.get("path")
                or value.get("route")
                or ""
            )
        else:
            candidate = value
        normalized = ArtifactQueueProcessor._static_hosting_control_candidate_entry(candidate)
        return [normalized] if normalized else []

    @classmethod
    def _static_hosting_control_line_candidate_values(
        cls,
        item: tuple[str, str],
    ) -> list[str]:
        source_label, raw_line = item
        line = str(raw_line or "").strip()
        if not line or line.startswith("#"):
            return []
        values: list[str] = []

        def _append(value: object) -> None:
            candidate = cls._static_hosting_control_candidate_entry(value)
            if candidate:
                values.append(candidate)

        for angle_url in re.findall(r"<([^<>\s]+)>", line):
            _append(angle_url)

        parts = line.split()
        if not parts:
            return values

        first = parts[0].strip()
        if first.startswith(("/", "./", "../", "http://", "https://", "//")):
            _append(first)

        if source_label == "static-hosting-redirects" and len(parts) >= 2:
            target = parts[1].strip()
            if not re.fullmatch(r"\d{3}!?", target):
                _append(target)

        if source_label == "static-hosting-headers":
            for part in parts[1:]:
                if part.startswith(("http://", "https://", "//", "/", "./", "../")):
                    _append(part.rstrip(";"))

        return values

    @staticmethod
    def _static_hosting_control_url_candidate_entry(
        raw_entry: tuple[str, str],
    ) -> str:
        raw_value, base_url = raw_entry
        value = str(raw_value or "").strip().strip("\"'`<>")
        if not value:
            return ""
        parsed = urlparse(value)
        if parsed.scheme in {"http", "https"} and parsed.netloc:
            return _normalize_artifact_text_url(value)
        if value.startswith("//"):
            parsed_base = urlparse(str(base_url or "").strip())
            scheme = parsed_base.scheme if parsed_base.scheme in {"http", "https"} else "https"
            return _normalize_artifact_text_url(f"{scheme}:{value}")
        resolved = _resolve_artifact_route_url(
            value,
            base_url=base_url,
            allow_bare_file=True,
            allow_route_path=True,
        )
        if resolved:
            return resolved
        return _artifact_package_registry_host_or_url_candidate(value)

    def _api_spec_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "").strip()
        if not raw_text:
            return ""
        source_label = _api_spec_config_artifact_label(source_hint)
        parse_text = textwrap.dedent(raw_text).strip()
        document = self._api_spec_load_document(parse_text)
        if not source_label and not self._api_spec_document_looks_supported(document, parse_text):
            return ""

        if source_label == "openapi-overlay":
            raw_values = self._api_spec_overlay_text_candidate_values(parse_text)
            if not raw_values:
                raw_values = self._api_spec_document_candidate_values(document)
        else:
            raw_values = self._api_spec_document_candidate_values(document)
        if source_label and not raw_values:
            raw_values = self._api_spec_text_fallback_candidate_values(
                parse_text,
                source_label=source_label,
            )

        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._api_spec_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _api_spec_load_document(text: str) -> Any:
        raw_text = str(text or "").strip()
        if not raw_text:
            return None
        parsed = _safe_json_loads(raw_text)
        if parsed is not None:
            return parsed
        if yaml is None:
            return None
        try:
            documents = list(yaml.safe_load_all(raw_text))
        except Exception:  # noqa: BLE001
            return None
        for document in documents:
            if isinstance(document, (dict, list)):
                return document
        return None

    @classmethod
    def _api_spec_document_looks_supported(cls, document: Any, raw_text: str = "") -> bool:
        if isinstance(document, dict):
            normalized = cls._yaml_normalized_mapping(document)
            if any(key in normalized for key in ("openapi", "swagger", "asyncapi")):
                return True
            keys = set(normalized)
            if "info" in keys and (keys & {"paths", "components", "definitions", "channels"}):
                return True
        lowered = str(raw_text or "").lower()
        return any(marker in lowered for marker in ("openapi:", "swagger:", "asyncapi:"))

    def _api_spec_document_candidate_values(self, document: Any) -> list[str]:
        if not isinstance(document, (dict, list)):
            return []
        values: list[str] = []
        if isinstance(document, dict):
            values.extend(self._api_spec_swagger_server_candidates(document))
        values.extend(
            self._api_spec_value_candidate_values(
                document,
                (),
                use_workers=True,
            )
        )
        return values[:512]

    def _api_spec_value_candidate_values(
        self,
        value: Any,
        path: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        candidates: list[str] = []
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            is_server_mapping = self._api_spec_server_mapping_looks_supported(normalized)
            if is_server_mapping:
                candidates.extend(self._api_spec_server_mapping_candidates(value))
            child_jobs = [
                (child_index, key, child, path, is_server_mapping)
                for child_index, (key, child) in enumerate(value.items())
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._api_spec_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_spec_child_candidate_values_for_node(
                        key,
                        child,
                        path,
                        is_server_mapping,
                    )
                    for _child_index, key, child, path, is_server_mapping in child_jobs
                ]
            )
            for child_values in child_batches:
                candidates.extend(child_values)
            return candidates
        if isinstance(value, list):
            item_jobs = [
                (item_index, item, path)
                for item_index, item in enumerate(value[:256])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._api_spec_list_item_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_spec_value_candidate_values(
                        item,
                        path,
                        use_workers=False,
                    )
                    for _item_index, item, path in item_jobs
                ]
            )
            for item_values in item_batches:
                candidates.extend(item_values)
        return candidates

    def _api_spec_child_candidate_values(
        self,
        child_job: tuple[int, Any, Any, tuple[str, ...], bool],
    ) -> list[str]:
        _child_index, key, child, path, is_server_mapping = child_job
        return self._api_spec_child_candidate_values_for_node(
            key,
            child,
            path,
            is_server_mapping,
        )

    def _api_spec_child_candidate_values_for_node(
        self,
        key: Any,
        child: Any,
        path: tuple[str, ...],
        is_server_mapping: bool,
    ) -> list[str]:
        key_text = str(key or "").strip()
        key_fingerprint = self._yaml_key_fingerprint(key_text)
        child_path = (*path, key_fingerprint)
        if is_server_mapping and key_fingerprint in {
            "url",
            "host",
            "hostname",
            "protocol",
            "scheme",
            "pathname",
            "path",
            "basepath",
        }:
            return []
        candidates: list[str] = []
        if self._api_spec_key_is_urlish(key_fingerprint, path) and isinstance(
            child,
            (str, int, float),
        ):
            candidates.append(str(child))
        if self._api_spec_path_allows_urlish_map_keys(child_path):
            candidates.extend(self._api_spec_mapping_urlish_keys(child))
        candidates.extend(
            self._api_spec_value_candidate_values(
                child,
                child_path,
                use_workers=False,
            )
        )
        return candidates

    def _api_spec_list_item_candidate_values(
        self,
        item_job: tuple[int, Any, tuple[str, ...]],
    ) -> list[str]:
        _item_index, item, path = item_job
        return self._api_spec_value_candidate_values(
            item,
            path,
            use_workers=False,
        )

    @staticmethod
    def _api_spec_key_is_urlish(key_fingerprint: str, path: tuple[str, ...]) -> bool:
        if key_fingerprint in {
            "url",
            "urls",
            "termsofservice",
            "baseurl",
            "endpoint",
            "endpoints",
            "callbackurl",
            "callbackurls",
            "webhookurl",
            "webhookurls",
        }:
            return True
        if key_fingerprint in {"host", "hostname"} and path and path[-1] in {"server", "servers"}:
            return True
        return False

    @staticmethod
    def _api_spec_path_allows_urlish_map_keys(path: tuple[str, ...]) -> bool:
        return any(part in path for part in {"callbacks", "webhooks"})

    @staticmethod
    def _api_spec_mapping_urlish_keys(value: Any) -> list[str]:
        if not isinstance(value, dict):
            return []
        return [
            str(key or "").strip()
            for key in value
            if isinstance(key, str) and "://" in str(key)
        ][:64]

    @classmethod
    def _api_spec_server_mapping_looks_supported(cls, normalized: dict[str, Any]) -> bool:
        if "url" in normalized:
            return True
        return bool(
            ({"host", "hostname"} & set(normalized))
            and ({"protocol", "scheme"} & set(normalized))
        )

    def _api_spec_server_mapping_candidates(self, mapping: dict[str, Any]) -> list[str]:
        normalized = self._yaml_normalized_mapping(mapping)
        values: list[str] = []
        direct_url = self._yaml_ref_value(normalized, "url")
        if direct_url:
            values.append(direct_url)
        host = self._yaml_ref_value(normalized, "host", "hostname")
        if host:
            protocol = self._yaml_ref_value(normalized, "protocol", "scheme")
            path = self._yaml_ref_value(normalized, "pathname", "path", "basePath", "base_path")
            candidate = self._api_spec_host_protocol_candidate(host, protocol=protocol, path=path)
            if candidate:
                values.append(candidate)
        return values

    def _api_spec_swagger_server_candidates(self, mapping: dict[str, Any]) -> list[str]:
        normalized = self._yaml_normalized_mapping(mapping)
        if "swagger" not in normalized:
            return []
        host = self._yaml_ref_value(normalized, "host")
        if not host:
            return []
        base_path = self._yaml_ref_value(normalized, "basePath", "base_path")
        schemes_value = normalized.get("schemes") or normalized.get("scheme")
        schemes: list[str] = []
        if isinstance(schemes_value, list):
            schemes = [str(scheme or "").strip() for scheme in schemes_value[:8]]
        elif isinstance(schemes_value, (str, int, float)):
            schemes = [str(schemes_value).strip()]
        if not schemes:
            schemes = ["https"]
        candidates: list[str] = []
        for scheme in schemes:
            candidate = self._api_spec_host_protocol_candidate(host, protocol=scheme, path=base_path)
            if candidate:
                candidates.append(candidate)
        return candidates

    @staticmethod
    def _api_spec_host_protocol_candidate(
        host: str,
        *,
        protocol: str = "",
        path: str = "",
    ) -> str:
        host_value = str(host or "").strip().strip("\"'")
        if not host_value:
            return ""
        url_scheme = ArtifactQueueProcessor._api_spec_protocol_to_url_scheme(protocol)
        if host_value.lower().startswith(("http://", "https://", "ws://", "wss://")):
            candidate = host_value
        elif url_scheme:
            candidate = f"{url_scheme}://{host_value.lstrip('/')}"
        else:
            return ""
        path_value = str(path or "").strip()
        if path_value and not any(marker in path_value for marker in ("{", "}", "${", "{{")):
            parsed = urlparse(candidate)
            if parsed.scheme in {"http", "https", "ws", "wss"} and parsed.netloc:
                existing_path = str(parsed.path or "").rstrip("/")
                appended_path = "/" + path_value.strip("/")
                candidate = parsed._replace(path=f"{existing_path}{appended_path}").geturl()
        return candidate

    @staticmethod
    def _api_spec_protocol_to_url_scheme(protocol: str) -> str:
        lowered = str(protocol or "").strip().lower()
        if not lowered:
            return "https"
        if lowered in {"https", "http"}:
            return lowered
        if lowered in {"wss", "tls"}:
            return "https"
        if lowered == "ws":
            return "http"
        return ""

    @staticmethod
    def _api_spec_text_fallback_candidate_values(text: str, *, source_label: str = "") -> list[str]:
        values: list[str] = []
        source = str(source_label or "").strip().lower()
        key_pattern = (
            r"""
                url|urls|termsOfService|baseUrl|endpoint|endpoints|
                callbackUrl|callbackUrls|webhookUrl|webhookUrls|host
            """
            if source == "api-blueprint"
            else r"""
                url|urls|termsOfService|baseUrl|endpoint|endpoints|
                callbackUrl|callbackUrls|webhookUrl|webhookUrls
            """
        )
        urlish_line = re.compile(
            rf"""
            ^\s*(?:-\s*)?["']?
            (?P<key>
                {key_pattern}
            )
            ["']?\s*[:=]\s*["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        for line in str(text or "").splitlines()[:2048]:
            match = urlish_line.match(line)
            if not match:
                continue
            value = str(match.group("value") or "").strip()
            if value:
                values.append(value)
        return values

    @staticmethod
    def _api_spec_overlay_text_candidate_values(text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        pattern = re.compile(
            r"""
            ^\s*(?:-\s*)?["']?
            (?P<key>extends|url|urls|baseUrl|endpoint|endpoints)
            ["']?\s*[:=]\s*["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        values: list[str] = []
        for line in parse_text.splitlines()[:4096]:
            match = pattern.match(line)
            if not match:
                continue
            value = str(match.group("value") or "").strip().strip("\"'")
            if value:
                values.append(value)
        return values

    @staticmethod
    def _api_spec_url_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value or re.search(r"\s", value):
            return ""
        if any(marker in value for marker in ("{", "}", "${", "$(", "{{", "}}", "<", ">")):
            return ""
        lowered = value.lower()
        if lowered.startswith(("mailto:", "tel:", "s3://", "gs://")):
            return ""
        if lowered.startswith("wss://"):
            value = f"https://{value.split('://', 1)[1]}"
        elif lowered.startswith("ws://"):
            value = f"http://{value.split('://', 1)[1]}"
        normalized = _artifact_package_registry_host_or_url_candidate(value)
        if not normalized:
            return ""
        parsed = urlparse(normalized)
        hostname = str(parsed.hostname or "").strip().lower().strip(".")
        if hostname in {"localhost", "localhost.localdomain"}:
            return ""
        try:
            parsed_ip = ipaddress.ip_address(hostname)
        except ValueError:
            parsed_ip = None
        if parsed_ip is not None and _is_placeholder_host_ip(str(parsed_ip)):
            return ""
        return normalized

    def _api_client_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        raw_text = str(text or "").strip()
        if not raw_text or not _api_client_collection_artifact_label(source_hint):
            return ""
        parse_text = textwrap.dedent(raw_text).strip()
        source_label = _api_client_collection_artifact_label(source_hint)
        document = self._api_spec_load_document(parse_text)
        if source_label == "selenium-side":
            raw_values = self._api_client_selenium_side_candidate_values(document)
            if not raw_values:
                raw_values = self._api_client_document_candidate_values(document)
        elif source_label == "dredd-config":
            raw_values = self._api_client_dredd_candidate_values(document, parse_text)
        elif source_label == "schemathesis-config":
            raw_values = self._api_client_schemathesis_candidate_values(document, parse_text)
        elif source_label == "pactum-config":
            raw_values = self._api_client_pactum_candidate_values(document, parse_text)
        elif source_label == "pact-contract":
            raw_values = self._api_client_pact_contract_candidate_values(document, parse_text)
        elif source_label == "bruno":
            raw_values = self._api_client_bruno_candidate_values(document, parse_text)
        else:
            raw_values = self._api_client_document_candidate_values(document)
        text_families = ["jmeter"]
        if source_label == "k6-script":
            text_families.append("k6")
        if source_label == "locustfile":
            text_families.append("locust")
        for values in self._api_client_text_candidate_family_batches(text_families, parse_text):
            raw_values.extend(values)
        if not raw_values:
            fallback_batches = self._api_client_text_candidate_family_batches(("fallback",), parse_text)
            raw_values = list(fallback_batches[0]) if fallback_batches else []

        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._api_client_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _api_client_document_candidate_values(self, document: Any) -> list[str]:
        if not isinstance(document, (dict, list)):
            return []
        return self._api_client_value_candidate_values(
            document,
            (),
            use_workers=True,
        )[:512]

    def _api_client_value_candidate_values(
        self,
        value: Any,
        path: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        candidates: list[str] = []
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            url_object_candidate = self._api_client_url_object_candidate(value)
            if url_object_candidate:
                candidates.append(url_object_candidate)
            variable_candidate = self._api_client_variable_mapping_candidate(value)
            if variable_candidate:
                candidates.append(variable_candidate)
            child_jobs = [
                (child_index, key, child, path, self._api_client_url_object_looks_supported(normalized))
                for child_index, (key, child) in enumerate(value.items())
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._api_client_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_client_child_candidate_values_for_node(
                        key,
                        child,
                        path,
                        parent_url_object_supported,
                    )
                    for (
                        _child_index,
                        key,
                        child,
                        path,
                        parent_url_object_supported,
                    ) in child_jobs
                ]
            )
            for child_values in child_batches:
                candidates.extend(child_values)
            return candidates
        if isinstance(value, list):
            item_jobs = [
                (item_index, item, path)
                for item_index, item in enumerate(value[:512])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._api_client_list_item_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_client_value_candidate_values(
                        item,
                        path,
                        use_workers=False,
                    )
                    for _item_index, item, path in item_jobs
                ]
            )
            for item_values in item_batches:
                candidates.extend(item_values)
        return candidates

    def _api_client_child_candidate_values(
        self,
        child_job: tuple[int, Any, Any, tuple[str, ...], bool],
    ) -> list[str]:
        _child_index, key, child, path, parent_url_object_supported = child_job
        return self._api_client_child_candidate_values_for_node(
            key,
            child,
            path,
            parent_url_object_supported,
        )

    def _api_client_child_candidate_values_for_node(
        self,
        key: Any,
        child: Any,
        path: tuple[str, ...],
        parent_url_object_supported: bool,
    ) -> list[str]:
        key_text = str(key or "")
        key_fingerprint = self._yaml_key_fingerprint(key_text)
        child_path = (*path, key_fingerprint)
        if key_fingerprint in {"url", "rawurl", "baseurl", "endpoint", "target"}:
            if isinstance(child, dict):
                object_candidate = self._api_client_url_object_candidate(child)
                return [object_candidate] if object_candidate else []
            if isinstance(child, (str, int, float)):
                return [str(child)]
            return []
        if key_fingerprint == "raw" and parent_url_object_supported:
            if isinstance(child, (str, int, float)):
                return [str(child)]
            return []
        if self._api_client_variable_name_is_urlish(key_text) and isinstance(
            child,
            (str, int, float),
        ):
            return [str(child)]
        return self._api_client_value_candidate_values(
            child,
            child_path,
            use_workers=False,
        )

    def _api_client_list_item_candidate_values(
        self,
        item_job: tuple[int, Any, tuple[str, ...]],
    ) -> list[str]:
        _item_index, item, path = item_job
        return self._api_client_value_candidate_values(
            item,
            path,
            use_workers=False,
        )

    def _api_client_variable_mapping_candidate(self, value: dict[str, Any]) -> str:
        normalized = self._yaml_normalized_mapping(value)
        variable_name = self._yaml_ref_value(
            normalized,
            "key",
            "name",
            "id",
            "_key",
            "_name",
        )
        if not self._api_client_variable_name_is_urlish(variable_name):
            return ""
        variable_value = self._yaml_ref_value(
            normalized,
            "value",
            "currentValue",
            "current_value",
            "initialValue",
            "initial_value",
            "defaultValue",
            "default_value",
            "secretValue",
            "secret_value",
        )
        if not variable_value:
            return ""
        return variable_value

    @staticmethod
    def _api_client_variable_name_is_urlish(value: str) -> bool:
        fingerprint = ArtifactQueueProcessor._yaml_key_fingerprint(value)
        if not fingerprint:
            return False
        return any(
            marker in fingerprint
            for marker in (
                "url",
                "uri",
                "host",
                "hostname",
                "domain",
                "endpoint",
                "baseurl",
                "baseuri",
            )
        )

    def _api_client_selenium_side_candidate_values(self, document: Any) -> list[str]:
        if not isinstance(document, dict):
            return []

        base_values = self._api_client_selenium_side_base_values(document)
        normalized_bases = [
            normalized
            for normalized in (
                self._api_client_url_candidate_entry(base_value)
                for base_value in base_values
            )
            if normalized
        ]
        base_url = normalized_bases[0] if normalized_bases else ""
        values: list[str] = list(base_values)
        values.extend(self._api_client_selenium_side_navigation_values(document, base_url=base_url))
        return values[:512]

    @classmethod
    def _api_client_selenium_side_base_values(cls, document: dict[str, Any]) -> list[str]:
        values: list[str] = []
        for key in ("url", "baseUrl", "baseURL", "base_url", "origin"):
            value = document.get(key)
            if isinstance(value, (str, int, float)) and str(value or "").strip():
                values.append(str(value).strip())
        urls_value = document.get("urls")
        if isinstance(urls_value, list):
            for item in urls_value[:32]:
                if isinstance(item, (str, int, float)) and str(item or "").strip():
                    values.append(str(item).strip())
        return values

    def _api_client_selenium_side_navigation_values(
        self,
        value: Any,
        *,
        base_url: str,
    ) -> list[str]:
        return self._api_client_selenium_side_navigation_values_for_node(
            value,
            base_url=base_url,
            use_workers=True,
        )

    def _api_client_selenium_side_navigation_values_for_node(
        self,
        value: Any,
        *,
        base_url: str,
        use_workers: bool,
    ) -> list[str]:
        values: list[str] = []
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            command = str(normalized.get("command") or "").strip().lower().replace("_", "").replace("-", "")
            if command in {"open", "openwindow"}:
                for key in ("target", "url"):
                    candidate = self._api_client_selenium_side_navigation_target(
                        normalized.get(key),
                        base_url=base_url,
                    )
                    if candidate:
                        values.append(candidate)
            child_jobs = [
                (child_index, child, base_url)
                for child_index, child in enumerate(value.values())
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._api_client_selenium_side_navigation_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_client_selenium_side_navigation_values_for_node(
                        child,
                        base_url=base_url,
                        use_workers=False,
                    )
                    for _child_index, child, base_url in child_jobs
                ]
            )
            for child_values in child_batches:
                values.extend(child_values)
            return values
        if isinstance(value, list):
            item_jobs = [
                (item_index, item, base_url)
                for item_index, item in enumerate(value[:512])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._api_client_selenium_side_navigation_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._api_client_selenium_side_navigation_values_for_node(
                        item,
                        base_url=base_url,
                        use_workers=False,
                    )
                    for _item_index, item, base_url in item_jobs
                ]
            )
            for item_values in item_batches:
                values.extend(item_values)
        return values

    def _api_client_selenium_side_navigation_child_values(
        self,
        child_job: tuple[int, Any, str],
    ) -> list[str]:
        _child_index, child, base_url = child_job
        return self._api_client_selenium_side_navigation_values_for_node(
            child,
            base_url=base_url,
            use_workers=False,
        )

    @staticmethod
    def _api_client_selenium_side_navigation_target(value: Any, *, base_url: str) -> str:
        if not isinstance(value, (str, int, float)):
            return ""
        candidate = str(value or "").strip().strip("\"'")
        if not candidate or re.search(r"\s", candidate):
            return ""
        if any(marker in candidate for marker in ("{", "}", "${", "$(", "{{", "}}", "<", ">")):
            return candidate
        lowered = candidate.lower()
        if lowered.startswith(("http://", "https://", "ws://", "wss://")):
            return candidate
        if candidate.startswith("//"):
            parsed_protocol_relative = urlparse(f"https:{candidate}")
            hostname = str(parsed_protocol_relative.hostname or "")
            if "." in hostname:
                return f"https:{candidate}"
            return ""
        if candidate.startswith(("/", "./", "../")) and base_url:
            return urljoin(base_url.rstrip("/") + "/", candidate)
        if _artifact_package_registry_host_or_url_candidate(candidate):
            return candidate
        return ""

    def _api_client_dredd_candidate_values(self, document: Any, text: str) -> list[str]:
        text_batches = self._api_client_text_candidate_family_batches(("dredd",), text)
        values = list(text_batches[0]) if text_batches else []
        for value in self._api_client_document_candidate_values(document):
            if value not in values:
                values.append(value)
        return values[:512]

    def _api_client_dredd_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        pattern = re.compile(
            r"""
            ^\s*(?:-\s*)?["']?
            (?P<key>
                endpoint|base[-_]?url|base[-_]?uri|api[-_]?url|api[-_]?uri|
                blueprint|api[-_]?description|api[-_]?descriptions
            )
            ["']?\s*[:=]\s*["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        return self._api_client_api_config_line_candidate_values(parse_text, pattern)

    def _api_client_schemathesis_candidate_values(self, document: Any, text: str) -> list[str]:
        text_batches = self._api_client_text_candidate_family_batches(("schemathesis",), text)
        values = list(text_batches[0]) if text_batches else []
        for value in self._api_client_document_candidate_values(document):
            if value not in values:
                values.append(value)
        return values[:512]

    def _api_client_schemathesis_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        pattern = re.compile(
            r"""
            ^\s*(?:-\s*)?["']?
            (?P<key>
                schema|schema[-_]?url|base[-_]?url|base[-_]?uri|
                endpoint|endpoint[-_]?url|api[-_]?url|api[-_]?uri
            )
            ["']?\s*[:=]\s*["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        return self._api_client_api_config_line_candidate_values(parse_text, pattern)

    def _api_client_api_config_line_candidate_values(
        self,
        parse_text: str,
        pattern: re.Pattern[str],
    ) -> list[str]:
        line_entries = self._run_ordered_local_batch(
            [(line_index, line, pattern) for line_index, line in enumerate(parse_text.splitlines()[:4096])],
            self._api_client_api_config_line_candidate_value,
            default_factory=str,
        )
        return [str(value or "").strip() for value in line_entries if str(value or "").strip()]

    def _api_client_api_config_line_candidate_value(
        self,
        item: tuple[int, str, re.Pattern[str]],
    ) -> str:
        _line_index, line, pattern = item
        match = pattern.match(line)
        if not match:
            return ""
        return str(match.group("value") or "").strip().strip("\"'")

    def _api_client_pactum_candidate_values(self, document: Any, text: str) -> list[str]:
        text_batches = self._api_client_text_candidate_family_batches(("pactum", "fallback"), text)
        values = list(text_batches[0]) if text_batches else []
        for value in self._api_client_document_candidate_values(document):
            if value not in values:
                values.append(value)
        fallback_values = text_batches[1] if len(text_batches) > 1 else []
        for value in fallback_values:
            if value not in values:
                values.append(value)
        return values[:512]

    def _api_client_pactum_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        patterns = (
            re.compile(
                r"""
                \b(?:pactum\s*\.\s*)?(?:request\s*\.\s*)?setBaseUrl
                \s*\(\s*(?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
        )
        pattern_batches = self._run_ordered_local_batch(
            [(pattern_index, pattern, parse_text) for pattern_index, pattern in enumerate(patterns)],
            self._api_client_pactum_pattern_candidate_entries,
            default_factory=list,
        )
        candidates: list[tuple[int, str]] = []
        for pattern_entries in pattern_batches:
            candidates.extend(pattern_entries)
        candidates.sort(key=lambda item: item[0])
        return [value for _position, value in candidates[:512]]

    def _api_client_pactum_pattern_candidate_entries(
        self,
        item: tuple[int, re.Pattern[str], str],
    ) -> list[tuple[int, str]]:
        _pattern_index, pattern, parse_text = item
        entries: list[tuple[int, str]] = []
        for match in pattern.finditer(parse_text):
            value = str(match.group("value") or "").strip()
            if value:
                entries.append((match.start(), value))
        return entries

    def _api_client_pact_contract_candidate_values(self, document: Any, text: str) -> list[str]:
        return pact_contract_candidate_values(
            document,
            text,
            normalize_url=self._api_client_url_candidate_entry,
            document_values=self._api_client_document_candidate_values,
            fallback_values=self._api_client_text_fallback_candidate_values,
            is_urlish_key=self._api_client_variable_name_is_urlish,
        )

    def _api_client_bruno_candidate_values(self, document: Any, text: str) -> list[str]:
        values = self._api_client_document_candidate_values(document)
        values.extend(self._api_client_bruno_text_candidate_values(text))
        return values[:512]

    def _api_client_bruno_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if "{{" not in parse_text and "url:" not in parse_text.lower():
            return []
        field_pattern = re.compile(
            r"""
            ^\s*(?P<key>[A-Za-z][A-Za-z0-9_.-]{0,80})\s*:\s*
            (?P<value>[^\s#;,]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        variables: dict[str, str] = {}
        raw_entries: list[tuple[int, str]] = []
        offset = 0
        for line in parse_text.splitlines()[:4096]:
            match = field_pattern.match(line)
            if match:
                key = str(match.group("key") or "").strip()
                value = self._api_client_bruno_clean_value(match.group("value"))
                if value:
                    if self._api_client_variable_name_is_urlish(key) and "{{" not in value:
                        variables[key.lower()] = value
                    if self._api_client_bruno_field_is_endpoint(key):
                        raw_entries.append((offset + match.start("value"), value))
            offset += len(line) + 1
        resolved_entries = self._run_ordered_local_batch(
            [(position, value, variables) for position, value in raw_entries],
            self._api_client_bruno_resolved_candidate_entry,
            default_factory=lambda: (-1, ""),
        )
        return [
            value
            for _position, value in resolved_entries
            if value
        ][:512]

    @staticmethod
    def _api_client_bruno_clean_value(value: Any) -> str:
        return str(value or "").strip().strip("\"'`,")

    @staticmethod
    def _api_client_bruno_field_is_endpoint(value: str) -> bool:
        fingerprint = ArtifactQueueProcessor._yaml_key_fingerprint(value)
        return fingerprint in {
            "url",
            "rawurl",
            "baseurl",
            "baseuri",
            "endpoint",
            "host",
            "hostname",
            "target",
        }

    def _api_client_bruno_resolved_candidate_entry(
        self,
        item: tuple[int, str, dict[str, str]],
    ) -> tuple[int, str]:
        position, raw_value, variables = item
        value = self._api_client_bruno_resolve_variables(raw_value, variables)
        return (position, value)

    @staticmethod
    def _api_client_bruno_resolve_variables(
        raw_value: str,
        variables: dict[str, str],
    ) -> str:
        value = ArtifactQueueProcessor._api_client_bruno_clean_value(raw_value)
        if "{{" not in value:
            return value

        def _replace(match: re.Match[str]) -> str:
            variable_name = str(match.group(1) or "").strip().lower()
            replacement = variables.get(variable_name)
            if not replacement:
                return match.group(0)
            if replacement.endswith("/") and match.end() < len(value) and value[match.end()] == "/":
                return replacement.rstrip("/")
            return replacement

        return re.sub(r"\{\{\s*([A-Za-z0-9_.-]+)\s*\}\}", _replace, value)

    def _api_client_text_candidate_family_batches(
        self,
        families: Sequence[str],
        text: str,
    ) -> list[list[str]]:
        return self._run_ordered_local_batch(
            [(family, text) for family in families],
            self._api_client_text_candidate_family_values,
            default_factory=list,
        )

    def _api_client_text_candidate_family_values(self, item: tuple[str, str]) -> list[str]:
        family, text = item
        if family == "dredd":
            return self._api_client_dredd_text_candidate_values(text)
        if family == "schemathesis":
            return self._api_client_schemathesis_text_candidate_values(text)
        if family == "pactum":
            return self._api_client_pactum_text_candidate_values(text)
        if family == "fallback":
            return self._api_client_text_fallback_candidate_values(text)
        if family == "jmeter":
            return self._api_client_jmeter_text_candidate_values(text)
        if family == "k6":
            return self._api_client_k6_text_candidate_values(text)
        if family == "locust":
            return self._api_client_locust_text_candidate_values(text)
        return []

    def _api_client_url_object_candidate(self, value: Any) -> str:
        if not isinstance(value, dict):
            return ""
        normalized = self._yaml_normalized_mapping(value)
        if not self._api_client_url_object_looks_supported(normalized):
            return ""
        raw_value = self._yaml_ref_value(normalized, "raw", "url")
        if raw_value:
            candidate = self._api_client_url_candidate_entry(raw_value)
            if candidate:
                return candidate
        host = self._api_client_url_component_value(
            normalized.get("host") or normalized.get("hostname")
        )
        if not host:
            return ""
        protocol = self._yaml_ref_value(normalized, "protocol", "scheme")
        path_value = self._api_client_url_path_value(normalized.get("path") or normalized.get("pathname"))
        return self._api_spec_host_protocol_candidate(host, protocol=protocol, path=path_value)

    @staticmethod
    def _api_client_url_object_looks_supported(normalized: dict[str, Any]) -> bool:
        keys = set(normalized)
        if "raw" in keys:
            return True
        has_host = bool({"host", "hostname"} & keys)
        has_scheme = bool({"protocol", "scheme"} & keys)
        has_path = bool({"path", "pathname"} & keys)
        return bool(has_host and (has_scheme or has_path))

    @staticmethod
    def _api_client_url_component_value(value: Any) -> str:
        if isinstance(value, list):
            parts = [
                str(item or "").strip().strip("\"'")
                for item in value[:16]
                if isinstance(item, (str, int, float)) and str(item or "").strip()
            ]
            return ".".join(parts)
        if isinstance(value, (str, int, float)):
            return str(value).strip().strip("\"'")
        return ""

    @staticmethod
    def _api_client_url_path_value(value: Any) -> str:
        if isinstance(value, list):
            parts = [
                quote(str(item or "").strip().strip("\"'").strip("/"), safe="@._-+~")
                for item in value[:64]
                if isinstance(item, (str, int, float)) and str(item or "").strip().strip("/")
            ]
            return "/".join(parts)
        if isinstance(value, (str, int, float)):
            return str(value).strip().strip("\"'").strip("/")
        return ""

    def _api_client_text_fallback_candidate_values(self, text: str) -> list[str]:
        line_pattern = re.compile(
            r"""
            ^\s*(?:-\s*)?
            (?:(?:\*|Given|When|Then|And|But)\s+)?
            ["']?
            (?P<key>url|raw|baseUrl|baseUri|endpoint|endpoints|host|hostname|serviceUrl|target)
            ["']?(?:\s*[:=]\s*|\s+)["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        xml_attr_pattern = re.compile(
            r"""
            \b(?:url|baseUrl|baseUri|endpoint|host|hostname|serviceUrl)
            \s*=\s*
            (?P<quote>["'])(?P<value>.+?)(?P=quote)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        xml_endpoint_text_pattern = re.compile(
            r"""
            <[^>]*?(?:url|baseUrl|baseUri|endpoint|host|hostname|serviceUrl)[^>]*>
            \s*(?P<value>[^<>\s]+)\s*
            </[^>]+>
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        candidates: list[tuple[int, str]] = []
        offset = 0
        line_jobs: list[tuple[int, str, re.Pattern[str]]] = []
        for line in parse_text.splitlines()[:4096]:
            line_jobs.append((offset, line, line_pattern))
            offset += len(line) + 1
        line_entries = self._run_ordered_local_batch(
            line_jobs,
            self._api_client_text_fallback_line_candidate_entry,
            default_factory=lambda: (-1, ""),
        )
        candidates.extend(
            (position, value)
            for position, value in line_entries
            if position >= 0 and value
        )
        pattern_batches = self._run_ordered_local_batch(
            [
                (pattern_index, pattern, parse_text)
                for pattern_index, pattern in enumerate((xml_attr_pattern, xml_endpoint_text_pattern))
            ],
            self._api_client_text_fallback_pattern_candidate_entries,
            default_factory=list,
        )
        for pattern_entries in pattern_batches:
            candidates.extend(pattern_entries)
        candidates.sort(key=lambda item: item[0])
        return [value for _position, value in candidates[:512]]

    def _api_client_text_fallback_line_candidate_entry(
        self,
        item: tuple[int, str, re.Pattern[str]],
    ) -> tuple[int, str]:
        offset, line, pattern = item
        match = pattern.match(line)
        if not match:
            return (-1, "")
        value = str(match.group("value") or "").strip()
        if not value:
            return (-1, "")
        return (offset + match.start(), value)

    def _api_client_text_fallback_pattern_candidate_entries(
        self,
        item: tuple[int, re.Pattern[str], str],
    ) -> list[tuple[int, str]]:
        _pattern_index, pattern, parse_text = item
        entries: list[tuple[int, str]] = []
        for match in pattern.finditer(parse_text):
            value = str(match.group("value") or "").strip()
            if value:
                entries.append((match.start(), value))
        return entries

    def _api_client_jmeter_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if "HTTPSampler" not in parse_text and "jmeterTestPlan" not in parse_text:
            return []
        sampler_pattern = re.compile(
            r"<HTTPSamplerProxy\b[^>]*>(?P<body>.*?)</HTTPSamplerProxy>",
            re.IGNORECASE | re.DOTALL,
        )
        sampler_bodies = [
            str(sampler_match.group("body") or "")
            for sampler_match in sampler_pattern.finditer(parse_text)
        ]
        candidates = self._run_ordered_local_batch(
            sampler_bodies,
            self._api_client_jmeter_sampler_candidate_value,
            default_factory=str,
        )
        return [candidate for candidate in candidates if candidate]

    def _api_client_jmeter_sampler_candidate_value(self, body: str) -> str:
        prop_pattern = re.compile(
            r"""
            <stringProp\b[^>]*\bname=(?P<quote>["'])
            (?P<name>HTTPSampler\.(?:domain|protocol|path|port))
            (?P=quote)[^>]*>
            (?P<value>.*?)
            </stringProp>
            """,
            re.IGNORECASE | re.DOTALL | re.VERBOSE,
        )
        props: dict[str, str] = {}
        for prop_match in prop_pattern.finditer(str(body or "")):
            key = str(prop_match.group("name") or "").rsplit(".", 1)[-1].lower()
            value = html.unescape(str(prop_match.group("value") or "")).strip()
            if value:
                props[key] = value
        direct_path = str(props.get("path") or "").strip()
        if direct_path.lower().startswith(("http://", "https://", "ws://", "wss://")):
            return direct_path
        domain = str(props.get("domain") or "").strip()
        if not domain:
            return ""
        protocol = str(props.get("protocol") or "").strip()
        port = str(props.get("port") or "").strip()
        if port and not domain.endswith(f":{port}") and port.isdigit():
            domain = f"{domain}:{port}"
        return ArtifactQueueProcessor._api_spec_host_protocol_candidate(
            domain,
            protocol=protocol,
            path=direct_path,
        )

    def _api_client_k6_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not any(marker in parse_text for marker in ("http.", "ws.connect", "WebSocket", "baseURL", "baseUrl")):
            return []
        patterns = (
            re.compile(
                r"""
                \bhttp\.request\s*\(\s*
                (?P<method_quote>["'])[A-Z]+(?P=method_quote)\s*,\s*
                (?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
            re.compile(
                r"""
                \b(?:http\.(?:get|post|put|patch|del|delete|head|options)|ws\.connect|new\s+WebSocket)
                \s*\(\s*(?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
            re.compile(
                r"""
                \b(?:url|baseURL|baseUrl|base_uri|baseUri|endpoint|target)
                \s*[:=]\s*(?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
        )
        pattern_batches = self._run_ordered_local_batch(
            [(pattern_index, pattern, parse_text) for pattern_index, pattern in enumerate(patterns)],
            self._api_client_k6_pattern_candidate_entries,
            default_factory=list,
        )
        candidates: list[tuple[int, str]] = []
        for pattern_entries in pattern_batches:
            candidates.extend(pattern_entries)
        candidates.sort(key=lambda item: item[0])
        return [value for _position, value in candidates[:512]]

    def _api_client_k6_pattern_candidate_entries(
        self,
        item: tuple[int, re.Pattern[str], str],
    ) -> list[tuple[int, str]]:
        _pattern_index, pattern, parse_text = item
        entries: list[tuple[int, str]] = []
        for match in pattern.finditer(parse_text):
            value = str(match.group("value") or "").strip()
            if value:
                entries.append((match.start(), value))
        return entries

    def _api_client_locust_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not any(marker in parse_text for marker in ("HttpUser", "self.client", "host", "FastHttpUser")):
            return []
        patterns = (
            re.compile(
                r"""
                ^\s*(?:[A-Za-z_][\w.]*\.)?host\s*=\s*
                (?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.MULTILINE | re.VERBOSE,
            ),
            re.compile(
                r"""
                \bself\.client\.request\s*\(\s*
                (?P<method_quote>["'])[A-Z]+(?P=method_quote)\s*,\s*
                (?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
            re.compile(
                r"""
                \bself\.client\.(?:get|post|put|patch|delete|head|options)
                \s*\(\s*(?P<quote>["'])(?P<value>[^"'\s,]+)(?P=quote)
                """,
                re.IGNORECASE | re.VERBOSE,
            ),
        )
        pattern_batches = self._run_ordered_local_batch(
            [(pattern_index, pattern, parse_text) for pattern_index, pattern in enumerate(patterns)],
            self._api_client_locust_pattern_candidate_entries,
            default_factory=list,
        )
        candidates: list[tuple[int, str]] = []
        for pattern_entries in pattern_batches:
            candidates.extend(pattern_entries)
        candidates.sort(key=lambda item: item[0])
        return [value for _position, value in candidates[:512]]

    def _api_client_locust_pattern_candidate_entries(
        self,
        item: tuple[int, re.Pattern[str], str],
    ) -> list[tuple[int, str]]:
        _pattern_index, pattern, parse_text = item
        entries: list[tuple[int, str]] = []
        for match in pattern.finditer(parse_text):
            value = str(match.group("value") or "").strip()
            if value:
                entries.append((match.start(), value))
        return entries

    @staticmethod
    def _api_client_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    def _http_request_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not self._http_request_text_source_looks_supported(source_hint):
            return ""
        raw_values = self._http_request_text_candidate_values(text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._http_request_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _http_request_text_source_looks_supported(source_hint: str) -> bool:
        suffix = Path(str(source_hint or "").replace("\\", "/")).suffix.lower()
        return suffix in {".http", ".rest", ".hurl"}

    def _http_request_text_candidate_values(self, text: str) -> list[str]:
        line_entries = self._run_ordered_local_batch(
            str(text or "").splitlines()[:4096],
            self._http_request_text_line_candidate_value,
            default_factory=str,
        )
        return [str(value or "").strip() for value in line_entries if str(value or "").strip()]

    @staticmethod
    def _http_request_text_line_candidate_value(raw_line: str) -> str:
        line = str(raw_line or "").strip()
        if not line or line.startswith(("#", "//", "--")):
            return ""
        request_match = re.match(
            r"""
            ^\s*
            (?P<method>GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS|TRACE)
            \s+
            (?P<target>[^\s#]+)
            """,
            line,
            re.IGNORECASE | re.VERBOSE,
        )
        if request_match:
            return str(request_match.group("target") or "").strip()
        variable_match = re.match(
            r"""
            ^\s*@?
            (?P<key>[A-Za-z0-9_.\-]*?(?:url|uri|host|hostname|domain|endpoint|baseurl|baseuri)[A-Za-z0-9_.\-]*)
            \s*[:=]\s*
            (?P<value>[^\s#]+)
            """,
            line,
            re.IGNORECASE | re.VERBOSE,
        )
        if variable_match:
            return str(variable_match.group("value") or "").strip().strip("\"'")
        return ""

    @staticmethod
    def _http_request_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    def _http_transcript_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not parse_text.strip():
            return ""
        if not self._http_transcript_text_source_looks_supported(source_hint):
            return ""
        if not self._http_transcript_text_looks_supported(parse_text):
            return ""
        raw_values = self._http_transcript_text_candidate_values(parse_text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._http_transcript_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _http_transcript_text_source_looks_supported(source_hint: str) -> bool:
        normalized = str(source_hint or "").replace("\\", "/").lower()
        if not normalized:
            return False
        suffix = Path(normalized).suffix.lower()
        if suffix in {".http", ".rest"}:
            return True
        if ".saz/" in normalized or normalized.endswith(".saz"):
            return True
        if "#pcap-strings" in normalized:
            return True
        if re.search(r"(?:^|/)(?:raw/)?\d+_[cs]\.txt$", normalized):
            return True
        return bool(
            re.search(
                r"(?:^|/)(?:request|response|session|http)[-_]?(?:raw|headers)?\.txt$",
                normalized,
            )
        )

    @staticmethod
    def _http_transcript_text_looks_supported(text: str) -> bool:
        sample = str(text or "")[:16384]
        if _HTTP_TRANSCRIPT_REQUEST_LINE_RE.search(sample):
            return True
        return bool(re.search(r"(?im)^\s*HTTP/\d(?:\.\d)?\s+\d{3}\b", sample))

    def _http_transcript_text_candidate_values(self, text: str) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        values: list[str] = []
        for match in _HTTP_TRANSCRIPT_URL_FIELD_RE.finditer(parse_text):
            field_value = str(match.group("value") or "").strip().strip("\"'")
            if field_value:
                values.append(field_value)

        current_host = ""
        current_scheme = ""
        pending_targets: list[str] = []

        def flush_pending() -> None:
            nonlocal pending_targets
            if not current_host or not pending_targets:
                return
            for target in pending_targets:
                candidate = self._http_transcript_absolute_url(
                    target,
                    host=current_host,
                    scheme=current_scheme,
                )
                if candidate:
                    values.append(candidate)
            pending_targets = []

        for raw_line in parse_text.splitlines()[:4096]:
            line = raw_line.strip()
            if not line:
                current_host = ""
                current_scheme = ""
                pending_targets = []
                continue

            request_match = _HTTP_TRANSCRIPT_REQUEST_LINE_RE.match(line)
            if request_match:
                method = str(request_match.group("method") or "").upper()
                target = str(request_match.group("target") or "").strip()
                if method == "CONNECT":
                    connect_host = self._http_transcript_host_candidate(target)
                    if connect_host:
                        current_host = connect_host
                        current_scheme = "https"
                        values.append(f"https://{connect_host}")
                    continue
                if target.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
                    values.append(target)
                    parsed_target = urlparse(target if "://" in target else f"https:{target}")
                    if parsed_target.netloc:
                        current_host = parsed_target.netloc
                    if parsed_target.scheme:
                        current_scheme = parsed_target.scheme
                    continue
                if target.startswith("/"):
                    if current_host:
                        candidate = self._http_transcript_absolute_url(
                            target,
                            host=current_host,
                            scheme=current_scheme,
                        )
                        if candidate:
                            values.append(candidate)
                    else:
                        pending_targets.append(target)
                    continue

            header_match = _HTTP_TRANSCRIPT_HEADER_RE.match(line)
            if not header_match:
                continue
            name = str(header_match.group("name") or "").strip().lower()
            value = str(header_match.group("value") or "").strip().strip("\"'")
            if not value:
                continue
            if name in {"host", ":authority", "x-forwarded-host"}:
                host = self._http_transcript_host_candidate(value)
                if host:
                    current_host = host
                    flush_pending()
                continue
            if name in {":scheme", "x-forwarded-proto", "x-forwarded-protocol"}:
                scheme = self._http_transcript_scheme_candidate(value)
                if scheme:
                    current_scheme = scheme
                    flush_pending()
                continue
            if name in {
                "location",
                "content-location",
                "origin",
                "referer",
                "referrer",
                "x-original-url",
                "x-rewrite-url",
                "x-forwarded-uri",
                "x-forwarded-url",
            }:
                if value.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
                    values.append(value)
                elif value.startswith("/") and current_host:
                    candidate = self._http_transcript_absolute_url(
                        value,
                        host=current_host,
                        scheme=current_scheme,
                    )
                    if candidate:
                        values.append(candidate)

        return values[:512]

    @staticmethod
    def _http_transcript_host_candidate(value: str) -> str:
        candidate = str(value or "").strip().strip("\"'")
        if not candidate:
            return ""
        candidate = candidate.split(",", 1)[0].strip()
        candidate = candidate.split(";", 1)[0].strip()
        candidate = re.sub(r"^\w+://", "", candidate).strip("/")
        candidate = candidate.split("/", 1)[0].strip()
        candidate = candidate.split("@", 1)[-1].strip()
        if not candidate or re.search(r"\s", candidate):
            return ""
        return candidate

    @staticmethod
    def _http_transcript_scheme_candidate(value: str) -> str:
        scheme = str(value or "").strip().lower().split(",", 1)[0].strip()
        if scheme in {"http", "https", "ws", "wss"}:
            return scheme
        return ""

    def _http_transcript_absolute_url(
        self,
        target: str,
        *,
        host: str,
        scheme: str = "",
    ) -> str:
        host_candidate = self._http_transcript_host_candidate(host)
        if not host_candidate:
            return ""
        target_value = str(target or "").strip()
        if not target_value or target_value == "*":
            return ""
        if target_value.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
            return target_value
        if not target_value.startswith("/"):
            return ""
        url_scheme = self._http_transcript_scheme_candidate(scheme)
        if not url_scheme:
            lowered_host = host_candidate.lower()
            url_scheme = "http" if lowered_host.endswith(":80") else "https"
        return f"{url_scheme}://{host_candidate}{target_value}"

    @staticmethod
    def _http_transcript_url_candidate_entry(raw_value: str) -> str:
        candidate = _normalize_artifact_text_url(str(raw_value or "").strip().strip("\"'"))
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(candidate)

    def _structured_payload_lines(
        self,
        raw_values: Sequence[str],
        normalizer: Callable[[str], str],
        *,
        casefold_seen: bool,
    ) -> str:
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            normalizer,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            key = normalized.lower() if casefold_seen else normalized
            if not normalized or key in seen:
                continue
            seen.add(key)
            lines.append(normalized)
        return "\n".join(lines)

    @staticmethod
    def _ssh_payload_entry(raw_value: str) -> str:
        candidate = str(raw_value or "").strip().strip("[]")
        return f"ssh://{candidate}" if candidate else ""

    @staticmethod
    def _postgres_payload_entry(raw_value: str) -> str:
        candidate = str(raw_value or "").strip().strip("[]")
        return f"postgres://{candidate}" if candidate else ""

    @staticmethod
    def _trimmed_payload_entry(raw_value: str) -> str:
        return str(raw_value or "").strip()

    def _connection_client_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not connection_client_config_artifact_label(source_hint):
            return ""
        return self._structured_payload_lines(
            connection_client_host_candidates(text),
            self._ssh_payload_entry,
            casefold_seen=False,
        )

    def _database_client_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not database_client_config_artifact_label(source_hint):
            return ""
        return self._structured_payload_lines(
            database_client_endpoint_candidates(text),
            self._trimmed_payload_entry,
            casefold_seen=True,
        )

    def _storage_client_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not storage_client_config_artifact_label(source_hint):
            return ""
        return self._structured_payload_lines(
            storage_client_config_candidates(text),
            self._trimmed_payload_entry,
            casefold_seen=True,
        )

    def _amplify_client_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not amplify_client_config_artifact_label(source_hint):
            return ""
        return self._structured_payload_lines(
            amplify_client_config_text_candidates(text),
            self._trimmed_payload_entry,
            casefold_seen=True,
        )

    def _orm_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not orm_config_artifact_label(source_hint):
            return ""
        return self._structured_payload_lines(
            orm_config_host_candidates(text),
            self._postgres_payload_entry,
            casefold_seen=False,
        )

    def _framework_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not framework_config_artifact_label(source_hint):
            return ""
        db_payload = self._structured_payload_lines(
            framework_config_host_candidates(text),
            self._postgres_payload_entry,
            casefold_seen=False,
        )
        service_payload = self._structured_payload_lines(
            framework_config_service_endpoint_candidates(text),
            self._trimmed_payload_entry,
            casefold_seen=True,
        )
        return "\n".join(part for part in (db_payload, service_payload) if part)

    def _tunnel_config_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not tunnel_config_artifact_label(source_hint):
            return ""
        normalized = self._run_ordered_local_batch(
            tunnel_config_endpoint_candidates(text),
            lambda endpoint: self._edge_proxy_endpoint_url_candidate(endpoint, default_scheme="https"),
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for endpoint in normalized:
            lowered = endpoint.lower()
            if not endpoint or lowered in seen:
                continue
            seen.add(lowered)
            lines.append(endpoint)
        return "\n".join(lines)

    def _browser_state_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if _browser_state_artifact_label(source_hint) not in _BROWSER_STATE_STRUCTURED_LABELS:
            return ""
        documents = self._json_documents_from_text(text, source_hint=source_hint)
        if not documents:
            return ""
        raw_value_batches = self._run_ordered_local_batch(
            documents,
            self._browser_state_document_candidate_values,
            default_factory=list,
        )
        prepared_value_batches = self._run_ordered_local_batch(
            list(enumerate(raw_value_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        raw_values = [
            str(raw_value or "").strip()
            for raw_value_batch in prepared_value_batches
            for raw_value in raw_value_batch
            if str(raw_value or "").strip()
        ]
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._browser_state_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            lowered = normalized.lower()
            if not normalized or lowered in seen:
                continue
            seen.add(lowered)
            lines.append(normalized)
        return "\n".join(lines)

    def _browser_state_document_candidate_values(self, document: Any) -> list[str]:
        return self._browser_state_document_candidate_values_for_path((document, ()))

    def _browser_state_document_candidate_values_for_path(
        self,
        document_path: tuple[Any, tuple[str, ...]],
    ) -> list[str]:
        value, path = document_path
        candidates: list[str] = []

        def _append(value: Any) -> None:
            candidate = str(value or "").strip()
            if candidate:
                candidates.append(candidate)

        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            if self._browser_state_mapping_looks_like_cookie(normalized):
                _append(self._yaml_ref_value(normalized, "domain", "host", "hostname"))
            child_jobs = [
                (child, path, (*path, self._yaml_key_fingerprint(str(raw_key or ""))), normalized)
                for raw_key, child in list(value.items())[:512]
            ]
            child_batches = self._run_ordered_local_batch(
                child_jobs,
                self._browser_state_child_candidate_values,
                default_factory=list,
            )
            return self._browser_state_candidate_batch_values((candidates, *child_batches))
        if isinstance(value, list):
            item_batches = self._run_ordered_local_batch(
                [(item, path) for item in value[:512]],
                self._browser_state_document_candidate_values_for_path,
                default_factory=list,
            )
            return self._browser_state_candidate_batch_values(item_batches)
        return []

    def _browser_state_child_candidate_values(
        self,
        child_job: tuple[Any, tuple[str, ...], tuple[str, ...], dict[str, Any]],
    ) -> list[str]:
        child, parent_path, child_path, normalized = child_job
        key = child_path[-1] if child_path else ""
        candidates: list[str] = []
        if key == "value" and self._browser_state_path_allows_storage_value(parent_path, normalized):
            storage_name = self._yaml_ref_value(normalized, "name", "key")
            candidates.extend(
                self._browser_state_storage_value_candidates(
                    child,
                    child_path,
                    storage_name=storage_name,
                )
            )
        elif isinstance(child, (str, int, float)):
            child_text = str(child or "").strip()
            if key in _BROWSER_STATE_URLISH_FIELD_KEYS:
                candidates.append(child_text)
            elif (
                child_text.startswith(("s3://", "gs://"))
                or "://" in child_text
                or _classify_seed_value(child_text) == "email"
            ):
                candidates.append(child_text)
        candidates.extend(self._browser_state_document_candidate_values_for_path((child, child_path)))
        return self._browser_state_candidate_batch_values((candidates,))

    @staticmethod
    def _browser_state_candidate_batch_values(candidate_batches: Sequence[Sequence[str]]) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()
        for batch in candidate_batches:
            for value in batch:
                candidate = str(value or "").strip()
                lowered = candidate.lower()
                if not candidate or lowered in seen:
                    continue
                seen.add(lowered)
                candidates.append(candidate)
        return candidates[:1024]

    @staticmethod
    def _browser_state_mapping_looks_like_cookie(normalized: dict[str, Any]) -> bool:
        return bool(
            "domain" in normalized
            and "name" in normalized
            and (
                "value" in normalized
                or "path" in normalized
                or "expires" in normalized
                or "samesite" in normalized
            )
        )

    @staticmethod
    def _browser_state_path_allows_storage_value(path: tuple[str, ...], normalized: dict[str, Any]) -> bool:
        if any(part in _BROWSER_STATE_STORAGE_PATH_KEYS for part in path):
            return True
        return bool("name" in normalized and "value" in normalized and "domain" not in normalized)

    def _browser_state_storage_value_candidates(
        self,
        value: Any,
        path: tuple[str, ...],
        *,
        storage_name: str = "",
    ) -> list[str]:
        if not isinstance(value, (str, int, float)):
            return []
        raw_value = str(value or "").strip()
        if not raw_value:
            return []
        decoded = _safe_json_loads(raw_value)
        if isinstance(decoded, (dict, list)):
            return self._browser_state_document_candidate_values(decoded)
        if raw_value.startswith(("http://", "https://", "ws://", "wss://", "s3://", "gs://")):
            return [raw_value]
        if "://" in raw_value or "@" in raw_value:
            return [raw_value]
        if len(raw_value) <= 512 and not re.search(r"\s", raw_value):
            path_hint = ".".join((*path, self._yaml_key_fingerprint(storage_name)))
            if any(marker in path_hint for marker in ("url", "host", "origin", "endpoint", "api")):
                return [raw_value]
        return []

    @staticmethod
    def _browser_state_candidate_entry(raw_value: str) -> str:
        value = str(raw_value or "").strip().strip("\"'")
        if not value:
            return ""
        if _classify_seed_value(value) == "email":
            return value.lower()
        if value.lower().startswith(("s3://", "gs://")):
            return value
        if value.startswith(".") and re.fullmatch(r"\.[A-Za-z0-9][A-Za-z0-9.-]{1,253}", value):
            value = value.lstrip(".")
        return ArtifactQueueProcessor._http_transcript_url_candidate_entry(value)

    def _charles_session_json_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if _artifact_format_label(source_hint) != "charles-session-json":
            return ""
        document = _safe_json_loads(str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES])
        if not isinstance(document, (dict, list)):
            return ""
        raw_values = self._charles_session_json_candidate_values(document)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._charles_session_json_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _charles_session_json_candidate_values(self, document: Any) -> list[str]:
        candidate_batches: list[list[str]] = []
        if isinstance(document, dict):
            normalized = self._yaml_normalized_mapping(document)
            candidate_batches.append(
                self._charles_session_mapping_url_candidates(document, normalized)
            )
            children = list(document.values())[:512]
        elif isinstance(document, list):
            children = list(document[:512])
        else:
            children = []
        candidate_batches.extend(
            self._run_ordered_local_batch(
                list(enumerate(children)),
                self._charles_session_json_child_candidate_values,
                default_factory=list,
            )
        )
        return self._charles_session_candidate_batch_values(candidate_batches)

    def _charles_session_json_child_candidate_values(
        self,
        child_job: tuple[int, Any],
    ) -> list[str]:
        _child_index, child = child_job
        return self._charles_session_json_candidate_values(child)

    @staticmethod
    def _charles_session_candidate_batch_values(
        candidate_batches: Sequence[Sequence[str]],
    ) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()
        for batch in candidate_batches:
            for value in batch:
                candidate = str(value or "").strip()
                lowered = candidate.lower()
                if not candidate or lowered in seen:
                    continue
                seen.add(lowered)
                candidates.append(candidate)
                if len(candidates) >= 512:
                    return candidates
        return candidates

    def _charles_session_mapping_url_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> list[str]:
        candidates: list[str] = []
        for key in (
            "url",
            "requestUrl",
            "request_url",
            "targetUrl",
            "target_url",
            "originalUrl",
            "original_url",
            "redirectUrl",
            "redirect_url",
            "location",
        ):
            value = self._yaml_ref_value(normalized, key)
            if value:
                candidates.append(value)

        request_origin = self._charles_session_request_origin_url(normalized)
        if request_origin:
            candidates.append(request_origin)

        for redirect in self._charles_session_response_redirect_values(normalized):
            if redirect.lower().startswith(("http://", "https://", "ws://", "wss://", "//")):
                candidates.append(redirect)
            elif redirect.startswith("/") and request_origin:
                candidates.append(urljoin(f"{request_origin.rstrip('/')}/", redirect))

        return candidates

    def _charles_session_request_origin_url(self, normalized: dict[str, Any]) -> str:
        request_value = normalized.get("request")
        if isinstance(request_value, dict):
            request_normalized = self._yaml_normalized_mapping(request_value)
            direct = self._yaml_ref_value(request_normalized, "url", "requestUrl", "request_url")
            if direct:
                candidate = self._charles_session_json_url_candidate_entry(direct)
                parsed = urlparse(candidate)
                if parsed.scheme in {"http", "https"} and parsed.netloc:
                    return parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")
            nested_origin = self._charles_session_request_origin_url(request_normalized)
            if nested_origin:
                return nested_origin

        direct = self._yaml_ref_value(normalized, "url", "requestUrl", "request_url")
        if direct:
            candidate = self._charles_session_json_url_candidate_entry(direct)
            parsed = urlparse(candidate)
            if parsed.scheme in {"http", "https"} and parsed.netloc:
                return parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")

        host = self._yaml_ref_value(normalized, "host", "hostname", "domain")
        if not host:
            return ""
        path = self._yaml_ref_value(normalized, "path", "uri", "urlPath", "url_path", "requestPath", "request_path")
        scheme = self._yaml_ref_value(normalized, "scheme", "protocol")
        port = self._yaml_ref_value(normalized, "port")
        secure = self._yaml_ref_value(normalized, "ssl", "secure", "tls")
        host_candidate = self._http_transcript_host_candidate(host)
        if not host_candidate:
            return ""
        if port and str(port).isdigit() and ":" not in host_candidate:
            host_candidate = f"{host_candidate}:{port}"
        if not scheme:
            secure_value = str(secure or "").strip().lower()
            if secure_value in {"true", "1", "yes"}:
                scheme = "https"
            elif secure_value in {"false", "0", "no"}:
                scheme = "http"
        if not path:
            path = "/"
        return self._http_transcript_absolute_url(path, host=host_candidate, scheme=scheme)

    def _charles_session_response_redirect_values(self, normalized: dict[str, Any]) -> list[str]:
        values: list[str] = []
        response_value = normalized.get("response")
        if isinstance(response_value, dict):
            response_normalized = self._yaml_normalized_mapping(response_value)
            for key in ("redirectUrl", "redirect_url", "location"):
                direct = self._yaml_ref_value(response_normalized, key)
                if direct:
                    values.append(direct)
            values.extend(self._charles_session_header_values(response_normalized, {"location", "content-location"}))
        values.extend(self._charles_session_header_values(normalized, {"location", "content-location"}))
        return values[:64]

    def _charles_session_header_values(
        self,
        normalized: dict[str, Any],
        names: set[str],
    ) -> list[str]:
        values: list[str] = []
        header_value = normalized.get("headers") or normalized.get("responseheaders") or normalized.get("response_headers")
        header_items: list[Any] = []
        if isinstance(header_value, list):
            header_items = header_value[:256]
        elif isinstance(header_value, dict):
            header_items = [header_value]
        for item in header_items:
            if isinstance(item, dict):
                item_normalized = self._yaml_normalized_mapping(item)
                name = str(self._yaml_ref_value(item_normalized, "name", "key") or "").strip().lower()
                value = self._yaml_ref_value(item_normalized, "value")
                if name in names and value:
                    values.append(value)
                for header_name in names:
                    direct = self._yaml_ref_value(item_normalized, header_name)
                    if direct:
                        values.append(direct)
            elif isinstance(item, str):
                header_match = _HTTP_TRANSCRIPT_HEADER_RE.match(item.strip())
                if not header_match:
                    continue
                name = str(header_match.group("name") or "").strip().lower()
                value = str(header_match.group("value") or "").strip()
                if name in names and value:
                    values.append(value)
        return values

    @staticmethod
    def _charles_session_json_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._http_transcript_url_candidate_entry(raw_value)

    def _burp_site_map_xml_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if _burp_site_map_artifact_label(source_hint) != "burp-site-map":
            return ""
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not parse_text.strip():
            return ""
        try:
            root = ElementTree.fromstring(parse_text)
        except Exception:  # noqa: BLE001
            return ""
        item_nodes = [
            node
            for node in list(root.iter())[:512]
            if self._xml_local_name(str(node.tag or "")).lower() == "item"
        ]
        if not item_nodes:
            item_nodes = [root]
        item_batches = self._run_ordered_local_batch(
            item_nodes[:128],
            self._burp_site_map_item_payload_text,
            default_factory=str,
        )
        prepared_batches = self._run_ordered_local_batch(
            list(enumerate(item_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for batch in prepared_batches:
            for candidate in batch:
                value = str(candidate or "").strip()
                lowered = value.lower()
                if not value or lowered in seen:
                    continue
                seen.add(lowered)
                lines.append(value)
        return "\n".join(lines)

    def _burp_site_map_item_payload_text(self, item: Any) -> list[str]:
        if not hasattr(item, "tag"):
            return []
        direct_url = self._burp_xml_child_text(item, "url")
        host = self._burp_xml_child_text(item, "host")
        path = self._burp_xml_child_text(item, "path")
        protocol = self._burp_xml_child_text(item, "protocol") or self._burp_xml_child_text(item, "scheme")

        lines: list[str] = []
        origin_url = ""
        if direct_url:
            candidate = self._burp_site_map_url_candidate_entry(direct_url)
            if candidate:
                lines.append(candidate)
                parsed = urlparse(candidate)
                if parsed.scheme in {"http", "https"} and parsed.netloc:
                    origin_url = parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")
        if host and path:
            candidate = self._http_transcript_absolute_url(path, host=host, scheme=protocol)
            normalized = self._burp_site_map_url_candidate_entry(candidate)
            if normalized:
                lines.append(normalized)
                if not origin_url:
                    parsed = urlparse(normalized)
                    origin_url = parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")

        request_text = self._burp_xml_named_payload_text(item, "request")
        response_text = self._burp_xml_named_payload_text(item, "response")
        for transcript_text in (request_text, response_text):
            if transcript_text:
                lines.append(transcript_text[:4096])
        for value in self._http_transcript_text_candidate_values(request_text):
            candidate = self._burp_site_map_url_candidate_entry(value)
            if candidate:
                lines.append(candidate)
                if not origin_url:
                    parsed = urlparse(candidate)
                    if parsed.scheme in {"http", "https"} and parsed.netloc:
                        origin_url = parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")
        if origin_url:
            for location in self._saz_response_relative_locations(response_text):
                candidate = self._burp_site_map_url_candidate_entry(urljoin(f"{origin_url}/", location))
                if candidate:
                    lines.append(candidate)
        return lines

    @classmethod
    def _burp_xml_child_text(cls, item: Any, child_name: str) -> str:
        child_name_normalized = str(child_name or "").strip().lower()
        for child in list(item)[:256]:
            if cls._xml_local_name(str(getattr(child, "tag", "") or "")).lower() != child_name_normalized:
                continue
            return cls._xml_element_text(child)
        return ""

    @classmethod
    def _burp_xml_named_payload_text(cls, item: Any, child_name: str) -> str:
        child_name_normalized = str(child_name or "").strip().lower()
        for child in list(item)[:256]:
            if cls._xml_local_name(str(getattr(child, "tag", "") or "")).lower() != child_name_normalized:
                continue
            text_value = cls._xml_element_text(child)
            if str(child.attrib.get("base64") or "").strip().lower() == "true":
                try:
                    decoded = base64.b64decode(text_value.encode("ascii", errors="ignore"), validate=False)
                except Exception:  # noqa: BLE001
                    return ""
                return cls._decode_text_artifact_bytes(decoded[:_MAX_ARTIFACT_MEMBER_BYTES])
            return text_value
        return ""

    @staticmethod
    def _xml_local_name(value: str) -> str:
        text = str(value or "")
        if "}" in text:
            return text.rsplit("}", 1)[-1]
        return text.rsplit(":", 1)[-1]

    @staticmethod
    def _xml_element_text(element: Any) -> str:
        try:
            return "".join(element.itertext()).replace("\x00", "").strip()
        except Exception:  # noqa: BLE001
            return ""

    @staticmethod
    def _burp_site_map_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._http_transcript_url_candidate_entry(raw_value)

    def _extract_burp_site_map_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        text = self._read_text(path)
        payloads = self._burp_site_map_payload_tuples(text, str(path), path.name)
        return payloads or [(str(path), path.name, text)]

    def _burp_site_map_payload_tuples(
        self,
        text: str,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not parse_text.strip():
            return []
        try:
            root = ElementTree.fromstring(parse_text)
        except Exception:  # noqa: BLE001
            return []
        item_nodes = [
            node
            for node in list(root.iter())[:512]
            if self._xml_local_name(str(node.tag or "")).lower() == "item"
        ]
        if not item_nodes:
            return []
        payload_batches = self._run_ordered_local_batch(
            list(enumerate(item_nodes[:128], start=1)),
            lambda item_job: self._burp_site_map_item_payload_tuples(
                item_job,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_batches = self._run_ordered_local_batch(
            list(enumerate(payload_batches)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for batch in prepared_batches:
            payloads.extend(batch)
        return payloads

    def _burp_site_map_item_payload_tuples(
        self,
        item_job: tuple[int, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        index, item = item_job
        payloads: list[tuple[str, str, str]] = []
        summary_text = "\n".join(self._burp_site_map_item_payload_text(item))
        if summary_text.strip():
            payloads.append((source_file, f"{member_name}#burp-item-{index}", summary_text))
        request_text = self._burp_xml_named_payload_text(item, "request")
        if request_text.strip():
            payloads.append((source_file, f"{member_name}#burp-request-{index}.txt", request_text))
        response_text = self._burp_xml_named_payload_text(item, "response")
        if response_text.strip():
            payloads.append((source_file, f"{member_name}#burp-response-{index}.txt", response_text))
        return payloads

    def _graphql_config_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        if not _graphql_config_artifact_label(source_hint):
            return ""
        parse_text = textwrap.dedent(str(text or "")).strip()
        if not parse_text:
            return ""
        document = self._api_spec_load_document(parse_text)
        raw_values = self._graphql_config_document_candidate_values(document)
        if not raw_values:
            raw_values = self._graphql_config_text_fallback_candidate_values(parse_text)
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._graphql_config_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _graphql_config_document_candidate_values(self, document: Any) -> list[str]:
        if not isinstance(document, (dict, list)):
            return []
        return self._graphql_config_value_candidate_values(document, ())[:512]

    def _graphql_config_value_candidate_values(
        self,
        value: Any,
        path: tuple[str, ...],
    ) -> list[str]:
        return self._graphql_config_value_candidate_values_for_node(
            value,
            path,
            use_workers=True,
        )

    def _graphql_config_value_candidate_values_for_node(
        self,
        value: Any,
        path: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        candidates: list[str] = []
        if isinstance(value, dict):
            child_jobs = [
                (child_index, key, child, path)
                for child_index, (key, child) in enumerate(value.items())
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._graphql_config_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._graphql_config_child_candidate_values_for_node(
                        key,
                        child,
                        path,
                    )
                    for _child_index, key, child, path in child_jobs
                ]
            )
            for child_values in child_batches:
                candidates.extend(child_values)
            return candidates
        if isinstance(value, list):
            item_jobs = [
                (item_index, item, path)
                for item_index, item in enumerate(value[:512])
            ]
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._graphql_config_list_item_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._graphql_config_value_candidate_values_for_node(
                        item,
                        path,
                        use_workers=False,
                    )
                    for _item_index, item, path in item_jobs
                ]
            )
            for item_values in item_batches:
                candidates.extend(item_values)
        return candidates

    def _graphql_config_child_candidate_values(
        self,
        child_job: tuple[int, Any, Any, tuple[str, ...]],
    ) -> list[str]:
        _child_index, key, child, path = child_job
        return self._graphql_config_child_candidate_values_for_node(key, child, path)

    def _graphql_config_child_candidate_values_for_node(
        self,
        key: Any,
        child: Any,
        path: tuple[str, ...],
    ) -> list[str]:
        key_text = str(key or "")
        key_fingerprint = self._yaml_key_fingerprint(key_text)
        child_path = (*path, key_fingerprint)
        candidates: list[str] = []
        if self._graphql_config_key_is_urlish(key_fingerprint) and not isinstance(child, dict):
            candidates.extend(self._graphql_config_scalar_values(child))
        candidates.extend(
            self._graphql_config_value_candidate_values_for_node(
                child,
                child_path,
                use_workers=False,
            )
        )
        return candidates

    def _graphql_config_list_item_candidate_values(
        self,
        item_job: tuple[int, Any, tuple[str, ...]],
    ) -> list[str]:
        _item_index, item, path = item_job
        return self._graphql_config_value_candidate_values_for_node(
            item,
            path,
            use_workers=False,
        )

    @staticmethod
    def _graphql_config_key_is_urlish(key_fingerprint: str) -> bool:
        return key_fingerprint in {
            "schema",
            "schemas",
            "endpoint",
            "endpoints",
            "url",
            "urls",
            "uri",
            "uris",
            "baseurl",
            "baseuri",
            "serviceurl",
            "serviceuri",
        }

    def _graphql_config_scalar_values(self, value: Any) -> list[str]:
        if isinstance(value, (str, int, float)):
            return [str(value)]
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:128]:
                values.extend(self._graphql_config_scalar_values(item))
            return values
        if isinstance(value, dict):
            values = []
            for child in list(value.values())[:128]:
                values.extend(self._graphql_config_scalar_values(child))
            return values
        return []

    @staticmethod
    def _graphql_config_text_fallback_candidate_values(text: str) -> list[str]:
        key_pattern = re.compile(
            r"""
            ["']?
            (?P<key>schema|schemas|endpoint|endpoints|url|urls|uri|uris|baseUrl|baseUri|serviceUrl|serviceUri)
            ["']?
            \s*[:=]\s*
            ["'](?P<quoted>[^"']+)["']
            |
            ^\s*
            (?P<line_key>schema|endpoint|url|uri|baseUrl|baseUri|serviceUrl|serviceUri)
            \s*[:=]\s*
            (?P<bare>[^\s"',}\]]+)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        values: list[str] = []
        for match in key_pattern.finditer(str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]):
            value = str(match.group("quoted") or match.group("bare") or "").strip()
            if value:
                values.append(value)
        return values

    @staticmethod
    def _graphql_config_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    def _interface_definition_text_structured_payload_text(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> str:
        source_label = _interface_definition_artifact_label(source_hint)
        if not source_label:
            return ""
        raw_values = self._interface_definition_text_candidate_values(
            text,
            source_hint=source_hint,
        )
        candidate_entries = self._run_ordered_local_batch(
            raw_values,
            self._interface_definition_url_candidate_entry,
            default_factory=str,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            normalized = str(candidate or "").strip()
            if not normalized or normalized.lower() in seen:
                continue
            seen.add(normalized.lower())
            lines.append(normalized)
        return "\n".join(lines)

    def _interface_definition_text_candidate_values(
        self,
        text: str,
        *,
        source_hint: str = "",
    ) -> list[str]:
        parse_text = str(text or "")[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not parse_text.strip():
            return []

        key_value_pattern = re.compile(
            r"""
            ^\s*(?:-\s*)?["']?
            (?P<key>
                [A-Za-z0-9_.\-]*
                (?:baseUri|baseUrl|endpoint|url|uri|address|location|callbackUrl|serviceUrl|target|schema)
                [A-Za-z0-9_.\-]*
            )
            ["']?\s*[:=]\s*["']?(?P<value>[^\s"',\]]+)
            """,
            re.IGNORECASE | re.MULTILINE | re.VERBOSE,
        )
        xml_attr_pattern = re.compile(
            r"""
            \b(?:location|base|url|endpoint|address)
            \s*=\s*
            (?P<quote>["'])(?P<value>.+?)(?P=quote)
            """,
            re.IGNORECASE | re.VERBOSE,
        )
        proto_option_pattern = re.compile(
            r"""
            \boption\s+
            (?:
                \([^)]*(?:endpoint|url|uri|address|location)[^)]*\)|
                [A-Za-z0-9_.\-]*(?:endpoint|url|uri|address|location)[A-Za-z0-9_.\-]*
            )
            \s*=\s*
            (?P<quote>["'])(?P<value>.+?)(?P=quote)
            """,
            re.IGNORECASE | re.VERBOSE,
        )

        is_buf_config = bool(_buf_config_artifact_label(source_hint))
        pattern_jobs: list[tuple[str, Any, str]] = [
            ("key_value", key_value_pattern, parse_text),
            ("xml_attr", xml_attr_pattern, parse_text),
            ("proto_option", proto_option_pattern, parse_text),
        ]
        if is_buf_config:
            pattern_jobs.append(("buf_registry", self._buf_config_registry_ref_pattern(), parse_text))

        candidates: list[tuple[int, str]] = []
        pattern_batches = self._run_ordered_local_batch(
            pattern_jobs,
            self._interface_definition_pattern_candidates,
            default_factory=list,
        )
        for batch in pattern_batches:
            candidates.extend(batch)
        if is_buf_config:
            offset = len(parse_text) + 1
            for index, value in enumerate(self._buf_config_document_candidate_values(parse_text)):
                candidates.append((offset + index, value))
        candidates.sort(key=lambda item: item[0])
        return [value for _position, value in candidates[:512]]

    @staticmethod
    def _interface_definition_pattern_candidates(
        item: tuple[str, Any, str],
    ) -> list[tuple[int, str]]:
        _name, pattern, parse_text = item
        candidates: list[tuple[int, str]] = []
        for match in pattern.finditer(parse_text):
            value = str(match.group("value") or "").strip()
            if value:
                candidates.append((match.start(), value))
        return candidates

    @staticmethod
    def _interface_definition_url_candidate_entry(raw_value: str) -> str:
        return ArtifactQueueProcessor._api_spec_url_candidate_entry(raw_value)

    @staticmethod
    def _buf_config_registry_ref_pattern() -> re.Pattern[str]:
        return re.compile(
            r"""
            (?P<value>
                (?:
                    (?:https?://)?buf\.build
                    |
                    (?:https?://)?(?:[A-Za-z0-9-]+\.)+buf\.dev
                    |
                    (?:https?://)?(?:[A-Za-z0-9-]+\.)*buf[A-Za-z0-9-]*
                    \.[A-Za-z0-9.-]+\.[A-Za-z]{2,}
                )
                /
                [A-Za-z0-9_.-]{1,128}
                /
                [A-Za-z0-9_.-]{1,128}
                (?:/[A-Za-z0-9_.@+-]{1,128}){0,8}
            )
            """,
            re.IGNORECASE | re.VERBOSE,
        )

    def _buf_config_document_candidate_values(self, text: str) -> list[str]:
        document = self._api_spec_load_document(text)
        if not isinstance(document, (dict, list)):
            return []
        return self._buf_config_node_candidate_values(document, depth=0)[:256]

    def _buf_config_node_candidate_values(self, value: Any, *, depth: int) -> list[str]:
        if depth > 10:
            return []
        candidates: list[str] = []
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            triplet = self._buf_config_module_triplet_candidate(normalized)
            if triplet:
                candidates.append(triplet)
            for child in list(value.values())[:512]:
                candidates.extend(self._buf_config_node_candidate_values(child, depth=depth + 1))
            return candidates
        if isinstance(value, list):
            for child in value[:512]:
                candidates.extend(self._buf_config_node_candidate_values(child, depth=depth + 1))
            return candidates
        if isinstance(value, (str, int, float)):
            return [
                match.group("value")
                for match in self._buf_config_registry_ref_pattern().finditer(str(value))
            ][:32]
        return []

    @classmethod
    def _buf_config_module_triplet_candidate(cls, mapping: dict[str, Any]) -> str:
        remote = cls._yaml_ref_value(mapping, "remote")
        owner = cls._yaml_ref_value(mapping, "owner")
        repository = cls._yaml_ref_value(mapping, "repository", "repo")
        if not remote or not owner or not repository:
            return ""
        owner = owner.strip("/")
        repository = repository.strip("/").split(":", 1)[0]
        if not re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", owner):
            return ""
        if not re.fullmatch(r"[A-Za-z0-9_.-]{1,128}", repository):
            return ""
        return f"{remote.rstrip('/')}/{owner}/{repository}"

    def _yaml_goreleaser_config_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        if not self._yaml_mapping_looks_like_goreleaser_config(mapping, normalized, path_hint):
            return []

        candidates: list[str] = []
        seen: set[str] = set()
        for value in self._yaml_goreleaser_candidate_values_for_node(
            mapping,
            (),
            use_workers=True,
        ):
            candidate = str(value or "").strip()
            if not candidate or candidate.lower() in seen:
                continue
            seen.add(candidate.lower())
            candidates.append(candidate)
        return candidates

    def _yaml_goreleaser_candidate_values_for_node(
        self,
        value: Any,
        path: tuple[str, ...],
        *,
        use_workers: bool,
    ) -> list[str]:
        candidates: list[str] = []
        if isinstance(value, dict):
            if "blobs" in path:
                blob_candidate = self._yaml_goreleaser_blob_bucket_value(value)
                if blob_candidate:
                    candidates.append(blob_candidate)
            child_jobs = [
                (child_index, key, child, path)
                for child_index, (key, child) in enumerate(value.items())
            ]
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._yaml_goreleaser_child_candidate_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_goreleaser_child_candidate_values_for_node(
                        key,
                        child,
                        path,
                    )
                    for _child_index, key, child, path in child_jobs
                ]
            )
            for child_values in child_batches:
                candidates.extend(child_values)
            return candidates
        if isinstance(value, list):
            for item in value[:256]:
                candidates.extend(
                    self._yaml_goreleaser_candidate_values_for_node(
                        item,
                        path,
                        use_workers=False,
                    )
                )
        return candidates

    def _yaml_goreleaser_child_candidate_values(
        self,
        child_job: tuple[int, Any, Any, tuple[str, ...]],
    ) -> list[str]:
        _child_index, key, child, path = child_job
        return self._yaml_goreleaser_child_candidate_values_for_node(key, child, path)

    def _yaml_goreleaser_child_candidate_values_for_node(
        self,
        key: Any,
        child: Any,
        path: tuple[str, ...],
    ) -> list[str]:
        key_fingerprint = self._yaml_key_fingerprint(str(key or ""))
        child_path = (*path, key_fingerprint)
        candidates: list[str] = []
        if key_fingerprint in {
            "image",
            "images",
            "imagetemplate",
            "imagetemplates",
            "nametemplate",
            "nametemplates",
        } and any(part in child_path for part in ("docker", "dockers", "dockermanifests")):
            candidates.extend(self._yaml_goreleaser_image_template_values(child))
        candidates.extend(
            self._yaml_goreleaser_candidate_values_for_node(
                child,
                child_path,
                use_workers=False,
            )
        )
        return candidates

    def _yaml_goreleaser_image_template_values(self, value: Any) -> list[str]:
        candidates: list[str] = []
        for raw_value in self._yaml_goreleaser_scalar_values(value):
            image_candidate = _artifact_templated_container_image_url_candidate(
                raw_value,
                require_explicit_registry=True,
            )
            if image_candidate:
                candidates.append(image_candidate)
        return candidates

    def _yaml_goreleaser_blob_bucket_value(self, blob_mapping: dict[str, Any]) -> str:
        blob_normalized = self._yaml_normalized_mapping(blob_mapping)
        provider = self._yaml_key_fingerprint(
            self._yaml_ref_value(blob_normalized, "provider", "type")
        )
        bucket = self._yaml_valid_bucket_name(
            self._yaml_ref_value(
                blob_normalized,
                "bucket",
                "bucketName",
                "bucket_name",
                "name",
            )
        )
        if not bucket:
            return ""
        if provider in {"s3", "aws", "awss3"} and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
            return f"s3://{bucket}"
        if provider in {"gs", "gcs", "googlecloudstorage", "googlestorage"}:
            return f"gs://{bucket}"
        return ""

    def _yaml_goreleaser_scalar_values(self, value: Any) -> list[str]:
        if isinstance(value, (str, int, float)):
            return [str(value)]
        if isinstance(value, list):
            values: list[str] = []
            for item in value[:64]:
                values.extend(self._yaml_goreleaser_scalar_values(item))
            return values
        if isinstance(value, dict):
            values = []
            for item in list(value.values())[:64]:
                values.extend(self._yaml_goreleaser_scalar_values(item))
            return values
        return []

    def _yaml_mapping_looks_like_goreleaser_config(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> bool:
        del mapping
        keys = set(normalized)
        root_markers = {
            "projectname",
            "before",
            "builds",
            "archives",
            "checksum",
            "snapshot",
            "changelog",
            "release",
            "brews",
            "nfpms",
        }
        if (keys & {"dockers", "dockermanifests", "blobs"}) and (keys & root_markers):
            return True
        return "goreleaser" in path_hint and bool(keys & (root_markers | {"dockers", "dockermanifests", "blobs"}))

    def _yaml_gitops_manifest_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> list[str]:
        kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        api_version = self._yaml_ref_value(normalized, "apiVersion", "api_version").lower()
        if not kind or not api_version:
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        object_identifier = self._yaml_kubernetes_object_identifier(mapping)

        if "argoproj.io" in api_version and kind in {"application", "applicationset"}:
            if object_identifier:
                family = "argo-application" if kind == "application" else "argo-applicationset"
                _append(f"{family}://{object_identifier}")
            for repo_candidate in self._yaml_gitops_repository_candidates_from_mapping(mapping):
                _append(repo_candidate)
            return candidates

        if "source.toolkit.fluxcd.io" in api_version:
            family_map = {
                "gitrepository": "flux-gitrepository",
                "helmrepository": "flux-helmrepository",
                "ocirepository": "flux-ocirepository",
                "bucket": "flux-bucket",
            }
            family = family_map.get(kind)
            if family and object_identifier:
                _append(f"{family}://{object_identifier}")
            spec = self._yaml_child_mapping(mapping, "spec")
            if kind in {"gitrepository", "helmrepository", "ocirepository"}:
                repo_value = self._yaml_ref_value(
                    self._yaml_normalized_mapping(spec),
                    "url",
                    "repoURL",
                    "repoUrl",
                    "repo_url",
                )
                for repo_candidate in self._yaml_gitops_repository_candidates(repo_value):
                    _append(repo_candidate)
            if kind == "bucket":
                for bucket_candidate in self._yaml_flux_bucket_structured_candidates(spec):
                    _append(bucket_candidate)
            return candidates

        if "kustomize.toolkit.fluxcd.io" in api_version and kind == "kustomization":
            if object_identifier:
                _append(f"flux-kustomization://{object_identifier}")
            spec = self._yaml_child_mapping(mapping, "spec")
            source_ref = self._yaml_child_mapping(spec, "sourceRef", "source_ref")
            if source_ref:
                for source_candidate in self._yaml_flux_source_ref_candidates(source_ref):
                    _append(source_candidate)
            return candidates

        if self._yaml_manifest_looks_like_crossplane(api_version):
            for crossplane_candidate in self._yaml_crossplane_structured_candidates(
                mapping,
                kind=kind,
                api_version=api_version,
                object_identifier=object_identifier,
            ):
                _append(crossplane_candidate)
            return candidates

        return []

    def _yaml_gitops_repository_candidates_from_mapping(self, mapping: dict[str, Any]) -> list[str]:
        values = self._yaml_gitops_repository_values_for_node(
            mapping,
            use_workers=True,
        )
        candidates: list[str] = []
        seen: set[str] = set()
        candidate_batches = self._run_ordered_local_batch(
            values,
            self._yaml_gitops_repository_candidates,
            default_factory=list,
        )
        for candidate_batch in candidate_batches:
            for candidate in candidate_batch:
                lowered = candidate.lower()
                if lowered in seen:
                    continue
                seen.add(lowered)
                candidates.append(candidate)
        return candidates

    def _yaml_gitops_repository_values_for_node(
        self,
        value: Any,
        *,
        use_workers: bool,
    ) -> list[str]:
        values: list[str] = []
        if isinstance(value, dict):
            normalized = self._yaml_normalized_mapping(value)
            for key in ("repoURL", "repoUrl", "repo_url", "url"):
                ref_value = self._yaml_ref_value(normalized, key)
                if ref_value:
                    values.append(ref_value)
            name_hint = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "name"))
            value_ref = self._yaml_ref_value(normalized, "value")
            if value_ref and any(marker in name_hint for marker in ("repo", "repository", "sourceurl")):
                values.append(value_ref)
            child_jobs = list(enumerate(value.values()))
            child_batches = (
                self._run_ordered_local_batch(
                    child_jobs,
                    self._yaml_gitops_repository_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitops_repository_values_for_node(
                        child,
                        use_workers=False,
                    )
                    for _child_index, child in child_jobs
                ]
            )
            for child_values in child_batches:
                values.extend(child_values)
            return values
        if isinstance(value, list):
            item_jobs = list(enumerate(value))
            item_batches = (
                self._run_ordered_local_batch(
                    item_jobs,
                    self._yaml_gitops_repository_child_values,
                    default_factory=list,
                )
                if use_workers
                else [
                    self._yaml_gitops_repository_values_for_node(
                        item,
                        use_workers=False,
                    )
                    for _item_index, item in item_jobs
                ]
            )
            for item_values in item_batches:
                values.extend(item_values)
        return values

    def _yaml_gitops_repository_child_values(
        self,
        child_job: tuple[int, Any],
    ) -> list[str]:
        _child_index, child = child_job
        return self._yaml_gitops_repository_values_for_node(
            child,
            use_workers=False,
        )

    def _yaml_gitops_repository_candidates(self, value: Any) -> list[str]:
        raw_value = str(value or "").strip().strip("\"'")
        if not raw_value:
            return []
        candidates: list[str] = []

        if raw_value.startswith(("http://", "https://")):
            normalized = _normalize_artifact_text_url(raw_value)
            if normalized:
                candidates.append(self._strip_git_repository_suffix(normalized))
        elif raw_value.startswith(("oci://", "docker://")):
            candidate = _artifact_container_image_url_candidate(raw_value)
            if candidate:
                candidates.append(candidate)
        elif raw_value.startswith("git@"):
            match = re.fullmatch(r"git@([^:]+):(.+)", raw_value)
            if match:
                candidates.append(
                    self._strip_git_repository_suffix(
                        f"https://{match.group(1).lower()}/{match.group(2).strip('/')}"
                    )
                )
        elif raw_value.startswith(("ssh://", "git://")):
            parsed = urlparse(raw_value)
            host = str(parsed.hostname or "").lower()
            path = str(parsed.path or "").strip("/")
            if host and path:
                candidates.append(self._strip_git_repository_suffix(f"https://{host}/{path}"))

        deduped: list[str] = []
        seen: set[str] = set()
        for candidate in candidates:
            if not candidate or candidate.lower() in seen:
                continue
            seen.add(candidate.lower())
            deduped.append(candidate)
        return deduped

    @staticmethod
    def _strip_git_repository_suffix(value: str) -> str:
        candidate = str(value or "").strip().rstrip("/")
        if candidate.lower().endswith(".git"):
            return candidate[:-4]
        return candidate

    def _yaml_flux_source_ref_candidates(self, source_ref: dict[str, Any]) -> list[str]:
        normalized = self._yaml_normalized_mapping(source_ref)
        kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
        namespace = self._yaml_external_secret_ref_segment(
            self._yaml_ref_value(normalized, "namespace")
        )
        if not kind or not name:
            return []
        identifier = f"{namespace}/{name}" if namespace else name
        family_map = {
            "gitrepository": "flux-gitrepository",
            "helmrepository": "flux-helmrepository",
            "ocirepository": "flux-ocirepository",
            "bucket": "flux-bucket",
        }
        family = family_map.get(kind)
        return [f"{family}://{identifier}"] if family else []

    def _yaml_flux_bucket_structured_candidates(self, spec: dict[str, Any]) -> list[str]:
        if not spec:
            return []
        normalized = self._yaml_normalized_mapping(spec)
        bucket = self._yaml_valid_bucket_name(
            self._yaml_ref_value(normalized, "bucketName", "bucket_name", "bucket", "name")
        )
        provider = self._yaml_ref_value(normalized, "provider").lower()
        endpoint = self._yaml_ref_value(normalized, "endpoint").lower()
        region = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "region"))
        if not bucket:
            return []
        if "gcp" in provider or "google" in provider:
            return [f"gs://{bucket}"]
        if "azure" in provider:
            account_name = self._yaml_ref_value(normalized, "accountName", "account_name", "account")
            if re.fullmatch(r"[a-z0-9\-]{3,24}", account_name):
                return [f"https://{account_name.lower()}.blob.core.windows.net/{bucket}"]
        do_match = _DO_SPACES_ENDPOINT_HOST_RE.fullmatch(endpoint)
        if do_match:
            do_region = (do_match.group("region") or region or "").lower()
            if do_region:
                return [f"https://{bucket}.{do_region}.digitaloceanspaces.com"]
        return [f"s3://{bucket}"]

    @staticmethod
    def _yaml_manifest_looks_like_crossplane(api_version: str) -> bool:
        group = str(api_version or "").split("/", 1)[0].lower()
        return "crossplane.io" in group or group.endswith(".upbound.io")

    def _yaml_crossplane_structured_candidates(
        self,
        mapping: dict[str, Any],
        *,
        kind: str,
        api_version: str,
        object_identifier: str,
    ) -> list[str]:
        candidates: list[str] = []
        family = self._crossplane_provider_family(api_version)
        spec = self._yaml_child_mapping(mapping, "spec")

        if kind == "providerconfig":
            if object_identifier:
                candidates.append(f"crossplane-providerconfig://{family}/{object_identifier}")
            return candidates

        if kind in {"composition", "compositeresourcedefinition"}:
            if object_identifier:
                uri_family = "crossplane-composition" if kind == "composition" else "crossplane-xrd"
                candidates.append(f"{uri_family}://{object_identifier}")
            return candidates

        provider_ref = self._yaml_child_mapping(spec, "providerConfigRef", "provider_config_ref")
        if provider_ref:
            ref_name = self._yaml_external_secret_ref_segment(
                self._yaml_ref_value(self._yaml_normalized_mapping(provider_ref), "name")
            )
            if ref_name:
                candidates.append(f"crossplane-providerconfig://{family}/{ref_name}")

        external_name = self._yaml_crossplane_external_name(mapping)
        resource_name = external_name or object_identifier
        if resource_name:
            candidates.append(f"crossplane-resource://{family}/{kind}/{resource_name}")

        for cloud_candidate in self._yaml_crossplane_cloud_candidates(
            kind=kind,
            api_version=api_version,
            mapping=mapping,
            spec=spec,
            resource_name=resource_name,
        ):
            candidates.append(cloud_candidate)
        return candidates

    @staticmethod
    def _crossplane_provider_family(api_version: str) -> str:
        group = str(api_version or "").split("/", 1)[0].lower()
        for provider in ("aws", "gcp", "azure", "kubernetes", "digitalocean", "cloudflare"):
            if provider in group:
                return provider
        return group.replace(".", "-") or "crossplane"

    def _yaml_crossplane_external_name(self, mapping: dict[str, Any]) -> str:
        metadata = self._yaml_child_mapping(mapping, "metadata")
        annotations = self._yaml_child_mapping(metadata, "annotations")
        if not annotations:
            return ""
        for key, value in annotations.items():
            if str(key or "").strip().lower() == "crossplane.io/external-name":
                return self._yaml_external_secret_ref_segment(value)
        return ""

    def _yaml_crossplane_cloud_candidates(
        self,
        *,
        kind: str,
        api_version: str,
        mapping: dict[str, Any],
        spec: dict[str, Any],
        resource_name: str,
    ) -> list[str]:
        del mapping
        group = str(api_version or "").split("/", 1)[0].lower()
        for_provider = self._yaml_child_mapping(spec, "forProvider", "for_provider")
        normalized = self._yaml_normalized_mapping(for_provider) if for_provider else {}
        candidates: list[str] = []

        if kind == "bucket" and ("s3.aws" in group or "aws" in group):
            bucket = self._yaml_valid_bucket_name(
                self._yaml_ref_value(normalized, "bucket", "bucketName", "bucket_name")
                or resource_name
            )
            if bucket:
                candidates.append(f"s3://{bucket}")
        elif kind == "bucket" and ("storage.gcp" in group or "gcp" in group):
            bucket = self._yaml_valid_bucket_name(
                self._yaml_ref_value(normalized, "name", "bucket", "bucketName", "bucket_name")
                or resource_name
            )
            if bucket:
                candidates.append(f"gs://{bucket}")
        elif kind in {"storageaccount", "container"} and "azure" in group:
            account_name = self._yaml_ref_value(
                normalized,
                "storageAccountName",
                "storage_account_name",
                "accountName",
                "account_name",
            )
            container_name = self._yaml_ref_value(
                normalized,
                "name",
                "containerName",
                "container_name",
            )
            if re.fullmatch(r"[a-z0-9\-]{3,24}", account_name) and container_name:
                candidates.append(f"https://{account_name.lower()}.blob.core.windows.net/{container_name.lower()}")
        return candidates

    def _yaml_kubernetes_secret_manifest_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
    ) -> list[str]:
        kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        api_version = self._yaml_ref_value(normalized, "apiVersion", "api_version").lower()
        if kind == "secretproviderclass":
            return secret_provider_class_candidates(mapping)
        external_secret_kinds = {
            "externalsecret",
            "clusterexternalsecret",
            "secretstore",
            "clustersecretstore",
            "pushsecret",
        }
        if not (
            kind in external_secret_kinds
            or (kind == "sealedsecret" and "bitnami.com" in api_version)
            or (kind in external_secret_kinds and "external-secrets.io" in api_version)
        ):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        object_identifier = self._yaml_kubernetes_object_identifier(mapping)
        if object_identifier:
            object_uri = {
                "externalsecret": "external-secret",
                "clusterexternalsecret": "external-secret",
                "secretstore": "secret-store",
                "clustersecretstore": "cluster-secret-store",
                "pushsecret": "external-secret",
                "sealedsecret": "sealed-secret",
            }.get(kind)
            if object_uri:
                _append(f"{object_uri}://{object_identifier}")

        if kind == "sealedsecret":
            return candidates

        spec = self._yaml_child_mapping(mapping, "spec")
        spec_mappings = [spec] if spec else []
        external_secret_spec = self._yaml_child_mapping(spec, "externalSecretSpec", "external_secret_spec")
        if external_secret_spec:
            spec_mappings.append(external_secret_spec)

        remote_keys: list[str] = []
        for spec_mapping in spec_mappings:
            remote_keys.extend(self._yaml_external_secret_remote_ref_keys(spec_mapping))
            for store_ref in self._yaml_external_secret_store_refs(spec_mapping, object_identifier):
                _append(store_ref)
            provider = self._yaml_child_mapping(spec_mapping, "provider")
            for provider_candidate in self._yaml_external_secret_provider_candidates(provider, remote_keys):
                _append(provider_candidate)

        for remote_key in remote_keys:
            encoded_key = self._yaml_external_secret_ref_segment(remote_key)
            if encoded_key:
                _append(f"external-secret://remote-ref/{encoded_key}")

        return candidates

    def _yaml_kubernetes_object_identifier(self, mapping: dict[str, Any]) -> str:
        metadata = self._yaml_child_mapping(mapping, "metadata")
        if not metadata:
            return ""
        normalized = self._yaml_normalized_mapping(metadata)
        name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
        if not name:
            return ""
        namespace = self._yaml_external_secret_ref_segment(
            self._yaml_ref_value(normalized, "namespace")
        )
        return f"{namespace}/{name}" if namespace else name

    def _yaml_external_secret_store_refs(
        self,
        spec: dict[str, Any],
        object_identifier: str,
    ) -> list[str]:
        del object_identifier
        store_ref = self._yaml_child_mapping(spec, "secretStoreRef", "secret_store_ref")
        if not store_ref:
            return []
        normalized = self._yaml_normalized_mapping(store_ref)
        store_name = self._yaml_external_secret_ref_segment(self._yaml_ref_value(normalized, "name"))
        if not store_name:
            return []
        store_kind = self._yaml_key_fingerprint(self._yaml_ref_value(normalized, "kind"))
        if store_kind == "clustersecretstore":
            return [f"cluster-secret-store://{store_name}"]
        return [f"secret-store://{store_name}"]

    def _yaml_external_secret_remote_ref_keys(self, spec: dict[str, Any]) -> list[str]:
        remote_ref_jobs: list[tuple[str, dict[str, Any]]] = []
        data_entries = spec.get("data")
        if isinstance(data_entries, list):
            remote_ref_jobs.extend(
                ("data", entry)
                for entry in data_entries
                if isinstance(entry, dict)
            )
        data_from_entries = spec.get("dataFrom") or spec.get("datafrom")
        if isinstance(data_from_entries, list):
            remote_ref_jobs.extend(
                ("data_from", entry)
                for entry in data_from_entries
                if isinstance(entry, dict)
            )

        remote_ref_batches = self._run_ordered_local_batch(
            remote_ref_jobs,
            self._yaml_external_secret_remote_ref_entry_keys,
            default_factory=list,
        )
        keys: list[str] = []
        seen: set[str] = set()

        def _append(value: Any) -> None:
            key = str(value or "").strip().strip("\"'")
            if not key or key.lower() in seen:
                return
            seen.add(key.lower())
            keys.append(key)

        for remote_ref_batch in remote_ref_batches:
            for remote_key in remote_ref_batch:
                _append(remote_key)
        return keys

    def _yaml_external_secret_remote_ref_entry_keys(
        self,
        remote_ref_job: tuple[str, dict[str, Any]],
    ) -> list[str]:
        family, entry = remote_ref_job
        if family == "data":
            remote_ref = self._yaml_child_mapping(entry, "remoteRef", "remote_ref")
            if not remote_ref:
                return []
            normalized_remote = self._yaml_normalized_mapping(remote_ref)
            remote_key = self._yaml_ref_value(
                normalized_remote,
                "key",
                "remoteKey",
                "remote_key",
            )
            return [remote_key] if remote_key else []
        if family != "data_from":
            return []
        keys: list[str] = []
        for child_name in ("extract", "find"):
            child = self._yaml_child_mapping(entry, child_name)
            if not child:
                continue
            normalized_child = self._yaml_normalized_mapping(child)
            remote_key = self._yaml_ref_value(
                normalized_child,
                "key",
                "path",
                "name",
                "remoteKey",
                "remote_key",
            )
            if remote_key:
                keys.append(remote_key)
        return keys

    def _yaml_external_secret_provider_candidates(
        self,
        provider: dict[str, Any],
        remote_keys: Sequence[str],
    ) -> list[str]:
        if not provider:
            return []
        candidates: list[str] = []

        def _append(value: str) -> None:
            candidate = str(value or "").strip()
            if candidate:
                candidates.append(candidate)

        aws_provider = self._yaml_child_mapping(provider, "aws")
        if aws_provider:
            normalized_aws = self._yaml_normalized_mapping(aws_provider)
            region = self._yaml_external_secret_ref_segment(
                self._yaml_ref_value(normalized_aws, "region")
            )
            service = self._yaml_ref_value(normalized_aws, "service").lower()
            family = "aws-parameterstore" if "parameter" in service else "aws-secretsmanager"
            if region:
                _append(f"{family}://{region}")
                for remote_key in remote_keys:
                    encoded_key = self._yaml_external_secret_ref_segment(remote_key)
                    if encoded_key:
                        _append(f"{family}://{region}/{encoded_key}")

        gcp_provider = self._yaml_child_mapping(provider, "gcpsm", "gcp", "gcpSecretManager")
        if gcp_provider:
            normalized_gcp = self._yaml_normalized_mapping(gcp_provider)
            project_id = self._yaml_valid_project_ref(
                self._yaml_ref_value(
                    normalized_gcp,
                    "projectID",
                    "projectId",
                    "project_id",
                    "project",
                )
            )
            if project_id:
                _append(f"gcp-secretmanager://{project_id}")
                for remote_key in remote_keys:
                    encoded_key = self._yaml_external_secret_ref_segment(remote_key)
                    if encoded_key:
                        _append(f"gcp-secretmanager://{project_id}/{encoded_key}")

        azure_provider = self._yaml_child_mapping(provider, "azurekv", "azureKv", "azure-kv")
        if azure_provider:
            normalized_azure = self._yaml_normalized_mapping(azure_provider)
            vault_url = _normalize_artifact_text_url(
                self._yaml_ref_value(
                    normalized_azure,
                    "vaultUrl",
                    "vault_url",
                    "vault-url",
                )
            )
            if vault_url:
                _append(vault_url)

        vault_provider = self._yaml_child_mapping(provider, "vault")
        if vault_provider:
            normalized_vault = self._yaml_normalized_mapping(vault_provider)
            vault_url = self._yaml_vault_address_candidate(
                self._yaml_ref_value(
                    normalized_vault,
                    "server",
                    "url",
                    "address",
                    "uri",
                )
            )
            if vault_url:
                _append(vault_url)
                parsed = urlparse(vault_url)
                vault_path = self._yaml_external_secret_ref_segment(
                    self._yaml_ref_value(normalized_vault, "path")
                )
                if parsed.hostname:
                    identifier = parsed.hostname.lower()
                    if vault_path:
                        identifier = f"{identifier}/{vault_path}"
                    _append(f"hashicorp-vault://{identifier}")

        for child_name in ("webhook", "gitlab"):
            child = self._yaml_child_mapping(provider, child_name)
            if not child:
                continue
            normalized_child = self._yaml_normalized_mapping(child)
            endpoint = _normalize_artifact_text_url(
                self._yaml_ref_value(normalized_child, "url", "uri", "endpoint")
            )
            if endpoint:
                _append(endpoint)

        return candidates

    @staticmethod
    def _yaml_external_secret_ref_segment(value: Any) -> str:
        text = str(value or "").strip().strip("\"'").strip("/")
        if not text or len(text) > 512 or re.search(r"\s", text):
            return ""
        if "{{" in text or "}}" in text:
            return ""
        return quote(text, safe="/._:@+=-")

    def _yaml_sops_metadata_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        sops_mapping: dict[str, Any] | None = None
        if self._yaml_has_hint(path_hint, "sops"):
            sops_mapping = mapping
        else:
            candidate = normalized.get("sops")
            if isinstance(candidate, dict):
                sops_mapping = candidate
        if not isinstance(sops_mapping, dict):
            return []

        sops_jobs: list[tuple[str, dict[str, Any]]] = []
        for entry in self._yaml_sops_section_entries(sops_mapping, "kms"):
            sops_jobs.append(("aws_kms", entry))
        for entry in self._yaml_sops_section_entries(sops_mapping, "gcp_kms", "gcpKms", "gcp-kms"):
            sops_jobs.append(("gcp_kms", entry))
        for entry in self._yaml_sops_section_entries(sops_mapping, "azure_kv", "azureKv", "azure-kv"):
            sops_jobs.append(("azure_kv", entry))
        for entry in self._yaml_sops_section_entries(sops_mapping, "hc_vault", "hcVault", "hc-vault"):
            sops_jobs.append(("hc_vault", entry))

        candidate_entries = self._run_ordered_local_batch(
            sops_jobs,
            self._yaml_sops_metadata_entry_candidate,
            default_factory=str,
        )
        candidates: list[str] = []
        seen: set[str] = set()

        def _append(value: str) -> None:
            candidate = str(value or "").strip().strip("\"'")
            if not candidate:
                return
            lowered = candidate.lower()
            if lowered in seen:
                return
            seen.add(lowered)
            candidates.append(candidate)

        for candidate in candidate_entries:
            _append(candidate)
        return candidates

    def _yaml_sops_metadata_entry_candidate(self, sops_job: tuple[str, dict[str, Any]]) -> str:
        family, entry = sops_job
        if family == "aws_kms":
            arn = self._yaml_ref_value(entry, "arn")
            return str(arn).strip() if _AWS_KMS_ARN_RE.fullmatch(str(arn or "").strip()) else ""
        if family == "gcp_kms":
            resource_id = str(self._yaml_ref_value(entry, "resource_id", "resourceId", "resource-id") or "").strip()
            return resource_id if _GCP_KMS_RESOURCE_RE.fullmatch(resource_id) else ""
        if family == "azure_kv":
            vault_url = str(self._yaml_ref_value(entry, "vault_url", "vaultUrl", "vault-url") or "").strip()
            return _normalize_artifact_text_url(vault_url) if vault_url else ""
        if family == "hc_vault":
            vault_address = str(
                self._yaml_ref_value(
                    entry,
                    "vault_address",
                    "vaultAddress",
                    "vault-address",
                    "address",
                    "server",
                    "url",
                    "uri",
                )
                or ""
            ).strip()
            return self._yaml_vault_address_candidate(vault_address)
        return ""

    def _yaml_sops_section_entries(self, mapping: dict[str, Any], *keys: str) -> list[dict[str, Any]]:
        normalized_keys = {self._yaml_key_fingerprint(key) for key in keys}
        for key, value in mapping.items():
            if self._yaml_key_fingerprint(str(key or "")) not in normalized_keys:
                continue
            if isinstance(value, dict):
                return [value]
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
            return []
        return []

    @staticmethod
    def _yaml_vault_address_candidate(value: str) -> str:
        candidate = str(value or "").strip().strip("\"'")
        if not candidate:
            return ""
        normalized_url = _normalize_artifact_text_url(candidate)
        parsed = urlparse(normalized_url)
        if parsed.scheme in {"http", "https"} and parsed.netloc:
            return normalized_url
        if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9.-]{1,253}", candidate) and "." in candidate:
            return f"https://{candidate.lower().strip('.')}"
        return ""

    def _yaml_structured_candidates_from_env_map(
        self,
        env_map: dict[str, str],
        *,
        source_hint: str = "",
    ) -> list[str]:
        if not env_map:
            return []
        candidate_batches = self._run_ordered_local_batch(
            (
                "firebase",
                "supabase",
                "s3",
                "gcs",
                "do_spaces",
                "azure",
                "managed_hosting",
                "cloudflare",
                "amplify_client_config",
                "docker_auth",
                "restic",
                "borg",
                "duplicati",
                "env_values",
            ),
            lambda family: self._yaml_env_candidate_family(
                env_map,
                family,
                source_hint=source_hint,
            ),
            default_factory=list,
        )
        candidate_entry_batches = self._run_ordered_local_batch(
            list(enumerate(candidate_batches)),
            self._yaml_candidate_batch_entries,
            default_factory=list,
        )
        prepared_candidate_families = self._run_ordered_local_batch(
            list(enumerate(candidate_entry_batches)),
            self._yaml_candidate_family_entries,
            default_factory=list,
        )
        prepared_candidate_entries = self._run_ordered_local_batch(
            [
                (candidate_index, candidate)
                for candidate_index, candidate in enumerate(
                    candidate
                    for candidate_family in prepared_candidate_families
                    for candidate in candidate_family
                )
            ],
            self._yaml_candidate_merge_entry,
            default_factory=lambda: None,
        )
        return [candidate for candidate in prepared_candidate_entries if isinstance(candidate, str)]

    @staticmethod
    def _cloudflare_valid_ref(value: str) -> str:
        candidate = str(value or "").strip().strip("\"'").lower()
        if re.fullmatch(r"[a-z0-9][a-z0-9._\-]{1,127}", candidate):
            return candidate
        return ""

    @classmethod
    def _cloudflare_uri_candidate(cls, family: str, value: str) -> str:
        ref = cls._cloudflare_valid_ref(value)
        if not ref:
            return ""
        return f"cloudflare-{family}://{ref}"

    def _yaml_cloudflare_structured_candidates(
        self,
        mapping: dict[str, Any],
        normalized: dict[str, Any],
        path_hint: str,
    ) -> list[str]:
        del mapping
        candidate_refs: list[tuple[str, Any]] = []

        def _append(family: str, value: str) -> None:
            candidate_refs.append((family, value))

        explicit_cloudflare_hint = self._yaml_has_hint(
            path_hint,
            "cloudflare",
            "wrangler",
            "r2",
            "d1",
            "kv",
            "workers",
            "worker",
            "pages",
        )
        has_worker_markers = any(
            key in normalized
            for key in (
                "main",
                "compatibility_date",
                "compatibilitydate",
                "workers_dev",
                "workersdev",
                "account_id",
                "accountid",
            )
        )
        has_r2_key = any(
            key in normalized
            for key in (
                "cloudflare_r2_bucket",
                "cloudflarer2bucket",
                "r2_bucket",
                "r2bucket",
                "r2_bucket_name",
                "r2bucketname",
            )
        )
        has_d1_key = any(
            key in normalized
            for key in (
                "cloudflare_d1_database",
                "cloudflared1database",
                "cloudflare_d1_database_name",
                "cloudflared1databasename",
                "d1_database",
                "d1database",
                "d1_database_name",
                "d1databasename",
            )
        )
        has_kv_key = any(
            key in normalized
            for key in (
                "cloudflare_kv_namespace",
                "cloudflarekvnamespace",
                "cloudflare_kv_namespace_id",
                "cloudflarekvnamespaceid",
                "kv_namespace",
                "kvnamespace",
                "kv_namespace_id",
                "kvnamespaceid",
                "kv_id",
                "kvid",
            )
        )
        has_worker_key = any(
            key in normalized
            for key in (
                "cloudflare_worker",
                "cloudflareworker",
                "cloudflare_worker_name",
                "cloudflareworkername",
                "worker_name",
                "workername",
            )
        )
        has_pages_key = any(
            key in normalized
            for key in (
                "cloudflare_pages_project",
                "cloudflarepagesproject",
                "cloudflare_pages_project_name",
                "cloudflarepagesprojectname",
                "pages_project",
                "pagesproject",
                "pages_project_name",
                "pagesprojectname",
                "project_name",
                "projectname",
            )
        )

        r2_bucket = self._yaml_ref_value(
            normalized,
            "cloudflare_r2_bucket",
            "cloudflareR2Bucket",
            "r2_bucket",
            "r2Bucket",
            "r2_bucket_name",
            "r2BucketName",
        )
        if not r2_bucket and explicit_cloudflare_hint:
            r2_bucket = self._yaml_ref_value(
                normalized,
                "bucket_name",
                "bucketName",
                "bucket-name",
                "bucket",
                "name",
            )
        if r2_bucket and (explicit_cloudflare_hint or has_r2_key):
            _append("r2", r2_bucket)

        d1_database = self._yaml_ref_value(
            normalized,
            "cloudflare_d1_database",
            "cloudflareD1Database",
            "cloudflare_d1_database_name",
            "cloudflareD1DatabaseName",
            "d1_database",
            "d1Database",
            "d1_database_name",
            "d1DatabaseName",
        )
        if not d1_database and explicit_cloudflare_hint:
            d1_database = self._yaml_ref_value(
                normalized,
                "database_name",
                "databaseName",
                "database-name",
                "database_id",
                "databaseId",
                "database-id",
                "name",
            )
        if d1_database and (explicit_cloudflare_hint or has_d1_key):
            _append("d1", d1_database)

        kv_namespace = self._yaml_ref_value(
            normalized,
            "cloudflare_kv_namespace",
            "cloudflareKVNamespace",
            "cloudflare_kv_namespace_id",
            "cloudflareKVNamespaceId",
            "kv_namespace",
            "kvNamespace",
            "kv_namespace_id",
            "kvNamespaceId",
            "kv_id",
            "kvId",
        )
        if not kv_namespace and explicit_cloudflare_hint:
            kv_namespace = self._yaml_ref_value(
                normalized,
                "namespace_id",
                "namespaceId",
                "namespace-id",
                "id",
                "name",
            )
        if kv_namespace and (explicit_cloudflare_hint or has_kv_key):
            _append("kv", kv_namespace)

        worker_name = self._yaml_ref_value(
            normalized,
            "cloudflare_worker",
            "cloudflareWorker",
            "cloudflare_worker_name",
            "cloudflareWorkerName",
            "worker_name",
            "workerName",
        )
        if not worker_name and (explicit_cloudflare_hint or has_worker_markers):
            worker_name = self._yaml_ref_value(normalized, "name")
        if worker_name and (
            has_worker_key
            or has_worker_markers
            or self._yaml_has_hint(path_hint, "worker", "workers", "wrangler")
        ):
            _append("worker", worker_name)

        pages_project = self._yaml_ref_value(
            normalized,
            "cloudflare_pages_project",
            "cloudflarePagesProject",
            "cloudflare_pages_project_name",
            "cloudflarePagesProjectName",
            "pages_project",
            "pagesProject",
            "pages_project_name",
            "pagesProjectName",
            "project_name",
            "projectName",
        )
        if not pages_project and (
            self._yaml_has_hint(path_hint, "pages")
            or any(key in normalized for key in ("pages_build_output_dir", "pagesbuildoutputdir"))
        ):
            pages_project = self._yaml_ref_value(normalized, "name")
        if pages_project and (
            has_pages_key
            or self._yaml_has_hint(path_hint, "pages")
            or any(key in normalized for key in ("pages_build_output_dir", "pagesbuildoutputdir"))
        ):
            _append("pages", pages_project)

        candidate_entries = self._run_ordered_local_batch(
            candidate_refs,
            self._cloudflare_uri_candidate_entry,
            default_factory=str,
        )
        candidates: list[str] = []
        seen: set[str] = set()
        for candidate in candidate_entries:
            if not candidate or candidate in seen:
                continue
            seen.add(candidate)
            candidates.append(candidate)
        return candidates

    @classmethod
    def _cloudflare_uri_candidate_entry(cls, ref_entry: tuple[str, Any]) -> str:
        family, value = ref_entry
        return cls._cloudflare_uri_candidate(str(family or ""), str(value or ""))

    @staticmethod
    def _yaml_candidate_batch_entries(
        candidate_batch: tuple[int, Sequence[str]],
    ) -> list[str]:
        _batch_index, batch = candidate_batch
        return [candidate for candidate in batch]

    @staticmethod
    def _yaml_candidate_family_entries(
        candidate_family: tuple[int, Sequence[str]],
    ) -> list[str]:
        _family_index, family = candidate_family
        return [candidate for candidate in family]

    @staticmethod
    def _yaml_candidate_merge_entry(
        candidate_entry: tuple[int, str],
    ) -> str | None:
        _candidate_index, candidate = candidate_entry
        value = str(candidate or "").strip()
        if not value:
            return None
        return value

    def _borg_repository_candidates_from_env_map(self, env_map: dict[str, str]) -> list[str]:
        if not env_map:
            return []
        normalized = self._yaml_normalized_mapping(env_map)
        repository_values: list[str] = []
        seen_values: set[str] = set()
        for key in (
            "BORG_REPO",
            "BORG_REPOSITORY",
            "BORG_REPOSITORY_LOCATION",
            "BORG_REMOTE",
            "BORG_REMOTE_URL",
            "BORG_LOCATION",
        ):
            value = str(env_map.get(key) or normalized.get(self._yaml_key_fingerprint(key)) or "").strip()
            lowered = value.lower()
            if not value or lowered in seen_values:
                continue
            seen_values.add(lowered)
            repository_values.append(value)
        candidate_batches = self._run_ordered_local_batch(
            repository_values,
            lambda repository: self._borg_repository_candidates(repository, normalized),
            default_factory=list,
        )
        candidates: list[str] = []
        seen_candidates: set[str] = set()
        for candidate_batch in candidate_batches:
            for candidate in candidate_batch:
                lowered = str(candidate or "").strip().lower()
                if not candidate or lowered in seen_candidates:
                    continue
                seen_candidates.add(lowered)
                candidates.append(candidate)
        return candidates

    def _borg_repository_candidates(
        self,
        repository: str,
        context: dict[str, Any],
    ) -> list[str]:
        value = str(repository or "").strip().strip("\"'")
        if not value or "{{" in value or "}}" in value or re.search(r"\s", value):
            return []
        parsed = urlparse(value)
        scheme = parsed.scheme.lower()
        candidates: list[str] = []

        def _append(candidate: str) -> None:
            normalized = str(candidate or "").strip()
            if normalized:
                candidates.append(normalized)

        if scheme in {"http", "https"}:
            managed_url = _artifact_managed_cloud_url_candidate(value)
            if managed_url:
                _append(managed_url)
        elif scheme == "s3":
            for candidate in self._borg_s3_repository_candidates(value):
                _append(candidate)
        elif scheme in {"gcd", "gcs", "gs", "google", "googlestorage", "googlecloudstorage"}:
            bucket = self._borg_bucket_from_repository_url(value)
            if bucket:
                _append(f"gs://{bucket}")
        elif scheme in {"azure", "az", "azureblob"}:
            account_name = str(
                self._yaml_ref_value(
                    context,
                    "storage_account_name",
                    "storageAccountName",
                    "account_name",
                    "accountName",
                    "account",
                    "azure_storage_account",
                    "azureStorageAccount",
                    "AZURE_STORAGE_ACCOUNT",
                    "AZURE_BLOB_ACCOUNT",
                )
            ).strip().lower()
            container_name = self._borg_bucket_from_repository_url(value)
            if (
                re.fullmatch(r"[a-z0-9\-]{3,24}", account_name)
                and re.fullmatch(r"[^/?#]+", container_name)
            ):
                _append(f"https://{account_name}.blob.core.windows.net/{container_name}")
        elif scheme in {"ssh", "sftp"}:
            _append(self._borg_network_repository_candidate(value))
        elif not scheme:
            _append(self._borg_network_repository_candidate(value))

        deduped: list[str] = []
        seen: set[str] = set()
        for candidate in candidates:
            lowered = str(candidate or "").strip().lower()
            if not candidate or lowered in seen:
                continue
            seen.add(lowered)
            deduped.append(candidate)
        return deduped

    def _borg_s3_repository_candidates(self, repository_url: str) -> list[str]:
        parsed = urlparse(str(repository_url or "").strip())
        candidates: list[str] = []
        netloc = parsed.netloc.strip()
        path_segments = [segment for segment in parsed.path.split("/") if segment]
        bucket_candidate = ""
        if "@" in netloc:
            bucket_candidate = netloc.rsplit("@", 1)[1]
        elif netloc and "." in netloc and path_segments:
            bucket_candidate = path_segments[0]
            endpoint_url = _artifact_managed_cloud_url_candidate(
                f"https://{netloc}/{bucket_candidate}"
            )
            if endpoint_url:
                candidates.append(endpoint_url)
        elif netloc:
            bucket_candidate = netloc
        elif path_segments:
            bucket_candidate = path_segments[0]
        bucket = self._yaml_valid_bucket_name(bucket_candidate)
        if bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
            candidates.append(f"s3://{bucket}")
        return candidates

    def _borg_bucket_from_repository_url(self, repository_url: str) -> str:
        parsed = urlparse(str(repository_url or "").strip())
        if parsed.netloc:
            bucket = parsed.netloc
        elif parsed.path.startswith("/"):
            path_segments = [segment for segment in parsed.path.split("/") if segment]
            bucket = path_segments[0] if path_segments else ""
        else:
            bucket = parsed.path
        bucket = str(bucket or "").split("/", 1)[0].split(":", 1)[0].strip()
        return self._yaml_valid_bucket_name(bucket)

    def _borg_network_repository_candidate(self, repository: str) -> str:
        value = str(repository or "").strip().strip("\"'")
        if not value or re.search(r"\s", value):
            return ""
        parsed = urlparse(value)
        if parsed.scheme.lower() in {"ssh", "sftp"} and parsed.hostname:
            return _strip_artifact_network_dsn_userinfo(value)
        if re.match(r"^[A-Za-z]:[\\/]", value):
            return ""
        scp_match = re.match(
            r"^(?:(?:[^@\s:/]+)@)?(?P<host>[A-Za-z0-9_.-]+\.[A-Za-z0-9_.-]+):(?P<path>[^\"'<>`\s]+)$",
            value,
        )
        if not scp_match:
            return ""
        host = scp_match.group("host").lower().strip(".")
        path = scp_match.group("path").replace("\\", "/").lstrip("/")
        if not host or not path:
            return ""
        return f"ssh://{host}/{path}"

    def _restic_repository_candidates_from_env_map(self, env_map: dict[str, str]) -> list[str]:
        repository = str(env_map.get("RESTIC_REPOSITORY") or "").strip()
        if not repository:
            return []
        return self._restic_repository_candidates(repository, env_map)

    def _restic_repository_candidates(
        self,
        repository: str,
        env_map: dict[str, str],
    ) -> list[str]:
        value = str(repository or "").strip().strip("\"'")
        if not value:
            return []
        candidates: list[str] = []

        def _append(candidate: str) -> None:
            normalized = str(candidate or "").strip()
            if normalized:
                candidates.append(normalized)

        if value.startswith(("http://", "https://")):
            managed_url = _artifact_managed_cloud_url_candidate(value)
            if managed_url:
                _append(managed_url)
        elif value.startswith("rest:"):
            managed_url = _artifact_managed_cloud_url_candidate(value[5:])
            if managed_url:
                _append(managed_url)
        elif value.startswith("s3:"):
            for candidate in self._restic_s3_repository_candidates(value[3:]):
                _append(candidate)
        elif value.startswith("gs:"):
            bucket = self._restic_bucket_from_pathish(value[3:])
            if bucket:
                _append(f"gs://{bucket}")
        elif value.startswith("azure:"):
            account_name = str(
                env_map.get("AZURE_STORAGE_ACCOUNT")
                or env_map.get("AZURE_ACCOUNT_NAME")
                or env_map.get("AZURE_ACCOUNT")
                or ""
            ).strip().lower()
            container_name = self._restic_bucket_from_pathish(value[6:])
            if (
                re.fullmatch(r"[a-z0-9\-]{3,24}", account_name)
                and re.fullmatch(r"[^/?#]+", container_name)
            ):
                _append(f"https://{account_name}.blob.core.windows.net/{container_name}")

        deduped: list[str] = []
        seen: set[str] = set()
        for candidate in candidates:
            lowered = candidate.lower()
            if lowered in seen:
                continue
            seen.add(lowered)
            deduped.append(candidate)
        return deduped

    def _restic_s3_repository_candidates(self, repository_suffix: str) -> list[str]:
        suffix = str(repository_suffix or "").strip().strip("/")
        if not suffix:
            return []
        candidates: list[str] = []
        if suffix.startswith(("http://", "https://")):
            managed_url = _artifact_managed_cloud_url_candidate(suffix)
            if managed_url:
                candidates.append(managed_url)
            parsed = urlparse(suffix)
            path_segments = [segment for segment in parsed.path.split("/") if segment]
            bucket = self._yaml_valid_bucket_name(path_segments[0] if path_segments else "")
            if bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
                candidates.append(f"s3://{bucket}")
            return candidates
        segments = [segment for segment in suffix.split("/") if segment]
        if not segments:
            return []
        bucket_candidate = segments[1] if "." in segments[0] and len(segments) > 1 else segments[0]
        bucket = self._yaml_valid_bucket_name(bucket_candidate)
        if bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
            candidates.append(f"s3://{bucket}")
        if "." in segments[0]:
            managed_url = _artifact_managed_cloud_url_candidate(f"https://{suffix}")
            if managed_url:
                candidates.append(managed_url)
        return candidates

    def _restic_bucket_from_pathish(self, value: str) -> str:
        pathish = str(value or "").strip().strip("/")
        if not pathish:
            return ""
        bucket = pathish.split(":", 1)[0].split("/", 1)[0].strip()
        return self._yaml_valid_bucket_name(bucket)

    def _duplicati_target_url_candidates_from_env_map(self, env_map: dict[str, str]) -> list[str]:
        target_url = str(
            env_map.get("TARGETURL")
            or env_map.get("TARGET_URL")
            or env_map.get("TARGETURI")
            or env_map.get("TARGET_URI")
            or env_map.get("REMOTEURL")
            or env_map.get("REMOTE_URL")
            or ""
        ).strip()
        if not target_url:
            return []
        return self._duplicati_target_url_candidates(
            target_url,
            self._yaml_normalized_mapping(env_map),
        )

    def _duplicati_target_url_candidates(
        self,
        target_url: str,
        context: dict[str, Any],
    ) -> list[str]:
        value = str(target_url or "").strip().strip("\"'")
        if not value:
            return []
        parsed = urlparse(value)
        scheme = parsed.scheme.lower()
        if scheme in {"http", "https"}:
            managed_url = _artifact_managed_cloud_url_candidate(value)
            return [managed_url] if managed_url else []
        if scheme == "s3":
            return self._duplicati_s3_target_candidates(value)
        if scheme in {"gcd", "gcs", "gs", "google", "googlestorage", "googlecloudstorage"}:
            bucket = self._duplicati_bucket_from_target_url(value)
            return [f"gs://{bucket}"] if bucket else []
        if scheme in {"azure", "az", "azureblob"}:
            account_name = str(
                self._yaml_ref_value(
                    context,
                    "storage_account_name",
                    "storageAccountName",
                    "account_name",
                    "accountName",
                    "account",
                    "azure_storage_account",
                    "azureStorageAccount",
                    "auth_username",
                    "authUsername",
                    "username",
                )
            ).strip().lower()
            container_name = self._duplicati_bucket_from_target_url(value)
            if (
                re.fullmatch(r"[a-z0-9\-]{3,24}", account_name)
                and re.fullmatch(r"[^/?#]+", container_name)
            ):
                return [f"https://{account_name}.blob.core.windows.net/{container_name}"]
        return []

    def _duplicati_s3_target_candidates(self, target_url: str) -> list[str]:
        parsed = urlparse(str(target_url or "").strip())
        candidates: list[str] = []
        netloc = parsed.netloc.strip()
        path_segments = [segment for segment in parsed.path.split("/") if segment]
        bucket_candidate = ""
        if "@" in netloc:
            bucket_candidate = netloc.rsplit("@", 1)[1]
        elif netloc and "." in netloc and path_segments:
            bucket_candidate = path_segments[0]
            endpoint_url = _artifact_managed_cloud_url_candidate(
                f"https://{netloc}/{bucket_candidate}"
            )
            if endpoint_url:
                candidates.append(endpoint_url)
        elif netloc:
            bucket_candidate = netloc
        elif path_segments:
            bucket_candidate = path_segments[0]
        bucket = self._yaml_valid_bucket_name(bucket_candidate)
        if bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", bucket):
            candidates.append(f"s3://{bucket}")
        return candidates

    def _duplicati_bucket_from_target_url(self, target_url: str) -> str:
        parsed = urlparse(str(target_url or "").strip())
        if parsed.netloc:
            bucket = parsed.netloc
        elif parsed.path.startswith("/"):
            path_segments = [segment for segment in parsed.path.split("/") if segment]
            bucket = path_segments[0] if path_segments else ""
        else:
            bucket = parsed.path
        bucket = str(bucket or "").split("/", 1)[0].split(":", 1)[0].strip()
        return self._yaml_valid_bucket_name(bucket)

    def _yaml_env_candidate_family(
        self,
        env_map: dict[str, str],
        family: str,
        *,
        source_hint: str = "",
    ) -> list[str]:
        if family == "firebase":
            firebase_ref = self._yaml_valid_project_ref(
                env_map.get("FIREBASE_PROJECT_ID")
                or env_map.get("FIREBASE_PROJECT")
                or env_map.get("RTDB_PROJECT_ID")
                or env_map.get("FIREBASE_DATABASE_PROJECT")
                or ""
            )
            if firebase_ref:
                return [f"https://{firebase_ref}.firebaseio.com"]
            return []
        if family == "supabase":
            supabase_ref = self._yaml_valid_project_ref(
                env_map.get("SUPABASE_PROJECT_REF")
                or env_map.get("SUPABASE_REF")
                or env_map.get("NEXT_PUBLIC_SUPABASE_PROJECT_REF")
                or ""
            )
            if supabase_ref:
                return [f"https://{supabase_ref}.supabase.co"]
            return []
        if family == "s3":
            s3_bucket = self._yaml_valid_bucket_name(
                env_map.get("AWS_S3_BUCKET")
                or env_map.get("S3_BUCKET")
                or env_map.get("S3_BUCKET_NAME")
                or ""
            )
            if s3_bucket and re.fullmatch(r"[a-z0-9.\-]{3,63}", s3_bucket):
                return [f"s3://{s3_bucket}"]
            return []
        if family == "gcs":
            gcs_bucket = self._yaml_valid_bucket_name(
                env_map.get("GCS_BUCKET")
                or env_map.get("GOOGLE_STORAGE_BUCKET")
                or env_map.get("GCLOUD_STORAGE_BUCKET")
                or ""
            )
            if gcs_bucket:
                return [f"gs://{gcs_bucket}"]
            return []
        if family == "do_spaces":
            do_bucket = self._yaml_valid_bucket_name(
                env_map.get("DO_SPACES_BUCKET")
                or env_map.get("DIGITALOCEAN_SPACES_BUCKET")
                or ""
            )
            do_region = str(
                env_map.get("DO_SPACES_REGION")
                or env_map.get("DIGITALOCEAN_SPACES_REGION")
                or ""
            ).strip().lower()
            if do_bucket and re.fullmatch(r"[a-z0-9\-]{2,32}", do_region):
                return [f"https://{do_bucket}.{do_region}.digitaloceanspaces.com"]
            return []
        if family == "azure":
            azure_account = str(
                env_map.get("AZURE_STORAGE_ACCOUNT")
                or env_map.get("AZURE_BLOB_ACCOUNT")
                or ""
            ).strip().lower()
            azure_container = str(
                env_map.get("AZURE_STORAGE_CONTAINER")
                or env_map.get("AZURE_BLOB_CONTAINER")
                or ""
            ).strip().lower()
            if (
                re.fullmatch(r"[a-z0-9\-]{3,24}", azure_account)
                and re.fullmatch(r"[^/?#]+", azure_container)
            ):
                return [f"https://{azure_account}.blob.core.windows.net/{azure_container}"]
            return []
        if family == "managed_hosting":
            candidates: list[str] = []
            seen: set[str] = set()
            candidate_entries = self._run_ordered_local_batch(
                list(env_map.items()),
                self._yaml_managed_hosting_env_entry,
                default_factory=lambda: None,
            )
            for managed_url in candidate_entries:
                if not managed_url or managed_url in seen:
                    continue
                seen.add(managed_url)
                candidates.append(managed_url)
            return candidates
        if family == "cloudflare":
            normalized = self._yaml_normalized_mapping(env_map)
            return self._yaml_cloudflare_structured_candidates(env_map, normalized, "env")
        if family == "amplify_client_config":
            return amplify_client_config_candidates(env_map, source_hint=source_hint)
        if family == "docker_auth":
            return self._docker_auth_structured_candidates_from_env_map(env_map)
        if family == "restic":
            return self._restic_repository_candidates_from_env_map(env_map)
        if family == "borg":
            return self._borg_repository_candidates_from_env_map(env_map)
        if family == "duplicati":
            return self._duplicati_target_url_candidates_from_env_map(env_map)
        if family == "env_values":
            candidate_entries = self._run_ordered_local_batch(
                list(env_map.items()),
                self._yaml_env_value_candidate_entry,
                default_factory=lambda: None,
            )
            return [candidate for candidate in candidate_entries if candidate]
        return []

    @staticmethod
    def _yaml_managed_hosting_env_entry(entry: tuple[str, str]) -> str | None:
        env_name, env_value = entry
        upper_name = str(env_name or "").strip().upper()
        if not any(
            marker in upper_name
            for marker in (
                "URL",
                "URI",
                "HOST",
                "HOSTNAME",
                "DOMAIN",
                "ENDPOINT",
                "VERCEL",
                "NETLIFY",
                "AMPLIFY",
                "HEROKU",
            )
        ):
            return None
        managed_url = _artifact_managed_cloud_url_candidate(env_value)
        return managed_url or None

    @staticmethod
    def _yaml_env_value_candidate_entry(entry: tuple[str, str]) -> str | None:
        env_name, env_value = entry
        upper_name = str(env_name or "").strip().upper()
        value = str(env_value or "").strip()
        if not upper_name or not value:
            return None
        if "EMAIL" in upper_name and re.fullmatch(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", value):
            return value.lower()
        if any(
            marker in upper_name
            for marker in ("URL", "URI", "ENDPOINT", "PORTAL", "BASE_URL", "BASEURI")
        ):
            if value.startswith(("http://", "https://", "s3://", "gs://")):
                return value
            managed_url = _artifact_managed_cloud_url_candidate(value)
            if managed_url:
                return managed_url
        return None

    @classmethod
    def _docker_auth_structured_candidates_from_env_map(cls, env_map: dict[str, str]) -> list[str]:
        candidates: list[str] = []
        seen: set[str] = set()
        candidate_batches = cls._run_ordered_static_batch(
            list(env_map.items()),
            cls._docker_auth_structured_env_entry_candidates,
            default_factory=list,
        )
        for candidate_batch in candidate_batches:
            for candidate in candidate_batch:
                lowered = candidate.lower()
                if lowered in seen:
                    continue
                seen.add(lowered)
                candidates.append(candidate)
        return candidates

    @classmethod
    def _docker_auth_structured_env_entry_candidates(cls, item: tuple[str, str]) -> list[str]:
        raw_name, raw_value = item
        env_name = str(raw_name or "").strip().upper()
        value = str(raw_value or "").strip()
        if not value:
            return []
        if not cls._env_value_may_hold_docker_auth(env_name, value):
            return []
        return cls._docker_auth_config_candidates(value)

    @staticmethod
    def _env_value_may_hold_docker_auth(env_name: str, value: str) -> bool:
        if "DOCKER" in env_name or "CONTAINER_REGISTRY" in env_name:
            return True
        text = str(value or "").lstrip()
        return text.startswith("{") and '"auths"' in text[:512]

    @classmethod
    def _docker_auth_config_candidates(cls, value: Any) -> list[str]:
        payload = value if isinstance(value, dict) else _safe_json_loads(str(value or ""))
        if not isinstance(payload, dict):
            return []

        candidates: list[str] = []
        seen: set[str] = set()

        def _append_many(candidate_batch: Sequence[str]) -> None:
            for candidate in candidate_batch:
                normalized = str(candidate or "").strip()
                lowered = normalized.lower()
                if not normalized or lowered in seen:
                    continue
                seen.add(lowered)
                candidates.append(normalized)

        auths = payload.get("auths")
        if isinstance(auths, dict):
            auth_entry_batches = cls._run_ordered_static_batch(
                list(auths.items()),
                cls._docker_auth_config_auth_entry_candidates,
                default_factory=list,
            )
            for candidate_batch in auth_entry_batches:
                _append_many(candidate_batch)

        cred_helpers = payload.get("credHelpers") or payload.get("credhelpers")
        if isinstance(cred_helpers, dict):
            helper_batches = cls._run_ordered_static_batch(
                list(cred_helpers),
                cls._docker_auth_config_cred_helper_candidates,
                default_factory=list,
            )
            for candidate_batch in helper_batches:
                _append_many(candidate_batch)

        if not isinstance(auths, dict):
            legacy_batches = cls._run_ordered_static_batch(
                list(payload.items()),
                cls._docker_auth_config_legacy_entry_candidates,
                default_factory=list,
            )
            for candidate_batch in legacy_batches:
                _append_many(candidate_batch)
        return candidates

    @classmethod
    def _docker_auth_config_auth_entry_candidates(cls, item: tuple[Any, Any]) -> list[str]:
        raw_registry, raw_entry = item
        candidates: list[str] = []
        registry_url = cls._docker_registry_url_candidate(raw_registry)
        if registry_url:
            candidates.append(registry_url)
        if isinstance(raw_entry, dict):
            candidates.extend(cls._docker_auth_entry_principals(raw_entry))
        return candidates

    @classmethod
    def _docker_auth_config_cred_helper_candidates(cls, raw_registry: Any) -> list[str]:
        registry_url = cls._docker_registry_url_candidate(raw_registry)
        return [registry_url] if registry_url else []

    @classmethod
    def _docker_auth_config_legacy_entry_candidates(cls, item: tuple[Any, Any]) -> list[str]:
        raw_registry, raw_entry = item
        if str(raw_registry or "").strip() in {"credsStore", "credStore", "credHelpers", "credhelpers"}:
            return []
        if not isinstance(raw_entry, dict):
            return []
        return cls._docker_auth_config_auth_entry_candidates((raw_registry, raw_entry))

    @staticmethod
    def _docker_registry_url_candidate(value: Any) -> str:
        raw = str(value or "").strip()
        if not raw or raw == "*":
            return ""
        if raw.startswith("//"):
            raw = f"https:{raw}"
        elif "://" not in raw:
            raw = f"https://{raw}"
        parsed = urlparse(raw)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            return ""
        host = parsed.hostname.lower()
        try:
            netloc = f"{host}:{parsed.port}" if parsed.port else host
        except ValueError:
            netloc = host
        path = parsed.path.rstrip("/")
        return f"{parsed.scheme.lower()}://{netloc}{path}"

    @classmethod
    def _docker_auth_entry_principals(cls, entry: dict[str, Any]) -> list[str]:
        candidates: list[str] = []
        for key in ("email", "username", "user"):
            principal = cls._docker_auth_principal_candidate(entry.get(key))
            if principal:
                candidates.append(principal)
        auth_principal = cls._docker_auth_principal_from_auth_field(entry.get("auth"))
        if auth_principal:
            candidates.append(auth_principal)
        return candidates

    @staticmethod
    def _docker_auth_principal_candidate(value: Any) -> str:
        principal = str(value or "").strip()
        if _classify_seed_value(principal) == "email":
            return principal.lower()
        return ""

    @classmethod
    def _docker_auth_principal_from_auth_field(cls, value: Any) -> str:
        auth = str(value or "").strip()
        if not auth:
            return ""
        compact = re.sub(r"\s+", "", auth)
        if not compact:
            return ""
        padding = "=" * (-len(compact) % 4)
        try:
            decoded = base64.b64decode(compact + padding, validate=True).decode("utf-8", "ignore")
        except Exception:  # noqa: BLE001
            return ""
        principal, separator, _secret = decoded.partition(":")
        if not separator:
            return ""
        return cls._docker_auth_principal_candidate(principal)

    def _yaml_env_list_structured_candidates(self, entries: list[Any], *, source_hint: str = "") -> list[str]:
        return self._yaml_structured_candidates_from_env_map(
            self._yaml_env_map(entries),
            source_hint=source_hint,
        )

    def _collect_yaml_structured_payload_lines(
        self,
        value: Any,
        path: tuple[str, ...],
        append: Callable[[str], None],
        *,
        source_hint: str = "",
    ) -> None:
        if isinstance(value, dict):
            for candidate in self._yaml_map_structured_candidates(value, path, source_hint=source_hint):
                append(candidate)
            child_jobs = [
                ((*path, str(key or "").strip().lower()), item, source_hint)
                for key, item in value.items()
            ]
            child_batches = self._run_ordered_local_batch(
                child_jobs,
                self._yaml_structured_payload_line_batch,
                default_factory=list,
            )
            for child_batch in child_batches:
                for candidate in child_batch:
                    append(candidate)
            return
        if isinstance(value, list):
            for candidate in self._yaml_env_list_structured_candidates(value, source_hint=source_hint):
                append(candidate)
            child_batches = self._run_ordered_local_batch(
                [(path, item, source_hint) for item in value],
                self._yaml_structured_payload_line_batch,
                default_factory=list,
            )
            for child_batch in child_batches:
                for candidate in child_batch:
                    append(candidate)

    def _yaml_structured_payload_line_batch(
        self,
        child_job: tuple[tuple[str, ...], Any, str],
    ) -> list[str]:
        child_path, child_value, source_hint = child_job
        lines: list[str] = []
        self._collect_yaml_structured_payload_lines(
            child_value,
            child_path,
            lines.append,
            source_hint=source_hint,
        )
        return lines

    @staticmethod
    def _iter_terraform_state_resource_values(payload: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
        values: list[tuple[str, dict[str, Any]]] = []

        def _append(resource_type: str, item: Any) -> None:
            if not isinstance(item, dict):
                return
            normalized_type = str(resource_type or "").strip()
            if not normalized_type:
                return
            values.append((normalized_type, item))

        def _walk_resource_list(resource_items: Any) -> None:
            if not isinstance(resource_items, list):
                return
            for resource in resource_items:
                if not isinstance(resource, dict):
                    continue
                resource_type = str(resource.get("type") or "").strip()
                if not resource_type:
                    continue
                if isinstance(resource.get("values"), dict):
                    _append(resource_type, resource.get("values"))
                instances = resource.get("instances")
                if isinstance(instances, list):
                    for instance in instances:
                        if not isinstance(instance, dict):
                            continue
                        attributes = instance.get("attributes")
                        if isinstance(attributes, dict):
                            _append(resource_type, attributes)
                        elif isinstance(instance.get("values"), dict):
                            _append(resource_type, instance.get("values"))

        def _walk_module(module: Any) -> None:
            if not isinstance(module, dict):
                return
            _walk_resource_list(module.get("resources"))
            for child in module.get("child_modules") or []:
                _walk_module(child)

        _walk_resource_list(payload.get("resources"))
        for section_name in ("values", "planned_values", "prior_state"):
            section = payload.get(section_name)
            if not isinstance(section, dict):
                continue
            _walk_module(section.get("root_module"))
            if section_name == "prior_state":
                nested_values = section.get("values")
                if isinstance(nested_values, dict):
                    _walk_module(nested_values.get("root_module"))
        return values

    @staticmethod
    def _azure_storage_account_name_from_resource_values(values: dict[str, Any]) -> str:
        for key in ("storage_account_id", "storage_account_resource_id", "id"):
            resource_id = str(values.get(key) or "").strip()
            if not resource_id:
                continue
            match = re.search(r"/storageAccounts/([A-Za-z0-9]{3,24})(?:/|$)", resource_id)
            if match:
                return match.group(1).lower()
        return ""

    def _extract_text_payloads(
        self,
        path: Path,
        artifact_type: str,
        *,
        depth: int = 0,
    ) -> list[tuple[str, str, str]]:
        if depth > 2 or not path.exists():
            return []
        if artifact_type == "config":
            if path.suffix.lower() in _WARC_SUFFIXES:
                return self._extract_warc_payloads(path)
            if path.suffix.lower() in _HAR_SUFFIXES:
                return self._extract_har_payloads(path)
            if path.suffix.lower() in _PCAP_SUFFIXES:
                return self._extract_pcap_payloads(path)
            if path.suffix.lower() in _CALENDAR_CONTACT_SUFFIXES:
                return self._extract_calendar_contact_payloads(path)
            if path.suffix.lower() in _EMBEDDED_PLIST_SUFFIXES:
                return self._extract_embedded_plist_payloads(path)
            if _burp_site_map_artifact_label(path.name):
                return self._extract_burp_site_map_payloads(path)
            if path.suffix.lower() in _PLIST_SUFFIXES or path.read_bytes()[:8].startswith(_PLIST_MAGIC):
                return self._extract_plist_payloads(path)
            if _looks_like_terraform_state_name(path.name):
                return self._extract_terraform_state_payloads(path)
            return [(str(path), path.name, self._read_text(path))]
        if artifact_type == "document":
            if path.suffix.lower() in _PCAP_SUFFIXES or self._looks_like_pcap_bytes(path.read_bytes()[:4], path.name):
                return self._extract_pcap_payloads(path)
            if _looks_like_browser_binary_string_artifact_name(path.name):
                return self._extract_legacy_binary_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if windows_registry_hive_artifact_label(str(path)):
                return self._extract_legacy_binary_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if path.suffix.lower() in _OCR_IMAGE_SUFFIXES:
                return self._extract_image_payloads(path)
            if path.suffix.lower() in _PARQUET_COLUMNAR_SUFFIXES:
                return self._extract_parquet_payloads(path, depth=depth)
            if path.suffix.lower() in _BINARY_STRING_ARTIFACT_SUFFIXES:
                return self._extract_legacy_binary_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if path.suffix.lower() in _SQLITE_DATABASE_SUFFIXES or path.read_bytes()[:16].startswith(_SQLITE_MAGIC):
                return self._extract_sqlite_payloads(path)
            if path.suffix.lower() == ".msg":
                return self._extract_msg_payloads(path, depth=depth)
            if path.suffix.lower() == ".emlx":
                return self._extract_emlx_payloads(path, depth=depth)
            if path.suffix.lower() == ".eml":
                return self._extract_email_message_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if path.suffix.lower() == ".mbox":
                return self._extract_mbox_bytes_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if path.suffix.lower() in _MIME_ARCHIVE_SUFFIXES:
                return self._extract_email_message_payloads(
                    path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
                    str(path),
                    path.name,
                    depth=depth,
                )
            if path.suffix.lower() in _OPENXML_DOCUMENT_SUFFIXES and zipfile.is_zipfile(path):
                with zipfile.ZipFile(path) as zf:
                    return self._extract_text_payloads_from_zip(zf, str(path), depth=depth)
            if path.suffix.lower() == ".rtf":
                return self._extract_rtf_payloads(path, depth=depth)
            if path.suffix.lower() in _LEGACY_DOCUMENT_SUFFIXES:
                return self._extract_legacy_document_payloads(path, depth=depth)
            if path.suffix.lower() == ".pdf":
                return self._extract_pdf_payloads(path)
            return [(str(path), path.name, self._read_text(path))]
        if artifact_type == "archive":
            payloads = self._extract_archive_bytes_payloads(
                path.read_bytes(),
                str(path),
                path.name,
                depth=depth,
            )
            if payloads:
                return payloads
            return [(str(path), path.name, self._read_text(path))]
        return []

    @staticmethod
    def _safe_archive_member_name(raw_member_name: str) -> str:
        member_name = str(raw_member_name or "").strip().replace("\\", "/")
        if not member_name:
            return ""
        if member_name.startswith("/") or re.match(r"^[A-Za-z]:", member_name):
            return ""
        parts = [part for part in member_name.split("/") if part and part != "."]
        if not parts or any(part == ".." for part in parts):
            return ""
        return "/".join(parts)

    @staticmethod
    def _text_zip_member_entry(member: zipfile.ZipInfo) -> dict[str, str] | None:
        if member.is_dir():
            return None
        member_name = str(member.filename or "")
        size_limit = _artifact_member_scan_byte_limit(member_name)
        if member.file_size > size_limit:
            return None
        return {"name": member_name}

    @staticmethod
    def _text_tar_member_entry(member: tarfile.TarInfo) -> dict[str, str] | None:
        if not member.isfile():
            return None
        member_name = str(member.name or "")
        size_limit = _artifact_member_scan_byte_limit(member_name)
        if member.size > size_limit:
            return None
        return {"name": member_name}

    @staticmethod
    def _text_7z_member_entry(member: Any) -> dict[str, str] | None:
        raw_member_name = str(getattr(member, "filename", "") or "")
        member_name = ArtifactQueueProcessor._safe_archive_member_name(raw_member_name)
        if not member_name:
            return None
        if bool(getattr(member, "is_directory", False)) or bool(getattr(member, "is_symlink", False)):
            return None
        if not bool(getattr(member, "is_file", True)):
            return None
        size_limit = _artifact_member_scan_byte_limit(member_name)
        try:
            member_size = int(getattr(member, "uncompressed", 0) or 0)
        except (TypeError, ValueError):
            member_size = 0
        if member_size > size_limit:
            return None
        return {"name": member_name, "target": raw_member_name}

    @staticmethod
    def _text_member_job(
        member_job: tuple[str, bytes],
    ) -> tuple[str, bytes] | None:
        member_name, member_bytes = member_job
        normalized_name = str(member_name or "").strip()
        if not normalized_name or not member_bytes:
            return None
        return normalized_name, bytes(member_bytes)

    def _extract_text_payloads_from_zip(
        self,
        zf: zipfile.ZipFile,
        source_file: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        raw_member_jobs: list[tuple[str, bytes]] = []
        members = zf.infolist()
        member_entries = self._run_ordered_local_batch(
            members,
            self._text_zip_member_entry,
            default_factory=lambda: None,
        )
        for member, member_entry in zip(members, member_entries):
            if not isinstance(member_entry, dict):
                continue
            raw_member_jobs.append((str(member_entry["name"]), zf.read(member)))
        member_jobs = self._run_ordered_local_batch(
            raw_member_jobs,
            self._text_member_job,
            default_factory=lambda: None,
        )
        member_jobs = [
            member_job
            for member_job in member_jobs
            if isinstance(member_job, tuple)
        ]
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    def _extract_text_payloads_from_7z(
        self,
        data: bytes,
        source_file: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if py7zr is None:
            return []
        try:
            with py7zr.SevenZipFile(BytesIO(data), mode="r") as archive:
                if archive.needs_password():
                    return []
                members = archive.list()
                member_entries = self._run_ordered_local_batch(
                    members,
                    self._text_7z_member_entry,
                    default_factory=lambda: None,
                )
                selected_entries = [
                    entry
                    for entry in member_entries
                    if isinstance(entry, dict)
                ]
                if not selected_entries:
                    return []
                raw_member_jobs: list[tuple[str, bytes]] = []
                with tempfile.TemporaryDirectory() as temp_dir:
                    archive.extract(
                        path=temp_dir,
                        targets=[str(entry["target"]) for entry in selected_entries],
                    )
                    root = Path(temp_dir).resolve()
                    for entry in selected_entries:
                        member_name = str(entry["name"])
                        member_path = (root / Path(*member_name.split("/"))).resolve()
                        try:
                            member_path.relative_to(root)
                        except ValueError:
                            continue
                        if not member_path.is_file():
                            continue
                        size_limit = _artifact_member_scan_byte_limit(member_name)
                        try:
                            with member_path.open("rb") as handle:
                                member_bytes = handle.read(size_limit + 1)
                        except OSError:
                            continue
                        if len(member_bytes) > size_limit:
                            continue
                        raw_member_jobs.append((member_name, member_bytes))
        except Exception:  # noqa: BLE001
            return []

        member_jobs = self._run_ordered_local_batch(
            raw_member_jobs,
            self._text_member_job,
            default_factory=lambda: None,
        )
        member_jobs = [
            member_job
            for member_job in member_jobs
            if isinstance(member_job, tuple)
        ]
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    def _extract_text_payloads_from_tar(
        self,
        tf: tarfile.TarFile,
        source_file: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        raw_member_jobs: list[tuple[str, bytes]] = []
        members = tf.getmembers()
        member_entries = self._run_ordered_local_batch(
            members,
            self._text_tar_member_entry,
            default_factory=lambda: None,
        )
        for member, member_entry in zip(members, member_entries):
            if not isinstance(member_entry, dict):
                continue
            extracted = tf.extractfile(member)
            if extracted is None:
                continue
            raw_member_jobs.append((str(member_entry["name"]), extracted.read()))
        member_jobs = self._run_ordered_local_batch(
            raw_member_jobs,
            self._text_member_job,
            default_factory=lambda: None,
        )
        member_jobs = [
            member_job
            for member_job in member_jobs
            if isinstance(member_job, tuple)
        ]
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    @staticmethod
    def _tar_member_bytes(
        tf: tarfile.TarFile,
        member: tarfile.TarInfo,
        *,
        limit: int | None = None,
    ) -> bytes:
        member_name = ArtifactQueueProcessor._safe_archive_member_name(str(member.name or ""))
        if not member.isfile() or not member_name:
            return b""
        size_limit = limit if limit is not None else _artifact_member_scan_byte_limit(member_name)
        if member.size > size_limit:
            return b""
        extracted = tf.extractfile(member)
        if extracted is None:
            return b""
        return extracted.read(member.size + 1)

    def _extract_oci_image_layout_tar_payloads(
        self,
        tf: tarfile.TarFile,
        members: Sequence[tarfile.TarInfo],
        source_file: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        member_by_name = {
            safe_name: member
            for member in members
            if member.isfile()
            for safe_name in [self._safe_archive_member_name(str(member.name or ""))]
            if safe_name
        }
        if "oci-layout" not in member_by_name or "index.json" not in member_by_name:
            return []
        index_bytes = self._tar_member_bytes(tf, member_by_name["index.json"])
        index_payload = _safe_json_loads(self._decode_text_artifact_bytes(index_bytes))
        manifest_digests = oci_index_manifest_digests(index_payload)
        if not manifest_digests:
            return []

        payloads: list[tuple[str, str, str]] = []
        seen_blob_members: set[str] = set()

        def _append_member_payloads(member_name: str) -> bytes:
            member = member_by_name.get(member_name)
            if member is None or member_name in seen_blob_members:
                return b""
            member_bytes = self._tar_member_bytes(tf, member)
            if not member_bytes:
                return b""
            seen_blob_members.add(member_name)
            payloads.extend(
                self._extract_member_data_payloads(
                    member_bytes,
                    source_file,
                    member_name,
                    depth=depth,
                )
            )
            return member_bytes

        for metadata_member in ("oci-layout", "index.json"):
            _append_member_payloads(metadata_member)

        for manifest_digest in manifest_digests:
            manifest_member = oci_blob_member_name(manifest_digest)
            manifest_bytes = _append_member_payloads(manifest_member)
            manifest_payload = _safe_json_loads(
                self._decode_text_artifact_bytes(manifest_bytes)
            )
            config_member = oci_blob_member_name(
                oci_manifest_config_digest(manifest_payload)
            )
            if config_member:
                _append_member_payloads(config_member)
            for layer_digest in oci_manifest_layer_digests(manifest_payload):
                layer_member = oci_blob_member_name(layer_digest)
                member = member_by_name.get(layer_member)
                if member is None or layer_member in seen_blob_members:
                    continue
                layer_bytes = self._tar_member_bytes(
                    tf,
                    member,
                    limit=_REMOTE_ARTIFACT_MAX_BYTES,
                )
                if not layer_bytes:
                    continue
                seen_blob_members.add(layer_member)
                for layer_source, extract_path, text in self._extract_archive_bytes_payloads(
                    layer_bytes,
                    source_file,
                    layer_member,
                    depth=depth + 1,
                ):
                    prefixed_path = f"{layer_member}#oci-layer/{extract_path}"
                    payloads.append(
                        (
                            f"{layer_source}!{prefixed_path}",
                            prefixed_path,
                            text,
                        )
                    )
        return payloads

    def _extract_docker_save_image_tar_payloads(
        self,
        tf: tarfile.TarFile,
        members: Sequence[tarfile.TarInfo],
        source_file: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        member_by_name = {
            safe_name: member
            for member in members
            if member.isfile()
            for safe_name in [self._safe_archive_member_name(str(member.name or ""))]
            if safe_name
        }
        manifest_member = member_by_name.get("manifest.json")
        if manifest_member is None:
            return []
        manifest_bytes = self._tar_member_bytes(tf, manifest_member)
        entries = docker_save_manifest_entries(
            _safe_json_loads(self._decode_text_artifact_bytes(manifest_bytes))
        )
        if not entries:
            return []

        payloads: list[tuple[str, str, str]] = []
        seen_members: set[str] = set()

        def _append_member_payloads(member_name: str) -> bytes:
            member = member_by_name.get(member_name)
            if member is None or member_name in seen_members:
                return b""
            member_bytes = self._tar_member_bytes(tf, member)
            if not member_bytes:
                return b""
            seen_members.add(member_name)
            payloads.extend(
                self._extract_member_data_payloads(
                    member_bytes,
                    source_file,
                    member_name,
                    depth=depth,
                )
            )
            return member_bytes

        _append_member_payloads("manifest.json")
        for entry in entries:
            config_member = str(entry.get("config") or "")
            if config_member:
                _append_member_payloads(config_member)
            for layer_member in entry.get("layers") or []:
                layer_name = str(layer_member or "")
                member = member_by_name.get(layer_name)
                if member is None or layer_name in seen_members:
                    continue
                layer_bytes = self._tar_member_bytes(
                    tf,
                    member,
                    limit=_REMOTE_ARTIFACT_MAX_BYTES,
                )
                if not layer_bytes:
                    continue
                seen_members.add(layer_name)
                for layer_source, extract_path, text in self._extract_archive_bytes_payloads(
                    layer_bytes,
                    source_file,
                    layer_name,
                    depth=depth + 1,
                ):
                    prefixed_path = f"{layer_name}#docker-layer/{extract_path}"
                    payloads.append(
                        (
                            f"{layer_source}!{prefixed_path}",
                            prefixed_path,
                            text,
                        )
                    )
        return payloads

    def _extract_nested_archive_bytes(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        return self._extract_archive_bytes_payloads(
            data,
            source_file,
            member_name,
            depth=depth,
        )

    def _extract_member_data_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        lowered = member_name.lower()
        suffix = Path(lowered).suffix
        if _looks_like_react_native_js_bundle_name(member_name):
            return self._member_payloads(source_file, member_name, data)
        if _looks_like_hermes_bytecode_bundle_name(member_name):
            return self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if _looks_like_browser_binary_string_artifact_name(member_name):
            return self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if windows_registry_hive_artifact_label(member_name):
            return self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if suffix in _OCR_IMAGE_SUFFIXES:
            return self._extract_image_member_payloads(source_file, member_name, data)
        if suffix in _PARQUET_COLUMNAR_SUFFIXES:
            return self._extract_parquet_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if suffix in _BINARY_STRING_ARTIFACT_SUFFIXES:
            return self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if suffix in _WARC_SUFFIXES or self._looks_like_warc_bytes(data, member_name):
            return self._extract_warc_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix in _HAR_SUFFIXES:
            return self._extract_har_bytes_payloads(
                data[:_MAX_HAR_BYTES],
                source_file,
                member_name,
            )
        if suffix in _PCAP_SUFFIXES or self._looks_like_pcap_bytes(data, member_name):
            return self._extract_pcap_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix in _CALENDAR_CONTACT_SUFFIXES:
            return self._extract_calendar_contact_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix in _EMBEDDED_PLIST_SUFFIXES:
            return self._extract_embedded_plist_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix == ".msg":
            return self._extract_msg_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=min(2, depth + 1),
            )
        if suffix == ".emlx":
            return self._extract_emlx_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=min(2, depth + 1),
            )
        if suffix == ".eml":
            return self._extract_email_message_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=min(2, depth + 1),
            )
        if suffix == ".mbox":
            return self._extract_mbox_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=min(2, depth + 1),
            )
        if suffix in _MIME_ARCHIVE_SUFFIXES:
            return self._extract_email_message_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=min(2, depth + 1),
            )
        if suffix in _PLIST_SUFFIXES or data.startswith(_PLIST_MAGIC):
            return self._extract_plist_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix in _SQLITE_DATABASE_SUFFIXES or data.startswith(_SQLITE_MAGIC):
            return self._extract_sqlite_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if suffix in _OPENXML_DOCUMENT_SUFFIXES and zipfile.is_zipfile(BytesIO(data)):
            try:
                with zipfile.ZipFile(BytesIO(data)) as nested_zip:
                    return self._extract_text_payloads_from_zip(
                        nested_zip,
                        source_file,
                        depth=min(2, depth + 1),
                    )
            except Exception:  # noqa: BLE001
                return []
        if suffix == ".rtf":
            return self._extract_rtf_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        if suffix in _LEGACY_DOCUMENT_SUFFIXES or data.startswith(_OLE_MAGIC):
            return self._extract_legacy_binary_payloads(
                data,
                source_file,
                member_name,
                depth=depth,
            )
        if suffix == ".pdf":
            return self._extract_pdf_bytes_payloads(data, source_file, member_name)
        if _looks_like_terraform_state_name(member_name):
            return self._extract_terraform_state_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if _looks_like_container_image_blob_path(member_name) and _looks_like_container_image_json_payload(
            data
        ):
            return self._member_payloads(source_file, member_name, data)
        if _looks_text_config_name(member_name) or lowered.endswith(".rels"):
            return self._member_payloads(source_file, member_name, data)
        if depth >= 2:
            return []
        if lowered.endswith(_ARCHIVE_SUFFIXES) or self._looks_like_archive_bytes(data):
            return self._extract_nested_archive_bytes(data, source_file, member_name, depth + 1)
        return []

    def _extract_archive_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth > 2 or not data:
            return []
        if self._looks_like_warc_bytes(data, member_name):
            return self._extract_warc_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        if self._looks_like_pcap_bytes(data, member_name):
            return self._extract_pcap_bytes_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
            )
        payload_families = self._run_ordered_local_batch(
            ("crx", "zip", "7z", "ar", "tar", "cpio", "asar", "decompress"),
            lambda family: self._extract_archive_payload_family(
                family,
                data=data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            ),
            default_factory=list,
        )
        for family_payloads in payload_families:
            if family_payloads:
                return family_payloads
        return []

    def _extract_archive_payload_family(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if family == "crx":
            return self._extract_archive_crx_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "zip":
            return self._extract_archive_zip_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "7z":
            return self._extract_archive_7z_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "ar":
            return self._extract_archive_ar_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "tar":
            return self._extract_archive_tar_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "cpio":
            return self._extract_archive_cpio_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "asar":
            return self._extract_archive_asar_payloads(
                data,
                source_file=source_file,
                depth=depth,
            )
        if family == "decompress":
            return self._extract_archive_decompressed_payloads(
                data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        return []

    @staticmethod
    def _crx_zip_payload_bytes(data: bytes) -> bytes:
        if len(data) < 12 or not data.startswith(_CRX_ARCHIVE_MAGIC):
            return b""
        try:
            version = struct.unpack("<I", data[4:8])[0]
        except struct.error:
            return b""
        if version == 2:
            if len(data) < 16:
                return b""
            try:
                public_key_len, signature_len = struct.unpack("<II", data[8:16])
            except struct.error:
                return b""
            offset = 16 + public_key_len + signature_len
        elif version == 3:
            try:
                header_len = struct.unpack("<I", data[8:12])[0]
            except struct.error:
                return b""
            offset = 12 + header_len
        else:
            return b""
        if offset >= len(data):
            return b""
        payload = data[offset:]
        if not payload.startswith(b"PK\x03\x04"):
            return b""
        return payload

    def _extract_archive_crx_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        zip_payload = self._crx_zip_payload_bytes(data)
        if not zip_payload:
            return []
        return self._extract_archive_zip_payloads(
            zip_payload,
            source_file=source_file,
            depth=depth,
        )

    def _extract_archive_zip_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        try:
            if not zipfile.is_zipfile(BytesIO(data)):
                return []
            with zipfile.ZipFile(BytesIO(data)) as nested_zip:
                payloads = self._extract_text_payloads_from_zip(
                    nested_zip,
                    source_file,
                    depth=depth,
                )
                payloads.extend(self._extract_saz_session_pairing_payloads(nested_zip, source_file))
                return payloads
        except Exception:  # noqa: BLE001
            return []

    def _extract_saz_session_pairing_payloads(
        self,
        zf: zipfile.ZipFile,
        source_file: str,
    ) -> list[tuple[str, str, str]]:
        sessions: dict[str, dict[str, tuple[str, bytes]]] = {}
        members = zf.infolist()
        member_entries = self._run_ordered_local_batch(
            members,
            self._saz_raw_session_member_entry,
            default_factory=lambda: None,
        )
        for member, entry in zip(members, member_entries):
            if entry is None:
                continue
            session_id, side, member_name = entry
            try:
                member_bytes = zf.read(member)[:_MAX_ARTIFACT_MEMBER_BYTES]
            except Exception:  # noqa: BLE001
                continue
            if not member_bytes:
                continue
            sessions.setdefault(session_id, {})[side] = (member_name, member_bytes)
        if not sessions:
            return []
        session_jobs = [
            (session_id, session["c"], session["s"])
            for session_id, session in sorted(sessions.items())
            if "c" in session and "s" in session
        ]
        if not session_jobs:
            return []
        payload_batches = self._run_ordered_local_batch(
            session_jobs,
            lambda job: self._saz_session_pairing_payload(job, source_file=source_file),
            default_factory=lambda: None,
        )
        return [
            payload
            for payload in payload_batches
            if isinstance(payload, tuple)
        ]

    @staticmethod
    def _saz_raw_session_member_entry(
        member: zipfile.ZipInfo,
    ) -> tuple[str, str, str] | None:
        if member.is_dir() or member.file_size > _MAX_ARTIFACT_MEMBER_BYTES:
            return None
        member_name = ArtifactQueueProcessor._safe_archive_member_name(str(member.filename or ""))
        if not member_name:
            return None
        match = _SAZ_RAW_SESSION_MEMBER_RE.search(member_name)
        if not match:
            return None
        return (
            str(match.group("session_id") or ""),
            str(match.group("side") or "").lower(),
            member_name,
        )

    def _saz_session_pairing_payload(
        self,
        job: tuple[str, tuple[str, bytes], tuple[str, bytes]],
        *,
        source_file: str,
    ) -> tuple[str, str, str] | None:
        session_id, request_member, response_member = job
        request_member_name, request_bytes = request_member
        response_member_name, response_bytes = response_member
        request_text = self._decode_text_artifact_bytes(request_bytes[:_MAX_ARTIFACT_MEMBER_BYTES])
        response_text = self._decode_text_artifact_bytes(response_bytes[:_MAX_ARTIFACT_MEMBER_BYTES])
        origin_url = self._saz_request_origin_url(request_text)
        if not origin_url:
            return None
        lines: list[str] = []
        for location in self._saz_response_relative_locations(response_text):
            candidate = self._http_transcript_url_candidate_entry(urljoin(f"{origin_url}/", location))
            if candidate and candidate not in lines:
                lines.append(candidate)
        if not lines:
            return None
        extract_path = f"raw/{session_id}_c+s.txt#saz-session-pair"
        return (
            source_file,
            extract_path,
            "\n".join(
                [
                    f"request.member={request_member_name}",
                    f"response.member={response_member_name}",
                    *lines[:32],
                ]
            ),
        )

    def _saz_request_origin_url(self, request_text: str) -> str:
        for value in self._http_transcript_text_candidate_values(request_text):
            candidate = self._http_transcript_url_candidate_entry(value)
            parsed = urlparse(candidate)
            if parsed.scheme in {"http", "https"} and parsed.netloc:
                return parsed._replace(path="", params="", query="", fragment="").geturl().rstrip("/")
        return ""

    @staticmethod
    def _saz_response_relative_locations(response_text: str) -> list[str]:
        locations: list[str] = []
        for line in str(response_text or "").splitlines()[:2048]:
            header_match = _HTTP_TRANSCRIPT_HEADER_RE.match(line.strip())
            if not header_match:
                continue
            name = str(header_match.group("name") or "").strip().lower()
            if name not in {"location", "content-location"}:
                continue
            value = str(header_match.group("value") or "").strip().strip("\"'")
            if not value.startswith("/") or value.startswith("//"):
                continue
            if value not in locations:
                locations.append(value)
        return locations[:32]

    def _extract_archive_7z_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if py7zr is None or data[:6] != b"7z\xbc\xaf'\x1c":
            return []
        return self._extract_text_payloads_from_7z(
            data,
            source_file,
            depth=depth,
        )

    def _extract_archive_ar_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        member_jobs = self._ar_archive_member_jobs(data)
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    @staticmethod
    def _ar_archive_member_jobs(data: bytes) -> list[tuple[str, bytes]]:
        if not data.startswith(_AR_ARCHIVE_MAGIC):
            return []
        jobs: list[tuple[str, bytes]] = []
        string_table = b""
        offset = len(_AR_ARCHIVE_MAGIC)
        while offset + 60 <= len(data):
            header = data[offset : offset + 60]
            if header[58:60] != b"`\n":
                break
            raw_name = header[:16].decode("utf-8", errors="ignore").strip()
            try:
                member_size = int(header[48:58].decode("ascii", errors="ignore").strip() or "0")
            except ValueError:
                break
            member_start = offset + 60
            member_end = member_start + member_size
            if member_end > len(data):
                break
            member_data = data[member_start:member_end]
            offset = member_end + (member_size % 2)

            if raw_name in {"/", "/SYM64/"}:
                continue
            if raw_name == "//":
                string_table = member_data
                continue

            member_name = raw_name.rstrip("/").strip()
            payload = member_data
            if raw_name.startswith("#1/"):
                try:
                    name_size = int(raw_name[3:])
                except ValueError:
                    continue
                if name_size <= 0 or name_size > len(member_data):
                    continue
                member_name = member_data[:name_size].decode("utf-8", errors="ignore").strip()
                payload = member_data[name_size:]
            elif raw_name.startswith("/") and raw_name[1:].isdigit() and string_table:
                table_offset = int(raw_name[1:])
                if table_offset >= len(string_table):
                    continue
                table_tail = string_table[table_offset:]
                member_name = table_tail.split(b"\n", 1)[0].decode("utf-8", errors="ignore")
                member_name = member_name.rstrip("/").strip()

            safe_name = ArtifactQueueProcessor._safe_archive_member_name(member_name)
            if not safe_name or not payload or len(payload) > _REMOTE_ARTIFACT_MAX_BYTES:
                continue
            jobs.append((safe_name, bytes(payload)))
        return jobs

    def _extract_archive_cpio_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        member_jobs = self._cpio_newc_member_jobs(data)
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    @staticmethod
    def _cpio_newc_member_jobs(data: bytes) -> list[tuple[str, bytes]]:
        if data[:6] not in _CPIO_NEWC_MAGICS:
            return []
        jobs: list[tuple[str, bytes]] = []
        offset = 0
        while offset + 110 <= len(data):
            header = data[offset : offset + 110]
            if header[:6] not in _CPIO_NEWC_MAGICS:
                break
            try:
                mode = int(header[14:22].decode("ascii", errors="ignore"), 16)
                file_size = int(header[54:62].decode("ascii", errors="ignore"), 16)
                name_size = int(header[94:102].decode("ascii", errors="ignore"), 16)
            except ValueError:
                break
            if name_size <= 0 or name_size > _MAX_ARTIFACT_MEMBER_BYTES:
                break
            name_start = offset + 110
            name_end = name_start + name_size
            if name_end > len(data):
                break
            raw_name = data[name_start:name_end].rstrip(b"\x00").decode("utf-8", errors="ignore")
            data_start = name_end + ((4 - (name_end % 4)) % 4)
            data_end = data_start + file_size
            if data_end > len(data):
                break
            offset = data_end + ((4 - (data_end % 4)) % 4)
            if raw_name == "TRAILER!!!":
                break
            if file_size <= 0 or file_size > _REMOTE_ARTIFACT_MAX_BYTES:
                continue
            if mode & 0o170000 != 0o100000:
                continue
            safe_name = ArtifactQueueProcessor._safe_archive_member_name(raw_name)
            if not safe_name:
                continue
            jobs.append((safe_name, bytes(data[data_start:data_end])))
        return jobs

    def _extract_archive_asar_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        member_jobs = self._asar_archive_member_jobs(data)
        if not member_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            member_jobs,
            lambda member_job: self._extract_member_data_payloads(
                member_job[1],
                source_file,
                member_job[0],
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_batches = self._run_ordered_local_batch(
            [
                (member_index, member_payloads or [])
                for member_index, member_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for member_payloads in prepared_payload_batches:
            payloads.extend(member_payloads)
        return payloads

    @staticmethod
    def _asar_header_and_content_base(data: bytes) -> tuple[dict[str, Any], int] | None:
        if len(data) < 12:
            return None
        try:
            header_size, header_json_size = struct.unpack("<II", data[:8])
        except struct.error:
            return None
        if (
            header_size < 4
            or header_json_size <= 0
            or header_size > _MAX_ASAR_HEADER_BYTES
            or header_json_size > _MAX_ASAR_HEADER_BYTES
            or header_json_size > header_size - 4
        ):
            return None
        header_start = 8
        header_end = header_start + header_json_size
        content_base = 8 + header_size
        if header_end > len(data) or content_base > len(data) or content_base < header_end:
            return None
        try:
            header_text = data[header_start:header_end].decode("utf-8").strip()
            parsed = json.loads(header_text)
        except Exception:  # noqa: BLE001
            return None
        if not isinstance(parsed, dict) or not isinstance(parsed.get("files"), dict):
            return None
        return parsed, content_base

    @staticmethod
    def _asar_non_negative_int(value: Any) -> int | None:
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            return value if value >= 0 else None
        text = str(value or "").strip()
        if not text or not text.isdigit():
            return None
        try:
            return int(text)
        except ValueError:
            return None

    @classmethod
    def _asar_archive_member_jobs(cls, data: bytes) -> list[tuple[str, bytes]]:
        header_info = cls._asar_header_and_content_base(data)
        if header_info is None:
            return []
        header, content_base = header_info
        root_files = header.get("files")
        if not isinstance(root_files, dict):
            return []

        jobs: list[tuple[str, bytes]] = []

        def _visit(prefix: tuple[str, ...], entries: dict[str, Any], depth: int) -> None:
            if depth > 32 or len(jobs) >= _MAX_ASAR_MEMBERS:
                return
            for raw_name, entry in entries.items():
                if len(jobs) >= _MAX_ASAR_MEMBERS:
                    return
                name = str(raw_name or "").strip()
                if not name or not isinstance(entry, dict):
                    continue
                member_parts = (*prefix, name)
                child_files = entry.get("files")
                if isinstance(child_files, dict):
                    _visit(member_parts, child_files, depth + 1)
                    continue
                if bool(entry.get("unpacked")):
                    continue
                member_size = cls._asar_non_negative_int(entry.get("size"))
                relative_offset = cls._asar_non_negative_int(entry.get("offset"))
                if member_size is None or relative_offset is None or member_size <= 0:
                    continue
                member_name = "/".join(member_parts)
                safe_name = ArtifactQueueProcessor._safe_archive_member_name(member_name)
                if not safe_name:
                    continue
                suffix = Path(safe_name.lower()).suffix
                size_limit = _MAX_OCR_IMAGE_BYTES if suffix in _OCR_IMAGE_SUFFIXES else _MAX_ARTIFACT_MEMBER_BYTES
                if member_size > size_limit:
                    continue
                member_start = content_base + relative_offset
                member_end = member_start + member_size
                if member_start < content_base or member_end > len(data):
                    continue
                jobs.append((safe_name, bytes(data[member_start:member_end])))

        _visit((), root_files, 0)
        return jobs

    def _extract_archive_tar_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        try:
            with tarfile.open(fileobj=BytesIO(data), mode="r:*") as nested_tar:
                members = nested_tar.getmembers()
                if not any(member.isfile() for member in members):
                    return []
                oci_payloads = self._extract_oci_image_layout_tar_payloads(
                    nested_tar,
                    members,
                    source_file,
                    depth=depth,
                )
                if oci_payloads:
                    return oci_payloads
                docker_save_payloads = self._extract_docker_save_image_tar_payloads(
                    nested_tar,
                    members,
                    source_file,
                    depth=depth,
                )
                if docker_save_payloads:
                    return docker_save_payloads
                return self._extract_text_payloads_from_tar(
                    nested_tar,
                    source_file,
                    depth=depth,
                )
        except Exception:  # noqa: BLE001
            return []

    def _extract_archive_decompressed_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        decompressed = self._decompress_archive_stream_bytes(data, member_name)
        if decompressed is None:
            return []

        compression_kind, decompressed_bytes = decompressed
        nested_name = f"{member_name}#decompressed-{compression_kind}"
        nested_payloads = self._extract_archive_bytes_payloads(
            decompressed_bytes,
            source_file,
            nested_name,
            depth=depth + 1,
        )
        if nested_payloads:
            return nested_payloads
        return [
            (
                source_file,
                f"{nested_name}.txt",
                self._decode_text_artifact_bytes(decompressed_bytes),
            )
        ]

    @staticmethod
    def _archive_stream_kind(data: bytes, member_name: str) -> str:
        lowered = member_name.lower()
        if lowered.endswith((".gz", ".tgz", ".tar.gz")) or data[:2] == b"\x1f\x8b":
            return "gz"
        if lowered.endswith((".bz2", ".tbz", ".tbz2", ".tar.bz2")) or data[:3] == b"BZh":
            return "bz2"
        if lowered.endswith((".xz", ".txz", ".tar.xz")) or data[:6] == b"\xfd7zXZ\x00":
            return "xz"
        if lowered.endswith((".zst", ".tzst", ".tar.zst")) or data[:4] == b"\x28\xb5\x2f\xfd":
            return "zst"
        if lowered.endswith((".br", ".tbr", ".tar.br")):
            return "br"
        if lowered.endswith((".lz4", ".tlz4", ".tar.lz4")) or data[:4] == b"\x04\x22\x4d\x18":
            return "lz4"
        return ""

    def _decompress_archive_stream_bytes(
        self,
        data: bytes,
        member_name: str,
    ) -> tuple[str, bytes] | None:
        archive_kind = self._archive_stream_kind(data, member_name)
        if not archive_kind:
            return None
        try:
            if archive_kind == "gz":
                try:
                    return archive_kind, gzip.decompress(data)
                except Exception:  # noqa: BLE001
                    return archive_kind, zlib.decompress(data, wbits=16 + zlib.MAX_WBITS)
            if archive_kind == "bz2":
                try:
                    return archive_kind, bz2.decompress(data)
                except Exception:  # noqa: BLE001
                    decompressor = bz2.BZ2Decompressor()
                    return archive_kind, decompressor.decompress(data)
            if archive_kind == "xz":
                try:
                    return archive_kind, lzma.decompress(data)
                except Exception:  # noqa: BLE001
                    decompressor = lzma.LZMADecompressor()
                    return archive_kind, decompressor.decompress(data)
            if archive_kind == "zst" and zstandard is not None:
                decompressor = zstandard.ZstdDecompressor()
                with decompressor.stream_reader(BytesIO(data)) as reader:
                    decompressed = reader.read(_REMOTE_ARTIFACT_MAX_BYTES + 1)
                if len(decompressed) > _REMOTE_ARTIFACT_MAX_BYTES:
                    return None
                return archive_kind, decompressed
            if archive_kind == "br" and brotli is not None:
                decompressed = brotli.decompress(data)
                if len(decompressed) > _REMOTE_ARTIFACT_MAX_BYTES:
                    return None
                return archive_kind, decompressed
            if archive_kind == "lz4" and lz4_frame is not None:
                decompressor = lz4_frame.LZ4FrameDecompressor()
                decompressed = decompressor.decompress(
                    data,
                    max_length=_REMOTE_ARTIFACT_MAX_BYTES + 1,
                )
                if len(decompressed) > _REMOTE_ARTIFACT_MAX_BYTES:
                    return None
                if not getattr(decompressor, "eof", False):
                    return None
                return archive_kind, decompressed
        except Exception:  # noqa: BLE001
            return None
        return None

    @classmethod
    def _static_batch_worker_count(cls, item_count: int) -> int:
        if item_count <= 1:
            return max(0, item_count)
        raw_value = os.environ.get("FORGE_STATIC_ARTIFACT_MAX_WORKERS", "").strip()
        if not raw_value:
            return 1
        try:
            configured = int(raw_value)
        except ValueError:
            return 1
        return max(1, min(cls._MAX_STATIC_BATCH_WORKERS, item_count, configured))

    @classmethod
    def _run_ordered_static_batch(
        cls,
        items: Sequence[Any],
        worker: Callable[[Any], Any],
        *,
        default_factory: Callable[[], Any],
        max_workers: int | None = None,
    ) -> list[Any]:
        batch_items = list(items)
        if not batch_items:
            return []
        if max_workers is None:
            bounded_workers = cls._static_batch_worker_count(len(batch_items))
        else:
            bounded_workers = max(1, min(cls._MAX_STATIC_BATCH_WORKERS, len(batch_items), int(max_workers)))
        if bounded_workers <= 1:
            results: list[Any] = []
            for item in batch_items:
                try:
                    results.append(worker(item))
                except Exception:  # noqa: BLE001
                    results.append(default_factory())
            return results
        ordered_results: list[Any | None] = [None] * len(batch_items)
        with ThreadPoolExecutor(max_workers=bounded_workers) as executor:
            future_map = {
                executor.submit(worker, item): index
                for index, item in enumerate(batch_items)
            }
            for future in as_completed(future_map):
                index = future_map[future]
                try:
                    ordered_results[index] = future.result()
                except Exception:  # noqa: BLE001
                    ordered_results[index] = default_factory()
        return [result if result is not None else default_factory() for result in ordered_results]

    @classmethod
    def _decode_text_artifact_bytes(
        cls,
        data: bytes,
        *,
        limit: int = _MAX_ARTIFACT_MEMBER_BYTES,
    ) -> str:
        bounded = data[:limit]
        fallback = ""
        decoded_candidates = cls._run_ordered_static_batch(
            [
                (encoding, bounded)
                for encoding in ("utf-8-sig", "utf-16", "utf-16-le", "utf-16-be", "utf-8", "cp1252", "latin-1")
            ],
            cls._decode_text_artifact_entry,
            default_factory=str,
        )
        for text in decoded_candidates:
            if not text:
                continue
            if not fallback:
                fallback = text
            if (
                any(char.isalpha() for char in text[:512])
                or "://" in text
                or "@" in text
                or "=" in text
                or ";" in text
                or "{" in text
            ):
                return text
        return fallback

    @staticmethod
    def _decode_text_artifact_entry(entry: tuple[str, bytes]) -> str:
        encoding, bounded = entry
        try:
            return bounded.decode(encoding, errors="ignore").replace("\x00", "").strip()
        except Exception:  # noqa: BLE001
            return ""

    @staticmethod
    def _read_text(path: Path) -> str:
        return ArtifactQueueProcessor._decode_text_artifact_bytes(path.read_bytes())

    def _extract_calendar_contact_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        return self._extract_calendar_contact_bytes_payloads(
            path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
            str(path),
            path.name,
        )

    def _extract_calendar_contact_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        text = self._decode_text_artifact_bytes(data)
        if not text:
            return []
        unfolded = self._unfold_calendar_contact_text(text)
        summary_lines = self._calendar_contact_summary_lines(unfolded)
        payloads: list[tuple[str, str, str]] = []
        if summary_lines:
            payloads.append(
                (
                    source_file,
                    f"{member_name}#calendar-contact-summary",
                    "\n".join(summary_lines),
                )
            )
        if unfolded:
            payloads.append((source_file, member_name, unfolded))
        return payloads

    @staticmethod
    def _unfold_calendar_contact_text(text: str) -> str:
        lines = str(text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
        unfolded: list[str] = []
        for line in lines:
            if line.startswith((" ", "\t")) and unfolded:
                unfolded[-1] += line[1:]
                continue
            unfolded.append(line.rstrip())
        return "\n".join(unfolded).strip()

    @staticmethod
    def _calendar_contact_summary_lines(text: str) -> list[str]:
        line_candidates = ArtifactQueueProcessor._run_ordered_static_batch(
            str(text or "").splitlines(),
            ArtifactQueueProcessor._calendar_contact_summary_line_entry,
            default_factory=lambda: None,
        )
        lines: list[str] = []
        seen: set[str] = set()
        for summary_line in line_candidates:
            if not summary_line:
                continue
            if summary_line in seen:
                continue
            seen.add(summary_line)
            lines.append(summary_line)
            if len(lines) >= 80:
                break
        return lines

    @staticmethod
    def _calendar_contact_summary_line_entry(raw_line: str) -> str | None:
        interesting_keys = {
            "BEGIN",
            "FN",
            "N",
            "ORG",
            "TITLE",
            "SUMMARY",
            "DESCRIPTION",
            "EMAIL",
            "TEL",
            "URL",
            "LOCATION",
            "ATTENDEE",
            "ORGANIZER",
        }
        line = str(raw_line or "").strip()
        if not line or ":" not in line:
            return None
        key_part, raw_value = line.split(":", 1)
        key = key_part.split(";", 1)[0].strip().upper()
        if key not in interesting_keys:
            return None
        value = raw_value.strip()
        if key in {"ATTENDEE", "ORGANIZER"} and value.lower().startswith("mailto:"):
            value = value[7:].strip()
        if not value:
            return None
        if len(value) > 1024:
            value = value[:1024].rstrip()
        return f"{key.lower()}={value}"

    def _extract_pdf_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payload_fragments = self._run_ordered_local_batch(
            ("text", "metadata", "xmp", "ocr"),
            lambda family: self._extract_pdf_payload_fragment(
                family,
                data=data,
                source_file=str(path),
                member_name=path.name,
                path=path,
            ),
            default_factory=list,
        )
        prepared_fragments = self._run_ordered_local_batch(
            list(enumerate(payload_fragments)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for fragment in prepared_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_pdf_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        payload_fragments = self._run_ordered_local_batch(
            ("text", "metadata", "xmp", "ocr"),
            lambda family: self._extract_pdf_payload_fragment(
                family,
                data=bounded,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_fragments = self._run_ordered_local_batch(
            list(enumerate(payload_fragments)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for fragment in prepared_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_pdf_payload_fragment(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
        path: Path | None = None,
    ) -> list[tuple[str, str, str]]:
        if family == "text":
            if path is not None:
                return self._extract_pdf_text_payloads_from_path(path)
            return self._extract_pdf_text_payloads_from_bytes(
                data,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "metadata":
            metadata_lines = self._pdf_metadata_lines(data)
            if metadata_lines:
                return [(source_file, f"{member_name}#pdf-metadata", "\n".join(metadata_lines))]
            return []
        if family == "xmp":
            xmp_payload = self._pdf_xmp_payload(data)
            if xmp_payload:
                return [(source_file, f"{member_name}#pdf-xmp", xmp_payload)]
            return []
        if family == "ocr":
            if path is not None:
                return self._extract_pdf_ocr_payloads(path)
            return self._extract_pdf_bytes_ocr_payloads(
                data,
                source_file,
                member_name,
            )
        return []

    def _extract_pdf_text_payloads_from_path(
        self,
        path: Path,
    ) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        return [(str(path), path.name, self._read_text(path))]

    def _extract_pdf_text_payloads_from_bytes(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        return [
            (
                source_file,
                member_name,
                data[:_MAX_ARTIFACT_MEMBER_BYTES].decode("latin-1", errors="ignore"),
            )
        ]

    def _extract_sqlite_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        try:
            con = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        except sqlite3.Error:
            return [(str(path), path.name, self._read_text(path))]
        try:
            payloads = self._extract_sqlite_connection_payloads(
                con,
                str(path),
                path.name,
            )
        finally:
            con.close()
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_sqlite_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        suffix = Path(member_name).suffix or ".sqlite"
        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                temp_path = Path(temp_dir) / f"artifact{suffix}"
                temp_path.write_bytes(bounded)
                con = sqlite3.connect(f"file:{temp_path.as_posix()}?mode=ro", uri=True)
                try:
                    payloads = self._extract_sqlite_connection_payloads(
                        con,
                        source_file,
                        member_name,
                    )
                finally:
                    con.close()
        except Exception:  # noqa: BLE001
            payloads = []
        return payloads or self._member_payloads(source_file, member_name, bounded)

    def _extract_emlx_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_emlx_bytes_payloads(
            data,
            str(path),
            path.name,
            depth=depth,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_emlx_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        message_bytes = self._emlx_message_bytes(data)
        if not message_bytes:
            return self._member_payloads(source_file, member_name, data)
        return self._extract_email_message_payloads(
            message_bytes[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            member_name,
            depth=depth,
        )

    @staticmethod
    def _emlx_message_bytes(data: bytes) -> bytes:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return b""
        match = re.match(rb"\s*(\d+)\r?\n", bounded[:128])
        if not match:
            return bounded
        start = match.end()
        remaining = bounded[start:]
        if not remaining:
            return b""
        try:
            declared_length = int(match.group(1))
        except (TypeError, ValueError):
            return remaining
        if declared_length <= 0:
            return remaining
        if declared_length <= len(remaining):
            return remaining[:declared_length]
        return remaining

    def _extract_msg_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_msg_bytes_payloads(
            data,
            str(path),
            path.name,
            depth=depth,
        )
        return payloads or self._extract_legacy_document_payloads(path, depth=depth)

    def _extract_msg_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        try:
            import olefile  # noqa: PLC0415
        except Exception:  # noqa: BLE001
            return self._extract_legacy_binary_payloads(
                bounded,
                source_file,
                member_name,
                depth=depth,
            )
        try:
            with olefile.OleFileIO(BytesIO(bounded)) as ole:
                payloads = self._extract_msg_ole_payloads(
                    ole,
                    source_file,
                    member_name,
                    depth=depth,
                )
        except Exception:  # noqa: BLE001
            payloads = []
        if payloads:
            return payloads
        return self._extract_legacy_binary_payloads(
            bounded,
            source_file,
            member_name,
            depth=depth,
        )

    def _extract_msg_ole_payloads(
        self,
        ole: Any,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        summary_lines: list[str] = []
        attachments: dict[str, dict[str, Any]] = {}

        try:
            stream_parts_list = ole.listdir(streams=True, storages=False)
        except Exception:  # noqa: BLE001
            return []

        summary_lines.extend(self._ole_metadata_lines(ole))

        raw_property_entries: list[tuple[tuple[Any, ...], bytes]] = []
        for stream_parts in stream_parts_list:
            if not stream_parts:
                continue
            stream_name = str(stream_parts[-1] or "").strip()
            if not _MSG_PROPERTY_STREAM_RE.fullmatch(stream_name):
                continue
            try:
                stream_data = ole.openstream(stream_parts).read(_MAX_ARTIFACT_MEMBER_BYTES)
            except Exception:  # noqa: BLE001
                continue
            raw_property_entries.append((tuple(stream_parts), stream_data))
        property_entries = self._run_ordered_local_batch(
            raw_property_entries,
            self._msg_ole_property_entry,
            default_factory=lambda: None,
        )
        property_entries = [
            property_entry
            for property_entry in property_entries
            if isinstance(property_entry, tuple)
        ]
        job_batches = self._run_ordered_local_batch(
            property_entries,
            lambda property_entry: self._msg_ole_property_stream_job(
                property_entry,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        property_jobs = [
            job
            for job in job_batches
            if isinstance(job, MsgOLEPropertyJob)
        ]

        ordered_property_results = self._run_ordered_local_batch(
            property_jobs,
            self._extract_msg_ole_property_job,
            default_factory=MsgOLEPropertyResult,
        )

        for result in ordered_property_results:
            if result is None:
                continue
            payloads.extend(result.payloads)
            summary_lines.extend(result.summary_lines)
            if result.attachment_storage:
                attachment = attachments.setdefault(result.attachment_storage, {})
                for key, value in result.attachment_updates:
                    attachment[key] = value

        attachment_jobs: list[MsgAttachmentExtractionJob] = []
        if depth < 2 and attachments:
            built_attachment_jobs = self._run_ordered_local_batch(
                list(enumerate(attachments.values(), start=1)),
                lambda attachment_job: self._build_msg_attachment_job(
                    attachment_job,
                    source_file=source_file,
                    member_name=member_name,
                    depth=depth,
                ),
                default_factory=lambda: None,
            )
            attachment_jobs = [job for job in built_attachment_jobs if job is not None]

        payload_families = self._run_ordered_local_batch(
            ("summary", "attachments"),
            lambda family: self._extract_msg_post_property_payload_family(
                family,
                summary_lines=summary_lines,
                attachment_jobs=attachment_jobs,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        family_head_payloads = prepared_payload_families[0] if prepared_payload_families else []
        family_tail_payloads = prepared_payload_families[1] if len(prepared_payload_families) > 1 else []
        return [*family_head_payloads, *payloads, *family_tail_payloads]

    @staticmethod
    def _msg_ole_property_entry(
        property_entry: tuple[Sequence[Any], bytes],
    ) -> tuple[tuple[Any, ...], bytes] | None:
        stream_parts, stream_data = property_entry
        normalized_parts = tuple(stream_parts)
        if not normalized_parts or not stream_data:
            return None
        return normalized_parts, bytes(stream_data)

    def _msg_ole_property_stream_job(
        self,
        property_entry: tuple[Sequence[Any], bytes],
        *,
        source_file: str,
        member_name: str,
    ) -> MsgOLEPropertyJob | None:
        stream_parts, stream_data = property_entry
        if not stream_parts or not stream_data:
            return None
        stream_name = str(stream_parts[-1] or "").strip()
        match = _MSG_PROPERTY_STREAM_RE.fullmatch(stream_name)
        if not match:
            return None
        prop_id, prop_type = (group.upper() for group in match.groups())
        attachment_storage = next(
            (
                str(part or "").strip()
                for part in stream_parts[:-1]
                if str(part or "").strip().startswith(_MSG_ATTACHMENT_STORAGE_PREFIX)
            ),
            "",
        )
        label = _MSG_PROPERTY_LABELS.get(prop_id, f"prop_{prop_id.lower()}")
        return MsgOLEPropertyJob(
            source_file=source_file,
            member_name=member_name,
            attachment_storage=attachment_storage,
            label=label,
            prop_id=prop_id,
            prop_type=prop_type,
            stream_data=stream_data,
        )

    def _extract_msg_post_property_payload_family(
        self,
        family: str,
        *,
        summary_lines: Sequence[str],
        attachment_jobs: Sequence[MsgAttachmentExtractionJob],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_msg_summary_payloads(
                summary_lines,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "attachments":
            return self._extract_msg_attachment_job_payloads(attachment_jobs)
        return []

    def _extract_msg_summary_payloads(
        self,
        summary_lines: Sequence[str],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not summary_lines:
            return []
        return [(source_file, f"{member_name}#msg-meta", "\n".join(summary_lines[:256]))]

    def _extract_msg_attachment_job_payloads(
        self,
        attachment_jobs: Sequence[MsgAttachmentExtractionJob],
    ) -> list[tuple[str, str, str]]:
        if not attachment_jobs:
            return []
        ordered_attachment_payloads = self._run_ordered_local_batch(
            attachment_jobs,
            self._extract_msg_attachment_payloads,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (attachment_index, attachment_payloads or [])
                for attachment_index, attachment_payloads in enumerate(ordered_attachment_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for attachment_payloads in prepared_payloads:
            payloads.extend(attachment_payloads)
        return payloads

    def _build_msg_attachment_job(
        self,
        attachment_job: tuple[int, dict[str, Any]],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> MsgAttachmentExtractionJob | None:
        index, attachment = attachment_job
        attachment_data = attachment.get("data")
        if not isinstance(attachment_data, (bytes, bytearray)) or not attachment_data:
            return None
        attachment_name = self._msg_attachment_name(attachment, index)
        if not attachment_name:
            return None
        return MsgAttachmentExtractionJob(
            source_file=source_file,
            member_name=member_name,
            attachment_name=attachment_name,
            attachment_data=bytes(attachment_data)[:_MAX_ARTIFACT_MEMBER_BYTES],
            depth=depth + 1,
        )

    def _extract_msg_ole_property_job(
        self,
        job: MsgOLEPropertyJob,
    ) -> MsgOLEPropertyResult:
        if job.attachment_storage:
            if job.prop_id == "3701":
                return MsgOLEPropertyResult(
                    attachment_storage=job.attachment_storage,
                    attachment_updates=[
                        ("data", job.stream_data),
                        ("data_type", job.prop_type),
                    ],
                )
            attachment_text = self._msg_property_text(job.prop_id, job.prop_type, job.stream_data)
            if not attachment_text:
                return MsgOLEPropertyResult()
            return MsgOLEPropertyResult(
                attachment_storage=job.attachment_storage,
                attachment_updates=[(job.label, attachment_text)],
            )

        property_text = self._msg_property_text(job.prop_id, job.prop_type, job.stream_data)
        if not property_text:
            return MsgOLEPropertyResult()
        if job.prop_id in {"1000", "1013"}:
            suffix = ".html" if job.prop_id == "1013" or "<html" in property_text.lower() else ".txt"
            return MsgOLEPropertyResult(
                payloads=[
                    (
                        job.source_file,
                        f"{job.member_name}#msg-{job.label}{suffix}",
                        property_text,
                    )
                ]
            )
        return MsgOLEPropertyResult(summary_lines=[f"{job.label}={property_text}"])

    def _extract_msg_attachment_payloads(
        self,
        job: MsgAttachmentExtractionJob,
    ) -> list[tuple[str, str, str]]:
        return self._extract_member_data_payloads(
            job.attachment_data,
            job.source_file,
            f"{job.member_name}/{job.attachment_name}",
            depth=job.depth,
        )

    def _msg_property_text(
        self,
        prop_id: str,
        prop_type: str,
        data: bytes,
    ) -> str:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return ""
        if prop_type == "001F":
            return bounded.decode("utf-16-le", errors="ignore").replace("\x00", "").strip()
        if prop_type == "001E":
            return self._decode_text_artifact_bytes(bounded)
        if prop_type == "0102" and prop_id in {"007D", "1000", "1013"}:
            return self._decode_text_artifact_bytes(bounded)
        return ""

    @staticmethod
    def _msg_attachment_name(attachment: dict[str, Any], index: int) -> str:
        for key in ("attachment_long_filename", "attachment_filename"):
            candidate = Path(str(attachment.get(key) or "").strip()).name
            if candidate:
                return candidate
        mime_tag = str(attachment.get("attachment_mime_tag") or "").strip().lower()
        suffix = _suffix_from_content_type(mime_tag) if mime_tag else ""
        if suffix:
            return f"attachment-{index}{suffix}"
        attachment_data = attachment.get("data")
        if isinstance(attachment_data, (bytes, bytearray)) and attachment_data:
            inferred_suffix = ArtifactQueueProcessor._msg_attachment_suffix_from_data(
                bytes(attachment_data)[:_MAX_ARTIFACT_MEMBER_BYTES]
            )
            if inferred_suffix:
                return f"attachment-{index}{inferred_suffix}"
        return ""

    @staticmethod
    def _msg_attachment_suffix_from_data(data: bytes) -> str:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        if not bounded:
            return ""
        if zipfile.is_zipfile(BytesIO(bounded)):
            return ".zip"
        if bounded.startswith(_OLE_MAGIC):
            return ".msg"
        if bounded.startswith(b"%PDF-"):
            return ".pdf"
        if ArtifactQueueProcessor._looks_like_archive_bytes(bounded):
            return ".zip"
        text_sample = ArtifactQueueProcessor._decode_text_artifact_bytes(bounded[:8192])
        if text_sample and (
            "=" in text_sample
            or "@" in text_sample
            or "http://" in text_sample.lower()
            or "https://" in text_sample.lower()
        ):
            return ".txt"
        return ""

    @staticmethod
    def _looks_like_pcap_bytes(data: bytes, member_name: str = "") -> bool:
        lowered = str(member_name or "").strip().lower()
        if lowered.endswith(tuple(_PCAP_SUFFIXES)) or any(f"{suffix}#" in lowered for suffix in _PCAP_SUFFIXES):
            return True
        return data[:4] in _PCAP_CLASSIC_MAGICS or data[:4] == _PCAPNG_MAGIC

    def _extract_pcap_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        return self._extract_pcap_bytes_payloads(
            path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES],
            str(path),
            path.name,
        )

    def _extract_pcap_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._looks_like_pcap_bytes(data, member_name):
            return self._member_payloads(source_file, member_name, data)
        payload_fragments = self._run_ordered_local_batch(
            ("summary", "strings"),
            lambda family: self._extract_pcap_payload_family(
                family,
                data=data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_fragments = self._run_ordered_local_batch(
            list(enumerate(payload_fragments)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for fragment in prepared_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_pcap_payload_family(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            summary_lines = self._pcap_summary_lines(data, member_name)
            if summary_lines:
                return [(source_file, f"{member_name}#pcap-summary", "\n".join(summary_lines))]
            return []
        if family == "strings":
            strings_payload = self._binary_string_payload(data)
            if strings_payload:
                return [(source_file, f"{member_name}#pcap-strings", strings_payload)]
            return []
        return []

    def _pcap_summary_lines(self, data: bytes, member_name: str) -> list[str]:
        if data[:4] == _PCAPNG_MAGIC:
            return self._pcapng_summary_lines(data)
        if data[:4] in _PCAP_CLASSIC_MAGICS:
            return self._pcap_classic_summary_lines(data)
        if Path(member_name.lower()).suffix == ".pcapng":
            return ["format=pcapng"]
        return ["format=pcap"]

    @staticmethod
    def _pcap_classic_summary_lines(data: bytes) -> list[str]:
        endian = _PCAP_CLASSIC_MAGICS.get(data[:4])
        if not endian or len(data) < 24:
            return ["format=pcap"]
        try:
            version_major, version_minor, _thiszone, _sigfigs, snaplen, linktype = struct.unpack(
                f"{endian}HHIIII",
                data[4:24],
            )
        except struct.error:
            return ["format=pcap"]
        packet_count = 0
        captured_bytes = 0
        offset = 24
        while offset + 16 <= len(data) and packet_count < 1024:
            try:
                _ts_sec, _ts_usec, incl_len, _orig_len = struct.unpack(
                    f"{endian}IIII",
                    data[offset : offset + 16],
                )
            except struct.error:
                break
            offset += 16
            if incl_len > len(data) - offset:
                break
            packet_count += 1
            captured_bytes += incl_len
            offset += incl_len
        return [
            "format=pcap",
            f"version={version_major}.{version_minor}",
            f"linktype={linktype}",
            f"snaplen={snaplen}",
            f"packet_count={packet_count}",
            f"captured_bytes={captured_bytes}",
        ]

    @staticmethod
    def _pcapng_summary_lines(data: bytes) -> list[str]:
        if len(data) < 12:
            return ["format=pcapng"]
        byte_order_magic = data[8:12]
        if byte_order_magic == b"\x4d\x3c\x2b\x1a":
            endian = "<"
        elif byte_order_magic == b"\x1a\x2b\x3c\x4d":
            endian = ">"
        else:
            endian = "<"
        interface_count = 0
        packet_count = 0
        captured_bytes = 0
        offset = 0
        while offset + 12 <= len(data) and packet_count < 1024:
            try:
                block_type, block_length = struct.unpack(f"{endian}II", data[offset : offset + 8])
            except struct.error:
                break
            if block_length < 12 or offset + block_length > len(data):
                break
            if block_type == 0x00000001:
                interface_count += 1
            elif block_type == 0x00000006 and block_length >= 32:
                try:
                    captured_length = struct.unpack(f"{endian}I", data[offset + 20 : offset + 24])[0]
                except struct.error:
                    captured_length = 0
                packet_count += 1
                captured_bytes += min(captured_length, max(0, block_length - 32))
            elif block_type == 0x00000003 and block_length >= 16:
                try:
                    captured_length = struct.unpack(f"{endian}I", data[offset + 8 : offset + 12])[0]
                except struct.error:
                    captured_length = 0
                packet_count += 1
                captured_bytes += min(captured_length, max(0, block_length - 16))
            offset += block_length
        return [
            "format=pcapng",
            f"interface_count={interface_count}",
            f"packet_count={packet_count}",
            f"captured_bytes={captured_bytes}",
        ]

    @staticmethod
    def _looks_like_warc_bytes(data: bytes, member_name: str = "") -> bool:
        lowered = str(member_name or "").strip().lower()
        if lowered.endswith(".warc") or ".warc#" in lowered:
            return True
        stripped = data[:64].lstrip()
        return stripped.startswith(b"WARC/")

    def _extract_warc_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_warc_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_warc_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._looks_like_warc_bytes(data, member_name):
            return self._member_payloads(source_file, member_name, data)
        payloads = self._warc_payload_tuples(
            data[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            member_name,
        )
        return payloads or self._member_payloads(source_file, member_name, data)

    def _warc_payload_tuples(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        job_batches = self._run_ordered_local_batch(
            list(enumerate(self._iter_warc_records(data)[:24], start=1)),
            lambda record_job: self._warc_record_job(
                record_job,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        record_jobs = [
            job
            for job in job_batches
            if isinstance(job, WARCRecordExtractionJob)
        ]
        ordered_payloads = self._run_ordered_local_batch(
            record_jobs,
            self._extract_warc_record_payloads,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (record_index, record_payloads or [])
                for record_index, record_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        for record_payloads in prepared_payloads:
            payloads.extend(record_payloads)
        return payloads

    @staticmethod
    def _warc_record_job(
        record_job: tuple[int, bytes],
        *,
        source_file: str,
        member_name: str,
    ) -> WARCRecordExtractionJob | None:
        record_index, record = record_job
        if record_index <= 0:
            return None
        return WARCRecordExtractionJob(
            source_file=source_file,
            member_name=member_name,
            record_index=record_index,
            record=record,
        )

    def _extract_warc_record_payloads(
        self,
        job: WARCRecordExtractionJob,
    ) -> list[tuple[str, str, str]]:
        summary_lines, body_text = self._warc_record_payload(job.record)
        payload_families = self._run_ordered_local_batch(
            ("summary", "body"),
            lambda family: self._extract_warc_record_payload_family(
                family,
                job=job,
                summary_lines=summary_lines,
                body_text=body_text,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_warc_record_payload_family(
        self,
        family: str,
        *,
        job: WARCRecordExtractionJob,
        summary_lines: Sequence[str],
        body_text: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_warc_record_summary_payloads(job, summary_lines)
        if family == "body":
            return self._extract_warc_record_body_payloads(job, body_text)
        return []

    def _extract_warc_record_summary_payloads(
        self,
        job: WARCRecordExtractionJob,
        summary_lines: Sequence[str],
    ) -> list[tuple[str, str, str]]:
        if not summary_lines:
            return []
        return [
            (
                job.source_file,
                f"{job.member_name}#warc-record-{job.record_index}",
                "\n".join(summary_lines[:320]),
            )
        ]

    def _extract_warc_record_body_payloads(
        self,
        job: WARCRecordExtractionJob,
        body_text: str,
    ) -> list[tuple[str, str, str]]:
        if not body_text:
            return []
        return [
            (
                job.source_file,
                f"{job.member_name}#warc-body-{job.record_index}",
                body_text,
            )
        ]

    def _iter_warc_records(self, data: bytes) -> list[bytes]:
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        records: list[bytes] = []
        offset = 0
        while offset < len(bounded):
            start = bounded.find(b"WARC/", offset)
            if start == -1:
                break
            warc_header_bytes, remainder, separator_length = self._split_bytes_header_block(
                bounded[start:]
            )
            if not warc_header_bytes:
                break
            header_text = warc_header_bytes.decode("latin-1", errors="ignore")
            content_length = 0
            match = re.search(r"(?im)^Content-Length:\s*(\d+)\s*$", header_text)
            if match:
                try:
                    content_length = int(match.group(1))
                except (TypeError, ValueError):
                    content_length = 0
            body_start = start + len(warc_header_bytes) + separator_length
            if content_length > 0 and body_start + content_length <= len(bounded):
                record_end = body_start + content_length
            else:
                next_start = bounded.find(b"\nWARC/", max(body_start, start + 5))
                if next_start == -1:
                    record_end = len(bounded)
                else:
                    record_end = next_start + 1
            record = bounded[start:record_end].strip(b"\r\n")
            if record:
                records.append(record)
            offset = max(record_end, body_start)
            while offset < len(bounded) and bounded[offset : offset + 1] in {b"\r", b"\n"}:
                offset += 1
        return records

    def _warc_record_payload(
        self,
        record: bytes,
    ) -> tuple[list[str], str]:
        warc_header_bytes, content_bytes, _separator_length = self._split_bytes_header_block(record)
        if not warc_header_bytes:
            return [], ""
        http_header_bytes = b""
        body_bytes = content_bytes
        if self._looks_like_http_message_bytes(content_bytes):
            http_header_bytes, http_body_bytes, _http_separator_length = self._split_bytes_header_block(
                content_bytes
            )
            body_bytes = http_body_bytes
        family_results = self._run_ordered_local_batch(
            ("warc_summary", "http_summary", "body"),
            lambda family: self._warc_record_payload_family(
                family,
                warc_header_bytes=warc_header_bytes,
                http_header_bytes=http_header_bytes,
                body_bytes=body_bytes,
            ),
            default_factory=lambda: ([], ""),
        )
        prepared_family_entries = self._run_ordered_local_batch(
            list(enumerate(family_results)),
            self._warc_record_payload_family_entry,
            default_factory=lambda: None,
        )
        summary_lines: list[str] = []
        body_text = ""
        for family_entry in prepared_family_entries:
            if not isinstance(family_entry, dict):
                continue
            summary_lines.extend(list(family_entry.get("summary_lines") or []))
            family_body_text = str(family_entry.get("body_text") or "")
            if family_body_text and not body_text:
                body_text = family_body_text
        return summary_lines, body_text

    def _warc_record_payload_family(
        self,
        family: str,
        *,
        warc_header_bytes: bytes,
        http_header_bytes: bytes,
        body_bytes: bytes,
    ) -> tuple[list[str], str]:
        if family == "warc_summary":
            return (self._structured_header_lines(warc_header_bytes, prefix="warc"), "")
        if family == "http_summary":
            if not http_header_bytes:
                return ([], "")
            return (self._structured_header_lines(http_header_bytes, prefix="http"), "")
        if family == "body":
            return ([], self._har_text_from_bytes(body_bytes, limit=4096))
        return ([], "")

    @staticmethod
    def _warc_record_payload_family_entry(
        family_entry: tuple[int, tuple[Sequence[str], str]],
    ) -> dict[str, Any] | None:
        _family_index, payload = family_entry
        if not isinstance(payload, tuple) or len(payload) != 2:
            return None
        summary_lines, body_text = payload
        return {
            "summary_lines": [str(line) for line in summary_lines if str(line or "").strip()],
            "body_text": str(body_text or "").strip(),
        }

    @staticmethod
    def _split_bytes_header_block(data: bytes) -> tuple[bytes, bytes, int]:
        for separator in (b"\r\n\r\n", b"\n\n"):
            index = data.find(separator)
            if index != -1:
                return data[:index], data[index + len(separator) :], len(separator)
        return data, b"", 0

    @staticmethod
    def _looks_like_http_message_bytes(data: bytes) -> bool:
        if not data:
            return False
        header_bytes, _remainder, _separator_length = ArtifactQueueProcessor._split_bytes_header_block(data)
        first_line = header_bytes.splitlines()[0].strip() if header_bytes.splitlines() else b""
        if not first_line:
            return False
        if first_line.startswith(b"HTTP/"):
            return True
        return bool(re.match(rb"^[A-Z]{3,12}\s+\S+\s+HTTP/\d(?:\.\d+)?$", first_line))

    def _structured_header_lines(self, header_bytes: bytes, *, prefix: str) -> list[str]:
        text = header_bytes.decode("latin-1", errors="ignore").replace("\x00", "").strip()
        if not text:
            return []
        raw_lines = [line.strip() for line in text.splitlines() if line.strip()]
        if not raw_lines:
            return []
        lines = [f"{prefix}.start_line={raw_lines[0]}"]
        line_candidates = self._run_ordered_local_batch(
            raw_lines[1:64],
            lambda line: self._structured_header_line(prefix=prefix, line=line),
            default_factory=str,
        )
        lines.extend(candidate for candidate in line_candidates if candidate)
        return lines

    @staticmethod
    def _structured_header_line(*, prefix: str, line: str) -> str:
        if ":" not in line:
            return f"{prefix}.line={line}"
        name, value = line.split(":", 1)
        normalized_name = re.sub(r"[^a-z0-9]+", "_", name.strip().lower()).strip("_")
        if prefix == "warc" and normalized_name.startswith("warc_"):
            normalized_name = normalized_name[len("warc_") :]
        if normalized_name:
            return f"{prefix}.{normalized_name}={value.strip()}"
        return f"{prefix}.line={line}"

    def _extract_har_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_HAR_BYTES]
        payloads = self._extract_har_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_har_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        text = self._har_text_from_bytes(data, limit=_MAX_HAR_BYTES)
        if not text.strip():
            return self._member_payloads(source_file, member_name, data)
        try:
            payload = json.loads(text)
        except Exception:  # noqa: BLE001
            return self._member_payloads(source_file, member_name, data)
        har_payloads = self._har_payload_tuples(payload, source_file, member_name)
        return har_payloads or self._member_payloads(source_file, member_name, data)

    def _har_payload_tuples(
        self,
        payload: Any,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not isinstance(payload, dict):
            return []
        log_payload = payload.get("log")
        if not isinstance(log_payload, dict):
            return []
        payload_families = self._run_ordered_local_batch(
            ("summary", "entries"),
            lambda family: self._extract_har_payload_family(
                family,
                log_payload=log_payload,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_har_payload_family(
        self,
        family: str,
        *,
        log_payload: dict[str, Any],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_har_summary_payloads(
                log_payload,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "entries":
            return self._extract_har_entry_payloads(
                log_payload,
                source_file=source_file,
                member_name=member_name,
            )
        return []

    def _extract_har_summary_payloads(
        self,
        log_payload: dict[str, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        line_families = self._run_ordered_local_batch(
            ("version", "creator", "browser", "pages", "entries"),
            lambda family: self._har_summary_family_lines(family, log_payload=log_payload),
            default_factory=list,
        )
        prepared_line_families = self._run_ordered_local_batch(
            list(enumerate(line_families)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        summary_lines: list[str] = []
        for family_lines in prepared_line_families:
            summary_lines.extend(family_lines)
        if not summary_lines:
            return []
        return [(source_file, f"{member_name}#har-summary", "\n".join(summary_lines[:96]))]

    def _har_summary_family_lines(
        self,
        family: str,
        *,
        log_payload: dict[str, Any],
    ) -> list[str]:
        if family == "version":
            return self._har_summary_version_lines(log_payload)
        if family == "creator":
            return self._har_summary_creator_lines(log_payload)
        if family == "browser":
            return self._har_summary_browser_lines(log_payload)
        if family == "pages":
            return self._har_summary_page_lines(log_payload)
        if family == "entries":
            return self._har_summary_entry_count_lines(log_payload)
        return []

    def _har_summary_version_lines(self, log_payload: dict[str, Any]) -> list[str]:
        version = str(log_payload.get("version") or "").strip()
        if version:
            return [f"log.version={version}"]
        return []

    def _har_summary_creator_lines(self, log_payload: dict[str, Any]) -> list[str]:
        creator = log_payload.get("creator")
        if not isinstance(creator, dict):
            return []
        creator_name = str(creator.get("name") or "").strip()
        creator_version = str(creator.get("version") or "").strip()
        if creator_name or creator_version:
            return [f"creator={creator_name or 'unknown'} {creator_version}".strip()]
        return []

    def _har_summary_browser_lines(self, log_payload: dict[str, Any]) -> list[str]:
        browser = log_payload.get("browser")
        if not isinstance(browser, dict):
            return []
        browser_name = str(browser.get("name") or "").strip()
        browser_version = str(browser.get("version") or "").strip()
        if browser_name or browser_version:
            return [f"browser={browser_name or 'unknown'} {browser_version}".strip()]
        return []

    def _har_summary_page_lines(self, log_payload: dict[str, Any]) -> list[str]:
        pages = log_payload.get("pages")
        if not isinstance(pages, list):
            return []
        lines = [f"pages={len(pages)}"]
        line_batches = self._run_ordered_local_batch(
            list(enumerate(pages[:8], start=1)),
            self._har_summary_page_line_batch,
            default_factory=list,
        )
        prepared_line_batches = self._run_ordered_local_batch(
            list(enumerate(line_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        for line_batch in prepared_line_batches:
            lines.extend(line_batch)
        return lines

    def _har_summary_page_line_batch(self, page_job: tuple[int, Any]) -> list[str]:
        index, page = page_job
        if not isinstance(page, dict):
            return []
        lines: list[str] = []
        title = self._har_scalar_text(page.get("title"))
        page_id = self._har_scalar_text(page.get("id"))
        started = self._har_scalar_text(page.get("startedDateTime"))
        if title:
            lines.append(f"page[{index}].title={title}")
        if page_id:
            lines.append(f"page[{index}].id={page_id}")
        if started:
            lines.append(f"page[{index}].started={started}")
        return lines

    def _har_summary_entry_count_lines(self, log_payload: dict[str, Any]) -> list[str]:
        entries = log_payload.get("entries")
        if isinstance(entries, list):
            return [f"entries={len(entries)}"]
        return []

    def _extract_har_entry_payloads(
        self,
        log_payload: dict[str, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        entries = log_payload.get("entries")
        if not isinstance(entries, list):
            return []
        entry_job_batches = self._run_ordered_local_batch(
            list(enumerate(entries[:24], start=1)),
            lambda item: self._har_entry_job(
                item,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        entry_jobs = [
            entry_job
            for entry_job in entry_job_batches
            if isinstance(entry_job, HAREntryExtractionJob)
        ]
        ordered_payloads = self._run_ordered_local_batch(
            entry_jobs,
            self._extract_har_entry_payload,
            default_factory=lambda: None,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (entry_index, [entry_payload] if entry_payload is not None else [])
                for entry_index, entry_payload in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for entry_payloads in prepared_payloads:
            payloads.extend(entry_payloads)
        return payloads

    @staticmethod
    def _har_entry_job(
        item: tuple[int, Any],
        *,
        source_file: str,
        member_name: str,
    ) -> HAREntryExtractionJob | None:
        entry_index, entry = item
        return HAREntryExtractionJob(
            source_file=source_file,
            member_name=member_name,
            entry_index=int(entry_index),
            entry=entry,
        )

    def _extract_har_entry_payload(
        self,
        job: HAREntryExtractionJob,
    ) -> tuple[str, str, str] | None:
        entry_lines = self._har_entry_lines(job.entry)
        if not entry_lines:
            return None
        return (
            job.source_file,
            f"{job.member_name}#har-entry-{job.entry_index}",
            "\n".join(entry_lines[:320]),
        )

    def _har_entry_lines(self, entry: Any) -> list[str]:
        if not isinstance(entry, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("started", "request", "response", "websocket_messages"),
            lambda family: self._har_entry_family_lines(family, entry=entry),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_entry_family_lines(
        self,
        family: str,
        *,
        entry: dict[str, Any],
    ) -> list[str]:
        if family == "started":
            return self._har_entry_started_lines(entry)
        if family == "request":
            return self._har_request_lines(entry.get("request"))
        if family == "response":
            return self._har_response_lines(entry.get("response"))
        if family == "websocket_messages":
            return self._har_websocket_message_lines(entry)
        return []

    def _har_entry_started_lines(self, entry: dict[str, Any]) -> list[str]:
        started = self._har_scalar_text(entry.get("startedDateTime"))
        if started:
            return [f"startedDateTime={started}"]
        return []

    def _har_websocket_message_lines(self, entry: dict[str, Any]) -> list[str]:
        messages = self._har_websocket_message_values(entry)
        if not isinstance(messages, list):
            return []
        message_batches = self._run_ordered_local_batch(
            list(enumerate(messages[:64], start=1)),
            self._har_websocket_message_line_batch,
            default_factory=list,
        )
        lines: list[str] = []
        for message_lines in message_batches:
            lines.extend(message_lines)
        return lines

    def _har_websocket_message_line_batch(self, item: tuple[int, Any]) -> list[str]:
        message_index, message = item
        if not isinstance(message, dict):
            return []
        lines: list[str] = []
        for key, limit in (
            ("type", 64),
            ("time", 64),
            ("opcode", 64),
            ("data", 4096),
        ):
            value = self._har_scalar_text(message.get(key), limit=limit)
            if value:
                lines.append(f"websocket.message[{message_index}].{key}={value}")
        return lines

    @staticmethod
    def _har_websocket_message_values(entry: dict[str, Any]) -> Any:
        messages = entry.get("_webSocketMessages")
        if isinstance(messages, list):
            return messages
        return entry.get("webSocketMessages")

    def _har_request_lines(self, request: Any) -> list[str]:
        if not isinstance(request, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("request_line", "headers", "query", "cookies", "post_data"),
            lambda family: self._har_request_family_lines(family, request=request),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_request_family_lines(
        self,
        family: str,
        *,
        request: dict[str, Any],
    ) -> list[str]:
        if family == "request_line":
            return self._har_request_start_lines(request)
        if family == "headers":
            return self._har_request_header_lines(request)
        if family == "query":
            return self._har_request_query_lines(request)
        if family == "cookies":
            return self._har_request_cookie_lines(request)
        if family == "post_data":
            return self._har_request_post_data_lines(request)
        return []

    def _har_request_start_lines(self, request: dict[str, Any]) -> list[str]:
        lines: list[str] = []
        request_method = self._har_scalar_text(request.get("method"))
        request_url = self._har_scalar_text(request.get("url"), limit=2048)
        if request_method:
            lines.append(f"request.method={request_method}")
        if request_url:
            lines.append(f"request.url={request_url}")
        return lines

    def _har_request_header_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.header", request.get("headers"))

    def _har_request_query_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.query", request.get("queryString"))

    def _har_request_cookie_lines(self, request: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("request.cookie", request.get("cookies"))

    def _har_request_post_data_lines(self, request: dict[str, Any]) -> list[str]:
        post_data = request.get("postData")
        if not isinstance(post_data, dict):
            return []
        lines: list[str] = []
        mime_type = self._har_scalar_text(post_data.get("mimeType"))
        if mime_type:
            lines.append(f"request.postData.mimeType={mime_type}")
        lines.extend(self._har_name_value_lines("request.postData.param", post_data.get("params")))
        post_text = self._har_scalar_text(post_data.get("text"), limit=4096)
        if post_text:
            lines.append(f"request.postData.text={post_text}")
        return lines

    def _har_response_lines(self, response: Any) -> list[str]:
        if not isinstance(response, dict):
            return []
        line_families = self._run_ordered_local_batch(
            ("status_line", "headers", "content"),
            lambda family: self._har_response_family_lines(family, response=response),
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_families:
            lines.extend(family_lines)
        return lines

    def _har_response_family_lines(
        self,
        family: str,
        *,
        response: dict[str, Any],
    ) -> list[str]:
        if family == "status_line":
            return self._har_response_status_lines(response)
        if family == "headers":
            return self._har_response_header_lines(response)
        if family == "content":
            return self._har_response_content_lines(response)
        return []

    def _har_response_status_lines(self, response: dict[str, Any]) -> list[str]:
        lines: list[str] = []
        status_value = self._har_scalar_text(response.get("status"))
        redirect_url = self._har_scalar_text(response.get("redirectURL"), limit=2048)
        if status_value:
            lines.append(f"response.status={status_value}")
        if redirect_url:
            lines.append(f"response.redirectURL={redirect_url}")
        return lines

    def _har_response_header_lines(self, response: dict[str, Any]) -> list[str]:
        return self._har_name_value_lines("response.header", response.get("headers"))

    def _har_response_content_lines(self, response: dict[str, Any]) -> list[str]:
        response_content = response.get("content")
        if not isinstance(response_content, dict):
            return []
        lines: list[str] = []
        mime_type = self._har_scalar_text(response_content.get("mimeType"))
        if mime_type:
            lines.append(f"response.content.mimeType={mime_type}")
        image_payload_lines = self._har_content_image_payload_lines(response_content, mime_type=mime_type)
        if image_payload_lines:
            lines.extend(image_payload_lines)
            return lines
        content_text = self._har_content_text(response_content)
        if content_text:
            lines.append(f"response.content.text={content_text}")
        return lines

    def _har_content_text(self, content: dict[str, Any]) -> str:
        return har_content_text(
            content,
            scalar_text=lambda value, limit: self._har_scalar_text(value, limit=limit),
            text_from_bytes=lambda data, limit: self._har_text_from_bytes(data, limit=limit),
        )

    def _har_content_image_payload_lines(
        self,
        content: dict[str, Any],
        *,
        mime_type: str,
    ) -> list[str]:
        return har_content_image_payload_lines(
            content,
            mime_type=mime_type,
            suffix=_suffix_from_content_type(mime_type),
            image_suffixes=_OCR_IMAGE_SUFFIXES,
            max_image_bytes=_MAX_OCR_IMAGE_BYTES,
            ocr_text_limit=_OCR_TEXT_LIMIT,
            ocr_image_bytes=self._ocr_image_bytes,
            image_metadata_payload=self._image_metadata_payload,
        )

    def _har_name_value_lines(
        self,
        prefix: str,
        values: Any,
    ) -> list[str]:
        if not isinstance(values, list):
            return []
        line_candidates = self._run_ordered_local_batch(
            values[:32],
            lambda item: self._har_name_value_line(prefix, item),
            default_factory=str,
        )
        return [line for line in line_candidates if line]

    def _har_name_value_line(
        self,
        prefix: str,
        item: Any,
    ) -> str:
        if not isinstance(item, dict):
            return ""
        name = self._har_scalar_text(item.get("name"))
        value = self._har_scalar_text(
            item.get("value") if "value" in item else item.get("comment"),
            limit=2048,
        )
        if not value:
            return ""
        if name:
            return f"{prefix}.{name}={value}"
        return f"{prefix}={value}"

    @staticmethod
    def _har_scalar_text(value: Any, *, limit: int = 512) -> str:
        return har_scalar_text(value, limit=limit)

    @classmethod
    def _har_text_from_bytes(cls, data: bytes, *, limit: int = _MAX_ARTIFACT_MEMBER_BYTES) -> str:
        bounded = data[:limit]
        decode_entries = [(encoding, bounded) for encoding in ("utf-8-sig", "utf-8", "latin-1")]
        decoded_candidates = cls._run_ordered_static_batch(
            decode_entries,
            cls._har_text_decode_entry,
            default_factory=str,
            max_workers=len(decode_entries),
        )
        for text in decoded_candidates:
            if not text:
                continue
            if any(char.isalpha() for char in text[:512]) or "://" in text or "@" in text:
                return text
        return ""

    @staticmethod
    def _har_text_decode_entry(entry: tuple[str, bytes]) -> str:
        encoding, bounded = entry
        try:
            return bounded.decode(encoding, errors="ignore").replace("\x00", "").strip()
        except Exception:  # noqa: BLE001
            return ""

    def _extract_plist_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_plist_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_embedded_plist_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        if not path.exists():
            return []
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_embedded_plist_bytes_payloads(
            data,
            str(path),
            path.name,
        )
        return payloads or [(str(path), path.name, self._read_text(path))]

    def _extract_plist_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        try:
            payload = plistlib.loads(data)
        except Exception:  # noqa: BLE001
            return self._member_payloads(source_file, member_name, data)

        payloads: list[tuple[str, str, str]] = []
        payload_fragments = self._run_ordered_local_batch(
            ("xml", "values"),
            lambda family: self._extract_plist_payload_fragment(
                family,
                payload=payload,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        for fragment in payload_fragments:
            payloads.extend(fragment)
        return payloads

    def _extract_plist_payload_fragment(
        self,
        family: str,
        *,
        payload: Any,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "xml":
            try:
                xml_text = plistlib.dumps(payload, fmt=plistlib.FMT_XML, sort_keys=True).decode(
                    "utf-8",
                    errors="ignore",
                )
            except Exception:  # noqa: BLE001
                xml_text = ""
            if xml_text.strip():
                return [(source_file, f"{member_name}#plist-xml", self._xml_text_payload(xml_text))]
            return []
        if family == "values":
            flattened_lines = self._plist_text_lines(payload)
            if flattened_lines:
                return [(source_file, f"{member_name}#plist-values", "\n".join(flattened_lines[:256]))]
            return []
        return []

    def _extract_embedded_plist_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        plist_bytes = self._embedded_plist_bytes(data)
        if plist_bytes is None:
            return self._member_payloads(source_file, member_name, data)
        return self._extract_plist_bytes_payloads(
            plist_bytes[:_MAX_ARTIFACT_MEMBER_BYTES],
            source_file,
            f"{member_name}#embedded-plist",
        )

    @staticmethod
    def _embedded_plist_bytes(data: bytes) -> bytes | None:
        if not data:
            return None
        stripped = data.lstrip()
        if stripped.startswith(_PLIST_MAGIC) or stripped.startswith(b"<?xml") or stripped.startswith(b"<plist"):
            return stripped

        xml_start = data.find(b"<?xml")
        if xml_start == -1:
            xml_start = data.find(b"<plist")
        if xml_start != -1:
            xml_end = data.find(b"</plist>", xml_start)
            if xml_end != -1:
                return data[xml_start : xml_end + len(b"</plist>")]

        binary_start = data.find(_PLIST_MAGIC)
        if binary_start != -1:
            return data[binary_start:]
        return None

    def _plist_text_lines(
        self,
        value: Any,
        prefix: str = "",
    ) -> list[str]:
        if not isinstance(value, (dict, list, tuple)):
            rendered = self._plist_scalar_text(value)
            if not rendered:
                return []
            label = prefix or "value"
            return [f"{label}={rendered}"]

        entry_jobs = self._run_ordered_local_batch(
            self._plist_entry_job_sources(value),
            lambda entry_job: self._plist_entry_job(
                entry_job,
                prefix=prefix,
            ),
            default_factory=lambda: None,
        )
        entry_jobs = [
            entry_job
            for entry_job in entry_jobs
            if isinstance(entry_job, tuple)
        ]
        entry_batches = self._run_ordered_local_batch(
            entry_jobs,
            self._plist_entry_lines,
            default_factory=list,
        )
        prepared_entry_batches = self._run_ordered_local_batch(
            list(enumerate(entry_batches)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        lines: list[str] = []
        for batch in prepared_entry_batches:
            lines.extend(batch)
        return lines

    def _plist_entry_lines(self, entry_job: tuple[str, Any]) -> list[str]:
        nested_prefix, item = entry_job
        return self._plist_text_lines(item, nested_prefix)

    @staticmethod
    def _plist_entry_job_sources(
        value: Any,
    ) -> list[tuple[Any, Any]]:
        if isinstance(value, dict):
            return list(value.items())
        if isinstance(value, (list, tuple)):
            return list(enumerate(value))
        return []

    @staticmethod
    def _plist_entry_job(
        entry_source: tuple[Any, Any],
        *,
        prefix: str,
    ) -> tuple[str, Any] | None:
        key_or_index, item = entry_source
        if isinstance(key_or_index, int):
            nested_prefix = f"{prefix}[{key_or_index}]" if prefix else f"[{key_or_index}]"
            return nested_prefix, item
        key_text = str(key_or_index or "").strip() or "key"
        nested_prefix = f"{prefix}.{key_text}" if prefix else key_text
        return nested_prefix, item

    @staticmethod
    def _plist_scalar_text(value: Any) -> str:
        def _bounded(text: str, limit: int = 512) -> str:
            cleaned = str(text or "").strip()
            if len(cleaned) <= limit:
                return cleaned
            return f"{cleaned[: limit - 3]}..."

        if value is None:
            return ""
        if isinstance(value, bytes):
            text = value[:_MAX_ARTIFACT_MEMBER_BYTES].decode("utf-8", errors="ignore").strip()
            if not text:
                text = value[:_MAX_ARTIFACT_MEMBER_BYTES].decode("latin-1", errors="ignore").strip()
            return _bounded(text)
        if isinstance(value, (str, int, float, bool)):
            return _bounded(str(value))
        if isinstance(value, datetime):
            return value.isoformat()
        return _bounded(str(value))

    @staticmethod
    def _sqlite_identifier(name: str) -> str:
        escaped = str(name or "").replace('"', '""')
        return f'"{escaped}"'

    @staticmethod
    def _sqlite_cell_text(value: Any) -> str:
        def _bounded(text: str, limit: int) -> str:
            cleaned = str(text or "").strip()
            if len(cleaned) <= limit:
                return cleaned
            return f"{cleaned[: limit - 3]}..."

        if value is None:
            return ""
        if isinstance(value, bytes):
            text = value[:_MAX_SQLITE_TEXT_BYTES].decode("utf-8", errors="ignore").strip()
            if not text:
                text = value[:_MAX_SQLITE_TEXT_BYTES].decode("latin-1", errors="ignore").strip()
            return _bounded(text, 512)
        if isinstance(value, str):
            return _bounded(value, 512)
        if isinstance(value, (int, float)):
            return _bounded(str(value), 128)
        return _bounded(str(value), 256)

    def _extract_sqlite_connection_payloads(
        self,
        con: sqlite3.Connection,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        payloads: list[tuple[str, str, str]] = []
        try:
            object_rows = con.execute(
                """
                SELECT type, name, sql
                FROM sqlite_master
                WHERE type IN ('table', 'view')
                  AND name NOT LIKE 'sqlite_%'
                ORDER BY name ASC
                LIMIT ?
                """,
                (_MAX_SQLITE_TABLES,),
            ).fetchall()
        except sqlite3.Error:
            return payloads

        job_batches = self._run_ordered_local_batch(
            object_rows,
            lambda object_row: self._sqlite_object_job(
                object_row,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=lambda: None,
        )
        jobs = [
            job
            for job in job_batches
            if isinstance(job, SQLiteObjectExtractionJob)
        ]
        if not jobs:
            return payloads

        database_path = self._sqlite_connection_path(con)
        if database_path:
            for job in jobs:
                job.database_path = database_path

        if len(jobs) == 1 or self._max_workers <= 1 or not database_path:
            payloads.extend(
                self._extract_sqlite_connection_summary_payloads(
                    jobs,
                    source_file=source_file,
                    member_name=member_name,
                )
            )
            for job in jobs:
                payloads.extend(
                    self._extract_sqlite_object_payloads_from_connection(
                        con,
                        source_file=job.source_file,
                        member_name=job.member_name,
                        object_name=job.object_name,
                        object_sql=job.object_sql,
                    )
                )
            return payloads

        payload_families = self._run_ordered_local_batch(
            ("summary", "objects"),
            lambda family: self._extract_sqlite_connection_payload_family(
                family,
                jobs=jobs,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    @staticmethod
    def _sqlite_object_job(
        object_row: Sequence[Any],
        *,
        source_file: str,
        member_name: str,
    ) -> SQLiteObjectExtractionJob | None:
        _object_type, object_name, object_sql = object_row
        name = str(object_name or "").strip()
        if not name:
            return None
        return SQLiteObjectExtractionJob(
            database_path="",
            source_file=source_file,
            member_name=member_name,
            object_name=name,
            object_sql=str(object_sql or "").strip(),
        )

    def _extract_sqlite_connection_payload_family(
        self,
        family: str,
        *,
        jobs: list[SQLiteObjectExtractionJob],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_sqlite_connection_summary_payloads(
                jobs,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "objects":
            return self._extract_sqlite_connection_object_payloads(jobs)
        return []

    def _extract_sqlite_connection_summary_payloads(
        self,
        jobs: list[SQLiteObjectExtractionJob],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        object_names = [job.object_name for job in jobs if str(job.object_name or "").strip()]
        if not object_names:
            return []
        return [
            (
                source_file,
                f"{member_name}#sqlite-meta",
                "objects=" + ", ".join(object_names[:_MAX_SQLITE_TABLES]),
            )
        ]

    def _extract_sqlite_connection_object_payloads(
        self,
        jobs: list[SQLiteObjectExtractionJob],
    ) -> list[tuple[str, str, str]]:
        if not jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            jobs,
            self._extract_sqlite_object_payloads,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        prepared_object_payloads = self._run_ordered_local_batch(
            [
                (object_index, object_payloads or [])
                for object_index, object_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        for object_payloads in prepared_object_payloads:
            payloads.extend(object_payloads)
        return payloads

    @staticmethod
    def _sqlite_connection_path(con: sqlite3.Connection) -> str:
        try:
            rows = con.execute("PRAGMA database_list").fetchall()
        except sqlite3.Error:
            return ""
        for row in rows:
            try:
                database_name = str(row[1] or "").strip().lower()
                database_path = str(row[2] or "").strip()
            except Exception:  # noqa: BLE001
                continue
            if database_name == "main" and database_path:
                return database_path
        return ""

    def _extract_sqlite_object_payloads(
        self,
        job: SQLiteObjectExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if not job.database_path:
            return []
        database_uri = f"file:{Path(job.database_path).as_posix()}?mode=ro"
        try:
            con = sqlite3.connect(database_uri, uri=True)
        except sqlite3.Error:
            return []
        try:
            return self._extract_sqlite_object_payloads_from_connection(
                con,
                source_file=job.source_file,
                member_name=job.member_name,
                object_name=job.object_name,
                object_sql=job.object_sql,
            )
        finally:
            con.close()

    def _extract_sqlite_object_payloads_from_connection(
        self,
        con: sqlite3.Connection,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        object_sql: str,
    ) -> list[tuple[str, str, str]]:
        name = str(object_name or "").strip()
        if not name:
            return []
        sql_text = str(object_sql or "").strip()
        try:
            column_rows = con.execute(
                f"PRAGMA table_info({self._sqlite_identifier(name)})"
            ).fetchall()
        except sqlite3.Error:
            column_rows = []
        column_names = [str(row[1] or "").strip() for row in column_rows if str(row[1] or "").strip()]
        try:
            sample_rows = con.execute(
                f"SELECT * FROM {self._sqlite_identifier(name)} LIMIT ?",
                (_MAX_SQLITE_ROWS_PER_TABLE,),
            ).fetchall()
        except sqlite3.Error:
            sample_rows = []
        payload_families = self._run_ordered_local_batch(
            ("schema", "columns", "rows"),
            lambda family: self._extract_sqlite_object_payload_family(
                family,
                source_file=source_file,
                member_name=member_name,
                object_name=name,
                sql_text=sql_text,
                column_names=column_names,
                sample_rows=sample_rows,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    @staticmethod
    def _artifact_payload_tuple_batch_entries(
        payload_batch: tuple[int, Sequence[tuple[str, str, str]]],
    ) -> list[tuple[str, str, str]]:
        _batch_index, batch = payload_batch
        payloads: list[tuple[str, str, str]] = []
        for payload in batch:
            if not isinstance(payload, tuple) or len(payload) != 3:
                continue
            source_file, member_name, text = payload
            source_file_text = str(source_file or "").strip()
            member_name_text = str(member_name or "").strip()
            text_value = str(text or "")
            if source_file_text and member_name_text and text_value:
                payloads.append((source_file_text, member_name_text, text_value))
        return payloads

    def _extract_sqlite_object_payload_family(
        self,
        family: str,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        sql_text: str,
        column_names: Sequence[str],
        sample_rows: Sequence[Sequence[Any]],
    ) -> list[tuple[str, str, str]]:
        if family == "schema":
            return self._extract_sqlite_object_schema_payloads(
                source_file=source_file,
                member_name=member_name,
                object_name=object_name,
                sql_text=sql_text,
            )
        if family == "columns":
            return self._extract_sqlite_object_column_payloads(
                source_file=source_file,
                member_name=member_name,
                object_name=object_name,
                column_names=column_names,
            )
        if family == "rows":
            return self._extract_sqlite_object_row_payloads(
                source_file=source_file,
                member_name=member_name,
                object_name=object_name,
                column_names=column_names,
                sample_rows=sample_rows,
            )
        return []

    def _extract_sqlite_object_schema_payloads(
        self,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        sql_text: str,
    ) -> list[tuple[str, str, str]]:
        if not sql_text:
            return []
        return [(source_file, f"{member_name}#sqlite-schema-{object_name}", sql_text)]

    def _extract_sqlite_object_column_payloads(
        self,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        column_names: Sequence[str],
    ) -> list[tuple[str, str, str]]:
        names = [str(column_name or "").strip() for column_name in column_names if str(column_name or "").strip()]
        if not names:
            return []
        return [
            (
                source_file,
                f"{member_name}#sqlite-columns-{object_name}",
                "columns=" + ", ".join(names),
            )
        ]

    def _extract_sqlite_object_row_payloads(
        self,
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        column_names: Sequence[str],
        sample_rows: Sequence[Sequence[Any]],
    ) -> list[tuple[str, str, str]]:
        row_payloads = self._run_ordered_local_batch(
            list(enumerate(sample_rows, start=1)),
            lambda row_job: self._extract_sqlite_row_payload(
                row_job,
                source_file=source_file,
                member_name=member_name,
                object_name=object_name,
                column_names=column_names,
            ),
            default_factory=lambda: None,
        )
        return [payload for payload in row_payloads if payload is not None]

    def _extract_sqlite_row_payload(
        self,
        row_job: tuple[int, Sequence[Any]],
        *,
        source_file: str,
        member_name: str,
        object_name: str,
        column_names: Sequence[str],
    ) -> tuple[str, str, str] | None:
        index, row = row_job
        cell_candidates = self._run_ordered_local_batch(
            list(enumerate(row)),
            lambda cell_job: self._extract_sqlite_row_cell_line(
                cell_job,
                column_names=column_names,
            ),
            default_factory=str,
        )
        cells = [cell for cell in cell_candidates if cell]
        if not cells:
            return None
        return (
            source_file,
            f"{member_name}#sqlite-row-{object_name}-{index}",
            "\n".join(cells),
        )

    def _extract_sqlite_row_cell_line(
        self,
        cell_job: tuple[int, Any],
        *,
        column_names: Sequence[str],
    ) -> str:
        cell_index, value = cell_job
        rendered = self._sqlite_cell_text(value)
        if not rendered:
            return ""
        column_name = (
            column_names[cell_index]
            if cell_index < len(column_names) and column_names[cell_index]
            else f"col_{cell_index + 1}"
        )
        return f"{column_name}={rendered}"

    def _extract_email_message_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth > 2 or not data:
            return []
        try:
            message = BytesParser(policy=email_policy.default).parsebytes(data)
        except Exception:  # noqa: BLE001
            return [
                (
                    source_file,
                    member_name,
                    data[:_MAX_ARTIFACT_MEMBER_BYTES].decode("utf-8", errors="ignore"),
                )
            ]

        metadata_lines = self._email_message_metadata_lines(message)
        leaf_parts = [part for part in message.walk() if not part.is_multipart()]
        payload_families = self._run_ordered_local_batch(
            ("summary", "parts"),
            lambda family: self._extract_email_message_payload_family(
                family,
                metadata_lines=metadata_lines,
                leaf_parts=leaf_parts,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_email_message_payload_family(
        self,
        family: str,
        *,
        metadata_lines: Sequence[str],
        leaf_parts: Sequence[Any],
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_email_message_summary_payloads(
                metadata_lines,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "parts":
            return self._extract_email_message_part_payloads(
                leaf_parts,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        return []

    def _extract_email_message_summary_payloads(
        self,
        metadata_lines: Sequence[str],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not metadata_lines:
            return []
        return [(source_file, f"{member_name}#message-meta", "\n".join(metadata_lines))]

    def _extract_email_message_part_payloads(
        self,
        leaf_parts: Sequence[Any],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        ordered_part_payloads: list[list[tuple[str, str, str]] | None] = []
        part_jobs: list[tuple[int, EmailPartExtractionJob]] = []
        part_entries = self._run_ordered_local_batch(
            list(enumerate(leaf_parts, start=1)),
            lambda part_job: self._email_message_part_entry(
                part_job,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            ),
            default_factory=lambda: None,
        )
        for part_entry in part_entries:
            if not isinstance(part_entry, EmailPartPlanningEntry):
                continue
            if part_entry.payloads:
                ordered_part_payloads.append(part_entry.payloads)
                continue
            if part_entry.extraction_job is None:
                continue
            result_index = len(ordered_part_payloads)
            ordered_part_payloads.append(None)
            part_jobs.append((result_index, part_entry.extraction_job))
        if part_jobs:
            extracted_part_payloads = self._run_ordered_local_batch(
                part_jobs,
                self._extract_email_part_job_payload_entry,
                default_factory=lambda: None,
            )
            for extracted_part_payload in extracted_part_payloads:
                if not isinstance(extracted_part_payload, tuple) or len(extracted_part_payload) != 2:
                    continue
                result_index, part_payloads = extracted_part_payload
                if not isinstance(result_index, int) or result_index < 0:
                    continue
                if result_index >= len(ordered_part_payloads):
                    continue
                ordered_part_payloads[result_index] = list(part_payloads or [])
        prepared_part_payloads = self._run_ordered_local_batch(
            [
                (part_index, part_payloads or [])
                for part_index, part_payloads in enumerate(ordered_part_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        flattened_payloads: list[tuple[str, str, str]] = []
        for part_payloads in prepared_part_payloads:
            flattened_payloads.extend(part_payloads)
        return flattened_payloads

    def _email_message_part_entry(
        self,
        part_job: tuple[int, Any],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> EmailPartPlanningEntry | None:
        part_index, part = part_job
        content_type = str(part.get_content_type() or "").lower()
        filename = str(part.get_filename() or "").strip()

        if content_type == "message/rfc822":
            nested_payload = part.get_payload()
            nested_messages = nested_payload if isinstance(nested_payload, list) else []
            raw_nested_jobs: list[tuple[str, bytes]] = []
            for nested_index, nested_message in enumerate(nested_messages, start=1):
                try:
                    nested_bytes = nested_message.as_bytes(policy=email_policy.default)
                except Exception:  # noqa: BLE001
                    continue
                nested_name = filename or f"{member_name}.attached-{part_index}-{nested_index}.eml"
                raw_nested_jobs.append((nested_name, nested_bytes[:_MAX_ARTIFACT_MEMBER_BYTES]))
            nested_jobs = self._run_ordered_local_batch(
                raw_nested_jobs,
                self._nested_email_message_job,
                default_factory=lambda: None,
            )
            nested_jobs = [
                nested_job
                for nested_job in nested_jobs
                if isinstance(nested_job, tuple)
            ]
            if not nested_jobs:
                return None
            return EmailPartPlanningEntry(
                extraction_job=EmailPartExtractionJob(
                    source_file=source_file,
                    member_name=filename or f"{member_name}.attached-{part_index}.eml",
                    depth=depth,
                    nested_messages=nested_jobs,
                )
            )

        payload_bytes = part.get_payload(decode=True)
        if payload_bytes is None:
            raw_payload = part.get_payload()
            if isinstance(raw_payload, str):
                charset = part.get_content_charset() or "utf-8"
                payload_bytes = raw_payload.encode(charset, errors="ignore")
            else:
                payload_bytes = b""
        if not payload_bytes:
            return None

        if content_type in {"text/plain", "text/html"}:
            text = self._decode_email_part_text(part, payload_bytes)
            if not text.strip():
                return None
            suffix = ".html" if content_type == "text/html" else ".txt"
            return EmailPartPlanningEntry(
                payloads=[(source_file, f"{member_name}.part-{part_index}{suffix}", text)]
            )

        attachment_name = filename or f"{member_name}.attachment-{part_index}"
        suffix = Path(attachment_name.lower()).suffix
        size_limit = _MAX_OCR_IMAGE_BYTES if suffix in _OCR_IMAGE_SUFFIXES else _MAX_ARTIFACT_MEMBER_BYTES
        if len(payload_bytes) > size_limit:
            return None
        return EmailPartPlanningEntry(
            extraction_job=EmailPartExtractionJob(
                source_file=source_file,
                member_name=attachment_name,
                depth=depth,
                payload_bytes=payload_bytes,
            )
        )

    @staticmethod
    def _nested_email_message_job(
        nested_job: tuple[str, bytes],
    ) -> tuple[str, bytes] | None:
        nested_name, nested_bytes = nested_job
        normalized_name = str(nested_name or "").strip()
        if not normalized_name or not nested_bytes:
            return None
        return normalized_name, bytes(nested_bytes)[:_MAX_ARTIFACT_MEMBER_BYTES]

    def _extract_email_part_job_payload_entry(
        self,
        part_job: tuple[int, EmailPartExtractionJob],
    ) -> tuple[int, list[tuple[str, str, str]]] | None:
        result_index, job = part_job
        if result_index < 0:
            return None
        return result_index, self._extract_email_part_job(job)

    def _extract_email_part_job(
        self,
        job: EmailPartExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if job.nested_messages:
            nested_payloads = self._run_ordered_local_batch(
                job.nested_messages,
                lambda nested_job: self._extract_email_message_payloads(
                    nested_job[1],
                    job.source_file,
                    nested_job[0],
                    depth=job.depth + 1,
                ),
                default_factory=list,
            )
            prepared_nested_payloads = self._run_ordered_local_batch(
                [
                    (nested_index, nested_message_payloads or [])
                    for nested_index, nested_message_payloads in enumerate(nested_payloads)
                ],
                self._artifact_payload_tuple_batch_entries,
                default_factory=list,
            )
            payloads: list[tuple[str, str, str]] = []
            for nested_message_payloads in prepared_nested_payloads:
                payloads.extend(nested_message_payloads)
            return payloads
        if not job.payload_bytes:
            return []
        return self._extract_member_data_payloads(
            job.payload_bytes,
            job.source_file,
            job.member_name,
            depth=job.depth,
        )

    def _extract_mbox_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth > 2 or not data:
            return []
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        raw_message_jobs: list[tuple[int, bytes]] = []
        payloads: list[tuple[str, str, str]] = []
        message_count = 0
        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                temp_path = Path(temp_dir) / "mailbox.mbox"
                temp_path.write_bytes(bounded)
                box = mailbox.mbox(str(temp_path), create=False)
                try:
                    for index, message in enumerate(box, start=1):
                        message_count += 1
                        try:
                            message_bytes = message.as_bytes(policy=email_policy.default)
                        except TypeError:
                            message_bytes = message.as_bytes()
                        except Exception:  # noqa: BLE001
                            continue
                        raw_message_jobs.append((index, message_bytes))
                finally:
                    try:
                        box.close()
                    except Exception:  # noqa: BLE001
                        pass
        except Exception:  # noqa: BLE001
            return [
                (
                    source_file,
                    member_name,
                    bounded.decode("utf-8", errors="ignore"),
                )
            ]

        job_batches = self._run_ordered_local_batch(
            raw_message_jobs,
            self._mbox_message_job,
            default_factory=lambda: None,
        )
        message_jobs = [
            job
            for job in job_batches
            if isinstance(job, tuple)
        ]
        if message_jobs:
            payload_families = self._run_ordered_local_batch(
                ("summary", "messages"),
                lambda family: self._extract_mbox_payload_family(
                    family,
                    message_jobs=message_jobs,
                    message_count=message_count,
                    source_file=source_file,
                    member_name=member_name,
                    depth=depth,
                ),
                default_factory=list,
            )
            prepared_payload_families = self._run_ordered_local_batch(
                list(enumerate(payload_families)),
                self._artifact_payload_tuple_batch_entries,
                default_factory=list,
            )
            payloads: list[tuple[str, str, str]] = []
            for family_payloads in prepared_payload_families:
                payloads.extend(family_payloads)
            return payloads
        if message_count:
            return self._extract_mbox_summary_payloads(
                message_count,
                source_file=source_file,
                member_name=member_name,
            )
        return [
            (
                source_file,
                member_name,
                bounded.decode("utf-8", errors="ignore"),
            )
        ]

    def _extract_mbox_payload_family(
        self,
        family: str,
        *,
        message_jobs: Sequence[tuple[int, bytes]],
        message_count: int,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_mbox_summary_payloads(
                message_count,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "messages":
            return self._extract_mbox_message_payloads(
                message_jobs,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        return []

    @staticmethod
    def _mbox_message_job(
        message_job: tuple[int, bytes],
    ) -> tuple[int, bytes] | None:
        index, message_bytes = message_job
        bounded_bytes = bytes(message_bytes[:_MAX_ARTIFACT_MEMBER_BYTES])
        if index <= 0 or not bounded_bytes:
            return None
        return index, bounded_bytes

    def _extract_mbox_summary_payloads(
        self,
        message_count: int,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if message_count <= 0:
            return []
        return [(source_file, f"{member_name}#mbox-meta", f"message_count={message_count}")]

    def _extract_mbox_message_payloads(
        self,
        message_jobs: Sequence[tuple[int, bytes]],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        ordered_payloads = self._run_ordered_local_batch(
            message_jobs,
            lambda message_job: self._extract_email_message_payloads(
                message_job[1],
                source_file,
                f"{member_name}.message-{message_job[0]}.eml",
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (message_index, message_payloads or [])
                for message_index, message_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for message_payloads in prepared_payloads:
            payloads.extend(message_payloads)
        return payloads

    @classmethod
    def _decode_email_part_text(cls, part: Any, data: bytes) -> str:
        charset = str(part.get_content_charset() or "").strip().lower()
        bounded = data[:_MAX_ARTIFACT_MEMBER_BYTES]
        decode_entries = [(encoding, bounded) for encoding in (charset, "utf-8", "latin-1") if encoding]
        decoded_candidates = cls._run_ordered_static_batch(
            decode_entries,
            cls._decode_email_part_entry,
            default_factory=lambda: None,
            max_workers=len(decode_entries),
        )
        for decoded_candidate in decoded_candidates:
            if decoded_candidate is not None:
                return str(decoded_candidate)
        return data[:_MAX_ARTIFACT_MEMBER_BYTES].decode("utf-8", errors="ignore")

    @staticmethod
    def _decode_email_part_entry(entry: tuple[str, bytes]) -> str | None:
        encoding, bounded = entry
        try:
            return bounded.decode(encoding, errors="ignore")
        except Exception:  # noqa: BLE001
            return None

    def _extract_legacy_document_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        payloads = self._extract_legacy_binary_payloads(data, str(path), path.name, depth=depth)
        if payloads:
            return payloads
        return [(str(path), path.name, self._read_text(path))]

    def _extract_rtf_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES]
        return self._extract_rtf_bytes_payloads(data, str(path), path.name, depth=depth)

    def _extract_rtf_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        text_payload = self._rtf_to_text(data)
        if text_payload.strip():
            payload_families = self._run_ordered_local_batch(
                ("text", "embedded_archive"),
                lambda family: self._extract_rtf_payload_family(
                    family,
                    data=data,
                    source_file=source_file,
                    member_name=member_name,
                    text_payload=text_payload,
                    depth=depth,
                ),
                default_factory=list,
            )
            prepared_payload_families = self._run_ordered_local_batch(
                list(enumerate(payload_families)),
                self._artifact_payload_tuple_batch_entries,
                default_factory=list,
            )
            payloads: list[tuple[str, str, str]] = []
            for family_payloads in prepared_payload_families:
                payloads.extend(family_payloads)
            return payloads
        return self._extract_legacy_binary_payloads(
            data,
            source_file,
            member_name,
            depth=depth,
        )

    def _extract_rtf_payload_family(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
        text_payload: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if family == "text":
            return self._extract_rtf_text_payloads(
                text_payload,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "embedded_archive":
            return self._extract_rtf_embedded_archive_payloads(
                data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        return []

    def _extract_rtf_text_payloads(
        self,
        text_payload: str,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not text_payload.strip():
            return []
        return [(source_file, f"{member_name}#rtf-text", text_payload)]

    def _extract_rtf_embedded_archive_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth >= 2:
            return []
        return self._extract_embedded_archive_payloads(
            data,
            source_file,
            member_name,
            depth=depth,
        )

    def _extract_legacy_binary_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        payload_families = self._run_ordered_local_batch(
            ("strings", "embedded_archive", "ole"),
            lambda family: self._extract_legacy_binary_payload_family(
                family,
                data=data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_parquet_payloads(
        self,
        path: Path,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        try:
            if path.stat().st_size > _MAX_ARTIFACT_MEMBER_BYTES:
                raise ValueError("parquet artifact exceeds bounded parse size")
            data = path.read_bytes()
        except Exception:  # noqa: BLE001
            data = path.read_bytes()[:_MAX_ARTIFACT_MEMBER_BYTES] if path.exists() else b""
            return self._extract_legacy_binary_payloads(
                data,
                str(path),
                path.name,
                depth=depth,
            )
        return self._extract_parquet_bytes_payloads(
            data,
            str(path),
            path.name,
            depth=depth,
        )

    def _extract_parquet_bytes_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        try:
            import pyarrow.parquet as pq

            parquet_file = pq.ParquetFile(BytesIO(data))
            lines = self._parquet_summary_lines(parquet_file)
        except Exception:  # noqa: BLE001
            return self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        payloads = [(source_file, f"{member_name}#parquet-table", "\n".join(lines))]
        payloads.extend(
            self._extract_legacy_binary_payloads(
                data[:_MAX_ARTIFACT_MEMBER_BYTES],
                source_file,
                member_name,
                depth=depth,
            )
        )
        return payloads

    def _parquet_summary_lines(self, parquet_file: Any) -> list[str]:
        columns = list(parquet_file.schema_arrow.names)[:64]
        lines = ["format=parquet", f"columns={','.join(columns)}"]
        metadata = parquet_file.metadata
        if metadata is not None and getattr(metadata, "metadata", None):
            for key, value in list(metadata.metadata.items())[:64]:
                key_text = self._parquet_cell_text(key)
                value_text = self._parquet_cell_text(value)
                if key_text and value_text:
                    lines.append(f"metadata.{key_text}={value_text}")
        for row_group_index in range(min(int(parquet_file.num_row_groups or 0), 4)):
            table = parquet_file.read_row_group(row_group_index, columns=columns)
            lines.extend(self._parquet_table_lines(table, row_group_index))
            if len(lines) >= 256:
                break
        return lines[:256]

    def _parquet_table_lines(self, table: Any, row_group_index: int) -> list[str]:
        lines: list[str] = []
        row_count = min(int(getattr(table, "num_rows", 0) or 0), 64)
        for column_name in list(table.column_names)[:64]:
            values = table[column_name].slice(0, row_count).to_pylist()
            for row_index, raw_value in enumerate(values):
                value = self._parquet_cell_text(raw_value)
                if not self._parquet_interesting_value(value):
                    continue
                lines.append(f"row_group[{row_group_index}].row[{row_index}].{column_name}={value}")
                if len(lines) >= 192:
                    return lines
        return lines

    @staticmethod
    def _parquet_cell_text(value: Any) -> str:
        if value is None:
            return ""
        if isinstance(value, bytes | bytearray):
            return ArtifactQueueProcessor._decode_text_artifact_bytes(bytes(value), limit=512)
        if isinstance(value, (dict, list, tuple)):
            try:
                return json.dumps(value, default=str, sort_keys=True)[:512]
            except Exception:  # noqa: BLE001
                return str(value)[:512]
        return str(value).strip()[:512]

    @staticmethod
    def _parquet_interesting_value(value: str) -> bool:
        lowered = str(value or "").lower()
        return any(
            marker in lowered
            for marker in (
                "@",
                "://",
                "firebaseio.com",
                "supabase.co",
                ".s3.",
                "s3://",
                "gs://",
            )
        )

    def _extract_legacy_binary_payload_family(
        self,
        family: str,
        *,
        data: bytes,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if family == "strings":
            return self._extract_legacy_binary_string_payloads(
                data,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "embedded_archive":
            return self._extract_legacy_binary_embedded_archive_payloads(
                data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        if family == "ole":
            return self._extract_legacy_binary_ole_payloads(
                data,
                source_file=source_file,
                member_name=member_name,
                depth=depth,
            )
        return []

    def _extract_legacy_binary_string_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        binary_payload = self._binary_string_payload(data)
        if not binary_payload:
            return []
        return [(source_file, f"{member_name}#binary-strings", binary_payload)]

    def _extract_legacy_binary_embedded_archive_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth >= 2:
            return []
        payloads = self._extract_embedded_archive_payloads(
            data,
            source_file,
            member_name,
            depth=depth,
        )
        payloads.extend(
            self._extract_embedded_image_payloads(data, source_file, member_name)
        )
        return payloads

    def _extract_legacy_binary_ole_payloads(
        self,
        data: bytes,
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if not data.startswith(_OLE_MAGIC):
            return []
        return self._extract_ole_payloads(data, source_file, member_name, depth=depth)

    def _extract_ole_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        try:
            import olefile  # noqa: PLC0415
        except Exception:  # noqa: BLE001
            return []
        try:
            with olefile.OleFileIO(BytesIO(data)) as ole:
                metadata_lines = self._ole_metadata_lines(ole)
                raw_stream_entries: list[tuple[tuple[Any, ...], bytes]] = []
                for stream_parts in ole.listdir(streams=True, storages=False):
                    try:
                        stream_data = ole.openstream(stream_parts).read(_MAX_ARTIFACT_MEMBER_BYTES)
                    except Exception:  # noqa: BLE001
                        continue
                    raw_stream_entries.append((tuple(stream_parts), stream_data))
                stream_entries = self._run_ordered_local_batch(
                    raw_stream_entries,
                    self._ole_stream_entry,
                    default_factory=lambda: None,
                )
                stream_entries = [
                    stream_entry
                    for stream_entry in stream_entries
                    if isinstance(stream_entry, tuple)
                ]
                job_batches = self._run_ordered_local_batch(
                    stream_entries,
                    lambda stream_entry: self._ole_stream_job(
                        stream_entry,
                        source_file=source_file,
                        member_name=member_name,
                        depth=depth,
                    ),
                    default_factory=lambda: None,
                )
                stream_jobs = [
                    job
                    for job in job_batches
                    if isinstance(job, OLEStreamExtractionJob)
                ]
        except Exception:  # noqa: BLE001
            return []
        payload_families = self._run_ordered_local_batch(
            ("summary", "streams"),
            lambda family: self._extract_ole_payload_family(
                family,
                metadata_lines=metadata_lines,
                stream_jobs=stream_jobs,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    @staticmethod
    def _ole_stream_entry(
        stream_entry: tuple[Sequence[Any], bytes],
    ) -> tuple[tuple[Any, ...], bytes] | None:
        stream_parts, stream_data = stream_entry
        normalized_parts = tuple(stream_parts)
        stream_name = "/".join(str(part) for part in normalized_parts if str(part).strip())
        if not stream_name:
            return None
        return normalized_parts, bytes(stream_data)

    def _ole_stream_job(
        self,
        stream_entry: tuple[Sequence[Any], bytes],
        *,
        source_file: str,
        member_name: str,
        depth: int,
    ) -> OLEStreamExtractionJob | None:
        stream_parts, stream_data = stream_entry
        stream_name = "/".join(str(part) for part in stream_parts if str(part).strip())
        if not stream_name:
            return None
        return OLEStreamExtractionJob(
            source_file=source_file,
            member_name=member_name,
            stream_name=stream_name,
            stream_data=stream_data,
            depth=depth,
        )

    def _extract_ole_payload_family(
        self,
        family: str,
        *,
        metadata_lines: Sequence[str],
        stream_jobs: Sequence[OLEStreamExtractionJob],
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if family == "summary":
            return self._extract_ole_metadata_payloads(
                metadata_lines,
                source_file=source_file,
                member_name=member_name,
            )
        if family == "streams":
            return self._extract_ole_stream_job_payloads(stream_jobs)
        return []

    def _extract_ole_metadata_payloads(
        self,
        metadata_lines: Sequence[str],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not metadata_lines:
            return []
        return [(source_file, f"{member_name}#ole-metadata", "\n".join(metadata_lines))]

    def _extract_ole_stream_job_payloads(
        self,
        stream_jobs: Sequence[OLEStreamExtractionJob],
    ) -> list[tuple[str, str, str]]:
        if not stream_jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            stream_jobs,
            self._extract_ole_stream_payloads,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (stream_index, stream_payloads or [])
                for stream_index, stream_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for stream_payloads in prepared_payloads:
            payloads.extend(stream_payloads)
        return payloads

    def _extract_ole_stream_payloads(
        self,
        job: OLEStreamExtractionJob,
    ) -> list[tuple[str, str, str]]:
        payload_families = self._run_ordered_local_batch(
            ("strings", "nested_archive", "embedded_archive"),
            lambda family: self._extract_ole_stream_payload_family(family, job=job),
            default_factory=list,
        )
        prepared_payload_families = self._run_ordered_local_batch(
            list(enumerate(payload_families)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for family_payloads in prepared_payload_families:
            payloads.extend(family_payloads)
        return payloads

    def _extract_ole_stream_payload_family(
        self,
        family: str,
        *,
        job: OLEStreamExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if family == "strings":
            return self._extract_ole_stream_string_payloads(job)
        if family == "nested_archive":
            return self._extract_ole_stream_nested_archive_payloads(job)
        if family == "embedded_archive":
            return self._extract_ole_stream_embedded_archive_payloads(job)
        return []

    def _extract_ole_stream_string_payloads(
        self,
        job: OLEStreamExtractionJob,
    ) -> list[tuple[str, str, str]]:
        payload = self._binary_string_payload(job.stream_data)
        if not payload:
            return []
        return [
            (
                job.source_file,
                f"{job.member_name}#ole-stream:{job.stream_name}",
                payload,
            )
        ]

    def _extract_ole_stream_nested_archive_payloads(
        self,
        job: OLEStreamExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if job.depth >= 2 or not self._looks_like_archive_bytes(job.stream_data):
            return []
        return self._extract_nested_archive_bytes(
            job.stream_data,
            job.source_file,
            f"{job.member_name}/{job.stream_name}",
            job.depth + 1,
        )

    def _extract_ole_stream_embedded_archive_payloads(
        self,
        job: OLEStreamExtractionJob,
    ) -> list[tuple[str, str, str]]:
        if job.depth >= 2:
            return []
        member_name = f"{job.member_name}/{job.stream_name}"
        payloads = self._extract_embedded_archive_payloads(
            job.stream_data,
            job.source_file,
            member_name,
            depth=job.depth,
        )
        payloads.extend(
            self._extract_embedded_image_payloads(
                job.stream_data,
                job.source_file,
                member_name,
            )
        )
        return payloads

    @staticmethod
    def _rtf_to_text(data: bytes) -> str:
        raw = data.decode("latin-1", errors="ignore")
        if not raw:
            return ""
        out: list[str] = []
        index = 0
        skip_unicode_fallback = False
        while index < len(raw):
            char = raw[index]
            if char == "\\":
                if skip_unicode_fallback:
                    skip_unicode_fallback = False
                index += 1
                if index >= len(raw):
                    break
                control = raw[index]
                if control in {"\\", "{", "}"}:
                    out.append(control)
                    index += 1
                    continue
                if control == "'":
                    if index + 2 < len(raw):
                        hex_value = raw[index + 1 : index + 3]
                        if re.fullmatch(r"[0-9a-fA-F]{2}", hex_value):
                            try:
                                out.append(bytes.fromhex(hex_value).decode("cp1252", errors="ignore"))
                            except Exception:  # noqa: BLE001
                                pass
                            index += 3
                            continue
                if control == "~":
                    out.append(" ")
                    index += 1
                    continue
                if control == "_":
                    out.append("-")
                    index += 1
                    continue
                if control == "-":
                    index += 1
                    continue
                if control == "*":
                    index += 1
                    continue
                if control.isalpha():
                    start = index
                    while index < len(raw) and raw[index].isalpha():
                        index += 1
                    word = raw[start:index].lower()
                    sign = 1
                    if index < len(raw) and raw[index] == "-":
                        sign = -1
                        index += 1
                    number_start = index
                    while index < len(raw) and raw[index].isdigit():
                        index += 1
                    number: int | None = None
                    if index > number_start:
                        number = int(raw[number_start:index]) * sign
                    if index < len(raw) and raw[index] == " ":
                        index += 1
                    if word in {"line", "par"}:
                        out.append("\n")
                    elif word == "tab":
                        out.append("\t")
                    elif word in {"emdash", "endash"}:
                        out.append("-")
                    elif word == "bullet":
                        out.append("*")
                    elif word == "u" and number is not None:
                        if number < 0:
                            number += 65536
                        try:
                            out.append(chr(number))
                        except Exception:  # noqa: BLE001
                            pass
                        skip_unicode_fallback = True
                    continue
                index += 1
                continue
            if char in {"{", "}"}:
                index += 1
                continue
            if skip_unicode_fallback:
                skip_unicode_fallback = False
                index += 1
                continue
            out.append(char)
            index += 1
        text = "".join(out).replace("\x00", "")
        text = re.sub(r"[ \t]+\n", "\n", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

    def _extract_embedded_archive_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
        *,
        depth: int,
    ) -> list[tuple[str, str, str]]:
        if depth >= 2:
            return []
        job_batches = self._run_ordered_local_batch(
            self._embedded_archive_offsets(data)[:3],
            lambda offset_job: self._embedded_archive_job_entry(
                offset_job,
                source_file=source_file,
                member_name=member_name,
                data=data,
                depth=depth,
            ),
            default_factory=lambda: None,
        )
        jobs = [
            job
            for job in job_batches
            if isinstance(job, EmbeddedArchiveExtractionJob)
        ]
        if not jobs:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            jobs,
            self._extract_embedded_archive_job,
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (nested_index, nested_payloads or [])
                for nested_index, nested_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for nested_payloads in prepared_payloads:
            payloads.extend(nested_payloads)
        return payloads

    @staticmethod
    def _embedded_archive_job_entry(
        offset_job: tuple[str, int],
        *,
        source_file: str,
        member_name: str,
        data: bytes,
        depth: int,
    ) -> EmbeddedArchiveExtractionJob | None:
        archive_kind, offset = offset_job
        if offset < 0:
            return None
        return EmbeddedArchiveExtractionJob(
            source_file,
            member_name,
            archive_kind,
            offset,
            data[offset:],
            depth + 1,
        )

    def _extract_embedded_archive_job(
        self,
        job: EmbeddedArchiveExtractionJob,
    ) -> list[tuple[str, str, str]]:
        try:
            return self._extract_archive_bytes_payloads(
                job.blob,
                job.source_file,
                f"{job.member_name}#carved-{job.archive_kind}-{job.offset}",
                depth=job.depth,
            )
        except Exception:  # noqa: BLE001
            return []

    def _extract_pdf_ocr_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        return self._extract_pdf_ocr_payloads_from_path(
            path,
            source_file=str(path),
            member_name=path.name,
        )

    def _extract_pdf_bytes_ocr_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._ocr_binary or not self._pdf_raster_binary or not data:
            return []
        try:
            with tempfile.TemporaryDirectory() as temp_dir:
                temp_path = Path(temp_dir) / "embedded.pdf"
                temp_path.write_bytes(data[:_MAX_ARTIFACT_MEMBER_BYTES])
                return self._extract_pdf_ocr_payloads_from_path(
                    temp_path,
                    source_file=source_file,
                    member_name=member_name,
                )
        except Exception:  # noqa: BLE001
            return []

    def _extract_pdf_ocr_payloads_from_path(
        self,
        path: Path,
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        if not self._pdf_raster_binary or not path.exists():
            return []

        def _page_payloads(index: int, image_path: Path) -> list[tuple[str, str, str]]:
            try:
                payloads: list[tuple[str, str, str]] = []
                ocr_text = self._ocr_image_path(image_path)
                if ocr_text.strip():
                    payloads.append((source_file, f"{member_name}#ocr-page-{index}", ocr_text))
                barcode_payload = self._barcode_image_path_payload(image_path)
                if barcode_payload.strip():
                    payloads.append((source_file, f"{member_name}#barcode-page-{index}", barcode_payload))
                return payloads
            finally:
                image_path.unlink(missing_ok=True)

        page_job_batches = self._run_ordered_local_batch(
            list(enumerate(self._render_pdf_pages_for_ocr(path), start=1)),
            self._pdf_ocr_page_job,
            default_factory=lambda: None,
        )
        page_images = [
            page_job
            for page_job in page_job_batches
            if isinstance(page_job, tuple)
        ]
        if not page_images:
            return []
        ordered_payloads = self._run_ordered_local_batch(
            page_images,
            lambda page_image: _page_payloads(*page_image),
            default_factory=list,
        )
        prepared_payloads = self._run_ordered_local_batch(
            [
                (page_index, page_payloads if isinstance(page_payloads, list) else [])
                for page_index, page_payloads in enumerate(ordered_payloads)
            ],
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for page_payloads in prepared_payloads:
            payloads.extend(page_payloads)
        return payloads

    @staticmethod
    def _pdf_ocr_page_job(
        page_job: tuple[int, Path],
    ) -> tuple[int, Path] | None:
        index, image_path = page_job
        if index <= 0:
            return None
        return index, Path(image_path)

    @staticmethod
    def _retained_pdf_ocr_image_path(image_path: Path) -> Path | None:
        source_path = Path(image_path)
        if not source_path.exists():
            return None
        retained_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(delete=False, suffix=source_path.suffix or ".png") as handle:
                handle.write(source_path.read_bytes())
                retained_path = Path(handle.name)
            return retained_path
        except Exception:  # noqa: BLE001
            if retained_path is not None:
                retained_path.unlink(missing_ok=True)
            return None

    def _render_pdf_pages_for_ocr(self, path: Path) -> list[Path]:
        if not self._pdf_raster_binary or not path.exists():
            return []
        temp_dir = tempfile.TemporaryDirectory()
        temp_root = Path(temp_dir.name)
        output_prefix = temp_root / "page"
        try:
            proc = subprocess.run(
                [
                    self._pdf_raster_binary,
                    "-png",
                    "-f",
                    "1",
                    "-l",
                    str(_PDF_OCR_MAX_PAGES),
                    str(path),
                    str(output_prefix),
                ],
                capture_output=True,
                text=True,
                timeout=_PDF_RENDER_TIMEOUT_SECONDS,
                check=False,
            )
        except Exception:  # noqa: BLE001
            temp_dir.cleanup()
            return []
        if proc.returncode != 0:
            temp_dir.cleanup()
            return []
        image_paths = sorted(temp_root.glob("page-*.png"))
        if not image_paths:
            temp_dir.cleanup()
            return []
        retained_paths = self._run_ordered_local_batch(
            image_paths[:_PDF_OCR_MAX_PAGES],
            self._retained_pdf_ocr_image_path,
            default_factory=lambda: None,
        )
        results = [
            retained_path
            for retained_path in retained_paths
            if isinstance(retained_path, Path)
        ]
        temp_dir.cleanup()
        return results

    def _extract_image_payloads(self, path: Path) -> list[tuple[str, str, str]]:
        family_payloads = self._run_ordered_local_batch(
            ("ocr", "barcode", "metadata"),
            lambda family: self._extract_image_payload_family(family, path),
            default_factory=list,
        )
        payload_batches = self._run_ordered_local_batch(
            list(enumerate(family_payloads)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for batch in payload_batches:
            payloads.extend(batch)
        return payloads

    def _extract_image_member_payloads(
        self,
        source_file: str,
        member_name: str,
        data: bytes,
    ) -> list[tuple[str, str, str]]:
        family_payloads = self._run_ordered_local_batch(
            ("ocr", "barcode", "metadata"),
            lambda family: self._extract_image_member_payload_family(
                family,
                source_file=source_file,
                member_name=member_name,
                data=data,
            ),
            default_factory=list,
        )
        payload_batches = self._run_ordered_local_batch(
            list(enumerate(family_payloads)),
            self._artifact_payload_tuple_batch_entries,
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for batch in payload_batches:
            payloads.extend(batch)
        return payloads

    def _extract_embedded_image_payloads(
        self,
        data: bytes,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        image_entries = self._embedded_image_entries(data)
        if not image_entries:
            return []
        payload_batches = self._run_ordered_local_batch(
            list(enumerate(image_entries)),
            lambda entry: self._embedded_image_payload_batch(
                entry,
                source_file=source_file,
                member_name=member_name,
            ),
            default_factory=list,
        )
        payloads: list[tuple[str, str, str]] = []
        for payload_batch in payload_batches:
            payloads.extend(payload_batch)
        return payloads

    def _embedded_image_payload_batch(
        self,
        indexed_entry: tuple[int, tuple[str, str, int, bytes]],
        *,
        source_file: str,
        member_name: str,
    ) -> list[tuple[str, str, str]]:
        image_index, image_entry = indexed_entry
        _kind, suffix, _offset, image_data = image_entry
        image_member_name = f"{member_name}#embedded-image-{image_index}{suffix}"
        return self._extract_image_member_payloads(source_file, image_member_name, image_data)

    def _extract_image_payload_family(
        self,
        family: str,
        path: Path,
    ) -> list[tuple[str, str, str]]:
        if family == "ocr":
            ocr_text = self._ocr_image_path(path)
            if not ocr_text.strip():
                return []
            return [(str(path), f"{path.name}#ocr", ocr_text)]
        if family == "barcode":
            barcode_payload = self._barcode_image_path_payload(path)
            if not barcode_payload:
                return []
            return [(str(path), f"{path.name}#barcode", barcode_payload)]
        if family == "metadata":
            try:
                data = path.read_bytes()[:_MAX_OCR_IMAGE_BYTES]
            except Exception:  # noqa: BLE001
                return []
            metadata_payload = self._image_metadata_payload(data)
            if not metadata_payload:
                return []
            return [(str(path), f"{path.name}#image-metadata", metadata_payload)]
        return []

    def _extract_image_member_payload_family(
        self,
        family: str,
        *,
        source_file: str,
        member_name: str,
        data: bytes,
    ) -> list[tuple[str, str, str]]:
        if family == "ocr":
            ocr_text = self._ocr_image_bytes(data, Path(member_name).suffix.lower())
            if not ocr_text.strip():
                return []
            return [(source_file, f"{member_name}#ocr", ocr_text)]
        if family == "barcode":
            barcode_payload = self._barcode_image_bytes_payload(data)
            if not barcode_payload:
                return []
            return [(source_file, f"{member_name}#barcode", barcode_payload)]
        if family == "metadata":
            metadata_payload = self._image_metadata_payload(data[:_MAX_OCR_IMAGE_BYTES])
            if not metadata_payload:
                return []
            return [(source_file, f"{member_name}#image-metadata", metadata_payload)]
        return []

    def _image_metadata_payload(self, data: bytes) -> str:
        # EXIF/XMP/PNG text chunks are often enough for passive pivot extraction
        # even when OCR is unavailable on the operator workstation.
        return self._binary_string_payload(data)

    def _barcode_image_path_payload(self, path: Path) -> str:
        return "\n".join(barcode_payloads_from_path(path, max_bytes=_MAX_OCR_IMAGE_BYTES))

    def _barcode_image_bytes_payload(self, data: bytes) -> str:
        return "\n".join(barcode_payloads_from_bytes(data[:_MAX_OCR_IMAGE_BYTES]))

    def _ocr_image_path(self, path: Path) -> str:
        if not self._ocr_binary or not path.exists():
            return ""
        try:
            proc = subprocess.run(
                [self._ocr_binary, str(path), "stdout", "--psm", "6"],
                capture_output=True,
                text=True,
                timeout=_OCR_TIMEOUT_SECONDS,
                check=False,
            )
        except Exception:  # noqa: BLE001
            return ""
        if proc.returncode != 0:
            return ""
        return proc.stdout.replace("\x0c", "\n").strip()[:_OCR_TEXT_LIMIT]

    def _ocr_image_bytes(self, data: bytes, suffix: str) -> str:
        temp_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(delete=False, suffix=suffix or ".img") as handle:
                handle.write(data[:_MAX_OCR_IMAGE_BYTES])
                temp_path = Path(handle.name)
            return self._ocr_image_path(temp_path)
        finally:
            if temp_path is not None:
                temp_path.unlink(missing_ok=True)

    @staticmethod
    def _looks_like_archive_bytes(data: bytes) -> bool:
        prefix = data[:4]
        if prefix == _CRX_ARCHIVE_MAGIC:
            return True
        if prefix == b"PK\x03\x04" or prefix[:2] == b"\x1f\x8b" or prefix[:3] == b"BZh":
            return True
        if data[:6] == b"\xfd7zXZ\x00":
            return True
        if prefix == b"\x28\xb5\x2f\xfd":
            return True
        if prefix == b"\x04\x22\x4d\x18":
            return True
        if data[:6] == b"7z\xbc\xaf'\x1c":
            return True
        if data.startswith(_AR_ARCHIVE_MAGIC):
            return True
        if data[:6] in _CPIO_NEWC_MAGICS:
            return True
        if ArtifactQueueProcessor._asar_header_and_content_base(data) is not None:
            return True
        if len(data) > 262 and data[257:262] == b"ustar":
            return True
        return False

    def _embedded_image_entries(self, data: bytes) -> list[tuple[str, str, int, bytes]]:
        if len(data) < 10:
            return []
        max_scan = min(len(data), _MAX_ARTIFACT_MEMBER_BYTES)
        signatures = (
            ("png", ".png", b"\x89PNG\r\n\x1a\n"),
            ("jpeg", ".jpg", b"\xff\xd8\xff"),
            ("gif", ".gif", b"GIF87a"),
            ("gif", ".gif", b"GIF89a"),
            ("webp", ".webp", b"RIFF"),
            ("tiff", ".tif", b"II*\x00"),
            ("tiff", ".tif", b"MM\x00*"),
        )
        match_batches = self._run_ordered_local_batch(
            signatures,
            lambda signature_job: self._embedded_image_signature_matches(
                signature_job,
                data=data,
                max_scan=max_scan,
            ),
            default_factory=list,
        )
        raw_matches = [
            match
            for match_batch in match_batches
            for match in match_batch
        ]
        matches: list[tuple[str, str, int]] = []
        seen_offsets: set[int] = set()
        for kind, suffix, offset in sorted(raw_matches, key=lambda item: item[2]):
            if offset in seen_offsets:
                continue
            seen_offsets.add(offset)
            matches.append((kind, suffix, offset))
        entries: list[tuple[str, str, int, bytes]] = []
        covered_until = -1
        for index, (kind, suffix, offset) in enumerate(matches):
            if offset < covered_until:
                continue
            next_offset = next(
                (
                    candidate_offset
                    for _next_kind, _next_suffix, candidate_offset in matches[index + 1 :]
                    if candidate_offset > offset
                ),
                0,
            )
            image_data = self._embedded_image_bytes(
                kind,
                data,
                offset,
                next_offset=next_offset,
            )
            if not image_data:
                continue
            covered_until = max(covered_until, offset + len(image_data))
            entries.append((kind, suffix, offset, image_data))
            if len(entries) >= _EMBEDDED_IMAGE_MAX_CANDIDATES:
                break
        return entries

    @staticmethod
    def _embedded_image_signature_matches(
        signature_job: tuple[str, str, bytes],
        *,
        data: bytes,
        max_scan: int,
    ) -> list[tuple[str, str, int]]:
        image_kind, suffix, signature = signature_job
        matches: list[tuple[str, str, int]] = []
        start = 0
        while start < max_scan:
            offset = data.find(signature, start, max_scan)
            if offset < 0:
                break
            if image_kind != "webp" or data[offset + 8 : offset + 12] == b"WEBP":
                matches.append((image_kind, suffix, offset))
            start = offset + 1
        return matches

    @staticmethod
    def _embedded_image_bytes(
        image_kind: str,
        data: bytes,
        offset: int,
        *,
        next_offset: int = 0,
    ) -> bytes:
        if offset < 0 or offset >= len(data):
            return b""
        max_end = min(len(data), offset + _MAX_OCR_IMAGE_BYTES)
        if image_kind == "png":
            marker = data.find(b"IEND", offset + 8, max_end)
            end = marker + 8 if marker >= 0 else 0
        elif image_kind == "jpeg":
            marker = data.find(b"\xff\xd9", offset + 2, max_end)
            end = marker + 2 if marker >= 0 else 0
        elif image_kind == "gif":
            marker = data.find(b"\x3b", offset + 6, max_end)
            end = marker + 1 if marker >= 0 else 0
        elif image_kind == "webp":
            if offset + 12 > len(data) or data[offset : offset + 4] != b"RIFF":
                return b""
            if data[offset + 8 : offset + 12] != b"WEBP":
                return b""
            payload_size = int.from_bytes(data[offset + 4 : offset + 8], "little")
            end = offset + 8 + payload_size
        elif image_kind == "tiff":
            end = next_offset if next_offset > offset else max_end
        else:
            return b""
        if end <= offset or end > max_end:
            return b""
        return data[offset:end]

    def _embedded_archive_offsets(self, data: bytes) -> list[tuple[str, int]]:
        if len(data) < 8:
            return []
        max_scan = min(len(data), _MAX_ARTIFACT_MEMBER_BYTES)
        signatures = (
            ("zip", b"PK\x03\x04"),
            ("gz", b"\x1f\x8b\x08"),
            ("bz2", b"BZh"),
            ("xz", b"\xfd7zXZ\x00"),
            ("zst", b"\x28\xb5\x2f\xfd"),
            ("lz4", b"\x04\x22\x4d\x18"),
            ("7z", b"7z\xbc\xaf'\x1c"),
        )
        match_batches = self._run_ordered_local_batch(
            signatures,
            lambda signature_job: self._embedded_archive_signature_matches(
                signature_job,
                data=data,
                max_scan=max_scan,
            ),
            default_factory=list,
        )
        prepared_match_entries = self._run_ordered_local_batch(
            [
                (match_index, match_entry)
                for match_index, match_entry in enumerate(
                    match_entry
                    for match_batch in match_batches
                    for match_entry in match_batch
                )
            ],
            self._embedded_archive_match_entry,
            default_factory=lambda: None,
        )
        matches: list[tuple[str, int]] = []
        seen: set[tuple[str, int]] = set()
        for key in prepared_match_entries:
            if not isinstance(key, tuple) or len(key) != 2:
                continue
            if key in seen:
                continue
            seen.add(key)
            matches.append(key)
        matches.sort(key=lambda item: item[1])
        return matches[:8]

    @staticmethod
    def _embedded_archive_signature_matches(
        signature_job: tuple[str, bytes],
        *,
        data: bytes,
        max_scan: int,
    ) -> list[tuple[str, int]]:
        archive_kind, signature = signature_job
        matches: list[tuple[str, int]] = []
        start = 1
        while start < max_scan:
            offset = data.find(signature, start, max_scan)
            if offset < 1:
                break
            matches.append((archive_kind, offset))
            start = offset + 1
        return matches

    @staticmethod
    def _embedded_archive_match_entry(
        match_entry: tuple[int, tuple[str, int]],
    ) -> tuple[str, int] | None:
        _match_index, entry = match_entry
        if not isinstance(entry, tuple) or len(entry) != 2:
            return None
        archive_kind, offset = entry
        kind = str(archive_kind or "").strip()
        if not kind:
            return None
        try:
            normalized_offset = int(offset)
        except (TypeError, ValueError):
            return None
        if normalized_offset < 1:
            return None
        return kind, normalized_offset

    @staticmethod
    def _interesting_binary_string(value: str) -> bool:
        text = str(value or "").strip()
        if len(text) < 6 or len(text) > 512:
            return False
        if not any(char.isalpha() for char in text):
            return False
        return any(marker in text for marker in ("@", "://", "/", ".", "_", "-", " "))

    def _binary_string_payload(self, data: bytes) -> str:
        family_candidates = self._run_ordered_local_batch(
            ("ascii", "utf16"),
            lambda family: self._binary_string_candidate_family(data, family),
            default_factory=list,
        )
        family_entry_batches = self._run_ordered_local_batch(
            list(enumerate(family_candidates)),
            self._binary_string_family_entries,
            default_factory=list,
        )
        prepared_value_entries = self._run_ordered_local_batch(
            [
                (candidate_index, candidate)
                for candidate_index, candidate in enumerate(
                    candidate
                    for candidates in family_entry_batches
                    for candidate in candidates
                )
            ],
            self._binary_string_value_entry,
            default_factory=lambda: None,
        )
        values: list[str] = []
        seen: set[str] = set()
        for candidate in prepared_value_entries:
            if not candidate or candidate in seen:
                continue
            seen.add(candidate)
            values.append(candidate)
        return "\n".join(values[:128])

    def _binary_string_candidate_family(
        self,
        data: bytes,
        family: str,
    ) -> list[str]:
        if family == "ascii":
            return self._binary_string_ascii_candidates(data)
        if family == "utf16":
            return self._binary_string_utf16_candidates(data)
        return []

    @staticmethod
    def _binary_string_family_entries(
        family_batch: tuple[int, Sequence[str]],
    ) -> list[str]:
        _family_index, candidates = family_batch
        values: list[str] = []
        for candidate in candidates:
            normalized = str(candidate or "").strip()
            if normalized:
                values.append(normalized)
        return values

    @staticmethod
    def _binary_string_value_entry(
        candidate_entry: tuple[int, str],
    ) -> str | None:
        _candidate_index, candidate = candidate_entry
        value = str(candidate or "").strip()
        if not value:
            return None
        return value

    def _binary_string_ascii_candidates(self, data: bytes) -> list[str]:
        raw_matches = [match.group(0) for match in re.finditer(rb"[ -~]{6,}", data)]
        candidate_lines = self._run_ordered_local_batch(
            raw_matches,
            self._binary_string_ascii_candidate,
            default_factory=str,
        )
        return [candidate for candidate in candidate_lines if candidate]

    def _binary_string_ascii_candidate(self, raw_match: bytes) -> str:
        try:
            candidate = raw_match.decode("latin-1", errors="ignore").strip()
        except Exception:  # noqa: BLE001
            return ""
        if self._interesting_binary_string(candidate):
            return candidate
        return ""

    def _binary_string_utf16_candidates(self, data: bytes) -> list[str]:
        raw_matches = [match.group(0) for match in re.finditer(rb"(?:[\x20-\x7e]\x00){6,}", data)]
        candidate_lines = self._run_ordered_local_batch(
            raw_matches,
            self._binary_string_utf16_candidate,
            default_factory=str,
        )
        return [candidate for candidate in candidate_lines if candidate]

    def _binary_string_utf16_candidate(self, raw_match: bytes) -> str:
        try:
            candidate = raw_match.decode("utf-16le", errors="ignore").strip()
        except Exception:  # noqa: BLE001
            return ""
        if self._interesting_binary_string(candidate):
            return candidate
        return ""

    def _ole_metadata_lines(self, ole: Any) -> list[str]:
        try:
            metadata = ole.get_metadata()
        except Exception:  # noqa: BLE001
            return []
        line_candidates = self._run_ordered_local_batch(
            (
            "title",
            "subject",
            "author",
            "last_saved_by",
            "comments",
            "keywords",
            "company",
            "manager",
            ),
            lambda key: self._ole_metadata_line(metadata, key),
            default_factory=str,
        )
        lines = [line for line in line_candidates if line]
        deduped: list[str] = []
        seen: set[str] = set()
        for line in lines:
            if line in seen:
                continue
            seen.add(line)
            deduped.append(line)
        return deduped[:64]

    @staticmethod
    def _ole_metadata_line(metadata: Any, key: str) -> str:
        try:
            value = getattr(metadata, key, None)
        except Exception:  # noqa: BLE001
            value = None
        if value is None:
            return ""
        text = str(value).strip()
        if not text:
            return ""
        return f"{key}={text}"

    def _member_payloads(
        self,
        source_file: str,
        member_name: str,
        data: bytes,
    ) -> list[tuple[str, str, str]]:
        lowered = member_name.lower()
        text = self._decode_text_artifact_bytes(data)
        if lowered.endswith(".rels"):
            payloads = self._run_ordered_local_batch(
                ("relationships",),
                lambda family: self._extract_member_payload_family(
                    family,
                    source_file=source_file,
                    member_name=member_name,
                    lowered=lowered,
                    text=text,
                ),
                default_factory=list,
            )
            return payloads[0] if payloads else []
        if lowered.endswith((".xml", ".xhtml", ".xht", ".opf", ".ncx")):
            if database_client_config_artifact_label(member_name):
                return [(source_file, member_name, text)]
            payload_families = self._run_ordered_local_batch(
                ("text", "meta"),
                lambda family: self._extract_member_payload_family(
                    family,
                    source_file=source_file,
                    member_name=member_name,
                    lowered=lowered,
                    text=text,
                ),
                default_factory=list,
            )
            prepared_payload_families = self._run_ordered_local_batch(
                list(enumerate(payload_families)),
                self._artifact_payload_tuple_batch_entries,
                default_factory=list,
            )
            payloads: list[tuple[str, str, str]] = []
            for family_payloads in prepared_payload_families:
                payloads.extend(family_payloads)
            return payloads
        return [(source_file, member_name, text)]

    def _extract_member_payload_family(
        self,
        family: str,
        *,
        source_file: str,
        member_name: str,
        lowered: str,
        text: str,
    ) -> list[tuple[str, str, str]]:
        if family == "relationships" and lowered.endswith(".rels"):
            relationship_payload = self._relationship_payload(text)
            if relationship_payload:
                return [(source_file, f"{member_name}#relationships", relationship_payload)]
            return []
        if family == "text" and lowered.endswith((".xml", ".xhtml", ".xht", ".opf", ".ncx")):
            xml_text = self._xml_text_payload(text)
            if xml_text:
                return [(source_file, member_name, xml_text)]
            return []
        if family == "meta" and lowered.endswith((".xml", ".xhtml", ".xht", ".opf", ".ncx")):
            property_payload = self._xml_property_payload(member_name, text)
            if property_payload:
                return [(source_file, f"{member_name}#meta", property_payload)]
            return []
        return []

    @staticmethod
    def _normalize_xml_tag(tag: str) -> str:
        if "}" in tag:
            return tag.rsplit("}", 1)[-1]
        return tag

    def _xml_text_payload(self, text: str) -> str:
        try:
            root = ElementTree.fromstring(text)
        except Exception:  # noqa: BLE001
            return text
        value_candidates = self._run_ordered_local_batch(
            list(root.itertext()),
            self._xml_text_value,
            default_factory=str,
        )
        values = [value for value in value_candidates if value]
        return "\n".join(values)

    @staticmethod
    def _xml_text_value(value: Any) -> str:
        return str(value).strip()

    def _xml_property_payload(self, member_name: str, text: str) -> str:
        lowered = member_name.lower()
        interesting = (
            lowered.startswith("docprops/")
            or "comments" in lowered
            or "notesslides/" in lowered
            or "slide" in lowered
            or "sharedstrings" in lowered
            or lowered.endswith("workbook.xml")
            or lowered.endswith("document.xml")
            or lowered.endswith("presentation.xml")
        )
        if not interesting:
            return ""
        try:
            root = ElementTree.fromstring(text)
        except Exception:  # noqa: BLE001
            return ""
        line_candidates = self._run_ordered_local_batch(
            list(root.iter()),
            self._xml_property_line,
            default_factory=str,
        )
        line_entries = self._run_ordered_local_batch(
            list(enumerate(line_candidates)),
            self._ordered_line_entry,
            default_factory=lambda: None,
        )
        lines = [line for line in line_entries if isinstance(line, str)]
        deduped: list[str] = []
        seen: set[str] = set()
        for line in lines:
            if line in seen:
                continue
            seen.add(line)
            deduped.append(line)
        return "\n".join(deduped[:64])

    def _xml_property_line(self, element: Any) -> str:
        children = list(element)
        value = "".join(part.strip() for part in element.itertext() if part and part.strip())
        if children or not value:
            return ""
        tag = self._normalize_xml_tag(element.tag)
        return f"{tag}={value}"

    def _relationship_payload(self, text: str) -> str:
        try:
            root = ElementTree.fromstring(text)
        except Exception:  # noqa: BLE001
            return ""
        line_candidates = self._run_ordered_local_batch(
            list(root),
            self._relationship_line,
            default_factory=str,
        )
        line_entries = self._run_ordered_local_batch(
            list(enumerate(line_candidates)),
            self._ordered_line_entry,
            default_factory=lambda: None,
        )
        lines = [line for line in line_entries if isinstance(line, str)]
        return "\n".join(lines[:64])

    @staticmethod
    def _relationship_line(element: Any) -> str:
        target = str(element.attrib.get("Target") or "").strip()
        if not target:
            return ""
        rel_type = str(element.attrib.get("Type") or "").rsplit("/", 1)[-1]
        if rel_type:
            return f"{rel_type}={target}"
        return target

    def _pdf_metadata_lines(self, data: bytes) -> list[str]:
        text = data.decode("latin-1", errors="ignore")
        line_families = self._run_ordered_local_batch(
            ("Title", "Author", "Creator", "Producer", "Subject", "Keywords", "URI"),
            lambda key: self._pdf_metadata_lines_for_key(text, key),
            default_factory=list,
        )
        line_batches = self._run_ordered_local_batch(
            list(enumerate(line_families)),
            self._ordered_line_batch_entries,
            default_factory=list,
        )
        lines: list[str] = []
        for family_lines in line_batches:
            lines.extend(family_lines)
        deduped: list[str] = []
        seen: set[str] = set()
        for line in lines:
            if line in seen:
                continue
            seen.add(line)
            deduped.append(line)
        return deduped[:64]

    @staticmethod
    def _ordered_line_batch_entries(
        line_batch: tuple[int, Sequence[str]],
    ) -> list[str]:
        _batch_index, batch = line_batch
        return [line for line in batch if line]

    @staticmethod
    def _ordered_line_entry(
        line_entry: tuple[int, str],
    ) -> str | None:
        _entry_index, line = line_entry
        if not line:
            return None
        return line

    @staticmethod
    def _pdf_metadata_lines_for_key(text: str, key: str) -> list[str]:
        lines: list[str] = []
        if key == "URI":
            for match in re.finditer(r"/URI\s*\((.*?)\)", text, re.DOTALL):
                value = match.group(1).strip()
                if value:
                    lines.append(f"uri={value}")
            return lines
        for match in re.finditer(rf"/{key}\s*\((.*?)\)", text, re.DOTALL):
            value = match.group(1).replace("\\(", "(").replace("\\)", ")").strip()
            if value:
                lines.append(f"{key.lower()}={value}")
        return lines

    def _pdf_xmp_payload(self, data: bytes) -> str:
        text = data.decode("latin-1", errors="ignore")
        match = re.search(r"<x:xmpmeta\b.*?</x:xmpmeta>", text, re.DOTALL | re.IGNORECASE)
        if not match:
            return ""
        return self._xml_text_payload(match.group(0))

    def _email_message_metadata_lines(self, message: Any) -> list[str]:
        line_candidates = self._run_ordered_local_batch(
            (
            "subject",
            "from",
            "to",
            "cc",
            "bcc",
            "reply-to",
            "date",
            "message-id",
            "x-mailer",
            ),
            lambda header_name: self._email_message_metadata_line(message, header_name),
            default_factory=str,
        )
        lines = [line for line in line_candidates if line]
        deduped: list[str] = []
        seen: set[str] = set()
        for line in lines:
            lowered = line.lower()
            if lowered in seen:
                continue
            seen.add(lowered)
            deduped.append(line)
        return deduped[:64]

    @staticmethod
    def _email_message_metadata_line(message: Any, header_name: str) -> str:
        value = str(message.get(header_name) or "").strip()
        if not value:
            return ""
        return f"{header_name}={value}"

    def _artifact_payload_summary(
        self,
        path: Path,
        artifact_type: str,
        payloads: list[tuple[str, str, str]],
    ) -> dict[str, Any]:
        metadata_payloads = [extract_path for _, extract_path, _ in payloads if "#" in extract_path]
        relationship_payloads = [value for value in metadata_payloads if value.endswith("#relationships")]
        ocr_payloads = [value for value in metadata_payloads if "#ocr" in value]
        barcode_payloads = [value for value in metadata_payloads if "#barcode" in value]
        return {
            "parser": artifact_type,
            "format": _artifact_format_label(path),
            "payload_count": len(payloads),
            "metadata_payload_count": len(metadata_payloads),
            "relationship_payload_count": len(relationship_payloads),
            "ocr_payload_count": len(ocr_payloads),
            "barcode_payload_count": len(barcode_payloads),
            "barcode_decoder_backends": list(self._barcode_decoder_backends),
        }

    @staticmethod
    def _dedupe_firebase_projects(projects: list[FirebaseProject]) -> list[FirebaseProject]:
        deduped: list[FirebaseProject] = []
        seen: set[tuple[str, str, str]] = set()
        for project in projects:
            key = (project.project_id, project.source_file, project.extract_path)
            if key in seen:
                continue
            seen.add(key)
            deduped.append(project)
        return deduped

    @staticmethod
    def _dedupe_supabase_configs(configs: list[SupabaseConfig]) -> list[SupabaseConfig]:
        deduped: list[SupabaseConfig] = []
        seen: set[tuple[str, str, str]] = set()
        for config in configs:
            key = (config.project_ref, config.source_file, config.extract_path)
            if key in seen:
                continue
            seen.add(key)
            deduped.append(config)
        return deduped

    def _store_key_finding(
        self,
        con: sqlite3.Connection,
        *,
        service: str,
        domain: str,
        source_url: str,
        pattern_name: str,
        key_redacted: str,
        key_enc: str | None,
        source_backend: str = "mobile_config_parse",
        repo_name: str | None = None,
        validation_detail: str = "artifact_queue_ingest",
    ) -> None:
        con.execute(
            """
            INSERT OR IGNORE INTO key_scanner_findings
                (engagement_id, domain, service, pattern_name, source_backend, source_url, repo_name, key_redacted, key_enc, validation_state, validation_detail)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'UNCONFIRMED', ?)
            """,
            (
                self._engagement_id,
                domain,
                service,
                pattern_name,
                source_backend,
                source_url,
                repo_name or Path(source_url).name,
                key_redacted,
                key_enc,
                validation_detail,
            ),
        )

    def _insert_seed(
        self,
        con: sqlite3.Connection,
        seed_value: str,
        seed_type: str,
        *,
        source: str,
        confidence: float,
        depth: int = 1,
    ) -> bool:
        normalized_depth = max(0, int(depth or 0))
        before = con.total_changes
        con.execute(
            """
            INSERT INTO engagement_seeds
                (engagement_id, seed_value, seed_type, source, status, depth, confidence, metadata_json)
            VALUES (?, ?, ?, ?, 'pending', ?, ?, '{}')
            ON CONFLICT(engagement_id, seed_type, seed_value) DO UPDATE SET
                source=excluded.source,
                status='pending',
                depth=MIN(engagement_seeds.depth, excluded.depth),
                confidence=MAX(engagement_seeds.confidence, excluded.confidence),
                updated_at=CURRENT_TIMESTAMP
            """,
            (self._engagement_id, seed_value, seed_type, source, normalized_depth, confidence),
        )
        return con.total_changes > before

    def _artifact_child_seed_depth(
        self,
        con: sqlite3.Connection,
        source_seed_id: int | None,
    ) -> int:
        if source_seed_id is None:
            return 1
        row = con.execute(
            """
            SELECT depth
            FROM engagement_seeds
            WHERE id=? AND engagement_id=?
            """,
            (source_seed_id, self._engagement_id),
        ).fetchone()
        if row is None:
            return 1
        return max(1, int(row[0] or 0) + 1)

    def _lookup_seed_id(
        self,
        con: sqlite3.Connection,
        seed_value: str,
        seed_type: str,
    ) -> int | None:
        row = con.execute(
            """
            SELECT id
            FROM engagement_seeds
            WHERE engagement_id=? AND seed_type=? AND seed_value=?
            """,
            (self._engagement_id, seed_type, seed_value),
        ).fetchone()
        if row is None:
            return None
        return int(row[0])

    def _artifact_source_seed_id(
        self,
        con: sqlite3.Connection,
        source_url: str,
    ) -> int | None:
        normalized = str(source_url or "").strip()
        if not normalized:
            return None
        seed_type = _classify_seed_value(normalized)
        if seed_type not in {"url", "apk_url"}:
            return None
        candidate_types = [seed_type]
        if seed_type == "apk_url":
            candidate_types.append("url")
        elif seed_type == "url" and _is_mobile_bundle_url(normalized):
            candidate_types.insert(0, "apk_url")
        for candidate_type in dict.fromkeys(candidate_types):
            seed_id = self._lookup_seed_id(con, normalized, candidate_type)
            if seed_id is not None:
                return seed_id
        return None

    @staticmethod
    def _artifact_source_seed_provenance(
        con: sqlite3.Connection,
        source_seed_id: int,
    ) -> dict[str, Any]:
        row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_seeds
            WHERE id=?
            """,
            (source_seed_id,),
        ).fetchone()
        if row is None:
            return {}
        metadata = _safe_json_loads(str(row[0] or "{}"))
        if not isinstance(metadata, dict):
            return {}
        provenance: dict[str, Any] = {}
        for key in (
            "archive_sources",
            "provider_sources",
            "root_domain",
            "discovered_from",
            "source",
            "source_backend",
            "source_provider",
            "fixture_provider",
            "source_url",
            "source_seed_url",
            "content_type",
            "download_filename",
            "downloaded_from_remote",
            "parser",
            "payload_count",
            "metadata_payload_count",
            "relationship_payload_count",
            "ocr_payload_count",
            "barcode_payload_count",
            "hostname",
            "scan_domain",
            "scan_id",
            "scheme",
            "port",
        ):
            value = metadata.get(key)
            if value in (None, "", [], {}):
                continue
            if key in {"archive_sources", "provider_sources"}:
                if not isinstance(value, list):
                    continue
                normalized: list[str] = []
                for raw_item in value:
                    item = str(raw_item or "").strip()
                    if item and item not in normalized:
                        normalized.append(item)
                    if len(normalized) >= 8:
                        break
                if normalized:
                    provenance[key] = normalized
                continue
            if isinstance(value, (str, int, float, bool)):
                provenance[key] = value
        return provenance

    @staticmethod
    def _artifact_seed_metadata_from_evidence(
        evidence: dict[str, Any],
        *,
        source_seed_id: int,
    ) -> dict[str, Any]:
        allowed_keys = {
            "archive_sources",
            "provider_sources",
            "root_domain",
            "discovered_from",
            "source",
            "source_backend",
            "source_provider",
            "fixture_provider",
            "source_url",
            "source_seed_url",
            "source_file",
            "extract_path",
            "extract_rule",
            "format",
            "artifact_type",
            "content_type",
            "download_filename",
            "downloaded_from_remote",
            "parser",
            "payload_count",
            "metadata_payload_count",
            "relationship_payload_count",
            "ocr_payload_count",
            "hostname",
            "scan_domain",
            "scan_id",
            "scheme",
            "port",
        }
        metadata: dict[str, Any] = {
            "artifact_provenance": True,
            "artifact_source_seed_id": source_seed_id,
        }
        for key in sorted(allowed_keys):
            value = evidence.get(key)
            if value in (None, "", [], {}):
                continue
            if key in {"archive_sources", "provider_sources"}:
                if not isinstance(value, list):
                    continue
                normalized: list[str] = []
                for raw_item in value:
                    item = str(raw_item or "").strip()
                    if item and item not in normalized:
                        normalized.append(item)
                    if len(normalized) >= 8:
                        break
                if normalized:
                    metadata[key] = normalized
                continue
            if isinstance(value, (str, int, float, bool)):
                metadata[key] = value
        return metadata

    @staticmethod
    def _merge_artifact_seed_metadata(existing: Any, incoming: dict[str, Any]) -> dict[str, Any]:
        merged = dict(existing) if isinstance(existing, dict) else {}
        for key, value in incoming.items():
            if value in (None, "", [], {}):
                continue
            if key in {"archive_sources", "provider_sources"}:
                existing_sources = merged.get(key)
                normalized: list[str] = []
                if isinstance(existing_sources, list):
                    for raw_item in existing_sources:
                        item = str(raw_item or "").strip()
                        if item and item not in normalized:
                            normalized.append(item)
                if isinstance(value, list):
                    for raw_item in value:
                        item = str(raw_item or "").strip()
                        if item and item not in normalized:
                            normalized.append(item)
                        if len(normalized) >= 8:
                            break
                if normalized:
                    merged[key] = normalized
                continue
            if key not in merged or merged.get(key) in (None, "", [], {}):
                merged[key] = value
        return merged

    def _merge_artifact_provenance_into_seed(
        self,
        con: sqlite3.Connection,
        target_seed_id: int,
        evidence: dict[str, Any],
        *,
        source_seed_id: int,
    ) -> None:
        incoming = self._artifact_seed_metadata_from_evidence(
            evidence,
            source_seed_id=source_seed_id,
        )
        if not incoming:
            return
        row = con.execute(
            """
            SELECT metadata_json
            FROM engagement_seeds
            WHERE id=? AND engagement_id=?
            """,
            (target_seed_id, self._engagement_id),
        ).fetchone()
        if row is None:
            return
        existing = _safe_json_loads(str(row[0] or "{}"))
        merged = self._merge_artifact_seed_metadata(existing, incoming)
        con.execute(
            """
            UPDATE engagement_seeds
            SET metadata_json=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=? AND engagement_id=?
            """,
            (
                json.dumps(merged, sort_keys=True),
                target_seed_id,
                self._engagement_id,
            ),
        )

    @staticmethod
    def _merge_relation_evidence(
        existing: Any,
        incoming: dict[str, Any] | None,
    ) -> dict[str, Any]:
        merged = dict(existing) if isinstance(existing, dict) else {}
        if not incoming:
            return merged
        for key, value in incoming.items():
            if value in (None, "", [], {}):
                continue
            merged[str(key)] = value
        return merged

    def _insert_relation(
        self,
        con: sqlite3.Connection,
        source_seed_id: int,
        target_seed_id: int,
        relation_type: str,
        confidence: float,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        existing_row = con.execute(
            """
            SELECT confidence, evidence_json
            FROM seed_relations
            WHERE engagement_id=? AND source_seed_id=? AND target_seed_id=? AND relation_type=?
            """,
            (self._engagement_id, source_seed_id, target_seed_id, relation_type),
        ).fetchone()
        if existing_row is not None:
            existing_metadata = _safe_json_loads(str(existing_row[1] or "{}"))
            merged_metadata = self._merge_relation_evidence(existing_metadata, metadata)
            con.execute(
                """
                UPDATE seed_relations
                SET confidence=?,
                    evidence_json=?
                WHERE engagement_id=? AND source_seed_id=? AND target_seed_id=? AND relation_type=?
                """,
                (
                    max(float(existing_row[0] or 0.0), float(confidence or 0.0)),
                    json.dumps(merged_metadata, sort_keys=True),
                    self._engagement_id,
                    source_seed_id,
                    target_seed_id,
                    relation_type,
                ),
            )
            return
        con.execute(
            """
            INSERT INTO seed_relations
                (engagement_id, source_seed_id, target_seed_id, relation_type, confidence, evidence_json)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                self._engagement_id,
                source_seed_id,
                target_seed_id,
                relation_type,
                confidence,
                json.dumps(metadata or {}),
            ),
        )

    def _link_artifact_source_seed(
        self,
        con: sqlite3.Connection,
        source_seed_id: int | None,
        target_seed_value: str,
        target_seed_type: str,
        *,
        confidence: float,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        if source_seed_id is None:
            return
        target_seed_id = self._lookup_seed_id(con, target_seed_value, target_seed_type)
        if target_seed_id is None or target_seed_id == source_seed_id:
            return
        evidence = {"rule": "artifact_seed_provenance"}
        if metadata:
            for key, value in metadata.items():
                if key == "rule":
                    if value:
                        evidence["extract_rule"] = value
                    continue
                evidence[key] = value
        for key, value in self._artifact_source_seed_provenance(con, source_seed_id).items():
            evidence.setdefault(key, value)
        self._merge_artifact_provenance_into_seed(
            con,
            target_seed_id,
            evidence,
            source_seed_id=source_seed_id,
        )
        self._insert_relation(
            con,
            source_seed_id,
            target_seed_id,
            "derived_from",
            confidence,
            evidence,
        )

    def _insert_email(
        self,
        con: sqlite3.Connection,
        email: str,
        *,
        source: str,
        depth: int = 1,
    ) -> bool:
        normalized = email.strip().lower()
        if "@" not in normalized:
            return False
        before = con.total_changes
        try:
            con.execute(
                """
                INSERT INTO emails (engagement_id, email, domain, source)
                VALUES (?, ?, ?, ?)
                """,
                (self._engagement_id, normalized, normalized.split("@", 1)[1], source),
            )
        except sqlite3.IntegrityError:
            pass
        except sqlite3.OperationalError:
            return False
        self._insert_seed(
            con,
            normalized,
            "email",
            source="artifact",
            confidence=0.74,
            depth=depth,
        )
        return con.total_changes > before

    @staticmethod
    def _classify_artifact(path: Path) -> str | None:
        return _classify_artifact_name(path)

    @staticmethod
    def _resolve_local_path(local_path: str, source_url: str) -> Path | None:
        for candidate in (local_path, source_url):
            if not candidate:
                continue
            path = Path(candidate)
            if path.exists():
                return path
        return None

    def _download_remote_artifact_request(
        self,
        request: ArtifactDownloadRequest,
    ) -> ArtifactDownloadResult:
        artifact_id = request.artifact_id
        source_url = request.source_url
        artifact_type = request.artifact_type
        parsed = urlparse(source_url)
        if parsed.scheme not in {"http", "https"}:
            return ArtifactDownloadResult(
                artifact_id=artifact_id,
                source_url=source_url,
                artifact_type=artifact_type,
            )
        cache_dir = self._db_path.parent / "artifact_cache" / str(self._engagement_id)
        cache_dir.mkdir(parents=True, exist_ok=True)
        filename = _select_remote_artifact_filename(
            artifact_id,
            source_url,
            artifact_type,
        )
        download_path = cache_dir / f"{artifact_id}-{filename}"
        if download_path.exists() and download_path.is_file():
            inferred_type = self._classify_artifact(download_path) or artifact_type
            return ArtifactDownloadResult(
                artifact_id=artifact_id,
                source_url=source_url,
                artifact_type=inferred_type,
                path=download_path,
                metadata_extra={"download_filename": download_path.name},
            )
        content_type = ""
        content_disposition = ""
        try:
            from urllib.error import HTTPError
            from urllib.request import Request, urlopen

            attempts = web_fetch_rate_limit_retries() + 1
            sleep_rate_limit_cooldown("web_fetch", source_url)
            for attempt in range(attempts):
                request_delay = web_fetch_request_delay_seconds()
                if request_delay > 0:
                    time.sleep(request_delay)
                request = Request(
                    source_url,
                    headers={"User-Agent": "FORGE/1.0 artifact-fetch"},
                )
                try:
                    total_bytes = 0
                    with urlopen(request, timeout=20.0) as response:
                        content_type = str(response.headers.get("Content-Type") or "").strip().lower()
                        content_disposition = str(response.headers.get("Content-Disposition") or "").strip()
                        filename = _select_remote_artifact_filename(
                            artifact_id,
                            source_url,
                            artifact_type,
                            content_disposition=content_disposition,
                            content_type=content_type,
                        )
                        download_path = cache_dir / f"{artifact_id}-{filename}"
                        if download_path.exists() and download_path.is_file():
                            inferred_type = self._classify_artifact(download_path) or artifact_type
                            return ArtifactDownloadResult(
                                artifact_id=artifact_id,
                                source_url=source_url,
                                artifact_type=inferred_type,
                                path=download_path,
                                metadata_extra={
                                    "content_disposition": content_disposition,
                                    "content_type": content_type,
                                    "download_filename": download_path.name,
                                },
                            )
                        with download_path.open("wb") as handle:
                            while True:
                                chunk = response.read(65_536)
                                if not chunk:
                                    break
                                total_bytes += len(chunk)
                                if total_bytes > _REMOTE_ARTIFACT_MAX_BYTES:
                                    raise ValueError("remote artifact exceeds size limit")
                                handle.write(chunk)
                    break
                except HTTPError as exc:
                    if exc.code == 429:
                        wait_seconds = web_fetch_retry_after_seconds(exc)
                        record_rate_limit_cooldown("web_fetch", source_url, wait_seconds)
                        if wait_seconds > 0:
                            time.sleep(wait_seconds)
                        if attempt < attempts - 1:
                            continue
                    raise
            else:
                raise RuntimeError("remote acquisition exhausted web-fetch retry budget")
        except Exception as exc:  # noqa: BLE001
            return ArtifactDownloadResult(
                artifact_id,
                source_url,
                artifact_type,
                error=f"remote acquisition failed: {type(exc).__name__}: {str(exc)[:180]}",
            )
        inferred_type = self._classify_artifact(download_path) or artifact_type
        return ArtifactDownloadResult(
            artifact_id=artifact_id,
            source_url=source_url,
            artifact_type=inferred_type,
            path=download_path,
            metadata_extra={
                "content_disposition": content_disposition,
                "content_type": content_type,
                "download_filename": download_path.name,
            },
        )

    def _download_remote_artifact(
        self,
        con: sqlite3.Connection,
        artifact_id: int,
        source_url: str,
        artifact_type: str,
    ) -> Path | None:
        result = self._download_remote_artifact_request(
            ArtifactDownloadRequest(
                artifact_id=artifact_id,
                source_url=source_url,
                artifact_type=artifact_type,
            )
        )
        if result.error:
            self._update_artifact_status(
                con,
                artifact_id,
                "failed",
                result.error,
            )
            return None
        if result.path is None:
            return None
        self._set_artifact_local_path(
            con,
            artifact_id,
            result.path,
            artifact_type=result.artifact_type,
            metadata_extra=result.metadata_extra,
        )
        return result.path

    @staticmethod
    def _set_artifact_local_path(
        con: sqlite3.Connection,
        artifact_id: int,
        local_path: Path,
        *,
        artifact_type: str | None = None,
        metadata_extra: dict[str, Any] | None = None,
    ) -> None:
        row = con.execute(
            "SELECT metadata_json FROM artifact_queue WHERE id=?",
            (artifact_id,),
        ).fetchone()
        existing_metadata = _safe_json_loads(str(row[0] or "{}")) if row is not None else {}
        merged_metadata = existing_metadata if isinstance(existing_metadata, dict) else {}
        merged_metadata.update(
            {
                "downloaded_from_remote": True,
                "download_path": local_path.as_posix(),
            }
        )
        if metadata_extra:
            merged_metadata.update(metadata_extra)
        con.execute(
            """
            UPDATE artifact_queue
            SET local_path=?,
                artifact_type=COALESCE(?, artifact_type),
                status='downloaded',
                metadata_json=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (
                local_path.as_posix(),
                artifact_type,
                json.dumps(merged_metadata, sort_keys=True),
                artifact_id,
            ),
        )

    @staticmethod
    def _update_artifact_status(
        con: sqlite3.Connection,
        artifact_id: int,
        status: str,
        notes: str,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        row = con.execute(
            "SELECT metadata_json FROM artifact_queue WHERE id=?",
            (artifact_id,),
        ).fetchone()
        existing_metadata = _safe_json_loads(str(row[0] or "{}")) if row is not None else {}
        merged_metadata = existing_metadata if isinstance(existing_metadata, dict) else {}
        if metadata:
            merged_metadata.update(metadata)
        con.execute(
            """
            UPDATE artifact_queue
            SET status=?, notes=?, metadata_json=?, updated_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (status, notes[:1024], json.dumps(merged_metadata, sort_keys=True), artifact_id),
        )
